INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-103','%d0%b3%d0%be%d1%80%d0%b4%d0%b8%d0%bd%d1%8f-%d0%b2%d0%b5%d0%bb%d0%b8%d1%87%d0%b5%','Гординя – величезна вирва втрати енергії!','Останнім часом отримую дуже багато запитань, пов''язаних із гординею.Називаючи цю людську якість енергетичною вирвою, я анітрохи не перебільшую, бо саме так і є. Гординя – це надмірна самовпевненість, перебільшення своїх здібностей, гордовитість, зазн...','["Останнім часом отримую дуже багато запитань, пов''язаних із гординею.Називаючи цю людську якість енергетичною вирвою, я анітрохи не перебільшую, бо саме так і є. Гординя – це надмірна самовпевненість, перебільшення своїх здібностей, гордовитість, зазнайство, егоїзм, невдячність і манія величі, які живлять велике Его хибною любов’ю. Насамперед гординя проявляється по відношенню до інших людей, але має і більш глибоке коріння – це відсутність подяки по відношенню до Творця. Коли людина забуває, що є лише провідником і починає уявляти себе “богом”, – її долає гординя. Дуже часто під виглядом любові до себе та інших маскують гординю; під виглядом доброти та чуйності маскують гординю; під виглядом святості та духовності маскують гординю. Ну і навпаки – чим вищий рівень розвитку людини, її душі, чим чистіші її мотиви – тим вільніша особистість від гордині… На внутрішні тертя і боротьбу йде колосальна кількість енергії, яка насправді дана людині для життя, любові, щастя та творення. На постійні докази своєї правоти йде у вирву гордині ще порція енергії. На недовіру, сумніви та повторну перевірку фактів – ще відніміть частину енергії. І що залишається людині в результаті? Зовсім мало! І цю невелику кількість енергії доводиться ще й відстоювати, берегти, плекати, постійно відчуваючи порожнечу. Гординя – це найкоротший шлях до самотності, хвороб та бідності! Як розпізнати наявність гордині, яка маскується у тобі? Я б виділила найпоширеніші маркери: ти весь час ділиш людей на табори – на розумних і дурних, вихованих та невихованих, культурних та некультурних… І при цьому дратуєшся при стиканні з “не своїм” табором; критикуючи інших, ти не помічаєш своїх недоліків; ти вважаєш себе кращим, крутішим, швидшим, ніж… і всіляко намагаєшся це продемонструвати; ти привласнюєш всі досягнення свого життя тільки собі, не враховуючи впливу інших, і виявляєш невдячність до Бога; ти не здатний щиро радіти успіхам інших; щедрість тобі невідома. Або ж інший перекіс – ти займаєшся благодійністю, чекаючи на похвалу та визнання; тобі складно визнавати свої помилки, вибачатися за них; ти не любиш себе, і виправдовуєш цим свої гіпервимоги до інших; ти дозволяєш собі маніпуляції та споживання, шантаж і залякування, знаючи про слабкості інших; ти перекладаєш відповідальність за свої невдачі на інших, а нагороди береш лише собі; ти боїшся зрад, тож нікому не довіряєш; ти не вмієш прощати ні себе, ні інших; твій світ складається зі “страхів” та “проблем”; легкість, радість та щастя інших тебе дратують, викликають зневагу, почуття переваги; я сам, я знаю, я все можу, хто ти, щоб давати мені поради … – ось списочок думок гордеця. Можна ще продовжити. Це лише основні маркери, але вже вчитуючись у список, усвідомлюєш, що, на жаль, гординя властива кожному з нас. Ми не святі, всі мають недоліки. Але жодні інші вади не ускладнюють і не руйнують життя так, як це робить гординя! Іноді клієнти мені кажуть: “Почекайте, але навколо мене справді повно ідіотів! І на роботі сидить купа негідних своїх положень кадрів! Ну чим я гірший за Степановича? Я ж розумніша, у мене дві вищі освіти…!”. Такі репліки я чую регулярно. І починаю пояснювати різницю між фіксацією чогось, як факту та гординею! Ми не овочі, у нас є емоції, почуття гідності та самооцінка. Коли гординя всередині людини під контролем, то немає, по-перше, критичності, а по-друге, немає ні бажання, ні потреби ділити людей на табори. Є розуміння та фіксація фактів! Є цілісність! Розуміння, що якщо я наразі маю саме це, то з якоїсь причини поки що не заслуговую на інше. Фільтр – якщо тебе щось дратує та чіпляє – ти під дією гордині! Якщо ти, помічаючи все на світі, зберігаєш спокій і перебуваєш у зоні комфорту – гордині немає. Проблеми маєш? – Подумай, чим заслужив їх, виправся, зцілися! Нагороди маєш? – Подякуй і поділись, на людяність не скупись! Знаєте, як буває: те, чим страждав чи хворів сам, найбільше впадає у вічі в оточуючих. Ось у мене так із гординею. Грішна – каюся. Носилася з собою, як з писаною торбою. Зневажливо ставилася до тих, хто знає менше або думає інакше. Коли пропрацювала гординю – люди вишикувалися в чергу, прийшло усвідомлення своїх заслуг, але у ключі роботи провідника, якого благословляють на дію Вищі Сили. Зникла інтелектуальна упередженість і з’явилася величезна подяка до близьких, до рідних. Як мінімум за те, що довго терпіли моє прагнення всім «причинити добро». Не рийте собі яму, визнайте наявність “якоря”! Чим швидше його позбудетеся, тим швидше життя заграє всіма фарбами радості і щастя в Любові до всього і всіх! Що ж я робила у боротьбі з гординею? По-перше, визнала її наявність. Це – чи не найважливіший крок. Поки не назвеш своїм ім’ям проблему, неможливо її позбутися. А далі з’явився шлях зцілення. Нема істини там, де є категоричність! Багатоваріантність – це вибір Бога; категоричність – шлях диявола. Тренування поблажливого ставлення до інших було марним, поки не пропрацювалася критичність до себе! Коли я чую фразу: “Та я до себе ще критичніший, ніж до інших!”, – вимовлену з гордістю, я посміхаюся, хочу підійти, обійняти і сказати: “Чувак, як я тебе розумію! Але ця бяка, ця какашка лікується, повір!”. Тому виділяю нехитрі, але важливі способи боротьби з гординею: полюби себе цілком і без залишку; якщо для цього потрібно пробачити купу людей з минулого і сьогодення – зроби це, пробач і прийми! Не вмієш, не знаєш як – приходь, навчимо! вивчи закони карми – це дозволить зрозуміти все, що відбувалося і відбувається, позбутися тривоги та порожніх очікувань. Розвивайся духовно постійно, а не у вигляді походу до церкви на Великдень та Різдво. Духовна гігієна така ж важлива, як і твої ритуали з чищенням зубів і миттям голови; заведи щоденник подяки та пропиши в ньому все, що можеш згадати з дитинства, пов’язане з іншими людьми – мама мене народила, годувала, ростила, виховувала, …; батько багато працював, був поруч, щиро намагався навчити чогось, що вважав правильним, брав на рибалку або не брав і слава богу; ріс у колі брата та сестри, не один, навчився грати, домовлятися, ділитися; або не було в мене мами та тата, але було коло однодумців, дитбудинківців, з якими я навчився співпрацювати, а на Новий рік подавали яблучний пиріг… Згадайте свої точки та запишіть їх. Повірте, якщо кожен день навіть подумки фіксувати подяку до свого оточення, то життя почне змінюватися на краще! контролюй свого внутрішнього критика! Якщо ти ще й досі знаходиш причини своїх проблем в інших людях, то ти так і не взяв відповідальності за своє життя на себе! Жодні обставини не можуть стати причиною безпросвітного горя та розчарування в людях та в житті. Жодні! Страждати безперечно легше, ніж бути щасливим. Але без викорінення гордині щастя не настане, повір! думай, відчувай і роби завжди однаково! Деколи люди проявляють вибірковість: тут я без гордині, а ось з тими людьми не можу, бо вони ж бомжі, цигани, мусульмани… підстав сюди будь-що. Якщо ти заявив про свою чесність, то будь ласкавий – доведи це дією! З Вітєю я дружу душа в душу, бо Вітьок теж підприємець, а з Ваською, колишнім однокласником, мені нема про що поговорити, він же лише охоронець, що з нього взяти! (Але ж поговорити можна з будь-яким, і знайдеться тема, було б бажання!). Або ще варіант: “Я тебе, Діно, любитиму і піклуватимуся про тебе, якщо ти щодня одягатимеш червоне плаття, а якщо ти цього не робитимеш, то не чекай від мене любові”- тут простежується умовність і ні про яке “і в хворобі, і в здоров’ї” мова йти вже не може. Гординя змушує підганяти оточення та світ під себе! навчись любити! Ось просто навчися любити і насолоджуватися роками, місяцями, днями, хвилинами, секундами, миттю… Не носитися зі своїми мріями в очікуванні щастя, а бути тут і зараз у своїй реальності, створеній власноруч. Навчися це любити! Саме Любляче серце відрізняє в натовпі гордовиту людину від негордовитої; шануй працю кожного, вибір кожного, шлях кожного! Тобі здається, що можна щось зробити краще? Не критикуй, а покажи та навчи! Поділися, а не нав’язуй! будь щедрим, віддай, перш ніж чекати і хотіти! Давай іншим більше, ніж чекаєш навзаєм. Ось просто перестань чекати і боятися, що на тобі їздитимуть: якщо ти зробив все вище описане, то неможливо на тобі їздити! Ти є джерело любові, ти є щастя, ти є процвітання та достаток, ти є частка Бога… як можна їздити на Богові? коли тобі дякують за щось і ти боїшся загордитися знову, згадуй, що завтра Творець може у тебе все відібрати! Або й просто зараз. А ще пограй у сніжки подяки! Коли тобі дякують за щось, береш цю подяку, подумки ліпиш сніжки з неї і розкидаєш своїм вчителям та наставникам, своїм близьким… Повір, вони навіть відчуватимуть, як у них “летить” щось добре. І ще … Гординя – це насправді грудка концентрованої слабкості, страждання душі, пораненої досвідом минулих втілень і даної реальності. Тому іноді є потреба у роботі над інкарнаційною пам’яттю з метою полегшення свого життя. Хочете покращити світ?! Врятуйте, дорогі, його від себе – від своєї гнівливості, своїх лінощів, своєї критичності, апатії, від своєї гордині… Я бажаю всім сміливості та завзятості у роботі зі своїми недоліками! Той, хто пізнав закони світобудови і Творця, не дивиться на світ очима гордеця! Живіть у радості, живіть свідомо! З повагою та любов’ю, Заверуха Ірина. © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','5 вересня 2023','7 хв читання','/images/posts/Gordinya-1200x675-1.jpg','[]',1,'2023-09-05T23:35:00','2023-09-05T23:35:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-182','%d1%8f%d0%ba-%d0%bd%d0%b0%d1%80%d0%be%d0%b4%d0%b8%d0%bb%d0%b0%d1%81%d1%8f-imaria','Як народилась IMaRia','Свого часу мені здавалося, що не впораюся… що колосально не впораюся і не витримаю напруження… Сила цієї напруги була така велика, що я засумнівалася в істинності шляху. Всередині мене відбувалася боротьба між західним раціоналістичним матеріалізмом ...','["Свого часу мені здавалося, що не впораюся… що колосально не впораюся і не витримаю напруження… Сила цієї напруги була така велика, що я засумнівалася в істинності шляху. Всередині мене відбувалася боротьба між західним раціоналістичним матеріалізмом та східним духовно-медитативним началом, як лід і полум’я, то розтоплюючи, то обпалюючи окропом гніву та іскрами від зіткнення. Я втомилася. Сильно. Так сильно втомилася і від людей, і від сім’ї, і від усієї цієї канителі з напругою життя, що грань здавалася піковою та нестерпною. Осінь насувалася на Землю, а на мене це цунамі. І я вирішила. Якщо дикі стихії буяють усередині і не вистачає якихось пазлів для їх стикування, значить, треба поринути в дику стихію, піти назустріч всьому цьому. Я поїхала в Карпати. Сама. Влаштувала собі мовчазний одиночний Ретрит. Жила в будиночку у товариша, на узліссі. Була надія знайти опору. Я робила йогу. Мало їла. Пила джерельну воду. Медитувала прямо на річці. Тобто сідала на містку, який через річку гірську, і медитувала на цей бурхливий потік, сподіваючись на очищення моєї свідомості. Я не розмовляла. Мовчала. І лише писала свої думки та обмінювалася ними з місцевими котами телепатично. Ходила на масаж, парила свої кістки в чані трав’яному. Загалом робила все, що могла. Але лід та полум’я всередині так і не з’єднувалися. І ось одного дня я вирішила піти ще далі і з’єднатися з природою ще глибше. Я встала о 4-й ранку, взула гумові чоботи, взяла з собою тільки воду в рюкзак за спиною і пішла в гори. Я брела навмання через нічне сонне село. Навколо нікого. Дикий ліс. Крокувала вгору. Поки на піку не зустріла сонце і світанковий тріумф третіх півнів. Немає таких слів, щоб передати почуття, які бурхливим потоком переповнювали мене тоді, по щоках текли сльози, все втратило сенс, ніби це був перший світанок у моєму житті і я щойно народилася. Мокра осіння земля дихала холодом і вогкістю. Туманний серпанок накривав долину і осідав унизу, але сонце наполегливо піднімалося вище і висвічувало небеса. А я стояла та дивилася. Пішла далі. По хребту безлюдних гір, що заросли лісом. Вдалині з’явився табун диких коней. Вони галопом мчали горами з такою силою Свободи, що я мимоволі розплакалася, сльози самі по собі бризнули з очей і вирвався дикий крик агонії зсередини найглибшого днища в мені. Із табуна коней один зупинився. Він глянув у мій бік і почав галопом бігти прямо на мене. Метрів 800-900 розділяли нас, і я в ступорі дивилася на цей біг, не відчуваючи нічого. Жеребець прискакав і різко зупинився перед моїм обличчям, опустивши голову з ніздрями, які випускали потужний пар. І ось тепер мене накрив шок від побаченого та усвідомленого. Він реально схилився до моїх ніг, дозволяючи себе гладити. Прекраснішого способу поговорити зі мною про самоцінність і не вигадаєш. Я плакала і від шоку, і від захоплення. Ішла далі. Якийсь час жеребець тупотів поряд. Потім він поскакав у Даль, з якої і з’явився. Тоді я ще не знала, що одного разу зустріну його знову. Що він знову прискаче галопом, але я буду тут не одна і допоможу своєму синові погладити його голову і не боятися дикої Сили природи. Я йшла далі… Не хотілося нічого аналізувати. Просто рух. Цілі не було. Найчистіша пригода без сенсу. Сонце вже піднялося досить високо. Погода була чудовою. Нагулявшись на гребені висоти, я почала спуск вниз у долину. Перейшла річку вбрід. Благо гумові чоботи були високими, а річка – не глибокою. Зате зустріла… Т И Ш У такої глибини, що не передати. Втомилася. Відверто кажучи, сильно втомилася. Спиною пригорнулася до дерева, заплющила очі, глибоко вдихнула і нааааааа видиху… провалилася в такууууууу безодню, що не описати. Моє тіло одночасно пронизалося мільярдами вихорів та потоків. Я відчула в кожній клітинці В И Б У Х, схожий на екстаз на рівному місці… Скрізь, де тільки можна було, виступив піт. Внутрішній жар викликав задишку, обличчя горіло вогнем дикої Сили… я не розуміла, що зі мною відбувається, і ніби задихалася сама собою. В очах все змішалося. Я розплющувала їх. Заплющувала. Але начебто це не працювало. Я бачила не ними. Вони перестали бути потрібними. Я зробила глибокий вдих і видих, і вибух повторився знову. Ще потужніший. Ще глибше пронизуючи мене струмом наскрізь. Це був дикий секс між небом та землею. Я зрозуміла, що всю мене пронизує оргазм. Таааак!!!! На рівні фізичного тіла це було схоже на оргазм. Але не в області геніталій, а СКРІЗЬ!! Скрізь у мені, і поза мною відбувалося ЖИТТЯ, Синергія, перетікання, вибух за вибухом… Моя матка та моє серце стали схожими на котел. Я відчула всередині величезну Силу початку творення. Це не передати словами. Це ні з чим не порівняти. Я дивилася на світ і не дивилася. Я була і мене не було. Я почувала себе Собою і я почувала себе всім: і деревом, і землею, і повітрям, і вітром, і водою, і мохом, і сонцем, і лісом, і всім, і нічим. Потім на мить мені здалося, що я вмираю. І вмиранню дала місце. Просто стікала вниз, сповзла, впала на сиру мокру землю. Агонія злиття всього з усім тривала… Такої насолоди від величі тотальної присутності та відсутності одночасно я не відчувала ніколи до цього і більше ніколи після цього. Я пізнала Любов і Силу, розчинившись у цьому потоці сексу Неба та Землі, і ніби в одну мить все ДІЗНАЛАСЯ. У голові з’явилися різні знання. Вони самі по собі начебто вибухали миттєво, різні архіви відкривалися і розкривалися розумінням. Начебто в мене вбудували мільйон енциклопедій і дали доступ до всіх мов Всесвіту. Я намагалася думати, але не могла. Не було того, що зазвичай думає. Уся реальність була реальною. Я з’являлася в якихось інших місцях, як спостерігач, що заглядає у вікно: в інших світах, тілах, просторах… Це відбувалося миттєво, дуже швидко, блискавично, миготіли іскри світла, і не було світу форм… Ніколи я не курила ніякої трави, не жувала грибів, не пила ніяких бовтанок, ніяких дослідів під впливом наркотичних речовин у мене не було, я прожила до цього і після цього чисту реальність, розширюючись як свідомість лише практикою медитації і моїм ЖИТТЯМ через усвідомленість… Але те, що зі мною відбувалося у лісі, було схоже на напівп’яне марення якогось там обкуреного нарика. Цей день змінив моє життя. Повністю. З «до» на «після». Мене колишньої не стало. Так Народилася Я IMaRia. Коли закінчилося завантаження та Активація пам’яті про те, хто я і навіщо. Я почала знову розрізняти земну реальність. Навколо було темно. Минули якісь миті, долі секунд. Але довкола я побачила темну ніч і зрозуміла, що насправді пролетіло багато годин. Не було страху. Не було паніки. Але була Я! Була тотально! Я встала із Землі, на якій валялася під деревом, мокра наскрізь. Мокрим було все, включно з білизною, не зрозуміло чому, начебто викупали. І побрела через ліс у село, до хати, де жила. Я тоді не знала жодних термінів, слів, пов’язаних із тим, що зі мною сталося… та й це не мало сенсу. Усі сенси загалом зникли. Я намагалася згадати свою «велику проблему» і чому тут опинилася – і не змогла. Пам’ять емоційну чуттєву ніби стерло. Все повернулося згодом. Тотальне обнулення. Тотальний спокій. Тотальна порожнеча та повнота одночасно. За два дні я звідти поїхала. Зовсім іншою людиною. Вагітною силами самої природи, наповненою знаннями про все; очищеною від всякої брехні і всіх правд. Після повернення додому я зрозуміла, що все інше. Точніше, воно можливо і таке ж, але в мені до всього інший дотик та ставлення. Чи зможу колись пояснити оточенню, що є інша реальність, ніж ігри розділеної на шматки свідомості? Чи можу я поділитися цим досвідом і реалізувати шлях Душі, який побачила чітко і ясно, лежачи на мокрій осінній землі у лісі? Чи зможу я…? Усе це втратило всякий сенс… Адже з’явилася єдина мета — БУТИ. ТУТ. ЗАРАЗ! …Там, де я прокинулася і усвідомлююся ВСІМ… © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','16 серпня 2023','6 хв читання','/images/posts/ImaRia.jpeg','[]',1,'2023-08-16T09:17:00','2023-08-16T09:17:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-191','%d1%82%d0%be%d0%bf-100-%d0%bd%d0%b5%d0%b7%d0%bb%d0%b0%d0%bc%d0%bd%d0%b8%d1%85-%d','ТОП-100 Незламних Українців','«Якби ви тільки почули ті голоси, які я чую серцем на кожній консультації чи груповій терапії… Іноді я ці ехо продовжую чути й серед ночі, коли давно згасли вогні та звуки активного міста…» Друзі, наразі без представлення гості. Просто вдумайтесь в ї...','["«Якби ви тільки почули ті голоси, які я чую серцем на кожній консультації чи груповій терапії… Іноді я ці ехо продовжую чути й серед ночі, коли давно згасли вогні та звуки активного міста…» Друзі, наразі без представлення гості. Просто вдумайтесь в її слова та звернення до вас. А далі долучайтесь, посилання після бесіди. Майстриня IMARIA. Берегиня України, Вчителька і Цілителька, Засновниця платформи багатовимірного розвитку Pipl; громадська діячка, практикуюча еніопсихологиня та Майстриня трансформації свідомості; наставниця соціальних Лідерів… ВАШІ ДУШІ ПРАГНУТЬ ЖИТИ, ЛЮДИ!!! Зрозумійте, будь-ласка, це не про егоїзм і збагачення, не про легкий кайф та боротьбу за краще місце під сонцем… «Жити» для Душі через тіло й матерію – це величезний шанс та дар. Це результат неймовірної титанічної праці за право бути ПРОЯВЛЕНИМ світлом; це фініш марафону між варіантами та контініумами обставин, які могли не статись, але вони стались. І ви ТУТ, І ЗАРАЗ ІСНУЄТЕ. КОЖНА СЕКУНДА, ХВИЛИНА – ЦЕ МОЖЛИВІСТЬ!!! …Неймовірна і самобутня, неповторна та безцінна можливість стати тим, хто ти Є насправді, хто нікуди не зникав і не зникне… Але потрібно СЕБЕ ЖИТИ, збагнути те блаженство Вічності, яке вдається осягнути лише через життя. Друзі, ви лише послухайте, як несамовито б’ється ваше серце за право на ВДОХ І ВИДИХ. Йому зовсім байдуже, чи синє у вас авто, чи жовте, чи спідничка брендова, чи ні. Ви надумали собі безліч обмежень та причин для гри в страждання, набудували догм і правил, вірувань та гонки-маршрути до цілей, забуваючи головне – ЖИТИИИИ… А це не про думати все підряд і бігати в пошуках відчуттів. ЖИТТЯ пробивається, коли ми перестаємо варитися в думках та бути залежними від емоцій й зовнішніх схвалень. ЖИТТЯ ми часто помічаємо якраз тоді, коли все згасло й замовкло, коли ми вимикаємо в собі усі радіо, усі «потрібно», усі «хочу». ЖИТТЯ таке, як воно є, екзистенціальне, а не те, що на екрані матриці, на екрані гри в страждання й боротьбу. Воно пробивається крізь бетон та не чекає сприятливих умов для БУТИ. Якщо ви досі вірите, що хтось чи щось вам заважає ЖИТИ й бути щасливими, то ви просто не зустріли іще свою власну Душу. Ви її не почули, не впізнали, не зрозуміли… От і все. А ЖИТИ прийшла саме ВОНА, сюди прийшла вона! І це її подіум, це її шанс… ВАШІ ДУШІ ПРАГНУТЬ ЖИТИ! У кожної є свій ПЛАН, але ж, який він далекий від тих сценаріїв его, що ви намалювали на високих парканах своїх ідентифікацій?! Не чекайте, доки припече чи настане сприятливий час для зустрічі й бесіди з СОБОЮ. Не чекайте мирних часів. Ініціюйте цю зустріч самі, станьте тими, хто бере відповідальність за своє ДИХАННЯ… МАЮ НАМІР: доки відчуваю зв’язок з цим світом і кожним імпульсом Творця – буду стукати у ваші серця та спонукати вас ЖИТИ ЖИВИМ ЖИТТЯМ… А воно те, яке ЗАРАЗ, і достойне низького поклону до землі, вдячності до небес… Бережіть свої Душі! Бо як не ви господарюєте в домі-тілі, то тоді ХТО??? Збільшуйте кількість життя в ЖИТТІ. Вибирайте його. Щомиті. Прошу вас! Запитуйте себе в простих речах на кожному кроці: «те, що я роблю зараз, це ЖИТТЯ?», «те, що я зараз п’ю, їм, думаю, кажу – це збільшує й покращує життя, чи вкорочує та погіршує його мені або довколишнім?»… Я ЧУЮ ВАШІ ДУШІ, І ВОНИ ХОЧУТЬ ЖИТИ… До зустрічі на душевних бесідах та практичних семінарах. «Все дуже й дуже просто», – Ірина ЗАВЕРУХА"]','Новини','Ірина Заверуха','3 січня 2024','3 хв читання','/images/posts/бізнес34-2048x1341-1.webp','[]',1,'2024-01-03T09:31:32','2024-01-03T09:31:32');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-200','%d0%ba%d0%be%d1%80%d0%be%d0%bd%d0%b0-%d0%b2%d1%96%d0%b4%d0%bf%d0%be%d0%b2%d1%96%','Корона відповідальності — прикраса жінки нового часу!','Єдина корона, яку ми достойні носити — це корона відповідальності за своє життя, за себе, і за все, що з нами відбувається! Гординя і гнів, якими ми часто себе прикрашаємо, мусять розчинитися. Залишиться сила та мудрість. Прийде відповідальність. Не ...','["Єдина корона, яку ми достойні носити — це корона відповідальності за своє життя, за себе, і за все, що з нами відбувається! Гординя і гнів, якими ми часто себе прикрашаємо, мусять розчинитися. Залишиться сила та мудрість. Прийде відповідальність. Не тікайте від себе, сміливо замінюйте старі налаштування й наповнюйтеся чистими енергіями, ресурсними, потоковими, богородичними. І що більше ми очищені, то більше енергії може ввійти. Тому очищайте свій простір, очищайте себе! І не тікайте від себе, любі жінки, беріть на себе відповідальність за своє життя, не чекайте когось чи чогось, а живіть уже зараз, створюйте баланс у собі! Впускайте в себе життя і ЖИВІТЬ! ♥️ Насолоджуйтеся і пам‘ятайте, що любов народжується у вашому серці! Бережіть себе з любов‘ю! © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','4 грудня 2022','3 хв читання','/images/posts/IMG_9387-scaled.jpg','[]',1,'2022-12-04T12:55:00','2022-12-04T12:55:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-213','%d0%b2%d0%b8%d0%bf%d1%80%d0%be%d0%b1%d1%83%d0%b2%d0%b0%d0%bd%d0%bd%d1%8f-%d0%bf%','Випробування приходять для духовного і ментального зміцнення!','Випробування приходять для нашого з вами духовного і ментального зміцнення, а не для паніки емоційної і знесилення тілесного… Ресурсність – наше все! Не зависай лише у «виживанні», підіймай голову до небес, … дякуй при цьому природі за щедрість… помі...','["Випробування приходять для нашого з вами духовного і ментального зміцнення, а не для паніки емоційної і знесилення тілесного… Ресурсність – наше все! Не зависай лише у «виживанні», підіймай голову до небес, … дякуй при цьому природі за щедрість… помічай Живе Життя, еволюціонуй в будь яких умовах. Душевну ресурсність черпай в творчості, моральну – в цінностях та спілкуванні з однодумцями, фізичну – в практиці тілесної дії, в служінні; … цілісну – в розвитку духовного інтелекту та спілкуванні з природою… «Перемагай на всіх фронтах! Прошу тебе, перемагай… Про волю й силу ти як білий птах, На висоті вітрів співай… Перемагай потоком щирих слів! Прошу тебе, перемагай… Не бійся тих, хто не зумів В душі своїй створити рай… Перемагай і лінь, і гнів, і злобу дня, Прошу тебе, перемагай… Іди вперед сміливо, навмання, Не падай в прірву болю – оживай… Перемагай свої ілюзії й ниття, Прошу тебе, перемагай… Плекай потоком вірності живе життя, І кожному зустрічному ти посмішку давай… Перемагай страхи сміливістю до дій, Прошу тебе, перемагай… За щастя тих, хто поряд порадій, А тим, хто проживає біль – поспівчувай. Перемагай свою гординю і печаль, Прошу тебе, перемагай… І навіть коли плаче серце і сльоза в очах, Ти знов від себе мужність вимагай. Перемагай на всіх фронтах! Прошу тебе, перемагай…» 17.09.2022 ©️ Ірина Заверуха Нескорені – разом ми Сила! © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','12 жовтня 2022','3 хв читання','/images/posts/358095877_235522099335057_7901617062961740807_n.jpg','[]',1,'2022-10-12T13:31:00','2022-10-12T13:31:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-218','%d1%89%d0%be-%d1%8f-%d0%b6%d0%b8%d0%b2%d1%83-%d0%b7%d0%b0%d1%80%d0%b0%d0%b7','Що я ЖИВУ зараз?','Я ЖИВУ! Ми Перемагаємо! … що я живу зараз? Поки веду семінар Хранителів Частот – і зцілюю, і на світанку йогу свідомості проводжу, і продовжую дистанційно онлайн марафон супроводжувати, де жінки з різних країн практикують вже 23 дні глибоку контактні...','["Я ЖИВУ! Ми Перемагаємо! … що я живу зараз? Поки веду семінар Хранителів Частот – і зцілюю, і на світанку йогу свідомості проводжу, і продовжую дистанційно онлайн марафон супроводжувати, де жінки з різних країн практикують вже 23 дні глибоку контактність зі своїм серцем через канал Богородиці; ділюсь знаннями, проводжу ініціації-посвяти; показую групі техніки роботи в місцях сили… безмежно тішусь успіхам команди безцінноі, що попри буремні часи – справляється з роботою… Щоб світло перемагало морок на Землі… щоб гниль ілюзій архівувалась і виходила істина на поверхню… щоб щасливішали люди і знали куди їм ЖИТИ! …Перли семінару? Та їх були сотні… Писатиму поступово,… що пригадається… «Душа Оживає через тіло пробуджене…» «Не розуміючи, що є «успіхом» чи «невдачею» в масштабі та проекції Душі, люди страждають довкола тих подій, які насправді є частиною базової еволюції свідомості…» «Ти принижуєш себе безсиллям, щоб мати підсвідоме гарантоване право на насилля десь інде…» …Кожного разу, коли веду ретрити і семінари, в мене є велике бажання розповідати про це в моменті, але як правило приходить настільки глибоке занурення в процес, що навіть сім’я моя не відволікає і чекає завершення, усі звикли і знають, що «потім», все «потім…», бо зараз іде віддача і служіння! Так і знову… Семінар пройшов на УРА… не зважаючи на довгу дорогу, на відсутність світла, зв’язку і різних побутових благ… група неймовірних Майстрів свого життя зустрілась в полі практики і Святкувала Таїнство Перемоги Знань над «обставинами»… – попрямували усі Хранителі до дому, розносити Золото ясності далі І я вам можу чітко сказати, що вони точно професіонали своєї справи… і тепер іще й пришвидшені і наповнені душевним ресурсом! Тож я радію і далі дію! Мій фронт – це мій труд! ТРИМАЙСЯ ЗА СВІТЛО ДУШІ! © Ірина Заверуха. Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','11 грудня 2022','3 хв читання','/images/posts/Seminar-KHraniteli-chastot.jpg','[]',1,'2022-12-11T13:57:00','2022-12-11T13:57:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-242','%d0%bc%d0%be%d1%8f-%d1%96%d1%81%d1%82%d0%be%d1%80%d1%96%d1%8f','Моя історія ✨','– То ж навіщо усе? – Хочу жити у найкращій версії цього Світу! Тому проявляю найщасливішу версію своєї долі… Вітаю вас, дорогий Гість, я дуже рада, що ми знайшли один до одного дорогу, а вірніше ПУТЬ..! Давайте знайомитися. Мене зовуть Заверуха Ірина...','["– То ж навіщо усе? – Хочу жити у найкращій версії цього Світу! Тому проявляю найщасливішу версію своєї долі… Вітаю вас, дорогий Гість, я дуже рада, що ми знайшли один до одного дорогу, а вірніше ПУТЬ..! Давайте знайомитися. Мене зовуть Заверуха Ірина. Нині також маю проявлене імʼя Душі - IMARIA і транслюю вібрацію свого духовного роду, я - інтуїт, сучасний енергоінформаційний цілитель, кармакоректор, еніопсихолог, астролог китайської метафізики (ба цзи, фен-шуй, цимень, вибору дат), ченнелер, духовний провідник, вчитель йоги свідомості і медитації, авторка, кохана і любляча дружина, і мама прекрасних дітей; засновниця платформи багатовимірного розвитку PIPL, громадська діячка, соціальний лідер країни, Берегиня …але все це скоріше ролі. Насправді – я є Дух, який пізнає життя через живонароджену втілену Душу. Запрошую і вас пізнати цю триєдність і вийти з ілюзії розділеності! Народилася я з даром до цілительства і яснобачення, які вдалося перетворити на благу діяльність та проявлену справу життя. Своєю творчістю і працею допомагаю людям знаходити вихід із різних ситуацій, набувати гармонії та цілісності, щастя та здоров''я, не зважаючи на обставини і події. Я навчаю хілерів і менторів жіночих, які разом зі мною пробуджують на Землі ген світочів, обʼєднають Хранителів Частот нейромережі нової реальності. Моя історія не має початку у вигляді особливої ​​дати, вона тягнеться з народження. З самого дитинства мене хвилювали питання саморозвитку, духовність і еволюція, я думала, що кожна людина прийшла на Землю не просто так, що зобов''язана знайти і зрозуміти своє місце в Світі. Слухала свою Душу і ніби чула розмови Душ довкола мене… Пізніше я зрозуміла, що це було буквально – я чую голос Душі будь чого! Зв''язок з Вищими силами був у мене завжди: контакти з Ангелами, взаємодія зі стихіями, космічність в і містичність; зв''язок із Землею – з енергією предків-цілителів, з духами лісу, з усім сущим; ... і найголовніше - почуття єдності з Абсолютом, з Творцем через злиття з його творіннями, пряма розмова з серцем Великої МА через свідомість людини Аватара Ірини. Ще дитиною я знала, що допомагатиму людям, у міру дорослішання змінювався лише спосіб, а мета «Жити і безумовно любити!» нікуди не поділася. Не розповідатиму багато, як пройшло моє дитинство, майже як у кожного в пострадянському просторі. Закінчила школу із золотою медаллю і, окрилена високою екосвідомою метою проявитися, - поїхала до Києва, щоб стати екологом. На той момент (в 1999 році) мені здавалося, що це найнадійніший спосіб досягти моєї мети. Але на першому курсі університету я зрозуміла, що займаюся боротьбою з наслідками, що якщо люди не змінять своє ставлення до життя, то жодна армія екологів Світ кращим не зробить! Я почала працювати у сфері екоосвіти з дітьми, зміни в яких давали надію на краще, щиро вірилося, що дитина з відповідальною життєвою позицією не зможе ніколи робити «боляче» іншим та самій собі. Так із екології простору я перейшла в вимір екології Душі. Працювала на високій посаді у Всеукраїнській Екологічній Лізі. Паралельно була студдеканом свого інституту. На четвертому курсі університету я вийшла заміж за людину близьку мені по духу. Я захоплювалася східною метафізикою, займалася йогою, а мій чоловік – айкідо. Перша громадська організація, створена моєю сім''єю у 2004 році, це був Клуб розвитку особистості «Каннагара», в якому діти та дорослі пізнавали ази східних єдиноборств та філософію балансу дао життя. Як істинна Жінка я присвятила багато років важливому прояву себе – сім''ї. Їхня підтримка і любов дозволили мені стати такою, якою я є зараз. Моя родина - моя потужна опора. Неможливо змінити світ на краще, не змінюючи себе. По суті, вся ілюзія неідеального світу існує всередині нашої системи доти, доки ми СЕБЕ не приведемо до гармонії, не полюбимо і не приймемо місію душі… Моя сім''я дуже допомогла мені в цьому – шліфуючи межі свого его стосунками, я навчилася робити маленькі кроки до великих цілей. Материнство щедро розкрило досі невидимі здібності, затвердило у правильності путі... путі інтуїції. На справді ви вже можете прочитати дуже багато моїх розповідей з опорою на особистий досвід в блозі, який є тут на сайті, а також в соцмережах. До видання готуються і книги, в яких зможете взяти для себе корисні інструменти для трансформації власної долі! Ну а зараз на регулярній основі я веду навчання для людей (в основному жінок), які готові вийти за межі ума і служити роду та часу як цілителі і провідники. У моєї платформи багатовимірного розвитку PIPL є флагманські програми, наприклад річна трансформаційна програма для жінок #КРИЛА - свобода бути собою! Є середовище росту і розвитку практиків - PIPL CLUB . Починає свою активну роботу IMARIA ACADEMIA , де я і мої учениці проводимо різні трансформаційні марафони. Метафізичному мистецтву фен-шуй і ба цзи, премудростям ці мен дун цзя та іншим напрямам східної філософії я навчалася після чіткого усвідомлення, що не нести людям ті імпульси, які через мене пропускають Вищі Сили, я просто не можу. Щоразу, коли робила спроби втекти від істинної себе – отримувала «по шапці» у вигляді хвороб, так мене «пробуджували» і спрямовували на істинний Шлях. У 2009 році я пройшла випробування на онкологічне захворювання, яке через роботу над собою благополучно перетворила на свій досвід і цінність, адже тепер ділюся ним з тими людьми, які ПОВІРИЛИ В ХВОРОБУ І ВТРАТИЛИ ЗВ''ЯЗОК З СОБОЮ. Немає невиліковних недугів, завжди з нами через тіло говорить Душа і просить змін, ефективних корекцій! Шлях із ілюзій став ясним і переріс у творчий Путь інтуїції! Коли з 2010 року я стала застосовувати та практикувати ба цзи та фен-шуй професійно, то просто була вражена легкості процесу та тому задоволенню від нього, яке народжувалося в мені. Результати і відгуки моїх клієнтів радували і надихали, хоча я й продовжувала зіштовхуватися і зі скептиками, і з глузуванням, і з нерозумінням. Щиро вдячна за ці стички, адже саме вони змушували мене йти далі, шукати причини та знаходити відповіді. Одного разу я прочитала книгу Майкла Роуча «Алмазна мудрість» і прийняла у своє життя Кармічний менеджмент. Це вкотре розширило мої горизонти. Слово \"Карма\" тоді вперше торкнулося мене глибоко і всередині щось зачепило. Мені завжди було важливо докопатися і знайти першопричину, тому я почала вивчати ази кармічного цілительства. Так до астрологічної аналітики додалася і кармічна діагностика як інструменти з долею людини. Мій шлях діагноста та цілителя продовжував йти паралельною дорогою з розвитком здібностей. За останні 20 років життя я багато чого пізнала, прожила, подолала, відвідала безліч тренінгів та семінарів в майже десятку духовних традицій, здобула кілька освіт, але найголовніше – накопичила досвід та глибокі знання, а не просто інформацію, якими зі мною щедро ділилися справжні Вчителі живі і Вишні. Низький уклін кожному з них: Кислій Любові Василівні, земля вам пухом; Лідії Янковській, Інні Волковій, Наталі Ладіні, Керол Салтер, Альберту Ігнатенку, Майклу Роучу, і цілому сангату Вчителів Золотої Мережі традиції Кундаліні йоги … усім усім, хто мені допомагав та підтримував! Після проведення чистки своїх родових каналів та підвищення рівня вібрацій свого поля через практики, я відчула неймовірну силу Безумовного Світла Творця-Батька та Безумовної Любові Матері ВсеСвіту, які почали струмувати через мене, протікати потоком… Вищі Вчителі з інших цивілізацій стали виходити на контакт частіше, передаючи інформацію і в медитаціях, і в усвідомлених сновидіннях, і навіть у свідомих моментах, будучи в місцях сили, які я відвідувала. Під час війни в Україні, я прожила активну фазу переходу в статус Берегині Землі, здібності підсилилися і активувалися нові спектри дарів. Я не покинула Україну, підтримуючи баланс практикою, зцілюючи людей, пропускаючи крізь серце величезну кількість болю та пошматованих душ… На сьогоднішній день я смілива на максимум і проявлена. Реалізовую програми, цілительні сатсанги, консультую, пишу послання, вірші, книги, медитації, веду блоги, виступаю з семінарами та майстер-класами, розвиваю команди і проекти, приділяю увагу благодійності та творчості, спрямованій на пробудження людей і розвиток зрілої цивілізації. Ласкаво просимо до спільноти Світочів, якщо вас зацікавило щось із описаного вище! Далі проявляю для вас трохи сухої статистики: З 2015 по 2019 рік - співорганізатор Фестивалю «Життя як Чудо» 2016 - засновниця Школи творчості та духовного розвитку «Путь Інтуїції» З 2017 по 2020 - автор рубрик і публікацій в медіа проектах «VIVA», WomanMagazine, Єдина… тощо… 2018 - Президент ГО «Aurum Soul Club», Дама Ордену Королеви Анни «Честь Вітчизни», Член Правління Всесвітньої Ліги Космогуманістів, створила соціальний простір саморозвитку для людей. Провела за рік - 3 жіночих фестивалі; Національний форум «Золото Материнства», фестиваль «Сімейні цінності і родові традиції»; підтримала увагою понад 10 соціальних і культурних проектів як співорганізатор; випустила 43 учениці з чотирьох потоків навчання… 2019 - ченелер світу IMARIA MASTER 2020 рік - заснувала Проект #Pipl - платформа багатовимірного розвитку З 2021 і по сей день - Просвітитель. З 2021 - Сертифікований Вчитель Вищої Йоги свідомості. 2021 рік - Дама ордену «Лідер України». Заснувала трансформаційну жіночу програму #КРИЛА . Почала готувати професійних Менторів і хілерів для світу. З 2022 року - Берегиня України. Провела понад 1300 благодійних консультацій для людей рідної держави з різними запитами. Не покидала територію України з 2022 по 2024 роки. Провела за два роки 26 виїзних заходів в Україні (ретритів і семінарів навчальних, планетарних практикумів) не зважаючи на умови і обставини блекаутів. 2023 рік - Вища суспільна нагорода орден «Святої Софії» за вклад в розвиток людей нації та цілісне холістичне здоровʼя. 2023 - увійшла в ТОП100 незламних Українців за результатами професійної діяльності. … І ось я тут… Пишу для вас. І будую нові творчі плани розвитку. Продовжую консультувати людей як особисто, так і дистанційно. Під час консультацій окремих людей – дотримуюся принципу “все індивідуально”, переглядаю людину і на рівні астрології, і на рівні кармічної матриці, і на рівні поля душі. Я просто щаслива, що можу допомагати іншим ставати кращими, здоровішими, успішнішими, впевненішими в собі, знаходити цілі і рухатися до них, рости духовно і проявлятися із богореалізованої свідомості. Я і сама йду таким же шляхом без зупинки, постійно розвиваючись. Золотий Вік Творця вже на порозі, Ера Жінки, епоха Великої МА прийшла, друзі! Ми з вами живемо в унікальні часи, друзі, і здатні розкрити на повну потужність свій дар душі і потенціал. До зустрічі! 🙏 © Ірина Заверуха, 2026 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','5 січня 2024','8 хв читання','/images/posts/IMG_9631-scaled.jpg','[]',1,'2024-01-05T22:33:35','2024-01-05T22:33:35');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-393','%d1%8f-%d0%b3%d0%be%d1%82%d1%83%d0%b2%d0%b0%d0%bb%d0%b0-%d1%81%d0%b2%d0%be%d1%94','Я готувала своє серце роками…','Я готувала своє серце роками… Я готувала його щодня і щохвилини, з тієї миті, як дізналась, усвідомила і відчула, що це таке насправді БУТИ ЖІНКОЮ-МАЙСТРОМ. Я готувала своє серце через працю і душі і его, через творчість, через навчання і діяння, чер...','["Я готувала своє серце роками… Я готувала його щодня і щохвилини, з тієї миті, як дізналась, усвідомила і відчула, що це таке насправді БУТИ ЖІНКОЮ-МАЙСТРОМ. Я готувала своє серце через працю і душі і его, через творчість, через навчання і діяння, через турботу про людей, про Живе Життя, готувала його до глибокої мудрості, до свободи видихати не лише використані гази, але й щасливих ДІТЕЙ і відпускати їх у небо вирієм, бо кожна вільна #душа туди прагне – у свободу Живого Життя… Я готувала своє #серце щоб довіряти, любити і при цьому нікого не тримати, не силувати правилами… і картинками про ідеальність, готувала себе так безумовно любити, щоб нічого собі не присвоїти… але усе мати, усе шанувати і плекати до останього подиху і тіло, і дім, і світ поза ним… У мене є і донька, і син, і безліч діток по світу, яких «серцем народила», хресною мамою стала для них не по назві, а по суті… Я знаю як тяжко зараз дівчатам, сестрам, матерям, донькам України живеться… З практики знаю. Бо усе відчуваю і буквально проживаю на землі рідній… Я знаю, що це таке імміграція, бо є дитиною батьків, які колись давно, понад 20 років тому виїзжали з України в пошуках ресурсів і порятунку… і залишились далеко… Все мені відомо не з теорії. Я знаю, що там за лаштунками красивих лозунгів про «добре там, де нас немає»… І тим, хто тут, в межах держави зараз з нами, і тим, кого сила закинула на інші береги реальності… Болить усім по-своєму… Моє Серце Берегині Землі плаче за кожним, хто на орбіту його попадав і попадає… І саме завдяки усьому цьому, що є і в мене і син… і донька, і діти-квіти, і душі споріднені, і цілі сім’ї, родини, і усі такі неповторні… з унікальними історіями життя… і учениці, і клієнти з понад 20 країн, і досвід, і практика… – маю зараз ГОТОВНІСТЬ пропускати потоки добра не лише як Голос Душі цілющими словами, але й як Факел Серця – світлими сильними потужними ділами… Хто іще не з нами? Знайомтесь тут https://taplink.cc/zaverukhairyna Долучайтесь! https://t.me/ZaverukhaIrina Приєднуйтесь і в щось включайтесь… Бо ніколи вже по-старому в темряві мороку сидіти – пора нам з вами світити і щасливіти… Мій фронт – це мій труд! Ваша Заверуха Ірина © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','10 грудня 2022','3 хв читання','/images/posts/YA-gotuvala-sebe-rokami-Zaverukha-Irina.jpg','[]',1,'2022-12-10T15:52:00','2022-12-10T15:52:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-399','%d0%bf%d1%80%d0%be-%d1%85%d0%b0%d1%80%d0%b0%d0%ba%d1%82%d0%b5%d1%80-%d0%b2-%d0%b','Про характер в енергіях дня','PRO характер в енергіях дня Кредо: «Не формуєш його? – то й не маєш його!» Я вважаю, що немає нічого красивішого в людині, ніж проявлений ХАРАКТЕР… Так! Переконана в цьому на практиці життя. Бо ті, у кого є воля виховувати із себе найщасливішу версію...','["PRO характер в енергіях дня Кредо: «Не формуєш його? – то й не маєш його!» Я вважаю, що немає нічого красивішого в людині, ніж проявлений ХАРАКТЕР… Так! Переконана в цьому на практиці життя. Бо ті, у кого є воля виховувати із себе найщасливішу версію себе – однозначно менше мають проблем, хвороб, криз, конфліктів і дефіцитів ресурсу… живуть в гармонії і транслюють внутрішню і зовнішню красу… Тож. Діємо, не покладаючи рук, АСУ Ангельскі Сили України… бо це теж фронт світла в боротьбі з мороком… Вчора провела все ж таки прямий ефір в спілкуванні з людьми. Як змогла. Без світла. На мобільному інеті. ПОСИЛАННЯ на ефір залишаю тут Хто був на ефірі - залиште свій слід під постом теж. Говорили про ПРОЖИТЕ нами з вами нещодавно; прогнози давала на грудень… поради (і персональні теж…) Розказувала про «куди несе далі» цей світ, і як знайти весла від лодки ефективного сценарію долі… То ж, рідні, з характером нашим з вами все Ок – і вихованні, і невгамовні, і культурні ми, і терплячі, і наполегливі українці… люди, народженні Україною (бо зараз наш дух розпорошено по світу, і дає він різним куточкам планети новий росток Сили…) … Дію! УВАГА! СКОРО! Прозвучить гучний анонс про запуск нашого флагмана PiplClub Усі, хто є частиною простору IMaRia & pipl матимуть пріоритетні бонуси на вступ до КЛУБУ, бо на перші місяців участі в ньому ми беремо не усіх, а лише тих, хто готовий до масштабування, процвітання та взлету ! Бо ці сім місяців я ПЕРСОНАЛЬНО вестиму практики живі по очищенню важких родових карм; даватиму сакральні знання про фундаментальне і супроводжуватиму людей до результатів, бо всію, знаю як і хочу… Тому спішіть бути в рядах АМБАСАДОРІВ! © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','7 грудня 2022','3 хв читання','/images/posts/Angelski-sili-Ukraini.jpg','[]',1,'2022-12-07T15:58:00','2022-12-07T15:58:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-404','%d0%b4%d0%be-%d1%87%d0%be%d0%b3%d0%be-%d0%b7%d0%b0%d1%80%d0%b0%d0%b7-%d1%81%d0%b','До чого зараз спонукає нас час і простір?','Я працюю щоденно з запитами людей різних характерів: від допоможіть знайти загиблих, переконатися, що живі… питаннях по хворобах, фінансах, стосунках, дітонародження… до відповідей про призначення Душі, місії, самореалізації. І так складається, що в ...','["Я працюю щоденно з запитами людей різних характерів: від допоможіть знайти загиблих, переконатися, що живі… питаннях по хворобах, фінансах, стосунках, дітонародження… до відповідей про призначення Душі, місії, самореалізації. І так складається, що в основному по запитах приходять люди, які в резонансі з простором. 🔸 То, до чого ж спонукає зараз нас час і простір? 🔸 Чому відбуваються так багато миттєвих смертей у тилу на фоні війни? 🔸 Які задачі постають перед особистістю від яких вже не відвернутися? Дивіться в цьому прямому відео https://www.youtube.com/watch?v=QbGX2mqAd9s ❓Які дії рекомендую? 1️⃣ Подивитися відео про листопад і процеси цього місяця, бо макрокосмічно листопад триватиме ще до 8 грудня 👉 https://youtu.be/L94p6trik5I 2️⃣ Працювати через тіло зі своєю свідомістю з темами зцілення від залежностей, зі страхами перед змінами та майбутнім. Комплекси у запису 💚 Розкриття серця та наповнення енергією (російською мовою) 👉 https://www.youtube.com/watch?v=1f8J-QyyhNc 💚 Дай силу своєму серцю (українською мовою) 👉 https://youtu.be/c9mQ-S1ua6M © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','1 грудня 2022','3 хв читання','/images/posts/Do-chogo-nas-sponukaie-prostir.jpeg','[]',1,'2022-12-01T16:10:00','2022-12-01T16:10:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-412','%d0%b4%d0%b5%d0%bd%d1%8c-%d0%b3%d1%96%d0%b4%d0%bd%d0%be%d1%81%d1%82%d1%96-%d1%82','День Гідності та Свободи','Чи це співпадіння, що День Гідності і Свободи в Україні святкується 21 листопада? Ні. Бо саме Архангел Михаїл і є тим, хто бореться з неГідниками мультиВсесвіту; з мразями, що чіпляються за владу над людьми, як за рятівний резиновий кораблик, і корча...','["Чи це співпадіння, що День Гідності і Свободи в Україні святкується 21 листопада? Ні. Бо саме Архангел Михаїл і є тим, хто бореться з неГідниками мультиВсесвіту; з мразями, що чіпляються за владу над людьми, як за рятівний резиновий кораблик, і корчать із себе вершителів доль. Але він ніколи не витримає шторму Часів Істини, бо брехня – це занадто тяжкий вантаж, він веде на дно. Лише відпустивши із липких рук владу, що не є від Бога, – а від его і сліпоти ілюзій, – душа людини здатна вирватися у вирій чистоти. То ж усім неГідникам тонути в потопі сліз Матері Землі начертано. І буде так. Бо так створено. Бо саме це і є баланс Живого Життя… Але давайте розбиратися! Чи завжди безумовна любов і світло, істина і свобода – це про ніжні танці дельфінів і трелі канарейок з дзвіночками та квіточками в руках? Ні. Бо бути в Добрі та Щасті, це рівнозначно бути в союзі Духу та Душі, в цілісності Сили, що веде до еволюції пробуджену свідомість, а не оте добреньке его, засліплене мислеформами про «я собі хочу, бо можу». Через серця достойних Людей шліфують свої мечі і щити Архангели! Тож треба ДУМАТИ вміти як гідні і достойні…☝️ З днем Гідності і Свободи, Воїни Світла, Воїни Добра! Маємо далі зупиняти навалу мороку і пам’ятати про свою Суть. Бо люблячі живуть в одному спільному світі, а кожне спляче его – у своєму окремому… 🙏🌏🕊😘💓 Окриляйте себе практикою віри і дії щодня. Не дозволяйте своєму его засліпити вас гординею через неприйняття інаковості та розділення на «кращих» і «гірших». Насправді усе не таке, яким здається. Ми різні, але ми разом!💞 Ворог і морок – це ті ілюзорні печалі, в які ми віримо і накопичили їх своїми вчинками, думками і брехнею слова. Ніхто і ніщо не зупинить потоку Живого Життя… і немає назад вороття! Тільки вперед… Велика Ма і воїнство гідне знищить усю павутину ілюзії. Усю! Маємо віднайти путь серця і прийти до Безумовної Любові в Свободі бути… 🌀 Як краще провести цей день? 💫 У відповідальності за свою Силу Пристрасті, яка вами направлена на творення, а не на деградацію. Наприклад. Фізично сильним людям важливо мати зони застосування свого потенціалу. Займатися господарством, працею тілесною, спортивними навантаженнями, що шліфують дух. Емоційно сильним важливо вміти не маніпулювати своїми станами, не насилувати оточення емоціями, а реалізовуватись через арт і мистецьку діяльність. Ментально сильним важливо свій інтелект направляти на нові винаходи, на адміністрування, на проектну діяльність, на навчання інших. Соціально сильним і добрим важливо не бути добренькими, жертва і тєрпілами, які замість усіх все роблять, а самі голодні і невиспані…; важливо гуртуватися довкола цінностей і популяризувати родинні та сімейні традиції, братися за руки, маючи щасливі причини, а не лише для революцій. Духовно сильним і вольовим важливо брати на себе відповідальність за інших, контролювати, створювати спільноти, долучатися до сфер служіння спільноБлагу Вишнього. Мудрим і Потоковим, інтуїтивно сильним важливо ділитися своєю енергією, інформацією, ЯсноБаченням і провідністю заради еволюції Єдиного простору Життя, не втікати від матеріальності, а сакралізувати побут, жити життя як найвеличнішу церемонію… 🙏Усвідом свою роль в цьому світі і прояви свою Пристрасть Душі… Не можеш ясно зрозуміти своє призначення і місію? Приходь за порадами. Я і мої учениці Спеціалісти проекту pipl, завжди готові дати підказки.🙏 🔘День сьогодні веде до Рівноваги Сил Пристрасті на Землі! А керує порядком Легіон Архангелів. © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','21 листопада 2022','3 хв читання','/images/posts/День-Гідності-та-Свободи.jpg','[]',1,'2022-11-21T16:21:00','2022-11-21T16:21:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-575','my-history','My history','– So why all this? – I want to live in the best version of this world! Therefore, I manifest the happiest version of my destiny… I congratulate you, dear Guest, I am very glad that we found a way to each other, or rather a WAY..! Давайте знайомитися....','["– So why all this? – I want to live in the best version of this world! Therefore, I manifest the happiest version of my destiny… I congratulate you, dear Guest, I am very glad that we found a way to each other, or rather a WAY..! Давайте знайомитися. Мене зовуть Заверуха Ірина. Нині також маю проявлене імʼя Душі - IMARIA і транслюю вібрацію свого духовного роду, я - інтуїт, сучасний енергоінформаційний цілитель, кармакоректор, еніопсихолог, астролог китайської метафізики (ба цзи, фен-шуй, цимень, вибору дат), ченнелер, духовний провідник, вчитель йоги свідомості і медитації, авторка, кохана і любляча дружина, і мама прекрасних дітей; засновниця платформи багатовимірного розвитку PIPL, громадська діячка, соціальний лідер країни, Берегиня …але все це скоріше ролі. Насправді – я є Дух, який пізнає життя через живонароджену втілену Душу. Запрошую і вас пізнати цю триєдність і вийти з ілюзії розділеності! Народилася я з даром до цілительства і яснобачення, які вдалося перетворити на благу діяльність та проявлену справу життя. Своєю творчістю і працею допомагаю людям знаходити вихід із різних ситуацій, набувати гармонії та цілісності, щастя та здоров''я, не зважаючи на обставини і події. Я навчаю хілерів і менторів жіночих, які разом зі мною пробуджують на Землі ген світочів, обʼєднають Хранителів Частот нейромережі нової реальності. Моя історія не має початку у вигляді особливої ​​дати, вона тягнеться з народження. З самого дитинства мене хвилювали питання саморозвитку, духовність і еволюція, я думала, що кожна людина прийшла на Землю не просто так, що зобов''язана знайти і зрозуміти своє місце в Світі. Слухала свою Душу і ніби чула розмови Душ довкола мене… Пізніше я зрозуміла, що це було буквально – я чую голос Душі будь чого! Зв''язок з Вищими силами був у мене завжди: контакти з Ангелами, взаємодія зі стихіями, космічність в і містичність; зв''язок із Землею – з енергією предків-цілителів, з духами лісу, з усім сущим; ... і найголовніше - почуття єдності з Абсолютом, з Творцем через злиття з його творіннями, пряма розмова з серцем Великої МА через свідомість людини Аватара Ірини. Ще дитиною я знала, що допомагатиму людям, у міру дорослішання змінювався лише спосіб, а мета «Жити і безумовно любити!» нікуди не поділася. Не розповідатиму багато, як пройшло моє дитинство, майже як у кожного в пострадянському просторі. Закінчила школу із золотою медаллю і, окрилена високою екосвідомою метою проявитися, - поїхала до Києва, щоб стати екологом. На той момент (в 1999 році) мені здавалося, що це найнадійніший спосіб досягти моєї мети. Але на першому курсі університету я зрозуміла, що займаюся боротьбою з наслідками, що якщо люди не змінять своє ставлення до життя, то жодна армія екологів Світ кращим не зробить! Я почала працювати у сфері екоосвіти з дітьми, зміни в яких давали надію на краще, щиро вірилося, що дитина з відповідальною життєвою позицією не зможе ніколи робити «боляче» іншим та самій собі. Так із екології простору я перейшла в вимір екології Душі. Працювала на високій посаді у Всеукраїнській Екологічній Лізі. Паралельно була студдеканом свого інституту. На четвертому курсі університету я вийшла заміж за людину близьку мені по духу. Я захоплювалася східною метафізикою, займалася йогою, а мій чоловік – айкідо. Перша громадська організація, створена моєю сім''єю у 2004 році, це був Клуб розвитку особистості «Каннагара», в якому діти та дорослі пізнавали ази східних єдиноборств та філософію балансу дао життя. Як істинна Жінка я присвятила багато років важливому прояву себе – сім''ї. Їхня підтримка і любов дозволили мені стати такою, якою я є зараз. Моя родина - моя потужна опора. Неможливо змінити світ на краще, не змінюючи себе. По суті, вся ілюзія неідеального світу існує всередині нашої системи доти, доки ми СЕБЕ не приведемо до гармонії, не полюбимо і не приймемо місію душі… Моя сім''я дуже допомогла мені в цьому – шліфуючи межі свого его стосунками, я навчилася робити маленькі кроки до великих цілей. Материнство щедро розкрило досі невидимі здібності, затвердило у правильності путі... путі інтуїції. На справді ви вже можете прочитати дуже багато моїх розповідей з опорою на особистий досвід в блозі, який є тут на сайті, а також в соцмережах. До видання готуються і книги, в яких зможете взяти для себе корисні інструменти для трансформації власної долі! Ну а зараз на регулярній основі я веду навчання для людей (в основному жінок), які готові вийти за межі ума і служити роду та часу як цілителі і провідники. У моєї платформи багатовимірного розвитку PIPL є флагманські програми, наприклад річна трансформаційна програма для жінок #КРИЛА - свобода бути собою! Є середовище росту і розвитку практиків - PIPL CLUB . Починає свою активну роботу IMARIA ACADEMIA , де я і мої учениці проводимо різні трансформаційні марафони. Метафізичному мистецтву фен-шуй і ба цзи, премудростям ці мен дун цзя та іншим напрямам східної філософії я навчалася після чіткого усвідомлення, що не нести людям ті імпульси, які через мене пропускають Вищі Сили, я просто не можу. Щоразу, коли робила спроби втекти від істинної себе – отримувала «по шапці» у вигляді хвороб, так мене «пробуджували» і спрямовували на істинний Шлях. У 2009 році я пройшла випробування на онкологічне захворювання, яке через роботу над собою благополучно перетворила на свій досвід і цінність, адже тепер ділюся ним з тими людьми, які ПОВІРИЛИ В ХВОРОБУ І ВТРАТИЛИ ЗВ''ЯЗОК З СОБОЮ. Немає невиліковних недугів, завжди з нами через тіло говорить Душа і просить змін, ефективних корекцій! Шлях із ілюзій став ясним і переріс у творчий Путь інтуїції! Коли з 2010 року я стала застосовувати та практикувати ба цзи та фен-шуй професійно, то просто була вражена легкості процесу та тому задоволенню від нього, яке народжувалося в мені. Результати і відгуки моїх клієнтів радували і надихали, хоча я й продовжувала зіштовхуватися і зі скептиками, і з глузуванням, і з нерозумінням. Щиро вдячна за ці стички, адже саме вони змушували мене йти далі, шукати причини та знаходити відповіді. Одного разу я прочитала книгу Майкла Роуча «Алмазна мудрість» і прийняла у своє життя Кармічний менеджмент. Це вкотре розширило мої горизонти. Слово \"Карма\" тоді вперше торкнулося мене глибоко і всередині щось зачепило. Мені завжди було важливо докопатися і знайти першопричину, тому я почала вивчати ази кармічного цілительства. Так до астрологічної аналітики додалася і кармічна діагностика як інструменти з долею людини. Мій шлях діагноста та цілителя продовжував йти паралельною дорогою з розвитком здібностей. За останні 20 років життя я багато чого пізнала, прожила, подолала, відвідала безліч тренінгів та семінарів в майже десятку духовних традицій, здобула кілька освіт, але найголовніше – накопичила досвід та глибокі знання, а не просто інформацію, якими зі мною щедро ділилися справжні Вчителі живі і Вишні. Низький уклін кожному з них: Кислій Любові Василівні, земля вам пухом; Лідії Янковській, Інні Волковій, Наталі Ладіні, Керол Салтер, Альберту Ігнатенку, Майклу Роучу, і цілому сангату Вчителів Золотої Мережі традиції Кундаліні йоги … усім усім, хто мені допомагав та підтримував! Після проведення чистки своїх родових каналів та підвищення рівня вібрацій свого поля через практики, я відчула неймовірну силу Безумовного Світла Творця-Батька та Безумовної Любові Матері ВсеСвіту, які почали струмувати через мене, протікати потоком… Вищі Вчителі з інших цивілізацій стали виходити на контакт частіше, передаючи інформацію і в медитаціях, і в усвідомлених сновидіннях, і навіть у свідомих моментах, будучи в місцях сили, які я відвідувала. Під час війни в Україні, я прожила активну фазу переходу в статус Берегині Землі, здібності підсилилися і активувалися нові спектри дарів. Я не покинула Україну, підтримуючи баланс практикою, зцілюючи людей, пропускаючи крізь серце величезну кількість болю та пошматованих душ… На сьогоднішній день я смілива на максимум і проявлена. Реалізовую програми, цілительні сатсанги, консультую, пишу послання, вірші, книги, медитації, веду блоги, виступаю з семінарами та майстер-класами, розвиваю команди і проекти, приділяю увагу благодійності та творчості, спрямованій на пробудження людей і розвиток зрілої цивілізації. Ласкаво просимо до спільноти Світочів, якщо вас зацікавило щось із описаного вище! Далі проявляю для вас трохи сухої статистики: З 2015 по 2019 рік - співорганізатор Фестивалю «Життя як Чудо» 2016 - засновниця Школи творчості та духовного розвитку «Путь Інтуїції» З 2017 по 2020 - автор рубрик і публікацій в медіа проектах «VIVA», WomanMagazine, Єдина… тощо… 2018 - Президент ГО «Aurum Soul Club», Дама Ордену Королеви Анни «Честь Вітчизни», Член Правління Всесвітньої Ліги Космогуманістів, створила соціальний простір саморозвитку для людей. Провела за рік - 3 жіночих фестивалі; Національний форум «Золото Материнства», фестиваль «Сімейні цінності і родові традиції»; підтримала увагою понад 10 соціальних і культурних проектів як співорганізатор; випустила 43 учениці з чотирьох потоків навчання… 2019 - ченелер світу. IMARIA MASTER 2020 рік - заснувала Проект #Pipl - платформа багатовимірного розвитку З 2021 і по сей день - Просвітитель. З 2021 - Сертифікований Вчитель Вищої Йоги свідомості. 2021 рік - Дама ордену «Лідер України». Заснувала трансформаційну жіночу програму #КРИЛА . Почала готувати професійних Менторів і хілерів для світу. З 2022 року - Берегиня України. Провела понад 1300 благодійних консультацій для людей рідної держави з різними запитами. Не покидала територію України з 2022 по 2024 роки. Провела за два роки 26 виїзних заходів в Україні (ретритів і семінарів навчальних, планетарних практикумів) не зважаючи на умови і обставини блекаутів. 2023 рік - Вища суспільна нагорода орден «Святої Софії» за вклад в розвиток людей нації та цілісне холістичне здоровʼя. 2023 - увійшла в #ТОП100 незламних Українців за результатами професійної діяльності. … І ось я тут… Пишу для вас. І будую нові творчі плани розвитку. Продовжую консультувати людей як особисто, так і дистанційно. Під час консультацій окремих людей – дотримуюся принципу “все індивідуально”, переглядаю людину і на рівні астрології, і на рівні кармічної матриці, і на рівні поля душі. Я просто щаслива, що можу допомагати іншим ставати кращими, здоровішими, успішнішими, впевненішими в собі, знаходити цілі і рухатися до них, рости духовно і проявлятися із богореалізованої свідомості. Я і сама йду таким же шляхом без зупинки, постійно розвиваючись. Золотий Вік Творця вже на порозі, Ера Жінки, епоха Великої МА прийшла, друзі! Ми з вами живемо в унікальні часи, друзі, і здатні розкрити на повну потужність свій дар душі і потенціал. До зустрічі! 🙏 © Iryna Zaverukha. All materials on this site are copyrighted. Copying and distribution of materials is possible only with the prior consent of the author and indication of an active link to this site"]','Блог','Ірина Заверуха','23 січня 2024','8 хв читання','/images/posts/1.jpg','[]',1,'2024-01-23T19:09:59','2024-01-23T19:09:59');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-586','how-imaria-was-born','How IMaRia was born','At one time, it seemed to me that I would not be able to cope… that I would be terribly unable to cope and would not be able to withstand the stress… The power of this tension was so great that I doubted the truth of the path. The struggle between We...','["At one time, it seemed to me that I would not be able to cope… that I would be terribly unable to cope and would not be able to withstand the stress… The power of this tension was so great that I doubted the truth of the path. The struggle between Western rationalistic materialism and Eastern spiritual-meditative principle was going on inside me, like ice and flame, sometimes melting and then burning with the boiling water of anger and sparks from the collision. Я втомилася. Сильно. Так сильно втомилася і від людей, і від сім’ї, і від усієї цієї канителі з напругою життя, що грань здавалася піковою та нестерпною. Осінь насувалася на Землю, а на мене це цунамі. І я вирішила. Якщо дикі стихії буяють усередині і не вистачає якихось пазлів для їх стикування, значить, треба поринути в дику стихію, піти назустріч всьому цьому. Я поїхала в Карпати. Сама. Влаштувала собі мовчазний одиночний Ретрит. Жила в будиночку у товариша, на узліссі. Була надія знайти опору. Я робила йогу. Мало їла. Пила джерельну воду. Медитувала прямо на річці. Тобто сідала на містку, який через річку гірську, і медитувала на цей бурхливий потік, сподіваючись на очищення моєї свідомості. Я не розмовляла. Мовчала. І лише писала свої думки та обмінювалася ними з місцевими котами телепатично. Ходила на масаж, парила свої кістки в чані трав’яному. Загалом робила все, що могла. Але лід та полум’я всередині так і не з’єднувалися. І ось одного дня я вирішила піти ще далі і з’єднатися з природою ще глибше. Я встала о 4-й ранку, взула гумові чоботи, взяла з собою тільки воду в рюкзак за спиною і пішла в гори. Я брела навмання через нічне сонне село. Навколо нікого. Дикий ліс. Крокувала вгору. Поки на піку не зустріла сонце і світанковий тріумф третіх півнів. Немає таких слів, щоб передати почуття, які бурхливим потоком переповнювали мене тоді, по щоках текли сльози, все втратило сенс, ніби це був перший світанок у моєму житті і я щойно народилася. Мокра осіння земля дихала холодом і вогкістю. Туманний серпанок накривав долину і осідав унизу, але сонце наполегливо піднімалося вище і висвічувало небеса. А я стояла та дивилася. Пішла далі. По хребту безлюдних гір, що заросли лісом. Вдалині з’явився табун диких коней. Вони галопом мчали горами з такою силою Свободи, що я мимоволі розплакалася, сльози самі по собі бризнули з очей і вирвався дикий крик агонії зсередини найглибшого днища в мені. Із табуна коней один зупинився. Він глянув у мій бік і почав галопом бігти прямо на мене. Метрів 800-900 розділяли нас, і я в ступорі дивилася на цей біг, не відчуваючи нічого. Жеребець прискакав і різко зупинився перед моїм обличчям, опустивши голову з ніздрями, які випускали потужний пар. І ось тепер мене накрив шок від побаченого та усвідомленого. Він реально схилився до моїх ніг, дозволяючи себе гладити. Прекраснішого способу поговорити зі мною про самоцінність і не вигадаєш. Я плакала і від шоку, і від захоплення. Ішла далі. Якийсь час жеребець тупотів поряд. Потім він поскакав у Даль, з якої і з’явився. Тоді я ще не знала, що одного разу зустріну його знову. Що він знову прискаче галопом, але я буду тут не одна і допоможу своєму синові погладити його голову і не боятися дикої Сили природи. Я йшла далі… Не хотілося нічого аналізувати. Просто рух. Цілі не було. Найчистіша пригода без сенсу. Сонце вже піднялося досить високо. Погода була чудовою. Нагулявшись на гребені висоти, я почала спуск вниз у долину. Перейшла річку вбрід. Благо гумові чоботи були високими, а річка – не глибокою. Зате зустріла… Т И Ш У такої глибини, що не передати. Втомилася. Відверто кажучи, сильно втомилася. Спиною пригорнулася до дерева, заплющила очі, глибоко вдихнула і нааааааа видиху… провалилася в такууууууу безодню, що не описати. Моє тіло одночасно пронизалося мільярдами вихорів та потоків. Я відчула в кожній клітинці В И Б У Х, схожий на екстаз на рівному місці… Скрізь, де тільки можна було, виступив піт. Внутрішній жар викликав задишку, обличчя горіло вогнем дикої Сили… я не розуміла, що зі мною відбувається, і ніби задихалася сама собою. В очах все змішалося. Я розплющувала їх. Заплющувала. Але начебто це не працювало. Я бачила не ними. Вони перестали бути потрібними. Я зробила глибокий вдих і видих, і вибух повторився знову. Ще потужніший. Ще глибше пронизуючи мене струмом наскрізь. Це був дикий секс між небом та землею. Я зрозуміла, що всю мене пронизує оргазм. Таааак!!!! На рівні фізичного тіла це було схоже на оргазм. Але не в області геніталій, а СКРІЗЬ!! Скрізь у мені, і поза мною відбувалося ЖИТТЯ, Синергія, перетікання, вибух за вибухом… Моя матка та моє серце стали схожими на котел. Я відчула всередині величезну Силу початку творення. Це не передати словами. Це ні з чим не порівняти. Я дивилася на світ і не дивилася. Я була і мене не було. Я почувала себе Собою і я почувала себе всім: і деревом, і землею, і повітрям, і вітром, і водою, і мохом, і сонцем, і лісом, і всім, і нічим. Потім на мить мені здалося, що я вмираю. І вмиранню дала місце. Просто стікала вниз, сповзла, впала на сиру мокру землю. Агонія злиття всього з усім тривала… Такої насолоди від величі тотальної присутності та відсутності одночасно я не відчувала ніколи до цього і більше ніколи після цього. Я пізнала Любов і Силу, розчинившись у цьому потоці сексу Неба та Землі, і ніби в одну мить все ДІЗНАЛАСЯ. У голові з’явилися різні знання. Вони самі по собі начебто вибухали миттєво, різні архіви відкривалися і розкривалися розумінням. Начебто в мене вбудували мільйон енциклопедій і дали доступ до всіх мов Всесвіту. Я намагалася думати, але не могла. Не було того, що зазвичай думає. Уся реальність була реальною. Я з’являлася в якихось інших місцях, як спостерігач, що заглядає у вікно: в інших світах, тілах, просторах… Це відбувалося миттєво, дуже швидко, блискавично, миготіли іскри світла, і не було світу форм… Ніколи я не курила ніякої трави, не жувала грибів, не пила ніяких бовтанок, ніяких дослідів під впливом наркотичних речовин у мене не було, я прожила до цього і після цього чисту реальність, розширюючись як свідомість лише практикою медитації і моїм ЖИТТЯМ через усвідомленість… Але те, що зі мною відбувалося у лісі, було схоже на напівп’яне марення якогось там обкуреного нарика. Цей день змінив моє життя. Повністю. З «до» на «після». Мене колишньої не стало. Так Народилася Я IMaRia. Коли закінчилося завантаження та Активація пам’яті про те, хто я і навіщо. Я почала знову розрізняти земну реальність. Навколо було темно. Минули якісь миті, долі секунд. Але довкола я побачила темну ніч і зрозуміла, що насправді пролетіло багато годин. Не було страху. Не було паніки. Але була Я! Була тотально! Я встала із Землі, на якій валялася під деревом, мокра наскрізь. Мокрим було все, включно з білизною, не зрозуміло чому, начебто викупали. І побрела через ліс у село, до хати, де жила. Я тоді не знала жодних термінів, слів, пов’язаних із тим, що зі мною сталося… та й це не мало сенсу. Усі сенси загалом зникли. Я намагалася згадати свою «велику проблему» і чому тут опинилася – і не змогла. Пам’ять емоційну чуттєву ніби стерло. Все повернулося згодом. Тотальне обнулення. Тотальний спокій. Тотальна порожнеча та повнота одночасно. За два дні я звідти поїхала. Зовсім іншою людиною. Вагітною силами самої природи, наповненою знаннями про все; очищеною від всякої брехні і всіх правд. Після повернення додому я зрозуміла, що все інше. Точніше, воно можливо і таке ж, але в мені до всього інший дотик та ставлення. Чи зможу колись пояснити оточенню, що є інша реальність, ніж ігри розділеної на шматки свідомості? Чи можу я поділитися цим досвідом і реалізувати шлях Душі, який побачила чітко і ясно, лежачи на мокрій осінній землі у лісі? Чи зможу я…? Усе це втратило всякий сенс… Адже з’явилася єдина мета — БУТИ. ТУТ. ЗАРАЗ! …Там, де я прокинулася і усвідомлююся ВСІМ… © Iryna Zaverukha. All materials on this site are copyrighted. Copying and distribution of materials is possible only with the prior consent of the author and indication of an active link to this site"]','Блог','Ірина Заверуха','24 січня 2024','7 хв читання','/images/posts/shamanka.jpg','[]',1,'2024-01-24T19:11:22','2024-01-24T19:11:22');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-593','trials-come-for-spiritual-and-mental-strengthening','Trials come for spiritual and mental strengthening!','Trials come for our spiritual and mental strengthening, not for emotional panic and physical exhaustion… Ресурсність – наше все! Не зависай лише у «виживанні», підіймай голову до небес, … дякуй при цьому природі за щедрість… помічай Живе Життя, еволю...','["Trials come for our spiritual and mental strengthening, not for emotional panic and physical exhaustion… Ресурсність – наше все! Не зависай лише у «виживанні», підіймай голову до небес, … дякуй при цьому природі за щедрість… помічай Живе Життя, еволюціонуй в будь яких умовах. Душевну ресурсність черпай в творчості, моральну – в цінностях та спілкуванні з однодумцями, фізичну – в практиці тілесної дії, в служінні; … цілісну – в розвитку духовного інтелекту та спілкуванні з природою… «Перемагай на всіх фронтах! Прошу тебе, перемагай… Про волю й силу ти як білий птах, На висоті вітрів співай… Перемагай потоком щирих слів! Прошу тебе, перемагай… Не бійся тих, хто не зумів В душі своїй створити рай… Перемагай і лінь, і гнів, і злобу дня, Прошу тебе, перемагай… Іди вперед сміливо, навмання, Не падай в прірву болю – оживай… Перемагай свої ілюзії й ниття, Прошу тебе, перемагай… Плекай потоком вірності живе життя, І кожному зустрічному ти посмішку давай… Перемагай страхи сміливістю до дій, Прошу тебе, перемагай… За щастя тих, хто поряд порадій, А тим, хто проживає біль – поспівчувай. Перемагай свою гординю і печаль, Прошу тебе, перемагай… І навіть коли плаче серце і сльоза в очах, Ти знов від себе мужність вимагай. Перемагай на всіх фронтах! Прошу тебе, перемагай…» 17.09.2022 ©️ Ірина Заверуха Нескорені – разом ми Сила! © Iryna Zaverukha. All materials on this site are copyrighted. Copying and distribution of materials is possible only with the prior consent of the author and indication of an active link to this site"]','Творчість','Ірина Заверуха','24 січня 2024','3 хв читання','/images/posts/viva-interview.jpg','[]',1,'2024-01-24T19:24:50','2024-01-24T19:24:50');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-601','top-100-unbreakable-ukrainians','TOP-100 Unbreakable Ukrainians','"If only you could hear the voices that I hear with my heart in every consultation or group therapy… Sometimes I still hear these echoes in the middle of the night, when the lights and sounds of an active city have long died out…" Friends, currently ...','["\"If only you could hear the voices that I hear with my heart in every consultation or group therapy… Sometimes I still hear these echoes in the middle of the night, when the lights and sounds of an active city have long died out…\" Friends, currently without guest introduction. Just think about her words and address to you. And then join, the link is after the conversation. Майстриня IMARIA. Берегиня України, Вчителька і Цілителька, Засновниця платформи багатовимірного розвитку Pipl; громадська діячка, практикуюча еніопсихологиня та Майстриня трансформації свідомості; наставниця соціальних Лідерів… ВАШІ ДУШІ ПРАГНУТЬ ЖИТИ, ЛЮДИ!!! Зрозумійте, будь-ласка, це не про егоїзм і збагачення, не про легкий кайф та боротьбу за краще місце під сонцем… «Жити» для Душі через тіло й матерію – це величезний шанс та дар. Це результат неймовірної титанічної праці за право бути ПРОЯВЛЕНИМ світлом; це фініш марафону між варіантами та контініумами обставин, які могли не статись, але вони стались. І ви ТУТ, І ЗАРАЗ ІСНУЄТЕ. КОЖНА СЕКУНДА, ХВИЛИНА – ЦЕ МОЖЛИВІСТЬ!!! …Неймовірна і самобутня, неповторна та безцінна можливість стати тим, хто ти Є насправді, хто нікуди не зникав і не зникне… Але потрібно СЕБЕ ЖИТИ, збагнути те блаженство Вічності, яке вдається осягнути лише через життя. Друзі, ви лише послухайте, як несамовито б’ється ваше серце за право на ВДОХ І ВИДИХ. Йому зовсім байдуже, чи синє у вас авто, чи жовте, чи спідничка брендова, чи ні. Ви надумали собі безліч обмежень та причин для гри в страждання, набудували догм і правил, вірувань та гонки-маршрути до цілей, забуваючи головне – ЖИТИИИИ… А це не про думати все підряд і бігати в пошуках відчуттів. ЖИТТЯ пробивається, коли ми перестаємо варитися в думках та бути залежними від емоцій й зовнішніх схвалень. ЖИТТЯ ми часто помічаємо якраз тоді, коли все згасло й замовкло, коли ми вимикаємо в собі усі радіо, усі «потрібно», усі «хочу». ЖИТТЯ таке, як воно є, екзистенціальне, а не те, що на екрані матриці, на екрані гри в страждання й боротьбу. Воно пробивається крізь бетон та не чекає сприятливих умов для БУТИ. Якщо ви досі вірите, що хтось чи щось вам заважає ЖИТИ й бути щасливими, то ви просто не зустріли іще свою власну Душу. Ви її не почули, не впізнали, не зрозуміли… От і все. А ЖИТИ прийшла саме ВОНА, сюди прийшла вона! І це її подіум, це її шанс… ВАШІ ДУШІ ПРАГНУТЬ ЖИТИ! У кожної є свій ПЛАН, але ж, який він далекий від тих сценаріїв его, що ви намалювали на високих парканах своїх ідентифікацій?! Не чекайте, доки припече чи настане сприятливий час для зустрічі й бесіди з СОБОЮ. Не чекайте мирних часів. Ініціюйте цю зустріч самі, станьте тими, хто бере відповідальність за своє ДИХАННЯ… МАЮ НАМІР: доки відчуваю зв’язок з цим світом і кожним імпульсом Творця – буду стукати у ваші серця та спонукати вас ЖИТИ ЖИВИМ ЖИТТЯМ… А воно те, яке ЗАРАЗ, і достойне низького поклону до землі, вдячності до небес… Бережіть свої Душі! Бо як не ви господарюєте в домі-тілі, то тоді ХТО??? Збільшуйте кількість життя в ЖИТТІ. Вибирайте його. Щомиті. Прошу вас! Запитуйте себе в простих речах на кожному кроці: «те, що я роблю зараз, це ЖИТТЯ?», «те, що я зараз п’ю, їм, думаю, кажу – це збільшує й покращує життя, чи вкорочує та погіршує його мені або довколишнім?»… Я ЧУЮ ВАШІ ДУШІ, І ВОНИ ХОЧУТЬ ЖИТИ… До зустрічі на душевних бесідах та практичних семінарах. «Все дуже й дуже просто», – Ірина ЗАВЕРУХА"]','Новини','Ірина Заверуха','24 січня 2024','3 хв читання','/images/posts/media-premiere.jpg','[]',1,'2024-01-24T19:37:27','2024-01-24T19:37:27');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-623','%d0%bc%d0%be%d1%8f-%d0%b8%d1%81%d1%82%d0%be%d1%80%d0%b8%d1%8f-2','Моя история','– Так зачем же все? – Хочу жить в лучшей версии этого Мира! Поэтому проявляю самую счастливую версию своей судьбы. Приветствую вас, дорогой Гость, я очень рада, что мы нашли друг к другу дорогу, а вернее ПУТЬ..! Давайте знайомитися. Мене зовуть Завер...','["– Так зачем же все? – Хочу жить в лучшей версии этого Мира! Поэтому проявляю самую счастливую версию своей судьбы. Приветствую вас, дорогой Гость, я очень рада, что мы нашли друг к другу дорогу, а вернее ПУТЬ..! Давайте знайомитися. Мене зовуть Заверуха Ірина. Нині також маю проявлене імʼя Душі - IMARIA і транслюю вібрацію свого духовного роду, я - інтуїт, сучасний енергоінформаційний цілитель, кармакоректор, еніопсихолог, астролог китайської метафізики (ба цзи, фен-шуй, цимень, вибору дат), ченнелер, духовний провідник, вчитель йоги свідомості і медитації, авторка, кохана і любляча дружина, і мама прекрасних дітей; засновниця платформи багатовимірного розвитку PIPL, громадська діячка, соціальний лідер країни, Берегиня …але все це скоріше ролі. Насправді – я є Дух, який пізнає життя через живонароджену втілену Душу. Запрошую і вас пізнати цю триєдність і вийти з ілюзії розділеності! Народилася я з даром до цілительства і яснобачення, які вдалося перетворити на благу діяльність та проявлену справу життя. Своєю творчістю і працею допомагаю людям знаходити вихід із різних ситуацій, набувати гармонії та цілісності, щастя та здоров''я, не зважаючи на обставини і події. Я навчаю хілерів і менторів жіночих, які разом зі мною пробуджують на Землі ген світочів, обʼєднають Хранителів Частот нейромережі нової реальності. Моя історія не має початку у вигляді особливої ​​дати, вона тягнеться з народження. З самого дитинства мене хвилювали питання саморозвитку, духовність і еволюція, я думала, що кожна людина прийшла на Землю не просто так, що зобов''язана знайти і зрозуміти своє місце в Світі. Слухала свою Душу і ніби чула розмови Душ довкола мене… Пізніше я зрозуміла, що це було буквально – я чую голос Душі будь чого! Зв''язок з Вищими силами був у мене завжди: контакти з Ангелами, взаємодія зі стихіями, космічність в і містичність; зв''язок із Землею – з енергією предків-цілителів, з духами лісу, з усім сущим; ... і найголовніше - почуття єдності з Абсолютом, з Творцем через злиття з його творіннями, пряма розмова з серцем Великої МА через свідомість людини Аватара Ірини. Ще дитиною я знала, що допомагатиму людям, у міру дорослішання змінювався лише спосіб, а мета «Жити і безумовно любити!» нікуди не поділася. Не розповідатиму багато, як пройшло моє дитинство, майже як у кожного в пострадянському просторі. Закінчила школу із золотою медаллю і, окрилена високою екосвідомою метою проявитися, - поїхала до Києва, щоб стати екологом. На той момент (в 1999 році) мені здавалося, що це найнадійніший спосіб досягти моєї мети. Але на першому курсі університету я зрозуміла, що займаюся боротьбою з наслідками, що якщо люди не змінять своє ставлення до життя, то жодна армія екологів Світ кращим не зробить! Я почала працювати у сфері екоосвіти з дітьми, зміни в яких давали надію на краще, щиро вірилося, що дитина з відповідальною життєвою позицією не зможе ніколи робити «боляче» іншим та самій собі. Так із екології простору я перейшла в вимір екології Душі. Працювала на високій посаді у Всеукраїнській Екологічній Лізі. Паралельно була студдеканом свого інституту. На четвертому курсі університету я вийшла заміж за людину близьку мені по духу. Я захоплювалася східною метафізикою, займалася йогою, а мій чоловік – айкідо. Перша громадська організація, створена моєю сім''єю у 2004 році, це був Клуб розвитку особистості «Каннагара», в якому діти та дорослі пізнавали ази східних єдиноборств та філософію балансу дао життя. Як істинна Жінка я присвятила багато років важливому прояву себе – сім''ї. Їхня підтримка і любов дозволили мені стати такою, якою я є зараз. Моя родина - моя потужна опора. Неможливо змінити світ на краще, не змінюючи себе. По суті, вся ілюзія неідеального світу існує всередині нашої системи доти, доки ми СЕБЕ не приведемо до гармонії, не полюбимо і не приймемо місію душі… Моя сім''я дуже допомогла мені в цьому – шліфуючи межі свого его стосунками, я навчилася робити маленькі кроки до великих цілей. Материнство щедро розкрило досі невидимі здібності, затвердило у правильності путі... путі інтуїції. На справді ви вже можете прочитати дуже багато моїх розповідей з опорою на особистий досвід в блозі, який є тут на сайті, а також в соцмережах. До видання готуються і книги, в яких зможете взяти для себе корисні інструменти для трансформації власної долі! Ну а зараз на регулярній основі я веду навчання для людей (в основному жінок), які готові вийти за межі ума і служити роду та часу як цілителі і провідники. У моєї платформи багатовимірного розвитку PIPL є флагманські програми, наприклад річна трансформаційна програма для жінок #КРИЛА - свобода бути собою! Є середовище росту і розвитку практиків - PIPL CLUB . Починає свою активну роботу IMARIA ACADEMIA , де я і мої учениці проводимо різні трансформаційні марафони. Метафізичному мистецтву фен-шуй і ба цзи, премудростям ці мен дун цзя та іншим напрямам східної філософії я навчалася після чіткого усвідомлення, що не нести людям ті імпульси, які через мене пропускають Вищі Сили, я просто не можу. Щоразу, коли робила спроби втекти від істинної себе – отримувала «по шапці» у вигляді хвороб, так мене «пробуджували» і спрямовували на істинний Шлях. У 2009 році я пройшла випробування на онкологічне захворювання, яке через роботу над собою благополучно перетворила на свій досвід і цінність, адже тепер ділюся ним з тими людьми, які ПОВІРИЛИ В ХВОРОБУ І ВТРАТИЛИ ЗВ''ЯЗОК З СОБОЮ. Немає невиліковних недугів, завжди з нами через тіло говорить Душа і просить змін, ефективних корекцій! Шлях із ілюзій став ясним і переріс у творчий Путь інтуїції! Коли з 2010 року я стала застосовувати та практикувати ба цзи та фен-шуй професійно, то просто була вражена легкості процесу та тому задоволенню від нього, яке народжувалося в мені. Результати і відгуки моїх клієнтів радували і надихали, хоча я й продовжувала зіштовхуватися і зі скептиками, і з глузуванням, і з нерозумінням. Щиро вдячна за ці стички, адже саме вони змушували мене йти далі, шукати причини та знаходити відповіді. Одного разу я прочитала книгу Майкла Роуча «Алмазна мудрість» і прийняла у своє життя Кармічний менеджмент. Це вкотре розширило мої горизонти. Слово \"Карма\" тоді вперше торкнулося мене глибоко і всередині щось зачепило. Мені завжди було важливо докопатися і знайти першопричину, тому я почала вивчати ази кармічного цілительства. Так до астрологічної аналітики додалася і кармічна діагностика як інструменти з долею людини. Мій шлях діагноста та цілителя продовжував йти паралельною дорогою з розвитком здібностей. За останні 20 років життя я багато чого пізнала, прожила, подолала, відвідала безліч тренінгів та семінарів в майже десятку духовних традицій, здобула кілька освіт, але найголовніше – накопичила досвід та глибокі знання, а не просто інформацію, якими зі мною щедро ділилися справжні Вчителі живі і Вишні. Низький уклін кожному з них: Кислій Любові Василівні, земля вам пухом; Лідії Янковській, Інні Волковій, Наталі Ладіні, Керол Салтер, Альберту Ігнатенку, Майклу Роучу, і цілому сангату Вчителів Золотої Мережі традиції Кундаліні йоги … усім усім, хто мені допомагав та підтримував! Після проведення чистки своїх родових каналів та підвищення рівня вібрацій свого поля через практики, я відчула неймовірну силу Безумовного Світла Творця-Батька та Безумовної Любові Матері ВсеСвіту, які почали струмувати через мене, протікати потоком… Вищі Вчителі з інших цивілізацій стали виходити на контакт частіше, передаючи інформацію і в медитаціях, і в усвідомлених сновидіннях, і навіть у свідомих моментах, будучи в місцях сили, які я відвідувала. Під час війни в Україні, я прожила активну фазу переходу в статус Берегині Землі, здібності підсилилися і активувалися нові спектри дарів. Я не покинула Україну, підтримуючи баланс практикою, зцілюючи людей, пропускаючи крізь серце величезну кількість болю та пошматованих душ… На сьогоднішній день я смілива на максимум і проявлена. Реалізовую програми, цілительні сатсанги, консультую, пишу послання, вірші, книги, медитації, веду блоги, виступаю з семінарами та майстер-класами, розвиваю команди і проекти, приділяю увагу благодійності та творчості, спрямованій на пробудження людей і розвиток зрілої цивілізації. Ласкаво просимо до спільноти Світочів, якщо вас зацікавило щось із описаного вище! Далі проявляю для вас трохи сухої статистики: З 2015 по 2019 рік - співорганізатор Фестивалю «Життя як Чудо» 2016 - засновниця Школи творчості та духовного розвитку «Путь Інтуїції» З 2017 по 2020 - автор рубрик і публікацій в медіа проектах «VIVA», WomanMagazine, Єдина… тощо… 2018 - Президент ГО «Aurum Soul Club», Дама Ордену Королеви Анни «Честь Вітчизни», Член Правління Всесвітньої Ліги Космогуманістів, створила соціальний простір саморозвитку для людей. Провела за рік - 3 жіночих фестивалі; Національний форум «Золото Материнства», фестиваль «Сімейні цінності і родові традиції»; підтримала увагою понад 10 соціальних і культурних проектів як співорганізатор; випустила 43 учениці з чотирьох потоків навчання… 2019 - ченелер світу. IMARIA MASTER 2020 рік - заснувала Проект #Pipl - платформа багатовимірного розвитку З 2021 і по сей день - Просвітитель. З 2021 - Сертифікований Вчитель Вищої Йоги свідомості. 2021 рік - Дама ордену «Лідер України». Заснувала трансформаційну жіночу програму #КРИЛА . Почала готувати професійних Менторів і хілерів для світу. З 2022 року - Берегиня України. Провела понад 1300 благодійних консультацій для людей рідної держави з різними запитами. Не покидала територію України з 2022 по 2024 роки. Провела за два роки 26 виїзних заходів в Україні (ретритів і семінарів навчальних, планетарних практикумів) не зважаючи на умови і обставини блекаутів. 2023 рік - Вища суспільна нагорода орден «Святої Софії» за вклад в розвиток людей нації та цілісне холістичне здоровʼя. 2023 - увійшла в #ТОП100 незламних Українців за результатами професійної діяльності. … І ось я тут… Пишу для вас. І будую нові творчі плани розвитку. Продовжую консультувати людей як особисто, так і дистанційно. Під час консультацій окремих людей – дотримуюся принципу “все індивідуально”, переглядаю людину і на рівні астрології, і на рівні кармічної матриці, і на рівні поля душі. Я просто щаслива, що можу допомагати іншим ставати кращими, здоровішими, успішнішими, впевненішими в собі, знаходити цілі і рухатися до них, рости духовно і проявлятися із богореалізованої свідомості. Я і сама йду таким же шляхом без зупинки, постійно розвиваючись. Золотий Вік Творця вже на порозі, Ера Жінки, епоха Великої МА прийшла, друзі! Ми з вами живемо в унікальні часи, друзі, і здатні розкрити на повну потужність свій дар душі і потенціал. До зустрічі! 🙏 © Ирина Заверуха. Все материалы этого сайта являются объектами авторского права. Копирование и распространение материалов возможно только при предварительном согласовании с автором и указанием активной ссылки на этот сайт"]','Блог','Ірина Заверуха','25 січня 2024','8 хв читання','/images/posts/end-is-beginning.jpg','[]',1,'2024-01-25T14:11:42','2024-01-25T14:11:42');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-626','%d1%82%d0%be%d0%bf-100-%d0%bd%d0%b5%d1%81%d0%be%d0%ba%d1%80%d1%83%d1%88%d0%b8%d0','ТОП-100 Несокрушимых Украинцев','«Если бы вы только услышали те голоса, которые я слышу сердцем на каждой консультации или групповой терапии… Иногда я эти эхо продолжаю слышать и ночью, когда давно погасли огни и звуки активного города…» Друзья, без представления гости. Просто вдума...','["«Если бы вы только услышали те голоса, которые я слышу сердцем на каждой консультации или групповой терапии… Иногда я эти эхо продолжаю слышать и ночью, когда давно погасли огни и звуки активного города…» Друзья, без представления гости. Просто вдумайтесь в ее слова и обращения к вам. А дальше присоединяйтесь, ссылку после беседы. Мастерица IMARIA. Берегиня Украины, Учительница и Целительница, Основательница платформы многомерного развития Pipl; общественный деятель, практикующая эниопсихологиня и Мастерица трансформации сознания; наставница социальных Лидеров… ВАШІ ДУШІ ПРАГНУТЬ ЖИТИ, ЛЮДИ!!! Зрозумійте, будь-ласка, це не про егоїзм і збагачення, не про легкий кайф та боротьбу за краще місце під сонцем… «Жити» для Душі через тіло й матерію – це величезний шанс та дар. Це результат неймовірної титанічної праці за право бути ПРОЯВЛЕНИМ світлом; це фініш марафону між варіантами та контініумами обставин, які могли не статись, але вони стались. І ви ТУТ, І ЗАРАЗ ІСНУЄТЕ. КОЖНА СЕКУНДА, ХВИЛИНА – ЦЕ МОЖЛИВІСТЬ!!! …Неймовірна і самобутня, неповторна та безцінна можливість стати тим, хто ти Є насправді, хто нікуди не зникав і не зникне… Але потрібно СЕБЕ ЖИТИ, збагнути те блаженство Вічності, яке вдається осягнути лише через життя. Друзі, ви лише послухайте, як несамовито б’ється ваше серце за право на ВДОХ І ВИДИХ. Йому зовсім байдуже, чи синє у вас авто, чи жовте, чи спідничка брендова, чи ні. Ви надумали собі безліч обмежень та причин для гри в страждання, набудували догм і правил, вірувань та гонки-маршрути до цілей, забуваючи головне – ЖИТИИИИ… А це не про думати все підряд і бігати в пошуках відчуттів. ЖИТТЯ пробивається, коли ми перестаємо варитися в думках та бути залежними від емоцій й зовнішніх схвалень. ЖИТТЯ ми часто помічаємо якраз тоді, коли все згасло й замовкло, коли ми вимикаємо в собі усі радіо, усі «потрібно», усі «хочу». ЖИТТЯ таке, як воно є, екзистенціальне, а не те, що на екрані матриці, на екрані гри в страждання й боротьбу. Воно пробивається крізь бетон та не чекає сприятливих умов для БУТИ. Якщо ви досі вірите, що хтось чи щось вам заважає ЖИТИ й бути щасливими, то ви просто не зустріли іще свою власну Душу. Ви її не почули, не впізнали, не зрозуміли… От і все. А ЖИТИ прийшла саме ВОНА, сюди прийшла вона! І це її подіум, це її шанс… ВАШІ ДУШІ ПРАГНУТЬ ЖИТИ! У кожної є свій ПЛАН, але ж, який він далекий від тих сценаріїв его, що ви намалювали на високих парканах своїх ідентифікацій?! Не чекайте, доки припече чи настане сприятливий час для зустрічі й бесіди з СОБОЮ. Не чекайте мирних часів. Ініціюйте цю зустріч самі, станьте тими, хто бере відповідальність за своє ДИХАННЯ… МАЮ НАМІР: доки відчуваю зв’язок з цим світом і кожним імпульсом Творця – буду стукати у ваші серця та спонукати вас ЖИТИ ЖИВИМ ЖИТТЯМ… А воно те, яке ЗАРАЗ, і достойне низького поклону до землі, вдячності до небес… Бережіть свої Душі! Бо як не ви господарюєте в домі-тілі, то тоді ХТО??? Збільшуйте кількість життя в ЖИТТІ. Вибирайте його. Щомиті. Прошу вас! Запитуйте себе в простих речах на кожному кроці: «те, що я роблю зараз, це ЖИТТЯ?», «те, що я зараз п’ю, їм, думаю, кажу – це збільшує й покращує життя, чи вкорочує та погіршує його мені або довколишнім?»… Я ЧУЮ ВАШІ ДУШІ, І ВОНИ ХОЧУТЬ ЖИТИ… До зустрічі на душевних бесідах та практичних семінарах. «Все дуже й дуже просто», – Ірина ЗАВЕРУХА"]','Новини','Ірина Заверуха','25 січня 2024','3 хв читання','/images/posts/shamanka.jpg','[]',1,'2024-01-25T14:19:01','2024-01-25T14:19:01');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-631','%d0%b8%d1%81%d0%bf%d1%8b%d1%82%d0%b0%d0%bd%d0%b8%d1%8f-%d0%bf%d1%80%d0%b8%d1%85%','Испытания приходят для духовного и ментального укрепления!','Испытания приходят для нашего с вами духовного и ментального укрепления, а не для эмоциональной паники и изнурения телесного… Ресурсность – наше все! Не зависай только в «выживании», поднимай голову к небесам… спасибо при этом природе за щедрость… за...','["Испытания приходят для нашего с вами духовного и ментального укрепления, а не для эмоциональной паники и изнурения телесного… Ресурсность – наше все! Не зависай только в «выживании», поднимай голову к небесам… спасибо при этом природе за щедрость… замечай Живую Жизнь, эволюционируй в любых условиях. Душевну ресурсність черпай в творчості, моральну – в цінностях та спілкуванні з однодумцями, фізичну – в практиці тілесної дії, в служінні; … цілісну – в розвитку духовного інтелекту та спілкуванні з природою… «Перемагай на всіх фронтах! Прошу тебе, перемагай… Про волю й силу ти як білий птах, На висоті вітрів співай… Перемагай потоком щирих слів! Прошу тебе, перемагай… Не бійся тих, хто не зумів В душі своїй створити рай… Перемагай і лінь, і гнів, і злобу дня, Прошу тебе, перемагай… Іди вперед сміливо, навмання, Не падай в прірву болю – оживай… Перемагай свої ілюзії й ниття, Прошу тебе, перемагай… Плекай потоком вірності живе життя, І кожному зустрічному ти посмішку давай… Перемагай страхи сміливістю до дій, Прошу тебе, перемагай… За щастя тих, хто поряд порадій, А тим, хто проживає біль – поспівчувай. Перемагай свою гординю і печаль, Прошу тебе, перемагай… І навіть коли плаче серце і сльоза в очах, Ти знов від себе мужність вимагай. Перемагай на всіх фронтах! Прошу тебе, перемагай…» 17.09.2022 ©️ Ірина Заверуха Нескорені – разом ми Сила! © Ирина Заверуха. Все материалы этого сайта являются объектами авторского права. Копирование и распространение материалов возможно только при предварительном согласовании с автором и указанием активной ссылки на этот сайт"]','Творчість','Ірина Заверуха','25 січня 2024','3 хв читання','/images/posts/viva-interview.jpg','[]',1,'2024-01-25T14:28:27','2024-01-25T14:28:27');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-642','%d0%ba%d0%b0%d0%ba-%d1%80%d0%be%d0%b4%d0%b8%d0%bb%d0%b0%d1%81%d1%8c-imaria','Как родилась IMaRia','В свое время мне казалось, что не справлюсь… что колоссально не справлюсь и не выдержу напряжения… Сила этого напряжения была так велика, что я усомнилась в истинности пути. Внутри меня шла борьба между западным рационалистическим материализмом и вос...','["В свое время мне казалось, что не справлюсь… что колоссально не справлюсь и не выдержу напряжения… Сила этого напряжения была так велика, что я усомнилась в истинности пути. Внутри меня шла борьба между западным рационалистическим материализмом и восточным духовно-медитативным началом, как лед и пламя, то растапливая, то обжигая кипятком гнева и искрами от столкновения. Я втомилася. Сильно. Так сильно втомилася і від людей, і від сім’ї, і від усієї цієї канителі з напругою життя, що грань здавалася піковою та нестерпною. Осінь насувалася на Землю, а на мене це цунамі. І я вирішила. Якщо дикі стихії буяють усередині і не вистачає якихось пазлів для їх стикування, значить, треба поринути в дику стихію, піти назустріч всьому цьому. Я поїхала в Карпати. Сама. Влаштувала собі мовчазний одиночний Ретрит. Жила в будиночку у товариша, на узліссі. Була надія знайти опору. Я робила йогу. Мало їла. Пила джерельну воду. Медитувала прямо на річці. Тобто сідала на містку, який через річку гірську, і медитувала на цей бурхливий потік, сподіваючись на очищення моєї свідомості. Я не розмовляла. Мовчала. І лише писала свої думки та обмінювалася ними з місцевими котами телепатично. Ходила на масаж, парила свої кістки в чані трав’яному. Загалом робила все, що могла. Але лід та полум’я всередині так і не з’єднувалися. І ось одного дня я вирішила піти ще далі і з’єднатися з природою ще глибше. Я встала о 4-й ранку, взула гумові чоботи, взяла з собою тільки воду в рюкзак за спиною і пішла в гори. Я брела навмання через нічне сонне село. Навколо нікого. Дикий ліс. Крокувала вгору. Поки на піку не зустріла сонце і світанковий тріумф третіх півнів. Немає таких слів, щоб передати почуття, які бурхливим потоком переповнювали мене тоді, по щоках текли сльози, все втратило сенс, ніби це був перший світанок у моєму житті і я щойно народилася. Мокра осіння земля дихала холодом і вогкістю. Туманний серпанок накривав долину і осідав унизу, але сонце наполегливо піднімалося вище і висвічувало небеса. А я стояла та дивилася. Пішла далі. По хребту безлюдних гір, що заросли лісом. Вдалині з’явився табун диких коней. Вони галопом мчали горами з такою силою Свободи, що я мимоволі розплакалася, сльози самі по собі бризнули з очей і вирвався дикий крик агонії зсередини найглибшого днища в мені. Із табуна коней один зупинився. Він глянув у мій бік і почав галопом бігти прямо на мене. Метрів 800-900 розділяли нас, і я в ступорі дивилася на цей біг, не відчуваючи нічого. Жеребець прискакав і різко зупинився перед моїм обличчям, опустивши голову з ніздрями, які випускали потужний пар. І ось тепер мене накрив шок від побаченого та усвідомленого. Він реально схилився до моїх ніг, дозволяючи себе гладити. Прекраснішого способу поговорити зі мною про самоцінність і не вигадаєш. Я плакала і від шоку, і від захоплення. Ішла далі. Якийсь час жеребець тупотів поряд. Потім він поскакав у Даль, з якої і з’явився. Тоді я ще не знала, що одного разу зустріну його знову. Що він знову прискаче галопом, але я буду тут не одна і допоможу своєму синові погладити його голову і не боятися дикої Сили природи. Я йшла далі… Не хотілося нічого аналізувати. Просто рух. Цілі не було. Найчистіша пригода без сенсу. Сонце вже піднялося досить високо. Погода була чудовою. Нагулявшись на гребені висоти, я почала спуск вниз у долину. Перейшла річку вбрід. Благо гумові чоботи були високими, а річка – не глибокою. Зате зустріла… Т И Ш У такої глибини, що не передати. Втомилася. Відверто кажучи, сильно втомилася. Спиною пригорнулася до дерева, заплющила очі, глибоко вдихнула і нааааааа видиху… провалилася в такууууууу безодню, що не описати. Моє тіло одночасно пронизалося мільярдами вихорів та потоків. Я відчула в кожній клітинці В И Б У Х, схожий на екстаз на рівному місці… Скрізь, де тільки можна було, виступив піт. Внутрішній жар викликав задишку, обличчя горіло вогнем дикої Сили… я не розуміла, що зі мною відбувається, і ніби задихалася сама собою. В очах все змішалося. Я розплющувала їх. Заплющувала. Але начебто це не працювало. Я бачила не ними. Вони перестали бути потрібними. Я зробила глибокий вдих і видих, і вибух повторився знову. Ще потужніший. Ще глибше пронизуючи мене струмом наскрізь. Це був дикий секс між небом та землею. Я зрозуміла, що всю мене пронизує оргазм. Таааак!!!! На рівні фізичного тіла це було схоже на оргазм. Але не в області геніталій, а СКРІЗЬ!! Скрізь у мені, і поза мною відбувалося ЖИТТЯ, Синергія, перетікання, вибух за вибухом… Моя матка та моє серце стали схожими на котел. Я відчула всередині величезну Силу початку творення. Це не передати словами. Це ні з чим не порівняти. Я дивилася на світ і не дивилася. Я була і мене не було. Я почувала себе Собою і я почувала себе всім: і деревом, і землею, і повітрям, і вітром, і водою, і мохом, і сонцем, і лісом, і всім, і нічим. Потім на мить мені здалося, що я вмираю. І вмиранню дала місце. Просто стікала вниз, сповзла, впала на сиру мокру землю. Агонія злиття всього з усім тривала… Такої насолоди від величі тотальної присутності та відсутності одночасно я не відчувала ніколи до цього і більше ніколи після цього. Я пізнала Любов і Силу, розчинившись у цьому потоці сексу Неба та Землі, і ніби в одну мить все ДІЗНАЛАСЯ. У голові з’явилися різні знання. Вони самі по собі начебто вибухали миттєво, різні архіви відкривалися і розкривалися розумінням. Начебто в мене вбудували мільйон енциклопедій і дали доступ до всіх мов Всесвіту. Я намагалася думати, але не могла. Не було того, що зазвичай думає. Уся реальність була реальною. Я з’являлася в якихось інших місцях, як спостерігач, що заглядає у вікно: в інших світах, тілах, просторах… Це відбувалося миттєво, дуже швидко, блискавично, миготіли іскри світла, і не було світу форм… Ніколи я не курила ніякої трави, не жувала грибів, не пила ніяких бовтанок, ніяких дослідів під впливом наркотичних речовин у мене не було, я прожила до цього і після цього чисту реальність, розширюючись як свідомість лише практикою медитації і моїм ЖИТТЯМ через усвідомленість… Але те, що зі мною відбувалося у лісі, було схоже на напівп’яне марення якогось там обкуреного нарика. Цей день змінив моє життя. Повністю. З «до» на «після». Мене колишньої не стало. Так Народилася Я IMaRia. Коли закінчилося завантаження та Активація пам’яті про те, хто я і навіщо. Я почала знову розрізняти земну реальність. Навколо було темно. Минули якісь миті, долі секунд. Але довкола я побачила темну ніч і зрозуміла, що насправді пролетіло багато годин. Не було страху. Не було паніки. Але була Я! Була тотально! Я встала із Землі, на якій валялася під деревом, мокра наскрізь. Мокрим було все, включно з білизною, не зрозуміло чому, начебто викупали. І побрела через ліс у село, до хати, де жила. Я тоді не знала жодних термінів, слів, пов’язаних із тим, що зі мною сталося… та й це не мало сенсу. Усі сенси загалом зникли. Я намагалася згадати свою «велику проблему» і чому тут опинилася – і не змогла. Пам’ять емоційну чуттєву ніби стерло. Все повернулося згодом. Тотальне обнулення. Тотальний спокій. Тотальна порожнеча та повнота одночасно. За два дні я звідти поїхала. Зовсім іншою людиною. Вагітною силами самої природи, наповненою знаннями про все; очищеною від всякої брехні і всіх правд. Після повернення додому я зрозуміла, що все інше. Точніше, воно можливо і таке ж, але в мені до всього інший дотик та ставлення. Чи зможу колись пояснити оточенню, що є інша реальність, ніж ігри розділеної на шматки свідомості? Чи можу я поділитися цим досвідом і реалізувати шлях Душі, який побачила чітко і ясно, лежачи на мокрій осінній землі у лісі? Чи зможу я…? Усе це втратило всякий сенс… Адже з’явилася єдина мета — БУТИ. ТУТ. ЗАРАЗ! …Там, де я прокинулася і усвідомлююся ВСІМ… © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','25 січня 2024','6 хв читання','/images/posts/media-premiere.jpg','[]',1,'2024-01-25T14:39:06','2024-01-25T14:39:06');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-807','%d1%82%d0%b8-%d0%b7%d1%96%d1%80%d0%ba%d0%b0-%d1%86%d0%b5%d0%bd%d1%82%d1%80%d1%83','Ти — Зірка! Центруйте в собі енергію!','Ти — Зірка!🌟✨ Центруйте в собі енергію! Фіксуйтеся завжди через вдих і видих! І відчуєте своє серце. Відчуєте Життя. Відчуєте Живе Життя. З’єднуючись в один простір, ми стаємо спочатку сузір‘ям, а потім однією Зіркою✨ І Зірка це не хтось. Зірка — це ...','["Ти — Зірка!🌟✨ Центруйте в собі енергію! Фіксуйтеся завжди через вдих і видих! І відчуєте своє серце. Відчуєте Життя. Відчуєте Живе Життя. З’єднуючись в один простір, ми стаємо спочатку сузір‘ям, а потім однією Зіркою✨ І Зірка це не хтось. Зірка — це кожен. Зірка — це ти!⭐️ Тому що Душа народжується тут, на Землі, але створюється вона на одній єдиній Зірці… І їй завжди хочеться СЯЯТИ💫 Вона завжди пам‘ятає про природу Зірки. Вона прагне до цього блаженного стану — сердечної безумовної любові та проявлення. Іноді вона так заплутується в пошуках, у лабіринтах розуму, що починає маленькі моменти задоволення, кайфу вважати щастям чи блаженством… Але це не те… До духовного блаженства нас ніхто і ніколи не приведе. Ми можемо його тільки відчути❤️ Голос своєї Душі почути. А як же вчителі, провідники? — запитаєте. Так, ми можемо опиратися на голос чиєїсь душі якийсь час, але прагнути до того моменту, коли самі керуємо простором свого життя. І сяємо! Сяємо любов‘ю, вірою і свободою! Свободою проявлення! І світимо! ☀️ Яскраво світимо! Пам‘ятаючи про свою зіркову природу! ✨✨✨ Юху!!! 🥳🥳🥳🥳🥳 Ми стартували сяючий та наповнюючий марафон “Від гордині до гордості бути Жінкою нового часу” Ми завжди радо чекаємо тебе у багатовимірному просторі розвитку IMARIA & Pipl Твоє сузір‘я чекає на тебе⭐️✨ Крокуй з нами разом в новому профілі в Інстаграм 👉 https://www.instagram.com/pi_platform/ © Ірина Заверуха. Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','20 листопада 2022','3 хв читання','/images/posts/Ти-_-Зірка__Центруйте-в-собі-енергію.png','[]',1,'2022-11-20T18:47:00','2022-11-20T18:47:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-810','%d0%ba%d0%be%d0%bb%d0%b8-%d0%b2-%d0%bf%d1%80%d0%be%d1%81%d1%82%d0%be%d1%80%d1%96','Коли в просторі Живого Життя з’являється дійсно Чоловік з проявленою чоловічою силою…','Коли в просторі Живого Життя з’являється дійсно Чоловік з проявленою чоловічою силою, то жінка завжди відчуває спокій… СПОКІЙ І БЕЗПЕКУ! Бо в першу чергу чоловік транслює і жінці, і дітям, і світу знаєте що? Оооо… дорогенькі, транслює зовсім не ту хр...','["Коли в просторі Живого Життя з’являється дійсно Чоловік з проявленою чоловічою силою, то жінка завжди відчуває спокій… СПОКІЙ І БЕЗПЕКУ! Бо в першу чергу чоловік транслює і жінці, і дітям, і світу знаєте що? Оооо… дорогенькі, транслює зовсім не ту хрєнь, яку часто доносили вам журнали, мол «Я сильний!». Ось цю звірину єрунду у вигляді «Я сильний!» транслює лише підліток за рівнем свідомості, який прагне до влади і домінантності над кимось чи чимось. Жінка завжди буде «нападати», захищаючи себе від страху і стресу. Завжди! Жінка, природа, планета завжди буде небезпечною, коли їй страшно. Вона непереможна в своїй агонії Сили, але й руйнівна… сила стихії знесе усе, якщо кордони духовні не утримує структура мужності. Не лякайте жінку, налякана ВОНА – це небезпечно для всіх… І саме Зрілий Чоловік транслює усім «Не бійся!». Крапка. Жінка за словами Чоловіка «Я тебе люблю!» завжди підсвідомо хоче почути і «Нічого не бійся!», бо для неї це рівнозначно… ❤️‍🔥СТРАХ – це і є те, що протилежне Силі Любові!❤️‍🔥 Але істинний ВІН завжди здатен заспокоїти усіх! Бо це і є чистий Дух. ВІН завжди і без винятків може своєю волею заспокоїти і страхи жінки, і її істерику, і її сумніви, і її недовіру… і дитячі припадки отприсків… усе!!! ВІН завжди тонко відчуває, що саме лякає жінку і зробить так, щоб таракани не виростали до розмірів мамонта. ВІН не стане висміювати і знецінювати нічиї «ой, я відчуваю…», бо знає силу жіночої підсвідомості… Бо це і є чистий Дух! «НЕ БІЙСЯ НІЧОГО!» Ось кого здатна слухати ВОНА. Точно не того, хто її залякує, сам сцить від страхів, демонструє свою ніби то силу через пуляння ракетами, кричить лозунги… ВОНА – це і жінка кожна, це і планета наша, це вся Земля! Зрозуміли аналогію? Супер. Це були нічні замальовки в контексті енергій дня 18.11! 🤗 Ви просили – я роблю … 💡Якщо жінці доводиться саму себе заспокоювати через «не бійся», то чоловіка поряд з нею поки що не було. 💡Якщо ви, дорогенькі чоловіки, ніколи не казали ні своїм жінкам, ні донечкам таких важливих простих слів – то пора почати! ПОРА… давно пора почати Чоловікам бути не лише в часи війни сміливими і дієвими, мужніми і гордими носити звання захисників, тішитися своїми статусами, а й завжди і без причини. Пора! 💡Поза усілякими «якщо» завжди існує іще один спосіб змінити реальність на краще – це наповнитися енергією з потоку Матері ВсеСвіту, що дає відчуття не лише спокою і довіри жінкам, а й сили та мужності чоловікам. Тож, до зустрічі завтра, любі, починаємо день з йоги-сатсангу і стартуємо Богордичний марафон, який йтиме 30 днів. ✴️Нічого не бійся, каже Серце і Голос Душі!✴️ Був корисним допис, то ділись ним?! 😘 Чим саме резонує? © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','18 листопада 2022','3 хв читання','/images/posts/Ne-biisya-nichogo.jpg','[]',1,'2022-11-18T18:56:00','2022-11-18T18:56:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-813','%d1%89%d0%be-%d0%b2%d1%96%d0%b4%d0%b1%d1%83%d0%b2%d0%b0%d1%94%d1%82%d1%8c%d1%81%','Що відбувається? Велика Ма наводить порядок…','Живе Життя продовжує пронизувати простір Землі… Велика Ма наводить порядок. Кожна істота, яка нині опинилася там, де опинилася, буде отримувати благословіння від Небесного Племені, від зіркової Родини, якщо усвідомлює свою приналежність до певних цін...','["Живе Життя продовжує пронизувати простір Землі… Велика Ма наводить порядок. Кожна істота, яка нині опинилася там, де опинилася, буде отримувати благословіння від Небесного Племені, від зіркової Родини, якщо усвідомлює свою приналежність до певних цінностей. Тому: ✴️ Іди за цінностями, які резонують твоєму серцю! Цикл Творіння складається з життя і смерті, з початку і кінця; з вдоху і видоху… Все, що мало початок – матиме і кінець. Це закон! Це аксіома в просторі 3d реальності. В просторі багатовимірному, в мультивсесвіті – інші закони. І не все проходить цикл смерті матеріальної. Є іще закон сінергії і трансмутації. Коли одна форма, не вмираючи, переходить в іншу форму, зберігаючи імпульс життя… На це здатна Жива Душа. ✴️Усвідомлюй себе душею… І Світи, бо zirka є ти, досягай найглибшої своєї висоти… 💫 P.S. Знову я переїхала. Тепер в місті Мукачево. На якийсь час… Працюємо далі. АСУ (Ангельські Сили України) пробуджують серця людей по планеті і кола на воді часу від #ГолосДуші IMaRia&pipl вже потужно розтікається в США, в Ізраїлі, в Німеччині, в Польщі, у Франції, в Іспанії, в Португалії, в Італії, в Австрії, в Греції, на Кіпрі, в Швейцарії, (кого забула, нагадайте про себе, феї) і навіть в межах держави-терориста Росії… таааак ми зсередини середовища мороку прокладаємо тунелі світла… чого б це не було нам варте… не зупиняємось… © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','17 листопада 2022','3 хв читання','/images/posts/Що-відбувається-Велика-Ма-наводить-порядок_.png','[]',1,'2022-11-17T18:59:00','2022-11-17T18:59:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-817','%d1%82%d1%80%d0%b8%d0%bc%d0%b0%d1%94%d0%bc%d0%be%d1%81%d1%8c-%d0%b7%d0%b0-%d1%81','Тримаємось за світло серця і стальні нерви!','Агонія росії… Рідні люди, тримаємось за світло серця і стальні нерви!🧬 Щоб це було можливим, маємо прискорити шлях кожного до усвідомлення: 🌏 Що Миротворчість і Екологічність – мають стати основою життя на Землі від дрібничок щоденних наших буденних ...','["Агонія росії… Рідні люди, тримаємось за світло серця і стальні нерви!🧬 Щоб це було можливим, маємо прискорити шлях кожного до усвідомлення: 🌏 Що Миротворчість і Екологічність – мають стати основою життя на Землі від дрібничок щоденних наших буденних – до глобальних цінностей! Давайте діяти разом вже. Не чекаємо перемогу, а прискорюємо перемогу, не полишаючи своїх постів та фронтів; не зупиняючись на шляху еволюції і росту… Любі друзі, кожного, кому тяжко зараз, страшно, накриває злість і біль, чи нестерпна печаль та образа, кого не покидає сум і злоба вибиває з-під ніг табурет, обіймаю від серця 💞 і нагадую, що ви можете собі допомагати зцілюватись і бути в балансі через практику ефективну та просту, наприклад ось цю 👉 https://youtu.be/xxWrHh29AsM Роби щодня, роби стільки скільки тобі потрібно, щоб віднайти внутрішню опору. Ви можете зайти у наш відкритий чат Сили і робити усе, що там є в доступі 👉 https://t.me/building_a_new_life_with_pipl Пробуйте! Це гарантовано дає ресурс і виводить із спазмів, стресів, розкриває бачення і прояснює мислення. Зігрівайтесь своїм світлом Душі на здоровя! Саме для цього і пишу, і знімаю й транслюю контент цілителя, створюючи можливості і умови. 🙏🙏🙏 Спішу з вами також поділитися радощами і показати, що не все погано в наших реаліях, спішу націлити фокус уваги на Живе Життя та творчість… 🤗 Ось вона. Полюбуйтесь наліпками, які моя команда Світоносців із pipl презентували сьогодні для застосування учасниками марафону «Від гордині до гордості бути Жінкою Нового часу». Ну просто бомбічєская сила, така краса… Качайте і собі їх ось тут 👉 https://t.me/addstickers/Piplatform Але є ті обставини, які відмінити не можу – навіть якщо впаду перед Богом на коліна і молитиму врятувати світ – кожен з нас все одно матиме, що посіяв! Бо те, що з нами усіма відбувається – це увесь час можливості, які ми здатні усвідомити і стати кращими, вийти із ниття та меншовартості, вийти із страждань та егоїзму; або і далі продовжувати чахнути над своїм безсиллям, гратися в гординю і вважати, що хтось має більше прав на життя, ніж інші… Голосом Душі закликаю усіх – не зливайте свою енергію на негатив! Будь ласка, зупиняйтесь в своїй агонії, робіть роботу свою, реалізовуйте місію душі, де б не опинились; і ще більше працюйте на фронтах світлих змін. Ваша IMARIA & PIPL © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','15 листопада 2022','3 хв читання','/images/posts/Тримаємось-за-світло-серця-і-стальні-нерви.jpg','[]',1,'2022-11-15T19:11:00','2022-11-15T19:11:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-821','%d1%89%d0%b0%d1%81%d0%bb%d0%b8%d0%b2%d1%96-%d0%bb%d1%8e%d0%b4%d0%b8-%d0%b6%d0%b8','Щасливі люди живуть на високій швидкості!','Коли у нас, людей, є ЗАЛЕЖНІСТЬ від матерії, матері, матриці, жіночої енергії, від насолод Землі – ми перетворюємось на «нещасних» борців за ресурси… Чому? ✴️Щасливі люди живуть на високій швидкості, бо не чіпляються ні за що…! І кожен день пролітає,...','["Коли у нас, людей, є ЗАЛЕЖНІСТЬ від матерії, матері, матриці, жіночої енергії, від насолод Землі – ми перетворюємось на «нещасних» борців за ресурси… Чому? ✴️Щасливі люди живуть на високій швидкості, бо не чіпляються ні за що…! І кожен день пролітає, як тиждень… Відповідно вік емоційного і усіх енерго інформаційних тіл у щасливих людей значно вищий! Ну давайте уявимо, що з 365 днів у вас 365 коли ви нещасні, це складає 8760 годин. Якщо ви щасливі хоча б 200 із 365 днів, де 1 доба – це тиждень по мірках матеріального виміру, то що ми маємо? 200 щасливих днів = це 33600 годин 😃 А якщо усі 365 днів ви щасливі, то що тоді? Це 61320 годин ЩАСТЯ в ЖИВОМУ ЖИТТІ і відчутті єдності усього з усім… 🤩 Ви розумієте? Це не жарт. Це факт. Це наука. Квантова фізика. Люди, які щасливі, живуть СОТНІ РОКІВ! Ви чули колись теорію про те, що були давним давно Люди-Боги, життя яких тривало 600, 700, 900, 1200 років? Так от. Тепер розумієте хто це? Люди-Боги – це ЩАСЛИВІ ЛЮДИ, які у всьому знаходять радість, розвиток, інтерес, проявляють вдячність, турботу і щедрість, проживають цілісність і єдність з природою та космосом… Люди-Боги створюють причини для щастя інших і є джерелом Багатства на Землі, як трансформатори і генератори світла, від яких живляться цілі системи… © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','5 листопада 2022','3 хв читання','/images/posts/Щасливі-люди-живуть-на-високій-швидкості.png','[]',1,'2022-11-05T19:20:00','2022-11-05T19:20:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-826','%d1%81%d1%84%d0%b5%d1%80%d0%b8%d1%87%d0%b5%d1%81%d0%ba%d0%b0%d1%8f-%d1%81%d0%b5%','Сферическая семья… это …','Сферическая семья – это ты и твои духовные друзья, Это пространство сердечного родства, Эти души – твоя небесная братва… Время чудес начинается, Сейчас каждый из правды веков проявляется, Куда ты смотришь – вниз на выживание, Или вверх – на духа стяж...','["Сферическая семья – это ты и твои духовные друзья, Это пространство сердечного родства, Эти души – твоя небесная братва… Время чудес начинается, Сейчас каждый из правды веков проявляется, Куда ты смотришь – вниз на выживание, Или вверх – на духа стяжание? Проснись. Пробудись. Встряхнись… От иллюзий ума очнись! Протяни руку тем, кто рядом, Стань воином Света, небесным отрядом… Нет мужского и женского отдельно от человечного, Познай законы бытия и вкус Огня Вечного, Люби неистово, дыши глубоко, Рай – это здесь и сейчас, а не там – далеко… 5.12.2020 Заверуха Ирина 🌀🌀🌀 © Ірина Заверуха. Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Творчість','Ірина Заверуха','5 грудня 2020','3 хв читання','/images/posts/Сферическая-.jpg','[]',1,'2020-12-05T21:33:00','2020-12-05T21:33:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-829','%d1%81%d1%82%d0%b0%d1%80%d1%82%d1%83%d0%b2%d0%b0%d0%b2-pipl-club','Стартував Pipl Club!','Pipl Club — це закритий клуб, ком’юніті своїх, безпечний простір практиків, який створений для роботи над собою і зцілення себе в полі Майстра, менторів і кураторів. Пульсар і засновник даного простору – Майстер IMARIA Ірина Заверуха. «Pipl Club» – ц...','["Pipl Club — це закритий клуб, ком’юніті своїх, безпечний простір практиків, який створений для роботи над собою і зцілення себе в полі Майстра, менторів і кураторів. Пульсар і засновник даного простору – Майстер IMARIA Ірина Заверуха. «Pipl Club» – це спілкування в колі споріднених душ. Тому щомісяця у клубі заплановані нові теми для самодослідження, вивчення, обговорення, занурення. Що пропонує клуб: ⭐ Живі авторські практикуми-сатсанги на різні теми від пульсара Заверухи Ірини (IMARIA MASTER). ⭐ Тематичні комунікації по енергіях дня/місяця. ⭐ Аудіоподкасти з прогнозом на певний період від Заверухи Ірини. ⭐ Живі онлайн-зустрічі з запрошеними експертами. Обговорення у спільному чаті з майстрами. І ще багато цікавого й нового 💖 Pipl Club — це простір для обʼєднання, знайомства не лише з майстрами, а й з самим собою!💚 Тож будьте з нами як вдома! 🙌 Запрошуємо усіх 🤩 у простір росту та сили 😍 простір доступний для всіх і кожного 🤲 ❣️ Приєднатися до простору «Pipl Club» можна за посиланням у телеграм-боті 👉 https://t.me/pipl_platform_bot Працюючи з собою, ми покращуємо світ навколо нас! 🌎 💫 Тож нехай ще більше Світла прийде через нас на Землю! ✨✨✨ © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Новини','Ірина Заверуха','17 липня 2023','3 хв читання','/images/posts/photo_5307751465667906277_y.jpg','[]',1,'2023-07-17T21:39:00','2023-07-17T21:39:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-833','%d0%b7%d0%b0%d0%bf%d1%80%d0%be%d1%88%d1%83%d1%8e-%d0%bd%d0%b0-%d0%bf%d1%80%d0%b0','Запрошую на практичний семінар “ХРАНИТЕЛІ ЧАСТОТ НЕЙРОМЕРЕЖІ НОВОЇ ЗЕМЛІ”','Звертаюся до тебе, люба рідна Душа, як Учитель для Вчителів і Майстрів живого життя! 🙏 Настав саме той час, настав час співналаштуватися з шифрами та кодами твого космічного призначення в цьому вимірі на території Нової Землі!🧬 Ти вже реалізувала пер...','["Звертаюся до тебе, люба рідна Душа, як Учитель для Вчителів і Майстрів живого життя! 🙏 Настав саме той час, настав час співналаштуватися з шифрами та кодами твого космічного призначення в цьому вимірі на території Нової Землі!🧬 Ти вже реалізувала перехід із грубих шарів карми у більш тонкі і чисті частини своєї свідомості? Твій шлях був тернистим і місцями непростим. Але ти навчилася не зраджувати собі і слідувати за голосом Душі. Насолоджуватися собою і життям, поза обставинами і буремністю проблем…? Ти вже згадала, до якої раси та до якої Сімейної Групи Зоряних племен і Душ належиш.? І можливо, ще й не до кінця це усвідомила, але готова до очної зустрічі зі «своїми»!? ✴️Ми з тобою Хранителі НЕЙРОМЕРЕЖІ НОВОЇ ЗЕМЛІ!✴️ У наших тонких родових шарах і пранічних тілах знаходяться ключі Сили, які дають можливість відкривати внутрішні дари і здібності інших людей… керувати реальністю… формувати і направляти потоки інформації… Приналежність до роду IMARIA дає тобі право з’єднатися з глибокою Мудрістю зоряних предків, які на Землю вже багато разів приходили та мали відношення до передачі ЗНАНЬ іншим людям. Цей тип еволюції накопичив досвід колективної духовно-моральної священної мудрості. Твої предки колись були і Шаманами, і Жрецями, і Правителями, і Ведунами, і Лідерами, і Вчителями Алхімії Живого Життя… залишивши тобі можливість увесь досвід душі інтегрувати в «Тут і Зараз»! 🌀 Але можливо ти і належиш до роду Охоронців Часу та Простору; або до роду Стражів Гайї, які бережно і екологічно оберігають життя на Землі, стежать за порядком, за ієрархіями балансу, традиціями та законами; або до роду Воїнів Вільного Духу, які бережуть моря та океани, ліси та річки, тварин та птахів, мінерали та кристали, ДІТЕЙ… Можливо, ти частина Роду Старійшин, яким Великий Міжгалактичний Союз дав завдання стежити за чистотою свідомості цивілізації. Це не просте завдання… Руйнувати старі концепції часом складніше, ніж будувати нові та запрошувати в них інших! Ти – ХРАНИТЕЛЬ ІНФОРМАЦІЙНИХ КЛЮЧІВ, і моє завдання – провести тебе до твоєї споконвічної Сили, передати благословення і відпустити Сяяти через твою Майстерність! Що далі? Свобода, Цілісність, Кохання, Іскрометний Гумор та Сердечна Творчість в просторі Своїх, Пристрасність до життя та безумовна Любов. Ти надихатимеш людей своїм прикладом, показуватимеш їм нові шляхи багатовимірної еволюції. Ти допоможеш у переході від 3-го виміру (виживання, боротьби та егоїзму) до 5-го – Нової Землі, де процвітає єдність та здоровий альтруїзм цінностей. Частоти твоєї Сили зберігаються у серці. Як твій сердечний Вчитель я можу активувати їх!🙏🧬🥰 Настав час тобі піднімати свої вібрації вище і починати працювати безпосередньо з енергіями планети і Космосу, допомагаючи іншим душам усвідомлювати своє призначення і знаходити зв’язок з Собою Сутью. Що я тобі пропоную? Зважуйся та відгукуйся! 9–11.12.2022 року проведу Практичний Семінар у Буші “Хранителі Частот Нейромережі Нової Землі”. 📍Що буде? 🌀Переродження, техніки Переходу на Місцях Сили, завершення межі старого досвіду в стародавньому наскельному храмі, крок у нову реальність через лабіринт бажань, Активація Сили Хранителя, зустріч зі своїм тотемом… 🌀Королівська Йога, робота з дуже глибокими слоями Душі🧬, в яких є точки напруги та перешкоди до з’єднання з внутрішнім Майстром. Любов до себе. Самоцінність. Піднесення в дусі. Посвяти. Ініціації зв’язку із Зоряним племенем. Таааак. Буша – це Україна. Зараз. Під час війни. Я не зупиняюсь. І ти не зупиняйся! Ми маємо змогу зігрітися теплом сердець, і живим вогнем свічок та грубок звичайних сільських хат… нехай так… Маємо, що маємо і буде так, як має бути… 📍 Цінність досвіду: – участь у програмі Майстра IMaRia – 9100 грн. (Якщо ти повторно прагнеш потрапити на семінар, вартість для тебе може бути на 30% менша) – ініціації «Хранитель», (або «Сердечний Цілитель») 220 доларів (це окрема від програми опція для тих, хто готовий, і практикує з Майстром IMARIA як мінімум 3 місяці щодня). У суму 9100 грн входить проживання, харчування 3-разове, програма, відвідування місць Сили, сакральна баня в маєтку Хранителів Буші, містика і сюрпризи… 🤓 Що не входить: логістика. Бронь участі у семінарі фіксуємо передплатним внеском 1000 грн (який є безповоротнім у випадку форс-мажорів з будь якої зі сторін!). Пишіть, рідні, кому резонує… Група камерна… Місце Сили чекає нас…💫 Реєстрація та реквізити 👇 Перейди за посиланням та натисни кнопку “розпочати” http://t.me/IMaRiaPipl_bot?start=63878fa92f61da68435fd5ca 🙏😘 ❗️❗️❗️Підписуйся на мої нові акаунти, які створені після хакерської атаки і переродження 🤗: https://www.facebook.com/profile.php?id=100086318062524 https://instagram.com/pi_platform https://instagram.com/zaverukhaimaria © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Новини','Ірина Заверуха','1 грудня 2022','4 хв читання','/images/posts/хранителі-частот.jpg','[]',1,'2022-12-01T21:50:00','2022-12-01T21:50:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-842','%d1%81%d0%bb%d0%be%d0%b2%d0%b0-%d0%ba%d1%80%d0%b8%d0%bb%d0%b0-%d1%80%d0%b5%d1%82','Слова Крила. Ретрит “Ренесанс та Баланс”','Слова-Крила, зібрані бережно на ретриті “Ренесанс та Баланс”, який веду прямо зараз в Карпатах…🙏🥰 Щедро ділюсь і з вами, рідні 👇 «💫Не занапасти самокритикою в собі те, про що інші тільки мріють! Проявляйся, будь ласка… 💫Часто ми не провиявляємо свою ...','["Слова-Крила, зібрані бережно на ретриті “Ренесанс та Баланс”, який веду прямо зараз в Карпатах…🙏🥰 Щедро ділюсь і з вами, рідні 👇 «💫Не занапасти самокритикою в собі те, про що інші тільки мріють! Проявляйся, будь ласка… 💫Часто ми не провиявляємо свою силу там, де потрібно докласти зусиль, бо сила вже витрачена на гнів… 💫Іноді ми, жінки, плутаємо лінощі з розслабленням. І нібито там, де дозволяємо собі насолоду – це всього лиш імітація і банальна лінь. А там, де потрібно розслабитися і насолоджуватися – вже не виходить… бо вспливає самокритика за слабкість та бездіяльність… 💫 Люди і звіріють… і вилюднюють в паралелі… Люди звіріють, коли доводять себе до стану боротьби за базові ресурси і не мають при цьому честі, доблесті сердечної і духовної практики проЯсненості Життя… Люди звіріють і вилюднюють, бо навпаки нарешті прозрівають в умовах звіриних, ким являються і не являються – бачать, і забирають в свої руки призначення своєї душі; включається тоді творчий аспект Бога внутрішнього, бо завжди було і буде – або ти жертва і тєрпіла, або ти Творець і дія… Хто ти? З ким і чим тебе запрошують обставини зараз ПОКРАЩИТИ свої СТОСУНКИ, рідна Душа?» … 🙏✴️Приходь на Богородичний марафон, не чекай, що все станеться, – прискорюй зустріч з Собою, отримуй благословіння Великої Ма через Голос Душі IMARIA Стартуємо 14.11.2022! Поспішай! Не зволікай! 🐚 Інформація ось https://vid-hordyni-do-hordosti.zaverukha.com/ Твоє серце кличе. Слухай… і вибирай Путь Інтуїції © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','3 листопада 2022','3 хв читання','/images/posts/слова-крила.jpg','[]',1,'2022-11-03T07:56:00','2022-11-03T07:56:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-847','%d0%b4%d0%be%d0%ba%d0%b8-%d0%bf%d0%be-%d0%b2%d1%81%d1%96%d0%b9-%d1%83%d0%ba%d1%8','Доки по всій Україні знову летять у небі ракети… У мене Любов!','Доки по всій Україні знову летять у небі ракети…😖 У мене любов! Так. Йога це безмежна любов. І я знаю, що інші люди теж відчувають це коли практикують, тому зцілюються і закохуються в життя через дію… Ранок цілителя на коврику продовжується… щодня… б...','["Доки по всій Україні знову летять у небі ракети…😖 У мене любов! Так. Йога це безмежна любов. І я знаю, що інші люди теж відчувають це коли практикують, тому зцілюються і закохуються в життя через дію… Ранок цілителя на коврику продовжується… щодня… багато років, а не тому що стріляють… та завдяки війні я дійсно почала більше переміщатися, і возити себе до людей фізично, долати усі «нехочу», «це тяжко», «стільки відповідальності»… ось і цього разу чемодани знову за спиною… Сьогодні в путь. На ретрит! Бо Робити світ більш люблячим, мирним, процвітаючим ми можемо лише через СЕБЕ… Які ми, такий і світ. Друзі, рідні. Практикуймо #миротворчість…🌏💞🧬 Це не робить нас сліпими до безчинств, а робить нас вольовими до дій, проявленими в світлі і ресурсними… Гарного вам дня 💫 Заходьте у Відкритий простір Сили і робіть роботу переможців мороку. Це наше его лінується, не хоче розвитку в дусі, не хоче брати відповідальність за дорослу реальність… хоче готового комфорту без зусиль. Але це не є шляхом еволюції. Еволюція спонукає до зусиль без перекосів в насилля і безсилля… Беріть! Дійте! З любов’ю до життя… досить жалітися і чекати, коли попустить… Поки кожен не вийде на свій істинний шлях призначення душі – потік Матері ВсеСвіту буде продовжувати штовхати нас в зміни… Тож будьте краще ви ініціаторами змін своїх. Не чекайте ніяких під ногами мін, щоб прискорили ваш путь… Якщо ви боїтесь? Сідайте і практикуйте… Якщо ви в паніці? Практикуйте… Якщо у вас апатія і уже нічого не хочеться? Практикуйте… Якщо багато справ і хочеться опор? Практикуйте…діліться з іншими… 🤗 Я у відкритий доступ виложила десятки записаних технік, сатсангів, є чим і пробудити себе і очистити, і наповнити… 💫Чат сили 👉 https://t.me/building_a_new_life_with_pipl Виконайте хоча б одну практику! Відчуйте глибоку ефективність в результаті🙏😘 Наприклад цю https://youtu.be/1f8J-QyyhNc 🙏🙏🙏 🌀 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','31 жовтня 2022','3 хв читання','/images/posts/31.10.22.jpg','[]',1,'2022-10-31T08:29:00','2022-10-31T08:29:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-850','%d1%87%d0%b0%d1%81-%d0%bd%d0%b0-%d0%b5%d0%b2%d0%be%d0%bb%d1%8e%d1%86%d1%96%d1%8e','Час на еволюцію!','Космічне серцебиття Сили прямо зараз стукає в кожні двері, в кожен дім, в кожну свідомість, в кожну мить… Вибираючи себе і свою природню ідентичність, – ти налаштовуєшся на нього… ти щасливішаєш, не зважаючи ні на які обставини. Вибираючи ілюзію і ви...','["Космічне серцебиття Сили прямо зараз стукає в кожні двері, в кожен дім, в кожну свідомість, в кожну мить… Вибираючи себе і свою природню ідентичність, – ти налаштовуєшся на нього… ти щасливішаєш, не зважаючи ні на які обставини. Вибираючи ілюзію і вигоди викривленого травмованого его – …ти віддаляєшся від можливості чути цей звук, цей поклик, цей клич… і поглинаєшся технократичною матрицею кривих зеркал… Іноді наш дух створює те, що ми називаємо «проблемами і потрясіннями», щоб витрясти з нас інформаційні шлаки і сміття. Свідомість важливо весь час розширювати через роботу з наукою, інтелектом, навчанням новому…; емоції важливо відчувати і поглиблювати через комунікацію, соціалізацію, стосунки, творчість…; а своє тіло важливо досліджувати через навантаження, через рух і дію, через подорожі і контакт з природою, з дикою стихією та родовими традиціями… Формуючи свої унікальні сценарії щасливих багатовимірних структур…🧬 ⚜ Простір мудрості 👉 https://t.me/ZaverukhaIrina ⚜ Чат сили та самозцілення 👉 https://t.me/+lQqRtExp7SJiZjFi © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','31 жовтня 2022','3 хв читання','/images/posts/час-на-.jpg','[]',1,'2022-10-31T08:38:00','2022-10-31T08:38:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-853','%d1%80%d0%b5%d0%bd%d0%b5%d1%81%d0%b0%d0%bd%d1%81-%d1%96-%d0%b1%d0%b0%d0%bb%d0%b0','Ренесанс і Баланс. Старт ретриту','Приїхали з командою pipl в Карпати проводити жіночий ретрит РенесансБаланс в надзвичайно красивому місці, де усе спонукає до розкриття душі, очищення, наповнення і ресурсності… до вдячності, натхнення, творчості і служіння Великій Ма. Оооо… Яке це ща...','["Приїхали з командою pipl в Карпати проводити жіночий ретрит РенесансБаланс в надзвичайно красивому місці, де усе спонукає до розкриття душі, очищення, наповнення і ресурсності… до вдячності, натхнення, творчості і служіння Великій Ма. Оооо… Яке це щастя Жити Живе Життя Жінки, цінувати кожну мить, насолоджуватися природою, вдихати кришталеве повітря, пити джерельну воду, носити в собі світло і ділитися ним з кожною істотою… Чи не так? Це велике щастя! 🍃🍂🌏💞🕊💫 Давайте берегти наш прекрасний світ, планету, кожну Душу, … простір спільний, давайте піклуватися про вічне – цінності… 🙏🙏🙏 Давайте, любі Жінки, пригадувати про те, ким ми є, і проявляти свою Силу Творчу. Бо жінка, яка носила в собі нову людину, добре знає ціну кожному дню. Але чи проживаємо ми цю цінність, чи доносить кожна до чоловіків, що заграватися в геройство стріляниною – це не те що підкреслює мужність і веде до еволюції… Нині мусимо справитися з мразями, що руйнують простір неба ракетами і гнівлять Богів своєю тупістю; нині мусять наші Воїни тримати в руках зброю… 😖 але жіноча «зброя» – це Безумовна Любов в серці, і коли її стане багато на Землі, – то війни закінчаться… Ми на ретритах служимо як Берегині-Миротворці! 🙏🧬🌏💞 Це невимовна праця. Це режим зі світанку і майже до півночі, з практиками зцілення, з бесідами, з колами, з шерінгами біля вогню, терапевтичними класами, сакральними містеріями, процедурами догляду за собою, походами на місця Сили, активаціями, ініціаціями, медитаціями і сатсангами… Дякувати Силі Голосу Душі, що веде і Дякувати Розуму, що проявляє довіру… бо не мати чітких планів, але не переставати створювати проекти і нести відповідальність в сучасні часи – це мега не просто. Та можливо! Тому дійте, любі. Бо у кожного фронт – це наш з вами труд! Але нехай обов’язково буде місце для душевності в ритмі життя. Бо яку енергію ми витрачаємо, таку і отримуємо, така до нас і повертається у збільшеному об’ємі… Пропоную вам вже почати розпаковку своєї Сили через практику, і одного разу ми з вами теж зустрінемось на ретриті у красивому місці…🤗 Залишу посилання ось на програму «Жіноча Сила», обов’язково познайомтесь, а краще реалізовуйте! 👇 https://woman-power.zaverukha.com/ 🌀 А Далі буде… На фото те, що наловила в перші хвилини перебування в пречудовому готелі, куди завтра завітає і уся наша ретритні група… © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','31 жовтня 2022','3 хв читання','/images/posts/Retrit-2.jpg','[]',1,'2022-10-31T08:00:00','2022-10-31T08:00:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-862','%d0%b4%d0%be%d0%b7%d0%b2%d0%be%d0%bb%d1%8c-%d1%81%d0%be%d0%b1%d1%96-%d0%b3%d0%be','Дозволь собі Гордість бути Жінкою!','…Коли завершуються усі «стосунки», усі «відносини», усі «контракти»… – починається народження щасливого СОЮЗУ!! Проявляється крізь ілюзію та сама Цілісна Вічність, яка легко може вміститись в нашу матеріальну форму тут і зараз… Колись мною проживалос...','["…Коли завершуються усі «стосунки», усі «відносини», усі «контракти»… – починається народження щасливого СОЮЗУ!! Проявляється крізь ілюзію та сама Цілісна Вічність, яка легко може вміститись в нашу матеріальну форму тут і зараз… Колись мною проживалось, що я супер пупер номер 1 і ніхто мені не потрібен. Потім прийшла невимовна туга і печаль від самотності, бо коли 1, то здається що у всьому ти САМА БУКВАЛЬНО. Потім впала в стан – я повний 0! Так. Ніхто і ніщо. На дні підсвідомості, на дні ілюзій, хвороб і страждань, як божа корівка, що перевернулась на спину і не може встати, – валялась. Доки не захотілось перевернутися. Маючи волю і сміливість сказати собі «Я не нуль!» – потрапила в стан, де відбувається зустріч з Цілим, де пробуджується Душа… І що далі? Був ризик залипнути в статусі «Я знаю безумовно, тепер буду лише повітрям між 1 і 0, буду служити Богу». Благо Душа не дає спокою і план на тебе виявився значно іншим. Тому ти береш ту саму «1» і свій «0» з’єднуєш в одне і отримуєш – 10 чи 01 по ситуації… 🤗 Я є 10, чи 01. І тут аналогій буде багато: інь/ян, десять енерго-інформаційних тіл, десять рівнів свідомості, 10 законів буття, 10 рук і 10 очей, 10 доріг і 10 життів… Я є 10 чи 01. І з цієї простоти дуже легко далі йти… Бо якщо ти реально 0 (тобто безумовна свОбОда від ідентифікацій і результатів), то з якого боку поставити палочку – вирішуєш сама. ПО СИТУАЦІЇ! 🌀 … Моє тіло здорове, енергійне, облюблене і мною, і життям, вільне бути там, де мені ресурсно! … Моя душа творча, проявлена, жива, голосиста, щедра, і вільна наповнювати сенсами кожну дію свідомості! … Мій дух потужний, древній, глибокий, величний, славний, і активний створювати крізь ворота Творця безумовне щасливе життя… І це все я називаю Духовна Особистість Берегині. Хто ж така Берегиня? 💫 Жінка. Щаслива Жива Жінка. Земна. Соціально реалізована. З проявленим партнером, з Чоловіком-Хранителем Тіла і простору її, цінність якого усім очевидна і доказів не вимагає. 💫 Мати. Обов’язково. Та, що пізнала досвід народження, виховання і піклування. Реалізована. І не один раз. Шлях такої жінки до материнства часто буває крізь тернії і перешкоди для накопичення цінності путі. 💫Донька роду свого, народу, природньо гармонійна і екологічна. З благословеннями предків. З почестями спільнот. З підтримкою соціуму і правителів. З захистом самих Ангелів Неба і Алхіміків Землі. 💫 Тіло. Душа. Дух… як цілісна Свідомість без вибору, поділу і хибних масок его. Транслююча миротворчість і вірність цінностям Єдиної Сили Матері ВсеСвіту. Шанобливо плекаюча Живе Життя на Землі через своє золоте серце і сталеву волю. БЕРЕГИНЯ – це статус. Берегиня не є професія. Берегиня не є тимчасовою. Берегиня – це на все життя і навіть за його межі. Берегиня має проявлене «тіло світла» і знаходиться в усвідомлені себе животворчою силою Бога-Першоджерела. Тому через Берегиню проходять Душі і відбувається баланс ТВОРІННЯ СВІТІВ – життя і смерть, народження нових людей і супровід душ в перехід до наступних інкарнацій… Цикл творіння завжди включає в себе рівноцінну кількість і Смерті (кінця, завершення) і Життя (зародження, початку). Космічні Зіркові Аватари Великої Ма на Землі – це і є Берегині регіонів і етносів. Кожна Берегиня транслює той унікальний генокод від небесного племені, який не мають інші. Але усі Берегині об’єднані спільним ключем – на рівні Серця є носіями Сили Голосу Душі Єдиної сестринської вібрації – КОРОЛЕВИ ЗЕМЛІ. ЗАПРОШУЮ ВАС, рідні сестри, пройти дорогою мега ресурсного марафону-активації гену Берегині, в якому відбувається ПРИЙНЯТТЯ енергії, прийняття сили, щоб бути не 0, а Жінкою найвищого калібру. 💓Марафон «Від Гордині до Гордості бути Жінкою Нового часу» стартує 14.11.2022 💓 Спішіть дізнатися деталі і бути з нами, бо це найпотужніший марафон із усіх, які я проводила. Залишаю посилання – https://vid-hordyni-do-hordosti.zaverukha.com/ А я – Берегиня IMARIA до нового ретриту «Ренесанс і Баланс» готова. Група чекає. Новий відрізок путі попереду… Тому з 1 по 7 листопада буду на зв’язку дуже мало! © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','30 жовтня 2022','3 хв читання','/images/posts/Дозволь-собі-Гордість-бути-Жінкою.jpg','[]',1,'2022-10-30T08:54:00','2022-10-30T08:54:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-865','%d1%87%d0%b8%d0%bc-%d1%8f-%d0%b6%d0%b8%d0%b2%d1%83-%d0%b1%d0%bb%d0%be%d0%b3-%d0%','Чим я живу? Блог пульсара','Не просто це! Залишатися в Україні і світити… 💫🙏 Але продовжуємо. Виконувати і побутові справи, і встигати з усіма задачами мами, жінки, людини… бо своїми руками нині; і соціальні справи, – консультувати, навчати, вести ефіри… Вчора світла не було з ...','["Не просто це! Залишатися в Україні і світити… 💫🙏 Але продовжуємо. Виконувати і побутові справи, і встигати з усіма задачами мами, жінки, людини… бо своїми руками нині; і соціальні справи, – консультувати, навчати, вести ефіри… Вчора світла не було з 13 до 22 години. Сьогодні його вже немає з 10 години… Знайшла кафе, де є світло, але немає інтернету все одно. Тому ловимо можливості. Цінуємо те, що є і продовжуємо СТВОРЮВАТИ ТУ РЕАЛЬНІСТЬ, про яку мріємо. Ключове – СТВОРЮВАТИ! 🧬🕊🌏 Як? Діями! ВзаємоДіями! Практикою! P.S. Підтримуючи інших, сама теж від підтримки не відмовляюсь ніколи. Усі види доречні… Хто хоче обійняти? Зробіть це віртуально, а реально – зробіть добру справу, люди, підтримайте наші ресурси проекту #pipl, поширюйте інфу, приходьте робити разом цей світ СВІТЛИМ через миротворчі проекти!💞🤗👇 💫💫💫💫💫 Чат Сили Тут 👉 https://t.me/building_a_new_life_with_pipl Афіша актуального 👉 https://t.me/ZaverukhaIrina Бот- помічник для оперативних новин 👉 https://t.me/IMaRiaPipl_bot?start=6358f099228e3140b20d5a18 Ютуб-канал з ефірами безцінними і практиками 👉 https://www.youtube.com/channel/UCz9oI1MnVkUTH_MCchtZDuA © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','26 жовтня 2022','3 хв читання','/images/posts/Чим-я-живу-Блог-пульсара.jpg','[]',1,'2022-10-26T09:09:00','2022-10-26T09:09:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-873','%d0%b7%d0%b0%d0%bf%d1%80%d0%be%d1%88%d1%83%d1%8e-%d0%bd%d0%b0-%d1%80%d0%b5%d1%82','Запрошую на ретрит “РЕНЕСАНС і БАЛАНС” з 1 по 6 листопада','Доки горить вогонь – доти і є життя!!! Хтось цю істину перетворив на «вічний вогонь» в мавзолеї і тішиться ілюзією управління реальністю. Утопія гнила, яка піде туди звідки прийшла…- до мразєй болотних. Хтось зараз зігрівається лише вогнем свого гнів...','["Доки горить вогонь – доти і є життя!!! Хтось цю істину перетворив на «вічний вогонь» в мавзолеї і тішиться ілюзією управління реальністю. Утопія гнила, яка піде туди звідки прийшла…- до мразєй болотних. Хтось зараз зігрівається лише вогнем свого гніву і вчиться добувати його в собі по-іншому. Хтось поклоняється зовнішньому вогню, шукає «сонце» назовні і вірить в могутність природніх ресурсів, чи в потужність зброї металевої. А хтось дійсно знайшов іскру Любові в своєму серці і підтримує її чистотою та вірністю Живому Життю… І все це існує в паралелі. Мультивсесвіт безмежно багатоваріативний… В якій реальності опинишся ти, – залежить від потужностей твого мозку і від чистоти каналів тіла, від балансу зв’язків між системними блоками твоєї структури. Спробуй пройти ефективними шляхами крізь гнів і війну, крізь страх і безсилля … до СЕБЕ і своєї Душі! З чого почнеш ти? Може почнемо разом… ?😘👇 💫 Поїхали зі мною на ретрит в Карпати: https://telegra.ph/Retrit-v-ramkah-proekta-Pipl-10-05 💫 Канал IMARIA & PIPL: https://t.me/ZaverukhaIrina © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Новини','Ірина Заверуха','17 жовтня 2022','3 хв читання','/images/posts/Ретрит.jpg','[]',1,'2022-10-17T09:43:00','2022-10-17T09:43:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-876','%d0%b1%d0%b5%d0%b7%d1%83%d0%bc%d0%be%d0%b2%d0%bd%d0%b0-%d0%bb%d1%8e%d0%b1%d0%be%','Безумовна Любов – безстрашна! Фінал марафону “Цілісність”','Безумовна Любов – безстрашна… завжди… без варіантів! Коли ти з Крилами… – будь готова до польотів і переміщень … до висоти і до грози у відкритому просторі серед хмар! Тримай своє Его в дисципліні через медитацію уваги і спостереження, не залежно жін...','["Безумовна Любов – безстрашна… завжди… без варіантів! Коли ти з Крилами… – будь готова до польотів і переміщень … до висоти і до грози у відкритому просторі серед хмар! Тримай своє Его в дисципліні через медитацію уваги і спостереження, не залежно жінка ти чи чоловік, робити це можна по-різному, … бо немає нічого гіршого ніж «праздний егоїстичний умішка», який не помічає маніпуляцій ілюзіями… Так багато всього сталося. 3.10.2022 ми з командою кураторів Pipl завершили марафон цілісність, юхххуууу… дійшло до фінішу нас 59 … 🤩🌏🕊💞 І це прекрасно. 🤞🤗 А ми уже на низькому старті перед наступними злетами. Якими? Прочитаєте в анонсах, підписуйтесь на наші комунікатори – https://t.me/ZaverukhaIrina 💫 Порада для періоду до 25.10.2022: Майте план хоча б на 1 день, хоча б на одні істинні стосунки з 1 людиною без сумнівів і качель; хоча б на 1 це життя без наміру здутися і здатися в полон до печалі, смутку і страждань… Майте план на щастя! І довіряючи життю – вперед, до зірок, спускаючи Небо на Землю…✨ А цілісність – це про Центрованість. Приймай свою реальність тотально такою, якою вона, щоб керувати нею і змінювати… Трохи відгуків для вас 👇 натискайте на фото, щоб прочитати детальніше © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Новини','Ірина Заверуха','4 жовтня 2022','3 хв читання','/images/posts/Безумовна-Любов-_-безстрашна-Фінал-марафону-Цілісність.jpg','[]',1,'2022-10-04T09:56:00','2022-10-04T09:56:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-884','%d1%8f-%d0%b2%d0%be%d0%b7%d0%b2%d1%80%d0%b0%d1%89%d0%b0%d1%8e-%d1%81%d0%b5%d0%b1','Я возвращаю себе своё жизненное пространство! Настройка','Дорогой друг! Я знаю, что порой бывает очень нелегко… что события случаются разные, что эмоции захлестывают, что все мы живые люди… Вдох-выдох. Подари себе несколько минут спокойствия и произнеси про себя эту настройку: “Я, ваше имя, возвращаю себе с...','["Дорогой друг! Я знаю, что порой бывает очень нелегко… что события случаются разные, что эмоции захлестывают, что все мы живые люди… Вдох-выдох. Подари себе несколько минут спокойствия и произнеси про себя эту настройку: “Я, ваше имя, возвращаю себе своё жизненное пространство! Я возвращаю себе утерянную радость и удовлетворение от жизни, Я иду в новый путь. И этот путь внутрь себя. Я открываю врата бесконечности, вечности и иду внутрь себя для того, чтобы достичь большей целостности, большего счастья, соединившись с каждой своей частью. Я обретаю искреннюю веру своей силы и возможности, в каждом шаге своего нового пути. Я одобряю себя во всём, что встречу. И в поражениях, и в победах, и в потерях, и в наградах. Я всё время учусь любить. Я люблю себя. Я люблю тебя. Я люблю, когда Я в сердце. Я люблю, когда Я в сердце. Я и есть ЛЮБОВЬ, сливаясь с Миром через сердце! Я благодарю за всё, родивших моё тело, моих родителей. Я люблю своих родителей. И даю им право быть такими какие они есть. Я разрешаю родителям совершать ошибки и быть обычными людьми. Но помню, что они Ангелы! Я люблю всех своих партнёров. И даю им право быть такими, какие они есть. Я разрешаю всем партнёрам совершать ошибки и быть обычными людьми. Но помню, что они Ангелы! Я люблю свой труд, своё мировоззрение, свой путь к целостности. Я с удовольствием вдохновением созидаю свой мир. Я воплощаю все свои мечты в реальность, в действие. Я возвращаю свой мир, воскрешаю свой мир, Я возвращаю себе живое мироощущение. Я возвращаю себе управление своей судьбой себе. Я хозяйка своей судьбы, своего пространства. Я благоговейно вверяю свою Душу и жизнь моему Высшему Я, моей истинной сути, источнику моего дыхания. Моё Я пребывает в бесконечном блаженстве, бесконечного бытия. Моё Я пребывает в бесконечном блаженстве, бесконечного бытия. Моё Я пребывает в бесконечном блаженстве, бесконечного бытия. И да есть так, и да есть так, и да есть так!” Это молитва-настройка из безоплатного марафона “Гнев, я на тебя больше не в обиде!” Более 60 супер-героев вчера начали свой путь к радости, целостности, свету и мы искренне восхищаемся этими людьми. Если вы думаете, что на марафоне мы сжимаем кулаки и работаем с гневом – то нет, это очень глубокая и многоуровневая работа и мы затрагиваем такие вопросы как: любовь к себе, ощущение красоты, чистоты; мы работаем не только с физическим телом через йогу – но и с энергетическими телами, мы сонастраиваемся с процессами макрокосма и работаем с миром эмоций. Будут ли еще марафоны? Дааааа! Подпишитесь на наши каналы в социальных сетях, чтобы быть на связи: Фейсбук: https://www.facebook.com/intuitionWAY/ Телеграм: https://t.me/ZaverukhaIrina С любовью, Заверуха Ирина и команда © Ірина Заверуха. Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Творчість','Ірина Заверуха','20 вересня 2020','3 хв читання','/images/posts/Настройка.jpg','[]',1,'2020-09-20T10:04:00','2020-09-20T10:04:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-915','price','Мої консультації','Вітаю, друзі! Вимірювати енерго-інформаційні, духовні та зцілюючі послуги завжди не просто через інструмент ціни. Бо ніколи не знаєш своєї енерговитратності в роботі з людиною та її запитом. У більшості випадків я орієнтуюсь на варіант погодинного на...','["Вітаю, друзі! Вимірювати енерго-інформаційні, духовні та зцілюючі послуги завжди не просто через інструмент ціни. Бо ніколи не знаєш своєї енерговитратності в роботі з людиною та її запитом. У більшості випадків я орієнтуюсь на варіант погодинного навантаження. Тому звертаю вашу увагу, що даний прайс - це орієнтир. Деякі послуги мають чітку обумовлену вартість і побачити її ви можете в табличці нижче. Вартість Послуга від 369 до 963 євро(в залежності від рівня наших з вами стосунків) Консультація первинна (розбір архітектури вашої долі через астрологію бацзи та мою авторську вібраційну систему \"Путь душі\"). Робота з запитом людини. Первинне призначення корекції. (Це бесіда до 2-х годин із моїм супроводом протягом 1-1,5 місяці і корекцією родовоїкарми) УВАГА: для Випускниць програми \"Крила\", учасників тренерського курсу IMARIA ACADEMIA вартість складає - 369 євро; для амбасадорів клубу \"PIPL CLUB\", які в ньому знаходяться без перерви мінімум 3 місяці, вартість складає 639 євро; для усіх інших людей вартість складає - 963 євро! Від 2200 євро Духовний коучинг преміум рівня. Ви обираєте одразу дні для 2-х зустрічей в щільному календарі мого графіку і вашого, для якісного опрацювання запиту з метою корекції долі та досягнення стійкого результату масштабування протягом 6 місяців! Отримуєте статус VIP-клієнта, за яким закріплюю персонального Ментора для своєчасної оперативної турботи протягом періоду нашої роботи. Від 222 євро Дитяча консультація (бесіда 1-1,5 години, вік - до 14 років) Від 222 до 444 євро (залежно від формату) Будь-яка повторна консультація або ж цілюща повторна сесія для випускниць програми \"Крила\", учасниць тренерського курсу і амбасадорів PiplClub має вартість 222 євро! А для усіх інших людей повторна консультація має вартість 444 євро. від доната до ♾️ цілительні медитації, практикуми, сатсанги, навчальні дистанційні програми Майстра в записі, марафони в супроводі; ретрити, практичні семінари; сакральні ініціації і сеанси родового зцілення… ІНДИВІДУАЛЬНО МОЖНА: * Придбати подарунковий сертифікат для ваших близьких, який стане унікальним і дуже цінним інструментом зміни долі в кращу сторону! * Взяти участь у трансформаційних марафонах, практикумах, вебінарах, смислових поїздках і в навчальних програмах, якісно змінити своє життя, про них є завжди своєчасна інформація: в телеграм-каналі проєкту тут - IMARIA & PIPL - Платформа багатовимірного розвитку Заверухи Ірини ; на сторінці у фейсбуці - Iryna Zaverukha Imaria Master в інстапросторі - irynazaverukha підписуйтесь всюди, щоб гарантовано бути на звʼязку! Зверніть увагу , що у вартість консультації не входять продукти, які призначаються Майстром для корекції! Для постійних клієнтів пані Ірина залишає право на індивідуальні знижки від 5 до 30 %! Знання мають бути оцінені людством за найвищою планкою, тому що на чистоті їх базується все інше в цьому світі. Ми ніколи не відмовляємося від щедрості в прояві подяки через фінансову підтримку і самі продовжуємо це коло творення, регулярно реалізовуючи соціальні, культурні, освітні в благодійні проекти! Тож якщо у вас з''явиться бажання підтримати розвиток Проєкту IMARIA & PIPL - не стримуйте своїх поривів, реквізити для переказів нижче вказані, тільки не забудьте дати нам знати про свій добрий вчинок! А ми віддячимо… З любов''ю та повагою, Заверуха Ірина IMARIA MASTER. РЕКВІЗИТИ ДЛЯ ОПЛАТИ в Україні: Рахунок Приватбанку: ФОП Заверуха-Середа Ірина Леонідівна UA36 3052 9900 0002 6007 0162 2140 4 ЄДРПОУ: 3041903540 (Призначення платежу «Надання інших індивідуальних послуг») Ви також можете СПЛАТИТИ ПОСЛУГИ з будь-якої країни світу через платіжну систему Wayforpay © Ірина Заверуха, 2025 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','1 січня 2024','3 хв читання','/images/posts/personal-consultation.jpg','[]',1,'2024-01-01T15:06:00','2024-01-01T15:06:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1010','%d1%89%d0%be-%d0%b2%d0%b0%d1%81-%d1%80%d0%be%d0%b1%d0%b8%d1%82%d1%8c-%d1%89%d0%b','Що вас РОБИТЬ ЩАСЛИВИМИ? Чек-лист','Цього дня я запрошую вас до простої дії… яка ні до чого не зобов''язує, але зігріває серце простотою ❤️‍🔥 і наповнює нас із вами гарними почуттями…🤗 Йдеться про Любов через маленькі звички і ритуали, через традиції і хвилинки щастя…😍 Що вас РОБИТЬ ЩАС...','["Цього дня я запрошую вас до простої дії… яка ні до чого не зобов''язує, але зігріває серце простотою ❤️‍🔥 і наповнює нас із вами гарними почуттями…🤗 Йдеться про Любов через маленькі звички і ритуали, через традиції і хвилинки щастя…😍 Що вас РОБИТЬ ЩАСЛИВИМИ, конкретно вас? 🥰 Давайте разом згадувати і заповнювати свої чек-листи тепла і затишку… Можливо, ваші пункти стануть для інших натхненням і метою на експерименти; можливо, ви знайдете в списках людей моменти, що резонують вам… Створимо нові нейронні зв''язки разом 🧬🤩🤩 Приєднуйтесь під публікацією…👇 А я почну з себе і чекатиму на ваші відповіді 💓😘💋 🐚Я люблю….: 🌿…музику! Інструментальну музику, від якої захоплює дух. І так, щоб співати на весь голос улюблену пісню, до мурашок… 🌿… перша година, коли всі роз''їхалися вранці у справах, а я нікуди не поспішаю, і в цій неспішності не треба бігти, нічого робити, ні про що дбати… можу просто мовчати, просто сидіти чи лежати… без мети й сенсу… тупо й тихо… слухати тільки своє дихання й тишу всередині… і навіть не називаю це медитацією. А самістю. Відчуваючи як насправді Я Сильно Є! 🌿… створити простір затишку і насолодитися ним… свічки, аромомасла і пахощі, фон, тепла вода у ванній і трошки піни… хоча б на 30 хвилин… 🌿… коли всі вдома і зайняті цікавими їм справами, і так спокійно-спокійно від цього… 🌿… як пахне чистий одяг, що висох на морозі… нова друкована паперова книжка… свіжорозпакований шоколад із керобу… 🌿… шелестіти опалим листям у лісі та хитатися на землі в першому снігу, що випав… люблю промокнути під зливою влітку, забувши парасольку та забивши на пристойності… 🌿… їхати! За кермом авто. Коли попереду - пригоди, які не розплановані. У яких багато місця на \"що завгодно\" і сюрпризи від потоку на шляху… 🌿… прокидаючись вранці, потягуватися стільки, скільки потрібно, щоб захотілося встати з ліжка на крилах натхнення… 🌿… зустрічатися з людьми і реалізовувати щось чудове; творити і перетікати через канал спільних цінностей… 🌿… обійняти дерево, заплющити очі й \"подивитися\" як насіння готується під землею до нового життя, як пробиваються паростки, як дихає природа силою… 🌿… спостерігати за хмарами і птахами… це кайф! Ловити вихори вітру і малювати ним по небу, фантазуючи візерунки. Але ще більший кайф, коли це відбувається після ПРАЦІ та напруженого дня. Коли позаду всі турботи і попереду - …нічого. 🌿… спіймати Хвилю Музи і створювати те, чого немає… милуватися результатом… чи то це їжа, чи то вірш, чи то виріб… Муза однаково щаслива, створюючи ЩОСЬ із нічого… 🌿… коли в мене запитують \"чим допомогти?\" … це якийсь особливий кайф причетності до важливого для мене. 🌿… приносити в будь-який простір трошки затишку, чистоти і свята… нічого не чекаючи… просто наповнювати ароматом свого світу все, до чого торкаюся… 🌿… пити гарячий-гарячий чай зі спеціями та прянощами… а якщо ще й чорнослив у шоколаді додати - це вже моя симфонія… 🌿… розширювати межі свідомості й відчувати цей процес… не важливо як - бути в потоці та йти за покликом волі й Духа… відчуваючи тотальну єдність з усім… 🌿… зустрічати гостей і момент, коли всі йдуть ))))… однаково радісно… 🌿… відчувати безпеку всіх рівнів і не турбуватися про ресурси, подбавши про них заздалегідь… люблю списки/плани/баланс… 🌿… процес зародження ідеї, коли відчуваєш, як тебе \"щось\" обрало, як Сила, що творить, зайшла в глибину серця і Тіла і пускає коріння… трепет неймовірний і внутрішній інтерес… - а що ж це буде в підсумку?!?! 🌿… кидати камінчики у воду і рахувати скільки хвиль у прибою на морі… 🌿… дивитися на землю з небес, з повітря, піднімаючись у гори високо, або піднімаючись на дерево, або літаючи на чомусь… 🌿… помічати і просто спостерігати за плином життя… 🌿… момент першого мазка на чистому полотні, коли серце вистрибує з грудей від остраху зіпсувати, але при цьому перемагає інтерес до споглядання того, що вийде… 🌿… створювати і ростити! Це прямо сильно люблю… 🌿… у новому місті чи країні стати на землю ногами і відчути відмінність із тим, до чого я звикла… це пронизує такими калейдоскопами барв, що не передати словами… я наче одразу знаю все про це місце і стаю ним… 🌿… ліс! Готова жити в ньому і нікуди не йти… розмовляти з деревами, або просто мовчати, слухати птахів, розповіді духів про інші світи… 🌿… ловити потік через концентрацію. Наче ти дивишся на чистий аркуш і тобі здається, що на ньому нічого немає, але раптом проявляється ЩОСЬ і дивує тебе інсайтом… 🌿… чистоту! Усього. І простору життя, і дому, і Тіла, і свідомості… коли так пахне свіжістю, що дух захоплює… 🌿… читати іншим вголос. Так, і звісно ж люблю, коли є кому це слухати… а потім обговорити, поміркувати… 🌿… відчувати себе красивою і милуватися красою інших людей, їхнім блиском очей, сяйвом Душі, усмішкою і рельєфами форми… 🌿… відчувати час і не чіплятися за його течію, а гратися з ним, то розтягуючи, то ущільнюючи… 🌿… коли інші люди щасливі… так само як і я… … ось саме тому і люблю ділитися тим, що робить мене щасливою! 🤗 (Це далеко не все, що я люблю і чому радію в дрібницях… але цього вже достатньо, щоб сказати: ЖИТТЯ - ти ЧУДОВЕ…) А що там у вас припаслося? 😘 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','1 лютого 2024','4 хв читання','/images/posts/чек-лист.jpg','[]',1,'2024-02-01T12:13:32','2024-02-01T12:13:32');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1023','%d0%b2%d1%96%d0%b4%d0%ba%d1%80%d0%b8%d1%82%d1%96-%d0%bf%d1%80%d0%b0%d0%ba%d1%82%','Відкриті практикуми служіння','Йога-сатсанги українською мовою Сатсанг - прямий канал, через який передається або ж приймається інформація. Це чистота потоку і можливість почути себе істинну. Під час сатсангу ми робимо дії - йогічні крії, під час виконання яких прискорюються розум...','["Йога-сатсанги українською мовою Сатсанг - прямий канал, через який передається або ж приймається інформація. Це чистота потоку і можливість почути себе істинну. Під час сатсангу ми робимо дії - йогічні крії, під час виконання яких прискорюються розумові процеси, омолоджується мозок, структується інформація. Сексуальна енергія — СИЛА творчого потенціалу! Забажай жити живе життя! Процвітання — це ти! Магія ранку - ресурс для жінки! Де є довіра - немає місця страхам! Вивільнення і зцілення люті! Архівуємо борги – створюємо мир! Баланс усіх систем – вільний потік енергії життя! Підсиль себе! Вивільни енергію для проявлення та балансу! Дай собі шанс на нове щасливе життя! Чому вчить Сила кожного з нас? Зцілення та розкриття серця Як отримати життєву силу та енергію? \"Сонце в тобі\" // Йога-сатсанг з IMARIA MASTER Медитації з Іриною Заверухою (IMARIA MASTER ) Практика дихання «Я — Миротворець». Медитація від стресу, страху, гніву, панічних атак та безсилля Налаштування зі своєю Душею та Світлом в собі через голос душі IMARIA MASTER. Алмаз Душі Самозцілення від конфліктів, залежностей, дефіцитних програм минулого. Зцілення глибиних неврозів, образ, печалі та пренатального гніву Медитація від гніву та безсилля Ви можете внести свої донати, перерахувавши довільну суму, яка буде направлена на розвиток проекту PIpl, щоб високовибраційні знання стали доступними для більшості людей на планеті Земля Щедрість та щира подяка — це сила, яка масштабує та відкриває серця, особливо коли мова йде про подяку Вчителю, Цілителю, Провіднику — Ірині Заверусі (Майстер IMaRia)"]','Блог','Ірина Заверуха','1 січня 2024','3 хв читання','/images/posts/photo_5343577132208606305_y.jpg','[]',1,'2024-01-01T10:43:00','2024-01-01T10:43:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1120','%d1%81%d1%8c%d0%be%d0%b3%d0%be%d0%b4%d0%bd%d1%96-%d0%b7%d0%b0%d0%ba%d1%96%d0%bd%','Сьогодні закінчується рік МЕТАЛЕВОГО БИКА. Метал іде з поля. Надовго.','- Що відбувається, Іро, що із зв''язком?" - сьогодні поставила запитання учениця. Ліг Київстар? Відповідь така: "У мене Київстар і я можу зателефонувати. Інтернет теж є. Все ок. Тому я не знаю, що тобі сказати локально. 😘 А загалом МЕРЕЖА - це стихія ...','["- Що відбувається, Іро, що із зв''язком?\" - сьогодні поставила запитання учениця. Ліг Київстар? Відповідь така: \"У мене Київстар і я можу зателефонувати. Інтернет теж є. Все ок. Тому я не знаю, що тобі сказати локально. 😘 А загалом МЕРЕЖА - це стихія металу (повітря), і сьогодні закінчується рік МЕТАЛЕВОГО БИКА. Можуть бути прояви на цю тему. Метал іде з поля. Надовго. І якщо він слабкий в інфополі людини або травмований - то будуть збої зв''язку в цієї людини. Якщо відбувається глобальний збій зв''язку і стосується багатьох, про що це? Про колективну свідомість! Метал - дисципліна, порядок, структура, воля, кордони, повага до правил і законів живого життя (не плутати із законами від розуму, які напридумували люди!). Метал - це легені в тілі, саме тому тримався коронавірус два роки, доки був 2 роки сильний метал; це духовна нейромережа світу, глобальна система, яка зв''язує все одне з одним, яка в людині відображає стан нервової системи й стан мозку загалом, його розвиток, зрілість, міць, прагнення до розвитку й розширення в дусі… відображає зв''язок серця й розуму. Метал - це гроші, фінанси, і все, що з ними пов''язано… Метал - це імпульси в нас і здатність розшифровувати, знати \"космічну мову\" й перекладати її на будь-яку іншу, маючи глибокий контакт із магнітним полем Землі; це вищі гормональні центри та зв''язки із Всесвітом, із простором Єдиного Початку, які пронизують наскрізь усе живе й суще… З''єднуючись зі стихією землі, метал породжує ДЕРЕВО. Завтра настає рік Дерева! Ось такі справи. Метал зробив усе, що міг. Але з його відступом трохи колише магнітне поле Землі. Академік іде з цього Університету. Це і сумно трохи. Мені сумно, тому що люди знову залишаються наодинці самі з собою, і своєю відповідальністю за все. Саме цьому і вчив МЕТАЛ - взяти відповідальність! Тепер ми будемо на практиці показувати чого навчилися. Чи все ми зрозуміли. Чи засвоїли академічні уроки ВИСОТИ? Метал дав Крила тим, хто народжений жити на ВИСОТІ, жити і творити реальність, а не прогинатися або боятися її… нести відповідальність за свої ресурси і породжувати нові… СИЛА металу йде надовго з домінантної, на кілька років. І прийде їй на зміну інша Сила - Дерева. Ця стихія буде провідною мінімум 4 роки. Тож відповідь, як завжди, одна - ЙТИ І ПРАЦЮВАТИ З Собою, якщо хочеться змін. Або просто спостерігати за тим, що відбувається, і не метушитися, а створювати в собі баланс! Як працювати з металом? Запитати себе - \"де я невігласно ставлюся до системи Творця?\", \"які правила я порушую?\", \"а я взагалі знаю правила життя на Землі?\", \"у чому я зраджую себе, що сказала зроблю й не роблю?\", \"які в мене способи спілкування з Єдиним Початком?\", \"Я в контакті зі своїм Вищим Я, я чую себе-Аватара?\"… Знайдіть відповіді на ці запитання. Виправте ситуацію всередині своїми діями, а не тільки думками про це. І вона зміниться зовні теж.\" 🙏 приходьте вчитися багатовимірному баченню реальності! https://pipl.net.ua/ © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','3 лютого 2022','3 хв читання','/images/posts/IMG_20240220_073305_048.png','[]',1,'2022-02-03T07:44:00','2022-02-03T07:44:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1123','%f0%9f%8c%9f%f0%9f%8c%88%f0%9f%8c%8e%d0%bd-%d0%be-%d0%b2-%d0%b8-%d0%b9-%d1%81%d0','🌟🌈🌎Н О В И Й  СВІТ!','На світанку, 28 січня 2022 року, на виході з медитації я змогла розшифрувати дуже чітку інформацію про процеси! Вдень проживала бранч про Інтуїцію, а ввечері своїм кільком ученицям розповіла про цей ченнелінг. Тепер ділюся з усіма вами, стоячи на пор...','["На світанку, 28 січня 2022 року, на виході з медитації я змогла розшифрувати дуже чітку інформацію про процеси! Вдень проживала бранч про Інтуїцію, а ввечері своїм кільком ученицям розповіла про цей ченнелінг. Тепер ділюся з усіма вами, стоячи на порозі грандіозних подій цього Нового року Нового світу…🤗🤩👇 Отже, друзі, я бачила як світ змінюється за 1 добу, ба більше, за 2 світанкові години в добі, - як мільйони Сердець різних конфесій, вірувань, організацій, філософій і течій, творчих напрямків в одній глибокій медитації пропускають через себе на Землю потоки неймовірної СИЛИ. Вона (Сила) показала мені себе Водою. Чистою і поживною. Теплою і Дбайливою… яка пронизує кожен паросток і насіннячко Землі, поливає кожне дерево і квітку (я розшифрувала це, як усе ЖИВЕ І ПРИРОДНЕ, натуральне і природне, все, в чому є потенціал майбутнього!). Я бачила молитви і медитації по всій планеті, мільйони зібралися в один єдиний час і траплялося щось неймовірне за масштабністю… Свідомість людства піднялася до високої межі світів, і стався вихід за ці межі. ПЕРЕХІД. За 1 добу. І далі я бачила Плеяди і плеядинців, мені рідний і знайомий вимір. І як ринули Душі нових дітей на Землю, майбутні генії, нові \"Бетховени\" і \"Моцарти\" але без геному виживання минулої епохи, чисті Творці реальності одухотвореної цивілізації щасливих людей 🤩 🤩 🤩 🤩 🤩. Ці діти народяться у 2023-24 роках і сформують інший світ! І в цих роках народяться і нові проєкти, організації, міста, цілі території, об''єднані схожими цінностями… Серце Пульсара, який подавав голос споконвічної Сили, що запускає хвилю глобальної медитації, - живе і присутнє на території Оріани (так я почула). За плечима її стоять брати-Ангели, але особистість у цього серця жіноча. І немає цій події жодних перешкод. Ніхто і нічого вже не скасує і не зупинить цю кРАсоту, проникне Сила в кожну живу клітину…🌊 ВЕСНА. Це буде весна! Квітуча і зелена планета переродиться 🌿🌷🌷🌷🌷🌷🌿🌷🌷🌷🌷. І коли прийде день, ми дізнаємося - коли цей і день, і час… І звичайно ж я побачила скоріше за все те, що безпосередньо стосується МЕНЕ, і Суті моєї. Нехай розшифровуються і далі через інших провідників шифри і коди… 🙏🙏🙏 Світ змінюється…🧬💗💗 Будьте готові бути Щасливими! Пропускати через себе цю вібрацію - безумовного щастя у світі з умовними межами… Важливо - ключ для ПЕРЕХОДУ лежить у дитинстві вашої душі, у дитинстві, у насолоді Живим Життям без умов, у простоті присутності. Усе є в нашому ТІЛІ, всі відповіді, всі архіви, ВСЕЕЕЕ… 🌀 Ваша IMaRia © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','31 січня 2022','3 хв читання','/images/posts/Новий-світ.jpg','[]',1,'2022-01-31T08:28:00','2022-01-31T08:28:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1126','%d1%87%d0%be%d0%bc%d1%83-%d0%b2%d0%b0%d0%bc-%d0%bd%d0%b5%d0%be%d0%b1%d1%85%d1%96','Чому вам необхідно бути інтуїтивними','…Якщо ви не #інтуїтивні, то навіть і не помічаєте, наскільки не належите самі собі, СОБІ-СУТІ… Вами й алгоритмами ваших умів системі матричній так легко зараз керувати, як ніколи, - не потрібно навіть напружуватися, щоб збирати на площах і здійснюват...','["…Якщо ви не #інтуїтивні, то навіть і не помічаєте, наскільки не належите самі собі, СОБІ-СУТІ… Вами й алгоритмами ваших умів системі матричній так легко зараз керувати, як ніколи, - не потрібно навіть напружуватися, щоб збирати на площах і здійснювати якісь дії, що загрожують вашій безпеці. Програмним забезпеченням впливаючи на точки емоційних тригерів, які ви залишаєте і несвідомо проявляєте на кожному кроці свого життя…- матрична система досягає зараз миттєвого результату. І цей результат полягає у використанні вашої життєвої енергії для цілей розвитку світу ТЕХНОКРАТИЧНОГО, але не людського. Який вихід? Бути інтуїтивними! Скрізь і в усьому! Упевнена, ті, у кого немає навіть шансу на це, на цей мій текст вже не натрапить. Сумно. Якщо #Майстри не будуть майоріти частотами розважального контенту, - ви й не відреагуєте своєю увагою, бо алгоритми матричної системи вам не покажуть нічого, що перебуває на висоті вібрацій #безумовнещастя без спроби когось \"няньчити\", або \"рятувати\", або \"присипляти в ілюзії\". Тому доводиться створювати контент сумнівного вмісту - який вказує на точки болю і дефіцитні \"хочу\". Сумно? Так. Знецінити можна тільки те, що супер цінно! Справжні мудрі знання - це супер цінності, алмази… Але з іншого боку, якщо ви читач, який відчуває відгук усередині і на це послання, і нас із вами багато… - то це радісна новина. Тому що тільки #синергія Природного (інстинктивного розуму) і Наукового (технократичного розуму) в точці тут і зараз здатна ситуацію направити в русло #ЕВОЛЮЦІЙНЕ, а не революційне. Пікова точка 🌀 Зараз… Не потрібно нічого розділяти, це так! Завдання зараз світ матерії і світ Духа з''єднати, вірніше усвідомити, що він ніколи й не ділився… 🤓 Це сон ілюзії диктує віру в поділ на частини. Але Майстри теж люди. Дуже чутливі. Дуже сенситивні до всього, що не є природним. І інстинкт самозбереження змушує йти зі шлакопроводу, де всі й далі \"купують і продають\", торгуючи секундами уваги й \"закоханістю\", і навіть не прагнучи фундаментальних знань і глибини, що в освіті, що у стосунках, що в їжі, що у вихованні дітей… Якщо Майстри підуть з інфоканалів соцмереж - людям просто жопа, вже вибачте, пишу як є. Так уже було колись. І так може статися знову. Державний інститут не особливо керує реальністю, радше намагається \"тримати обличчя\" і не облажатися. Релігійні егрегори теж на ладан дихають. Вони вже давно втратили Силу, що спрямовує. І той і інший інститути сподівалися на інструмент Страху, що карає, але для технократичної Матриці не відомі емоції, зокрема й страхи, вона за принципом айкідо оберне назад до тих, хто її створив, ще й роздмухає в розмірах - з мухи Слона. Тому зараз Сила світу Інформаційного є тією рушійною хвилею, яка конкурує з реальним ПОТОКОМ ІСТИНИ. І Майстри - це теж Сила ІНФОРМАЦІЙНА!!! Вартові й Хранителі ключів Істини. Розумієте? Якщо ви не підтримуєте своїми реакціями #труд Майстрів - скоро у ваших стрічках залишиться тільки реклама трусів, ремонтів, туристичних турів, розважальних передач і закритих тусовок, де ви середньостатистичний адепт зграї виживання без сенсу і мети… і що там ви ще зазвичай називаєте \"звичайним життям\"… А Майстри підуть із міст остаточно, бо вже нестерпно, і осядуть у лісах і на островах, зберігаючи залишки оазисів Землі з дерев і живої природи. Ви думаєте, що я надивилася фільмів або начиталася утопічних книжок? Ні. Я не дивлюся телевізор, фільми гостросюжетні сумнівного змісту, не гортаю стрічки, не читаю книжок кілька років (просто не можу, дуже багато пишу і в голові не хочу змішувати жодних теорій із Потоком ченнелінгу). Щоб не заляпуватися сміттям. Я вибіркова і шаноблива до свого мозку. Але при цьому в мене є колосальний #імунітет ментальної стійкості. Чому? Я проживала це втілення з дна світу, з найнижчих матеріальних низів, проходячи всі кола \"пекла\" і неприйняття, і не розлютившись, а навпаки - ще більше в любові через усвідомленість розкрившись… Я знаю все про гоніння, хвороби, нестачу, відкинутість, неприйняття, НА ПРАКТИЦІ все це знаю, про жертву, про тиранію, про страждання і безсилля, про насильство і смерть… нема чим лякати таких. Просто нічим. Ментальний імунітет рівня Сталевої Нервової Системи. І при цьому я багато практикую ПРИСУТНІСТЬ через #тіло і #цілісність, медитацію і йогу, усвідомленість і #творчість… служіння і турботу про рід, природу, не полишаючи і своєї жіночої відповідальності, не зрікаючись її… розширюючи орбіту серця і далі. Не всі Майстри прошиті наскрізь різними видами ментальних викликів. Але абсолютно всі проходили щонайменше один точно і вистояли, утрималися на хвилі Потоку і Витоку, а не Wi-Fi Гоблін FM. Людей гублять їхні ЕМОЦІЇ І ДУМКИ, незнання (невігластво) і наївність (дитячість, довірливість)! Ось що я намагаюся сказати. ❤️‍🔥Ставайте СИЛЬНИМИ МЕНТАЛЬНО, медитуйте! ❤️‍🔥Ставайте СИЛЬНИМИ ФІЗИЧНО, ставайте інтуїтивними, заберіть своє тіло у свою відповідальність, свої домівки, свої роди, свої народи і всю планету - заберіть у СВОЮ ВІДПОВІДАЛЬНІСТЬ! ❤️‍🔥Ставайте СИЛЬНО ЛЮБИМИМИ через турботу про інших, через служіння, відданість і смиренність, вірність і відповідальність. Навіть там, де нібито \"високі частоти\" радості фонять - теж алгоритми зчитують вас, і якщо ви не ІНТУЇТИВНІ, то не зможете відрізнити істинні свої потреби від хибних \"хочушек\", що обслуговують ваші тригери. Тому що людині важливо бути однаково ВІЛЬНОЮ і від страждань, і від умовного щастя. Розумієте? Однаково вільною і від страждань, і від пекучих бажань! Лише ця фаза присутності дає тотальну нейтральність без перекосів за полярностями. І коли чим займатися здатна без втрати енергії вам підказувати - ваша ІНТУЇТИВНІСТЬ. 💫💫💫💫💫💫 🤩Тут ми Підвищуємо частоти до рівня \"Я Майстер своєї долі\" 👇 https://t.me/pipl_platform_bot?start=pipl_club © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','29 січня 2021','4 хв читання','/images/posts/viva-interview.jpg','[]',1,'2021-01-29T08:33:00','2021-01-29T08:33:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1128','%d0%bb%d1%8e%d1%82%d0%b8%d0%b9-2022-%d1%89%d0%be-%d0%b2%d1%96%d0%b4%d0%b1%d1%83%','Лютий 2022. "що відбувається?", "що робити?", "що далі?"','Любі, ви засипали мене запитаннями. Схожими. Усі вони зводяться до одного "що відбувається?", "що робити?", "що далі?". ЗАСПОКОЇТИСЯ. Не трясти цей "акваріум із водою", і менше підніматиметься мулу нагору, роблячи воду каламутною і ситуації неясними!...','["Любі, ви засипали мене запитаннями. Схожими. Усі вони зводяться до одного \"що відбувається?\", \"що робити?\", \"що далі?\". ЗАСПОКОЇТИСЯ. Не трясти цей \"акваріум із водою\", і менше підніматиметься мулу нагору, роблячи воду каламутною і ситуації неясними!!! Розумієте аналогію? 💎 Зробіть мою відкриту медитацію \"МИР і ЩАСТЯ\" https://www.youtube.com/watch?v=xDmpdW7B3kc Ця медитація допомагає втихомирити в собі суєту і перестати розгойдувати океан інформації. ЗАРАЗ. До 4 лютого 2022 р. Відбувається у швидкому й активному темпі те, що не встигло з вами статися як УРОКИ ПЕРЕХОДУ протягом усього року 2021. Так, це місяць агонії. Але я вас прошу - читайте пункт #1 👆 👆. 💎 Займіть себе прибиранням! Всього. Свідомості, Душі, простору життя, зв''язків… Відпускайте самі те, що не ваше. Відпускайте! З любов''ю і вдячністю, без зачіпок. А ще у мене є відкрита безоплатна група, де спокійно проживають практики ті, кому важливо екологічно вміти відпускати і завершувати, зцілюючи себе і світ навколо. Приєднуйтесь, ми всім раді 👉 https://t.me/ZaverukhaIrina НОВИЙ ПОЧАТОК. Рік 2022 настає остаточно 4.02.2022 і ось з цієї точки майте на увазі, що ми цілий місяць закладатимемо тенденції своїх подій усього року. Тому давайте будемо поступально цілісні. Як? Знизу вгору наповнюючи себе ВІДПОВІДАЛЬНІСТЮ: 🌿турбота про здоров''я! Прямо почніть нарешті серйозно ставитися до цього. Пройдіть процедури, здайте аналізи, займіться вправами, змініть режим харчування…сну. Ви у себе не на 500 років тут у тілі, тож час почати розуміти, що жодна ні медицина за вас не відповідає, ні екологія, ні влада, якщо ви самі собі шкодите щодня… ні, так не можна! 🌿шукайте насолоди, які не приносять руйнування! Творчістю пробуйте займатися. Тим, що давно збиралися. Перестаньте думати, що на все потрібні гроші. Ви обмежуєте себе цими установками. Якщо будете чесними, то побачите, як це працює на практиці. До ждуна похмурого гроші не приходять, до скривдженої терпилки теж… Тож заявляйте про свої бажання собі і знімайте свої корони низької самооцінки та завищеної також… Якщо ви умілець успішний - проведіть кілька майстер класів безоплатно. Одні плюси. Усі відчують зв''язок із Єдиним і красивим началом. Ну ви зрозуміли - в лютому Творимо і насолоджуємося! 🤓😍🙌 🌿Створіть список своїх цінностей і знайдіть людей зі схожими. Вам потрібно цього захотіти. Об''єднуватися! Так, важливо в лютому об''єднуватися навколо спільних цінностей. І вони не можуть бути однобокими. Ну ніяк! Якщо ви заявили Мир у всьому Світі, а самі сваритеся вдома з дітьми, ненавидите сусідів, заздрите начальству, мрієте звалити з країни… То я перепрошую, але ви спите в ілюзії. Те, що заявляєте - потрібно транслювати і ДІЯТИ. Вам хочеться, щоб ліси були? Садіть дерева. Підтримуйте фінансово. Не можете? Напишіть мені, я вам покажу де можна це робити, користуючись своїми руками і лопатою, і не скиглити, що все погано і немає шансів. Досить! Психаніть. Психаніть по-серйозному. Досить боротися за справедливість. Будьте вже нарешті настільки зрілими і дорослими, щоб вами хотіли пишатися ваші діти. Щоб вам було що згадати не в плані, як ви замолоду бухали, як ви десь загубилися, як ви затусили і повисіли… Ви цим усім не сховаєтесь і не зігрієтеся у свої каламутні часи, нііі, вашу волю і ваш дух може підбадьорити ТВОРЧІСТЬ, вихід за межі, де ви ПЕРЕМОГЛИ!!! Розумієте. Ви зобов''язані стати ПЕРЕМОЖЦЯМИ СЕБЕ в лютому. Не шукайте ніяких ворогів або рятувальників ззовні. Їх немає там… Стати переможцями СЕБЕ, свого его і невігластва, своєї гордині і \"не хочу\"! 💎 Почніть з малого і досягніть Великого. Пробуджуйте свій дух і волю. Ось вам спосіб, дерзайте 👉 www.youtube.com/@IMARIA_Zaverukha_Pipl Спробуйте зробити хоча б один комплекс повністю і оцінити свою якість енергії і Силу за підсумком. Наприклад цей спробуйте 👉 https://youtu.be/R4gQ2hGxP5g потрібна 1 година часу і ваше бажання. 🌿почніть ДАРУВАТИ ЛЮБОВ і підтримку, а не шукати її! Нехай місяць лютий стане для вас дорогою Вдячності і любові. Прощайте, просіть вибачення, примиряйтеся з тими, від кого відвернулися ви, або від вас, об''єднуйте своїх рідних навколо того, що ВАМ цікаво і цінно і пояснюйте їм чому. Влаштовуйте ТВОРЧІ ДУХОВНІ ВЕЧОРИ, якщо хтось любить тільки їсти, а ви лекції слухати. Слухайте разом, а інші нехай їдять у паралелі, або роблять те, що важливо їм. Ну або, наприклад, домовтеся, що щовечора ви робите на 1 годину те, що цікаво і цінно комусь із сім''ї. Без оскаржень. Ви зблизитеся емоційно. Наприклад, ви приготуєте їжу разом, тому що один хтось любить готувати. Або ви почитаєте книжку про історію Месопотамії, тому що 1 любить читати, решта послухають. Ви підете гуляти - тому що один любить прогулянки. Ви проведете годину за фільмом, тому що один любить кіно. Ви будете разом прибирати, тому що комусь одному дуже важлива Чистота… Ви слухатимете про бізнес-процеси і теорії економічного розвитку, тому що хтось один підприємець. Ви сядете в медитацію і проведете її хто як зможе, тому що хтось один Учитель кундаліні Йоги 🤓 (як я наприклад…). Лютий вам на підтримку! Все залежить від нас самих, і на цій блакитній планеті немає випадкових і зайвих людей… 🌍🤗💗🤗💗 Просто потрібно збалансувати Силу і спрямувати її на #СЕНС ❤️‍🔥❤️‍🔥❤️‍🔥 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','29 січня 2022','4 хв читання','/images/posts/IMG_3918.jpg','[]',1,'2022-01-29T08:36:00','2022-01-29T08:36:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1131','%d0%b2%d0%b0%d0%b6%d0%ba%d0%be-%d0%b6%d0%b8%d0%b2%d0%b5%d1%82%d1%8c%d1%81%d1%8f-','Важко живеться тоді, коли ти не знаєш тобі куди...!','Якщо людина зустрілася з територією цінностей у своєму серці та зрозуміла справжню причину присутності Душі на Землі - їй нічого не страшно, вона буде по-справжньому щасливою та сповненою сенсу за різних обставин… вона натхненно фонтануватиме ентузіа...','["Якщо людина зустрілася з територією цінностей у своєму серці та зрозуміла справжню причину присутності Душі на Землі - їй нічого не страшно, вона буде по-справжньому щасливою та сповненою сенсу за різних обставин… вона натхненно фонтануватиме ентузіазмом і заряджатиме цим тих, з ким за цінностями схожа… І дратуватиме своєю енергією тих, кому зручно \"спати\", бо сонце не тільки гріє, а й сліпить. Я кличу як тільки вмію і можу - Пізнайте СЕБЕ, люди! Відчуйте Велику Цінність, заради якої ви будете готові добровільно прагнути стати коконом, щоб потім бути #метеликом і пурхати! Поки ми повзаємо у виживанні і боїмося померти - це не дає шансу пізнати красу світу. Потрібно здатися Потоку - раз; і ДОВІРИТИСЯ - два. І померти як его - три. А чи потрібно діяти? Потрібно. Після того, як почули голос Душі в серці і зрозуміли - як саме діяти. Розумничати марно… Бо важко живеться тоді, коли ти не знаєш тобі куди…! А якщо знаєш - тебе не зупинить ніхто і ніщо… Мені в БЕЗУМОВНЕ ЩАСТЯ, МИР, ГАРМОНІЮ, КРАСУ, ДОСТАТОК І МУДРІСТЬ… А це означає, що я буду причиною всього цього для себе і для інших. 🌍💗💎💫 🙌 Приходьте на консультації та діагностики долі, на корекції та зцілення! 🙌 Приходьте вчитися в проєкт #Pipl. Багато курсів в записі. 🙌 Приєднуйтесь до ресурсного простору #PiplClub © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','28 січня 2022','3 хв читання','/images/posts/Важко-тоді-коли-не-знаєш-тобі-куди.png','[]',1,'2022-01-28T08:43:00','2022-01-28T08:43:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1134','%d0%ba%d0%be%d1%80%d0%b8%d0%b4%d0%be%d1%80-%d0%b7%d0%b0%d1%82%d0%b5%d0%bc%d0%bd%','Коридор затемнень. Як діяти?','Нижче буде Розповідь про те, чому одним усе, а іншим «тримайтеся!» 👇 Наше Его намагається жити так, щоб після себе обов’язково залишити «сліди», і бажано «важливі та значущі»… не виходить творчим шляхом – так хоча б руйнівним… Хоча б якось… Природа е...','["Нижче буде Розповідь про те, чому одним усе, а іншим «тримайтеся!» 👇 Наше Его намагається жити так, щоб після себе обов’язково залишити «сліди», і бажано «важливі та значущі»… не виходить творчим шляхом – так хоча б руйнівним… Хоча б якось… Природа его саме така. Вона прагне розділяти і присвоювати. Але природа Духу і Душі, Волі і Любові абсолютно інша. Вона веде до єдності та свободи через ресурсне служіння Живому Життю … Его завжди керується концепціями болю і страждань, бо має кордони лише однієї особистості, бо обмеження на цьому тримаються, на умовних кордонах. Душа ж вічна, керується вона щастям і духовною інформацією, що постійно пронизує ВсеСвіт потоком такого тонкого високовібраційного «сексу»… Термін застосовую тут, але розумію, що різні люди пропустять крізь свій рівень свідомості це поняття і будуть мати на увазі «своє інше». Що ж я маю на увазі під високовібраційним «сексом»? 🤓 Де Бог, – там і Богиня. Де інь, там і ян. Все є Одне, неділиме, – життя і смерть, як початок і «кінець»… 🌀 Та насправді немає кінця, бо всюдисуща Сила породжує себе через себе, і це таїнство схоже на злиття, на соітіє, на «секс», на перетікання одне в одне неділимого в тонкоматеріальному плані потоку світла. Коли ми глибоко залежні від матерії, «спимо» в травмованій формі свого «я», що не усвідомлює себе реальним творцем, не бачить як своїми думками, діями і словами створює «мультики зовнішнього світу» – то ми й не розуміємо за ширмами ілюзій як насправді усе з усім поєднано безкінечним космічним «сексом», силою Живого Життя… Усеееее пов’язано з усім! Тож проявлена і пробуджена Душа ​​прагне жити так, щоб після себе не залишати слідів навіть на піску… щоб не порушити гармонію світу і не розтривожити тихий баланс Єдиного, де кожна піщинка є унікальним візерунком загальної картини… Пробуджена душа завжди виправляє помилки хибного Его з реального і минулого досвіду життя. Бо природнє не руйнує нічого «от ума» заради задоволення секундний утіх, чи заради втечі на секунди від свого безсилля – природнє плекає і служить ЦІЛОМУ; і смерть природня приходить теж природньо, коли приходить час духу змінювати форму Суті. Проявлений через душу Дух, що керує Істинним Розумом, створює нові варіації СЕБЕ в матеріальному світі, але ми це називаємо предметами, винаходами, грубоматеріальними енергіями, програмами, алгоритмами… Вони ж (предмети) при цьому творінням духу бути не перестали. Розумієте? Дух через пробуджене Я діє як Сила Творяща; але Дух той самий через спляче в егоїзмі «я» діє теж як Сила, – Руйнації і хаосу насилля. Це все є дух! А де ж береться енергія на усю матеріалізацію? В наших емоціях, через увагу направлену!!! Негативні емоції дають силу руйнаціям. Високі позитивні емоції вдячності, щастя, радості, ніжності, поваги, доброти, турботи… дають силу Волі внутрішньому Творцю. Баланс же підтримується Силою Живого Життя. 🌀 Відповідь усім, кому дуже хочеться й далі ділити світ і людей на «хороших» і «поганих», приписуючи одним «героїзм», а в інших викриваючи їхні «недо…». Зараз по суті ми маємо відділитися від матриці ілюзій розділення і зрозуміти, що все ЖИВЕ прагне до Єдності через наше прийняття факту: ТИ – це Я, а Я – це Ти! Усе ілюзорне прагне нас приспати й далі колисковими солодкими, нав’язуючи мнєніє, що ми то «хороші», а от «вони скоти». І це в проекції реальності вузької може бути і так на певному рівні. Але данна вузька проекція нам мир не прискорить. Бо такими самими «скотами» ми були колись самі для себе і інших. Не пам’ятаєте коли це? А пригадайте ту безмежну кількість насилля і самокритики, яку направили в свою ж сторону, а скільки ненависті і гніву за життя відчували до близьких і рідних, а до чужих…? То хто нам тоді дає право критикувати? Ніхто. Ми не ідеальні усі. Хтось вбиває фізично, а хтось вбивається емоційно/морально/духовно… Я знаю сотні людей, які насилували себе «псевдодуховністю» роками, знущаючись над тілом; мільйони щоденно знаходяться в емоційному внутрішньому насиллі із-за свого зовнішнього безсилля; тисячі відносяться толерантно до ментального і навіть ресурсного насилля, приймаючи чи за норму. Чому ж так? Що робити? Потрібно почати кожному з себе! Знайти КОНФЛІКТ ВНУТРІШНІЙ, і вийти з нього мирно, зігріваючи серце спочатку милістю свого Вчителя, а потім наповнити безумовною любов’ю усі темні кутки власної душі через служіння спільному простору життя. Це і є задача на усі коридори Затемнень! 🤗 (Як все це робити – навчаю на курсах і в практиках сатсангів. Приходьте самозцілювати себе. Хоча б почніть! Зробіть із доступних відкритих в записі. Це вже шанс. Почніть з вдячностей. Ось залишаю доступ до записаних глибоких послань ПОДЯКИ 👉 https://youtube.com/playlist?list=PL4fA4gJolPYMD9vEZ7iiJUFBN-C8x6vIg ) 🙏🙏🙏 Давайте усвідомлювати – не в Україні війна йде, а в усьому світі – між Одушевленим Началом Світлим, що пізнало Любов безмежну, безумовну і чисту (чи через любов своєї Матері і до матері, чи через любов Батька і до батька, чи через любов Партнера і до партнера, до дитини, самого себе до себе…) та Егоїстичним травмованим дефіцитним малодушшям, що ту саму любов шукає… і як її створювати, де брати, – не знає… 😑 Як «добувати», акумулювати і транслювати Любов, щоб з’явилось світло і закінчились війни, щоб зникли борги, гнів і руйнації, щоб перестали гинути фізично люди заради чиїхось ідей і вивільнився час на щастя… ?? Це цікавить усіх. Але не усі чомусь готові брати відповідальність за дії! Якщо ви готові, – вивчайте Етичні Закони Живого Життя і дійте… І навіть на руїнах вчорашніх ми створити здатні місце Сили, бо час так чи інакше усе зітре, – але оживити може Жива Людина своєю яскравою люблячою присутністю… 🤗🙏🌏🕊💞 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','25 жовтня 2022','5 хв читання','/images/posts/photo-58-scaled.jpg','[]',1,'2022-10-25T08:48:00','2022-10-25T08:48:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1257','%d0%ba%d0%be%d0%bb%d0%b8%d1%81%d1%8c-%d0%bd%d0%b0-%d0%b7%d0%b5%d0%bc%d0%bb%d1%96','Колись на Землі був Храм Знань…','Колись на Землі був Храм Знань… Його формували не муровані стіни, а люди-боги. Люди, що пропускали крізь себе світло інформації і являлись колонами цього священного храму. Їх називали Світочами. Всесвіт дуже різноманітний. Древній. Немає йому ні кінц...','["Колись на Землі був Храм Знань… Його формували не муровані стіни, а люди-боги. Люди, що пропускали крізь себе світло інформації і являлись колонами цього священного храму. Їх називали Світочами. Всесвіт дуже різноманітний. Древній. Немає йому ні кінця ні краю. Але ми звикли вимірювати усе часом і вірити в простір. Тож в простір Землі залітали різні істоти. І мирно налаштовані, і не дуже. Хранителі Частот Світла – Світочі самовіддано берегли Храм Знань через контакт своїх сердець телепатично. Вони були Алхіміками. Керували багатовимірністю часів, берегли баланс стихій, ділились мудрістю і слідкували за гармонією сил між Небом і Землею. Вони вели напрочуд просте життя серед інших істот, були різними – і помітними, і не помітними; вони займали різні соціальні і просторові посади і грали різні ролі… але завжди виділялись якимось невимовним магнетизмом і потужною енергетикою матеріалізації. Земля рухається. Вона весь час в дорозі. У неї є свій Путь Інтуїції. Є динаміка еволюції. На великій орбіті часу – немає часу. На маленькій орбіті часу – ми засинаємо в тимчасовій формі – в своєму тілі, і знову потрапляємо в поле Єдиної Сили, коли тіло вичерпало свої ресурси. Де ми беремо ресурси для тіла? В родовій системі. Це банк можливостей і генодосвіду. Де ми беремо ресурси для розширення свідомості? В небесному племені. Це банк знань і творчості. Коли ресурси поєднуються між собою в структурі тіла і серця людини, як два різнополярні потоки, – народжується творча іскра, зерно потенціалу, воно дає поштовх розширення для усієї системи, і так триває віками… Тіло людини зліплене з пластиліну Землі. Але воно не статичне. Програма керує динамікою розвитку. Змінюючи програму, ми можемо змінювати й результати – матерію. Програми – це наші думки, це потоки інформаційних кодів і шифрів, які зберігаються в крові. Тому кожна кров – унікальна. Наука іще не все знає про кров людини. Показує лише 1/10 від істини. Ми маємо різні налаштування системи, і доступ до ключів від програм є лише у Хранителів Ключів, в пам’яті їх НадСвідомості. Земля сама керувала народженням Хранителів для Храму Знань. У кожного завжди був Захисник і не один, іноді ціла родова система, та й народ і нація споРІДнених по духу. Доки в цей процес не втрутилися інші цивілізації, яким дуже захотілось керувати таким потужним інкубатором енергії, як Земля і використовувати цю Силу для своїх потреб. Так і сталося. Була міжгалактична війна. Страшна. Ми її програли. Були створені егрегоріальні структури влади. Я бачила як люди, що зібралися в натовп і моляться, співають, скандують щось …підкріплені невидимими каналами зв’язку, як лазерними дротами, до космічних станцій, які далі цю енергію генерують в надпотужні батареї. На них літають істоти з інших вимірів. Використовують для своїх потреб. Тобто люди, віддають свою силу творіння по суті, як донори, кожного разу приєднуючись до вузького егрегору догматичної віри в що завгодно, втрачаючи свою ВОЛЮ і творчу свободу. … Храм Знань був знищений. Хранителів вислідковували і вбивали. І не думайте, що це тривало декілька років, це тривало поколіннями. Різними методами знищували. І через боротьбу з культами, і через надумані гоніння на відьом, і через війни, через руйнацію артефактів… І не думайте, що ті кого вбивали, не пізнали такої ж участі вбивць. Пізнали! Вони проживали інкарнації нові і втілювались в людей, що знищували інших, бо так діє цей вірус «помсти і люті». Той, хто ненавидить свого тирана, сам стане тираном. Тому і сфера Знань теж тоді стала інфікована егрегором війни. Але в різних куточках планети залишилась інформація в самій землі, яку зберігали тіла Хранителів. І коли відбувається зустріч носія інформації з кров’ю живою і багряною – то пробуджується Сила і розпаковуються Знання. Вивільняється енергія минулого для реалізації задач майбутнього! Це алхімія. Саме це відбувається масово зараз через Україну! 🙏❤️‍🔥🌏🧬 Ми змінюємо структуру інформаційного тіла світу, ми не змогли реалізувати це без втрат – тому проливається кров, багато крові…😔 Ми повертаємось і відроджуємось! © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','15 жовтня 2022','3 хв читання','/images/posts/IMG_3918-1.jpg','[]',1,'2022-10-15T10:03:00','2022-10-15T10:03:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1351','%d0%b2-3d-%d1%80%d0%b5%d0%b0%d0%bb%d1%8c%d0%bd%d0%be%d1%81%d1%82%d1%96-%d0%b4%d1','В 3d реальності думки про гроші існують із 3-видів ментальних ілюзій','Ми хочемо гроші, тому що насправді нам потрібна фізична безпека і базовий побутовий комфорт. (Діалоги з космічно-земним родом, з Творцем і з усією Галактикою тут є ключовим фактором!) Ми хочемо стосунки і від них гроші (як похідну сексу), тому що нам...','["Ми хочемо гроші, тому що насправді нам потрібна фізична безпека і базовий побутовий комфорт. (Діалоги з космічно-земним родом, з Творцем і з усією Галактикою тут є ключовим фактором!) Ми хочемо стосунки і від них гроші (як похідну сексу), тому що нам насправді потрібна безумовна любов, базове прийняття себе і емоційна безпека. (Стосунки з жіночим аспектом та материнською проекцією тут є ключовим фактором!) Ми хочемо статусу, посад, знань, звань (і як результат цього - нам ввижаються великі гроші), тому що насправді нам потрібне безумовне визнання нас важливими і талановитими, безумовна цінність своєї присутності та унікальності… (Стосунки з чоловічим аспектом та батьковою проекцією тут є ключовим фактором!) Мислення в 3d вимірі сформоване на законах дуальної боротьби за ресурси, на конкуренції, на торгівлі силою любові, на уроках через біль та страждання… Це просто рівень в даній грі «життя». Дух знаходиться в «темниці ума», і душа обслуговує ментальні пастки его. І не має значення, яка там у людини посада, родословна і кількість дипломів… це все пусте… ‼️ За величезною кількістю цілей та мрій людей насправді стоять неврози і блоки психіки, вузли дефіцитів… Замість того, щоб тринькати свій час на досягнення купівлі якогось предмета, авто, телефону, чи дому… на досягнення статусів… - задумайтесь чого ви насправді прагнете, бажаючи цих РЕЧЕЙ? Невже грошей? Ні. Читай вище 👆знайди свій пункт і приміряй його на свою мотивацію. То чим би ви насправді займались, якби не думки про ресурси??? Люди з мисленням творців саме це і роблять, а свої вчорашні неврози виживання перетворюють на базові задачі і вивільняються для духовної творчості. ‼️ Зцілюючи свої спазми, люди приходять до стану спокою і свободи внутрішньої. Із якої стає очевидним, що ти вже Є, і є Суттю, а не варіацією декорацій. Мислення в 4d вимірі і 5d вимірі не прописане ні в яких астрологічних картах, нумерологічних чи кармічних діагностиках… бо усі ці системи створювались для еволюції свідомості в 3d вимірі і вони не підходять для медитативного ума, що подолав ілюзію хибного его. Пора рухатися далі! 💫🌎 Як відбувається перехід із рівня до рівня? Які правила гри в кожному із них? Чим суттєво відрізняються системи управління в епоху Водолія?… Чим саме займатися вам і чому? ✨✨✨ Читаю курс #ProResurs для амбасадорів Живого життя. День 2 позаду… 🤩🙏👌 … і я щаслива, що цей курс народився і проявляється для людей світу українською мовою, сердечною вібрацією розливається потоком… саме зараз… 🥰 ✨✨✨ Якщо розумієте, що і вам конче необхідні знання такого рівня. Пишіть про намір… формуватимемо бронь предзапису для бажаючих проходити дистанційний формат… © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','28 лютого 2024','3 хв читання','/images/posts/Про-ресурс-.jpg','[]',1,'2024-02-28T14:57:00','2024-02-28T14:57:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1355','%d0%bb%d1%8e%d0%b1%d0%be%d0%b2-%d0%b1%d0%b5%d0%b7-%d0%b3%d1%80%d0%b0%d0%b2%d1%96','Любов без гравітації…','Це та, яка окриляє, вивільняє, надихає… а не обмежує і зупиняє. Любов без гравітації проживається нами з рівня душі. І вона не про романтику чи якусь приземлену семантику… Я неймовірно щаслива усвідомлювати одну із своїх місій життя живого - активаці...','["Це та, яка окриляє, вивільняє, надихає… а не обмежує і зупиняє. Любов без гравітації проживається нами з рівня душі. І вона не про романтику чи якусь приземлену семантику… Я неймовірно щаслива усвідомлювати одну із своїх місій життя живого - активацію гену сестринства та братерства у світі… 🥰 Обʼєднувати людей, бути і мостом, і простором, і причиною зустрічей, знайомств, зародження, народження, зцілення, створення… 🥰 На ретритах і в програмах постійно бачу це явище. Як розкриваються Жінки, як сміливо в середовищі довіри та безпеки підсилюються і проявляються… Ось тут показую чудесні моменти спогадів з останнього досвіду.👇👇👇 Olena Kraievska проводила неймовірний МК про мейкап для себе. Усі були такі вдячні і задоволені новому досвіду… 🙏😍 А Anna Zyniuk просто так взяла і подарувала красивенний реглан крафтовий нашій ніжній, тендітній, сильній і талановитій редакторці проекту Pipl Kateryna Rayda Подарунки безмежно щедрі і сердечні - то у нас постійна традиція… Люди, ви неймовірні! Ми з вами неймовірні… і усе, що створюємо - неймовірне… От з Мария Птаха ми проживали таїнство ВАЛЯННЯ З ВОВНИ, більшість - вперше… створивши красиві пурпурові серця… А яка ж велична і елегантна сама Майстриня Марія…🥰🙏 ✨✨✨ 🤩 найближчий ретрит скоро! #ОНОВЛЕНА. #Цвітіння - потужне місце сили чекає на учасниць, на якому я не була іще жодного разу, але воно кличе давно СЕРЦЕМ великої МА. Локація не розголошується, щоб усі прокачали довіру до СЕБЕ, і прожили потужну пригоду ОНОВЛЕННЯ ЖИТТЯ… Кому дати деталі? Ставте ➕👇 https://www.facebook.com/share/p/EXDzrQuPP1RePWRi/ #IMARIAMASTER © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','27 лютого 2024','3 хв читання','/images/posts/Любов.png','[]',1,'2024-02-27T15:34:00','2024-02-27T15:34:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1412','%d0%bf%d1%80%d0%b0%d0%ba%d1%82%d0%b8%d1%87%d0%bd%d0%b8%d0%b9-%d1%81%d0%b5%d0%bc%','Практичний семінар «Хранителі Частот. Народження Фенікса»','Світочі, з 1 по 3 березня Ірина Заверуха проводить в Буші практичний семінар «Хранителі Частот. Народження Фенікса». …Душі твоїй потрібна жива вода? - завжди скажу тобі «да»… …Занурюю людей на дно самих СЕБЕ, як в колодязь… щоб вивільнились від ілюзі...','["Світочі, з 1 по 3 березня Ірина Заверуха проводить в Буші практичний семінар «Хранителі Частот. Народження Фенікса». …Душі твоїй потрібна жива вода? - завжди скажу тобі «да»… …Занурюю людей на дно самих СЕБЕ, як в колодязь… щоб вивільнились від ілюзій та гордині… Наповнились чистими знаннями, ресурсами творчості, без мук і конфузій… Іноді сама почуваюсь пірʼїнкою, Іноді - крилами роду, Але цього разу побуду - космічною Жар-Птицею… Феніксом пронесусь через ВсеСвіти, щоб зустрітись з #ХранителямиЧастот знову у Буші, бо кличе Сила служити… 🙏🙏🙏 Чому я везу людей до Буші? Відповідаю. Бо це МОГИЛА. Буквально. Велика могила, сильна стихія землі, територія, залита кровʼю слоями, напакована віками інформацією минулого. Це факт. Не моє мнєніє. Майже усе село - то історико-культурний заповідник і музей. А що таке музей? Це концентрований ІНЬ, «смерть», тобто дещо із минулого, … є тут і ворота ЗАВЕРШЕННЯ, і ворота ПЕРЕХОДУ. А там, де зустрічається найвища фаза інь, там сходяться потоки - бо тут же починається і Ян. В Буші найвищий рівень родового ІНЬ зустрічається з полярним йому родовим ЯН. І тому це для інтуїтів, що працюють з середовищем душі - гарний простір для зцілення людей. А іще я дуже відчуваю звʼязок з Вишніми Вознесеними Вчителями в Буші. Бо коридори між світами вони проклали там і ключі мають не усі, далекоооооо не усі. Ключі від дверей в самій крові і в тілі їх носіїв. Поки тіло не привезеш туди - ти й не знаєш, що їх маєш. І які двері вони відкривають. На Бушу мені вказала в 2018 році Богородиця через сон. Чітко і ясно даючи інструкції, що саме я маю робити. Як дію зараз? Кожну істоту бачу ясно на рівні структури вібраційної. І бачу ті «мертві» зони свідомості, які потребують хірургії душі, ампутації, сепарації, що заважає свободі бути. Фальшверсії розчиняються. Тому Буша це ніяке не місце сили для наповнення, якщо ви не потрудились бути чистими і готовими для прийняття змін життя. Зрозумійте, люди! Це МОГИЛА. Велика суцільна. Історично сформована і подіями теж. Має бути і глибока повага до цього факту та ролі. А не страшилки чи домисли. …І портал проходу до чистих лемурійських вимірів не відкритий там сам по собі серед Гайдамацького лісу. Нііііі! Портал - це СЕРЦЕ ПРОВІДНИКА, чисте серце Берегині є проходом… і духи місцеві навіть не пустять тих, хто прийшов клянчити і «брати». Нічого ви там не зустрінете. Лише село селом і дерева як дерева, каміння як каміння…, якщо ваші ДНК не містять кодів Аватара МА. І я не буду дозволяти собі писати більше, ніж здатна осягнути пересічна людина усе це. Нехай краще вчинки говорять самі за себе і ті, хто нас приймають в Буші. Моя Сила у вмінні бачити велич душі усіх живих істот… Мене кличе Велика МА йти до дерев -волхвиць і знову зцілювати Україну, навчати моїх Учениць бути Берегинями і тими, які ВТІЛЮВАТИ нові проекти здатні, передавати чисті спектри послань, знову віддаючи виміру смерті усе те, що вже не веде до еволюції, не бринить життям… дозволяти через серця лотосові висвічуватися крові роду. © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Новини','Ірина Заверуха','1 березня 2024','3 хв читання','/images/posts/photo_5400017971755211885_y.jpg','[]',1,'2024-03-01T11:48:27','2024-03-01T11:48:27');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1500','%d0%b4%d1%8f%d0%ba%d1%83%d1%8e-%d0%b2%d0%b0%d0%bc-%d0%b7%d0%b0-%d0%b2%d0%b0%d1%8','Дякую вам за ВАС, любі Жінки!','Дякую вам за ВАС, любі Жінки! 🪷😍🫶 Нехай бринить в душі мелодія весни… Нехай вночі стаються тільки добрі сни… Нехай буяє в кожній миті щедрість та краса… Нехай усі наші молитви завжди чують небеса! Нехай… ✴️ Зустрінемось завтра на світанку… в сердечно...','["Дякую вам за ВАС, любі Жінки! 🪷😍🫶 Нехай бринить в душі мелодія весни… Нехай вночі стаються тільки добрі сни… Нехай буяє в кожній миті щедрість та краса… Нехай усі наші молитви завжди чують небеса! Нехай… ✴️ Зустрінемось завтра на світанку… в сердечному потоці нового ранку… 🙏 А нині дарую КОЖНІЙ нагадування про спосіб, за допомогою якого розквітає наша істинна суть! Забирайте. Дивіться. Діліться з іншими жінками… 💗👇 https://youtu.be/gtH4zipZaKs?si=t4RBzoePh1nV4oux Це лекція-маніфест із закритого ретриту, лекція-ініціація, лекція-посвята… Я віддаю вам знання ✨ Тепер вона відкрита 🤗🌍🌟 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','8 березня 2024','3 хв читання','/images/posts/Дякую-вам-за-ВАС-любі-Жінки-___.png','[]',1,'2024-03-08T12:43:15','2024-03-08T12:43:15');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1617','%d0%bf%d0%be%d1%82%d1%80%d1%96%d0%b1%d0%bd%d0%be-%d0%b6%d0%b8%d1%82%d0%b8-%d1%81','Потрібно жити СЕБЕ - проявляти себе діями!','Головним результатом семінару «Хранителі Частот», який я провела кілька днів тому в Буші, є усвідомлення учасницями, що СТРАХ СВОЄЇ СИЛИ виявляється блокує усе і є потужним спазмом… 😬 Бо не достатньо знати хто ти. Потрібно жити СЕБЕ, тобто проявляти ...','["Головним результатом семінару «Хранителі Частот», який я провела кілька днів тому в Буші, є усвідомлення учасницями, що СТРАХ СВОЄЇ СИЛИ виявляється блокує усе і є потужним спазмом… 😬 Бо не достатньо знати хто ти. Потрібно жити СЕБЕ, тобто проявляти себе діями. Інакше для чого вся ця суєта…?! Замість проявлення істинного, людина пхає назад в своє серце усю палітру краси власної душі і задихається від нереалізованості особистості. Чому ж так? Тому що там, де не вистачає знань - будуть домисли. Там, де не вистачає енергії - буде виживання, економія, страх, контракти… Там, де не вистачає волі і духу - буде насилля, боротьба і конкуренція… То що будемо робити, любі люди? 🫢 Маємо перестати боятися своєї СИЛИ. Давайте про жінку. Бо я таки ментор для НЕЇ в першу чергу, а потім вже для всіх. ✴️Свято для жінки - це бути пробудженою і проявленою, коли тебе БАЧАТЬ в цій суті щодня, а не раз в рік… роблячи із цього імітацію поваги… Бо ти себе БАЧИШ щодня і щомиті. …Жертва і тєрпіла створює причини для тиранії. І сильна - це не та, яка нарощує мʼязи, щоб дати комусь в зуби і претендувати на грубу повагу через конкуренцію. Сильна та, яка не терпить муки і не мовчить, коли душа кричить, не зраджує своїм цінностям, любить себе діями, серцем наповнює простір, випромінює мудрість, світить творчістю, пишається інтелектом, якщо він є, або ж з легкістю визнає його відсутність, якщо таланти зовсім в іншому середовищі проявилися… Розумієш? Сила жінки - це не якість із порівняння з кимось. А твоя базова норма і близькість зі своєю суттю. Я щодня Жінка дивовижна - бачу (вижу) диво в усьому і завжди…🤩 І в собі шаную та плекаю цей стан живого життя… 🙏😍 Маніпулювати вами через якісь акції, пропозиції, маркетингові пастки теж не хочу і не буду… 😘 Тому як і вчора, сьогодні і завтра - працюю та живу заради щастя усього сущого в кожній миті, транслюючи любов діями…💗 А курс Я - Жінка неймовірний і безцінний так само доступний кожній леді! 🫶 А запис на ретрит весняний, де дійсно відбуваються якісні зміни і ресурсні прориви - ОНОВЛЕНА. Цвітіння - триває. Скоро завершення набору! Поспішіть… 🤗😉 А попередня бронь на річну трансформаційну програму #Крила2024 - відкрита! І це шанс - «один на мільйон» без перебільшень. Доступ до знань такого рівня проявляється сміливим і дієвим жінкам нашого часу. Хто розділяє мої цінності і відчуває, що бачить крізь мою особистість Силу МА, вчителя і приклад для натхнення - надихайтесь, навчайтесь. Які деталі вам надати, про що саме? 😘 Пишіть. Команда підхопить і вишле відповіді… P.S. Купатися в весні, любові, красі, увазі і повазі, в мирі і гармонії - це природній стан для кожної! Бажаю його проживати щодня, любі жінки і подруги, сестри сердечні… 😘🙏💗🪷 #IMARIA #soul #way #pipl #zaverukha #весна #живежиття #силасерця © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','7 березня 2024','3 хв читання','/images/posts/Своя-Сила.png','[]',1,'2024-03-07T13:39:05','2024-03-07T13:39:05');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1621','%d0%b7%d0%b0%d1%81%d0%b2%d1%96%d1%82%d0%b8%d0%bc%d0%be-%d1%83%d0%ba%d1%80%d0%b0%','Засвітимо українське сонце на небосхилі Нової Ери!','… Сакральні таїнства так само просто, як і слова космічні виходять крізь мене у простір і перетворюють середовище на вимір безмежної любові, довіри, безпеки і естетики душі… зцілюють… наповнюють… гармонізують… Я не можу це пояснити словами. З тих пір...','["… Сакральні таїнства так само просто, як і слова космічні виходять крізь мене у простір і перетворюють середовище на вимір безмежної любові, довіри, безпеки і естетики душі… зцілюють… наповнюють… гармонізують… Я не можу це пояснити словами. З тих пір, як майже завжди є фотооператор поряд з нами на заходах публічних, - стало можливим проявити моменти через фото… Але! Вони не передають той СТАН, який ми живемо і випромінюємо… 🥰 Правда, феї-жінки, учасниці? 🙏Мої золоті світочі Землі, я знаю, що важко за голосами свого ума, які фонять усілякими ілюзорними пісеньками про важливі справи і невідкладні задачі… почути справжній голос душі і не сплутати з его, не повестися на асоціації, не загратися в галюцинації… не назвати істинним свої очікування хибної уяви… особливо, якщо не проросла іще СИЛА життя живого наскрізь тебе повноцінної… Але я продовжую беззупинно йти своєю дорогою, доки натхнення дається! І любити діями… I ma way IMARIA✴️ - я йду путь #IMARIA, путь душі, що є любов від Бога… 💗 Ретрит \"Оновлена.Цвітіння\" - дуже не рядове дійство, а концентрована практика для тих, хто дійсно прагне розкритися як цілитель, як провідниця високих вібрацій, як жіноча сила і майстер свого життя, як любляча повнота… не менше… 👌 До зустрічі! 22-25.03 в схилах Карпатських лісів… там, де я іще не ходила ногами… 🥰 В групу можна потрапити до кінця цього тижня… 🫶 Робіть правильні рішення виважено! Хто був вчора на прямому ефірі в #PiplClub, той знає, яка саме потужна тема і вібрація заходить зараз на планету і змінить вона світ через 50 років на інший вимір буття. Дивитися душею в широку рамку бачення реальності значно радісніше, ніж зазирати в шпарину домислів ума. … а ми з моєю чарівною Наталія Пузенко вже готуємось і до зустрічі з жінками на ретриті, де проводимо потужну трансформаційну ресурсну чистку підсвідомості і активацію надсвідомого потенціалу через гру… І не лише до цього готується моя команда, щоб пройти крізь дану весну…🌳 Засвітимо українське сонце на небосхилі Нової Ери! 💫🤗😍 Нам тут жити… і жити ми будемо так, як веліло серце і чистий дух… 🕊️🌿🌎 Трансформуйся заради дійсно чогось більшого в собі! ✨✨✨ То з ким побачимось на ретриті? Деталі нижче👇 Ретрит \"Оновлена. Цвітіння\" #NeoBereginya #soul #way #pipl #zaverukha © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','5 березня 2024','3 хв читання','/images/posts/Ретрит.png','[]',1,'2024-03-05T14:05:14','2024-03-05T14:05:14');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1655','%d1%8f-%d0%b1%d0%b5%d1%80%d0%b5%d0%b3%d0%b8%d0%bd%d1%8f-%d0%b7%d0%b5%d0%bc%d0%bb','Я Берегиня Землі. Жінки - Берегині. Як розквітнути жіночому началу.','…Вчителі сердечні постійно вкладають свою енергію в звʼязок з виміром духовним! А люди мають вкладати постійно енергію у звʼязок вчителя з виміром матеріальним. Розповідала про це на останньому прямому ефірі. https://youtu.be/MNHi44ISSCQ Тому служити...','["…Вчителі сердечні постійно вкладають свою енергію в звʼязок з виміром духовним! А люди мають вкладати постійно енергію у звʼязок вчителя з виміром матеріальним. Розповідала про це на останньому прямому ефірі. https://youtu.be/MNHi44ISSCQ Тому служити вчителям матеріально - це те мінімальне, що учні можуть зробити в якості вдячності і гарантії контакту з Духом чистим та космічним родом в собі. Бо духовний вимір - це і є середовище нас в НАС… а Вчителі - це ті перекладачі із космічної на земну, яким завдячуємо наявністю безлічі мудрих знань у вимірі планети людей… Вчителі - це чиста свідомість, а не звання чи регалія, робота чи назва на дипломі… Розумієте? Але! Не можуть прийняти чисті стосунки з Вчителем ті, хто не пройшов ворота «матері і батька»! Це мега важливо. Люди, якщо не визріли ви до дорослої позиції, то об вчителів будете лише зцілювати свої неврози дитинства, а не наповнюватися вібраціями знань. Буде проявлятися біль контактування з «авторитетною персоною» і реалізовуватиметься добирання любові, безумовного прийняття, безумовного визнання… а не навчання, знову ж таки. Розумієте? Щоб глибше розкрилась суть - подивіться відео. Саме зараз - коли планета проходить дні СВОГО НАРОДЖЕННЯ. Коли бринить природа в спектрах Жінки-Епохи, коли вібрація Матері максимальна, а це значить, що все може швидко переродитися Саме зараз, зародитися по-новому Саме ЗАРАЗ!!! Із вузької рамки бачення реальності - місцями може бути «боляче» сприймати - полізуть на волю проявлятися неврози бунтаря із підсвідомості. Але! В цьому і полягає ефект самозцілення. Дякуйте кожному за можливість побачити своє нутро, якщо у людини є сила вивертати вас на «ізнанку», то ця людина точно не випадкова. Із широкої рамки бачення реальності - прямий ефір, про який писала на початку, покаже приклад багатьом «а що так можна - прямо і чітко без юління доносити?». Так і треба! Бути в своїй системній ролі, в честі, в чистоті, в правді… Але не виривайте нічого із контексту, не робіть стоп кадри, дивіться цілісно і побачите дуже цінне… Вчителі справжні сердечні завжди схожі на океан провокацій, які ведуть душі до пробудження і свободи. Тут лише питання часу буде координатою. Все. До вас зараз пише Вчитель Алхімії Живого Життя… свідомість моя розширена до рівня бути пропускною системою для вібрації МА, нести спектри любові, добра, процвітання і сакральних знань про гармонію… То ж подивіться відео, яке пробуджує свідомість Берегині! - https://youtu.be/gtH4zipZaKs?feature=shared якщо воно вам забринить… - приходьте навчатися, взаємодіяти, забирайте свої ключі від знань, окриляйтесь Силою і одушевленням, бо саме такий контент я творю… Люблю! До всебічних зустрічей всюди… ! © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','19 березня 2024','3 хв читання','/images/posts/photo_5397743876766294483_y.jpg','[]',1,'2024-03-19T11:48:36','2024-03-19T11:48:36');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1682','1682-2','Презентація першої авторської книги "Бесіди з Ангелами"','Ну що ж, друзі! Цей день настав і він сьогодні… В сторіс інстаграм я анонсую про вихід моєї книги-цілителя та запрошую на непересічну подію, яка відбудеться 14 квітня у Києві… - в мій 41-й день народження пройде жива презентація "Бесіди з Ангелами" !...','["Ну що ж, друзі! Цей день настав і він сьогодні… В сторіс інстаграм я анонсую про вихід моєї книги-цілителя та запрошую на непересічну подію, яка відбудеться 14 квітня у Києві… - в мій 41-й день народження пройде жива презентація \"Бесіди з Ангелами\" ! Ми створюємо нову долю нації, новий світ, нову цивілізацію… Я хочу подякувати Землі і лісам за те, що моя книга отримає втілення, що на її сторінках проявиться мудрість, тому саджатиму дерева… Постійно! Разом з партнером заходу, проектом ДеревоРод ми вже в квітні організовуємо посадку лісу на суму 50 000 грн. І кожна куплена людьми світу моя книга чи колода саджатимуть ліси в Україні… Ви повинні відчути цю Силу Живого Життя… просто зараз… Ми разом з вами маємо робити найважливіші кроки, найцінніші дії, щоб створювати причини для миру і гармонії… …юху… Ідіть дивитися мої сторіс в інста , я щодня розповідатиму щось нове про ПУТЬ, аж до 14.04. Купуйте книгу . Приїздіть фізично обійматися… реєструйтесь для онлайн участі, якщо ви десь в іншій галактиці… - але раджу приїхати фізично навіть з іншої країни, бо це того варте… Книга-миротворець і чудотворець запалить безмежну кількість вогників в серцях… і зробить свою справу - ПІДСИЛЕННЯ І ЗЦІЛЕННЯ… ПРОБУДЖЕННЯ і просвітлення… бо вона просвітницька… 🌟🌟🌟 Вона вже це робить… …допоки створює свою дорогу до реалізації і втілення… … дозволю собі емоції щастя тут… бо вони в мене є… Ааааа… Деталі про захід тут: https://pipl.net.ua/knyha-besidy-z-anhelamy 🌟 Хто планує точно бути? Хто книгу купує і тим самим бере участь у мега потужному проекті збереження життя і процвітання мудрості? Пишіть https://www.facebook.com/share/p/EQsR5wuq9TQHBRMa/ © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Новини','Ірина Заверуха','1 квітня 2024','3 хв читання','/images/posts/32.jpg','[]',1,'2024-04-01T09:36:27','2024-04-01T09:36:27');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1735','1735-2','Що нагорі, те і внизу','🌟Голосовий підкаст на тиждень вже в PiplClub ! Так. В закритому просторі, не в публічному доступі. Знаю, що скоро з багатьма людьми взагалі вібраційно перестану пересікатись. З деякими давно не пересікаюсь. Чому? Розказувала на курсі ProResurs про 3d...','["🌟Голосовий підкаст на тиждень вже в PiplClub ! Так. В закритому просторі, не в публічному доступі. Знаю, що скоро з багатьма людьми взагалі вібраційно перестану пересікатись. З деякими давно не пересікаюсь. Чому? Розказувала на курсі ProResurs про 3d, 4d і 5d реальність. Не тупіть, не зволікайте, купуйте курс в записі і майте відповіді на питання з практикою і деталями безцінними… Пишіть, кому курс потрібен👇 🌟В 19.00 сьогодні, 4.04, вестиму прямий ефір в інста, трохи розповім про ці виміри… 3d - 5d … І про тенденції квітня. Я не створюю прогнози. Давно. А пояснюю людям ситуацію в енерго-інформаційному полі. Деяким це не подобається. Яким? Із 3d виміру. Бо вони звикли отримувати інструкції. Перекладати відповідальність за життя на якусь авторитетну персону. А людям з 4d і 5d дуже подобається володіти сакральними знаннями із рівня 6d щоб творити світ, мати орієнтири в своїх діях, враховувати вібраційні коридори і континіуми, розвивати світлі проекти разом. Якщо ви геть нічого з мого допису зараз не зрозуміли, це свідчить, що ви сильно запізнюєтесь в розвитку і не живете в унісон з часом та еволюцією планети. Ідіть через тіло шукати свій дух і пробуджуватись. Десь ви сильно загубились. Робіть практику, дійте. Робіть йогу, медитуйте, рефлексуйте, ставайте частиною спільнот світочів… вибирайте… зараз є вибір… Поки що він є. Скоро побачите, яке усе насправді, і де був океан ілюзій. А що виявилось Силою, яка чекала свого часу за простотою форми. Спішіть! Дуже спішіть… Бо виміри розділяються. Не довго залишатимуться мости між 3d і 5d, «шпагат» буде іще кілька років і все… Далі - як рибки в акваріумі. Залежні. Невільні. Обмежені страхом і мисленням, яке не може долати коридори матриці будуть активно обслуговувати технократичну ілюзію своєю психічною енергією душі. Це не жарт. І не страшилка. Зараз іде боротьба і vійна за душі, за увагу, за енергію серця, а не ринки чи кордони. Політична і економічна палітра процесів - це дуже вузька рамка бачення того, що коїться… 🙏🙏🙏 https://youtu.be/8B-5RCV3Xwo © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','4 квітня 2024','3 хв читання','/images/posts/photo_5219708102138517787_y-1.jpg','[]',1,'2024-04-04T15:26:04','2024-04-04T15:26:04');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1739','%d0%b1%d0%b5%d1%81%d1%96%d0%b4%d0%b8-%d0%b7-%d0%b0%d0%bd%d0%b3%d0%b5%d0%bb%d0%b0','Книга "Бесіди з Ангелами"','… 💫 нова історія почалась… Книга-цілитель тут 👉 https://pipl.net.ua/knyha-besidy-z-anhelamy З любовʼю до людей світу…💗 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе ли...','["… 💫 нова історія почалась… Книга-цілитель тут 👉 https://pipl.net.ua/knyha-besidy-z-anhelamy З любовʼю до людей світу…💗 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Новини','Ірина Заверуха','15 квітня 2024','3 хв читання','/images/posts/photo-43-scaled.jpg','[]',1,'2024-04-15T12:12:29','2024-04-15T12:12:29');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1746','%e2%9c%a8%d0%ba%d0%bd%d0%b8%d0%b3%d0%b0-%d1%86%d1%96%d0%bb%d0%b8%d1%82%d0%b5%d0%','✨Книга-цілитель народилась і полетіла по світу!!!','… мої золоті люди-світочі, я настільки глибоко наповнена енергіями дня, що прожила вчора… і усвідомленнями масштабу події та інтеграції своїх станів, що поки можу сказати лише це… Я є любов, щастя, мир, гармонія, всесвіт! …дякую усім, хто був, є і бу...','["… мої золоті люди-світочі, я настільки глибоко наповнена енергіями дня, що прожила вчора… і усвідомленнями масштабу події та інтеграції своїх станів, що поки можу сказати лише це… Я є любов, щастя, мир, гармонія, всесвіт! …дякую усім, хто був, є і буде на дорогах життя! 🙏 ✨Книга-цілитель народилась і полетіла по світу, бо в неї є крила Ангелів, як і в мене…✨ 🤗🫶 Презентація книги у відкритому доступі інста залишається для усіх, кому є цінним доторкнутися до імпульсу Творця і творити СВОЄ…🤩 Заходьте. Дивіться. Живіть крізь неї … Презентація тут https://www.instagram.com/irynazaverukha?igsh=MTIyczc3emdndG9sdw== …Там є все - і історія живого життя, і моя історія поразок та перемог, і спонтанність, і медитація глибинна, і приклад путі подолання страху, і тріумф в моменті… і навіть пісня, яка просочилась у шпарину моєї творчої свідомості і зловила мить для проявлення… Хто був на офлайн і онлайн презентації - як ви? 🙌🤓 Ми святкували понад 8 годин зустріч, але в тих двох годинах офіційної частини презентації - цілий світ… 🥰✨🌍🕊️🌿 … деталі. Про кількість людей, організацію проекту, про покупки, зібрані кошти для посадки лісу, про викупаних в любові споріднених… - це все буде пізніше… Я розповім про всіх! 💚 Живу. Дихаю. Приймаю свою оновлену форму Суті. Світити і живе ростити - простота, в той же час неймовірна висота! 💫 Надихайтесь. Торкайтесь до поля і підсилюйте свої мрії… досягайте висот своїх, друзі! Книга тут https://pipl.net.ua/knyha-besidy-z-anhelamy Презентація тут https://www.instagram.com/irynazaverukha?igsh=MTIyczc3emdndG9sdw== Багато яскравих моментів в сторіс тут https://www.instagram.com/pi_platform?igsh=MTZoeWtxbDdidmJqaQ== © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','15 квітня 2024','3 хв читання','/images/posts/Презентація.png','[]',1,'2024-04-15T10:26:00','2024-04-15T10:26:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1862','%d0%b0%d0%ba%d1%82%d0%b8%d0%b2%d0%b0%d1%86%d1%96%d1%8f-%d1%82%d0%b2%d0%be%d1%80%','Активація творчої енергії і радості життя!','То що там у тебе на екрані життя - щаслива доля? Чи егрегоріальні контракти та стереотипи «пʼють пиво» і дивляться кіно ілюзій, відволікаючи від еволюції свідомість? 😘 Сьогодні в вечері вестиму ресурсну зустріч з розбором тенденцій місяця травня в за...','["То що там у тебе на екрані життя - щаслива доля? Чи егрегоріальні контракти та стереотипи «пʼють пиво» і дивляться кіно ілюзій, відволікаючи від еволюції свідомість? 😘 Сьогодні в вечері вестиму ресурсну зустріч з розбором тенденцій місяця травня в закритому клубі практиків живого життя PiplClub Якщо ви іще не з нами, - запрошую бути! Відчути потік, і дозволити собі більше… більше сили, більше радості, більше знань, більше можливостей і енергії, більше причин для щастя… Саме в даному місяці активуватиму цю вібрацію поля - Творчої енергії, що бринить із джерела буття! 🥰🤩🌍✨ Бо і мій творчий потік не пересихає… а масштабується і процвітає… бо любов керується лише любовʼю, генеруючи енергію в собі… Обіймаю дією… 🤗 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','6 травня 2024','3 хв читання','/images/posts/photo_5311999295697836140_y.jpg','[]',1,'2024-05-06T10:15:33','2024-05-06T10:15:33');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1867','%d0%bf%d1%80%d0%be%d1%8f%d0%b2%d0%bb%d0%b5%d0%bd%d0%bd%d1%8f-%d0%b4%d1%83%d1%85%','ПроЯвлення Духу','Мої висновки за результатами прожитого потужного місяця квітня і вхід в травень… 🌱Можливо все! Любов це єдина валюта, яка створює справжні коридори реальності для тих, хто щедрий серцем і сміливий духом, для тих, хто вільний від кармічних програм і ж...','["Мої висновки за результатами прожитого потужного місяця квітня і вхід в травень… 🌱Можливо все! Любов це єдина валюта, яка створює справжні коридори реальності для тих, хто щедрий серцем і сміливий духом, для тих, хто вільний від кармічних програм і живе без ілюзій залежності від матеріальних ресурсів; 🌱усі дивляться своє «кіно» згідно рамки рівня свідомості… хтось думає, що падає у прірву, для інших - це вільний політ крізь свободу без обмежень; хтось по реверсному путі проходить ворота «матері і батька», занурюється в традиції, переймає естафету хранителя, а хтось бачить це як деградацію і крок назад… долю тєрпіли… Ми усі в дорозі. І це дорога або еволюції, або інволюції… згідно наших екранів мислення 🧬люди, ставайте хакерами матричних алгоритмів! Приходьте на консультацію з деконструкції хламу ума. Вчіться. Робіть йогу свідомості (а не будь яку і все підряд, і не зрозуміло для чого… добро заради добра - це теж не відповідь!), медитуйте, заходьте в приСутність, вмирайте в своєму хибному его, щоб народитися в тілі душі, яке теж потрібно «насичувати», а не лише свій живіт наповнювати харчами🧬 🌱реалізація із повноти Суті своєї ніколи раніше не була настільки максимальною, як зараз. Можливості для всього мають усі! І лиш обмеження в ментальних установках та тілесно/емоційні неврози тримають людей в рабстві власних ідей про свої проблеми; 🌱ми нині проходимо активацію багатовимірної колективної душі. Хто ми? Світочі з мисленням 4d і 5d. Відбувається швидке народження нової матерії і прийняття нової форми життя, відносно формули ідентичної родової сили… 🌱в ДНК древніх душ відкривається доступ до памʼяті про першокоди, вони входять в резонанс з простором і або створюються повторення сценаріїв з більш глибокими кармічними наслідками, або обнуляються назавжди усі конфлікти. Зараз в серцях Світочів пробуджених примиряються гени Атлантів і Лемурійців, релігійних лідерів і колись ворогуючих кланів, космічних племен і земних правителів та династій… це не солодкий процес, тому в тілах коїться справжня імунна революція… а на екранах ума - vійни 🌱надзвичайно важливо підвищувати і підсилювати СВІДОМІСТЬ тіла, особливо жінкам… надзвичайно важливо підвищувати і підсилювати СВІДОМІСТЬ душі, особливо чоловікам… 🌱прокидаються старі портали планети, через які не «ходили», бо вони були створені, як аварійні, на всякий випадок. Всякий випадок - це зараз. Тому люди-портали, які просвітлені, своєю присутністю тілом-місцем сили і яснобаченням запускають процес активації проходів; 🌱матір майбутньої жінки-месії іще не зачата… ✨✨✨✨✨ ©️ IMARIAMASTER ПРОШУ ВАС - не приміряйте на себе описані мною процеси і ролі, якщо ви не живете ось так життя - через широке бачення реальності! Не домислюйте себе «колонами світла» ілюзорних структур по названію лиш тому, що вам хочеться вірити в себе, як в ісключітєльно важних міжгалактичних посланців… я серйозно. Ми просто усі є світлом… Але! Напрактикуйте силу магнітного поля і ауру нейтрального ума. Нещодавно розплутувала в одній древній могилі Десятинної площі енергетичні фантоми інформації, що колись давно перемішались кістками тіл і як наслідок генів роду - слуги, охоронця, потомків правителя і мольфарів-хранителів частот. Виконала труд, який віками не міг бути реалізований, бо раніше просто не вистачало психічної енергії і висоти свідомості. Тепер усі на своїх місцях. Рід Князів Київських побачив прохід, бо викривлення ДНК зцілено. Буде кардинальна зміна процесів на усіх фронтах влади. А воїни-охоронці стали воїнами - тими, хто на дверях стоїть і за порядок та безпеку відповідає. А слуги знайшли спокій в служінні на кухні через їжу і чистоту простору. Але найціннішою для мене була свобода структури Єдиного Роду Відунів і цілителів Землі, бо тепер ніхто з них не мусітиме відчувати в собі боротьбу між чотирма дорогами, і не буде мучитися від не своїх задач… 😘 Я і плачу від щастя, розповідаючи вам цей факт. І плачу від печалі, бо прочитають тисячі, а зрозуміють лише десятки… для мене це до сих пір сумний факт. Що люди шукають гроші, владу і бачать велич там, де натовп. Але справа в тому, що чим нижчий рівень вібрації - тим більший натовп. На високі вібрації живого життя перейшли лиш 6-7% населення планети. Ви розумієте, про що я пишу? Кого усе це стосується, - ті мають БАЧЕННЯ і потужно розвинену інтуїцію. Як мінімум - знаходяться в тісному контакті взаємодії з полем провідників. Таких як і мій Аватар, в тому числі, та інші. Смакувати розповіді «містичні» і не мати способу мислення цілісного, йогічного, чистого і усвідомленого служіння Ієрархії Світла - не потрібно. Не роздувайте своє его хибною значимістю! Дивіться в простоту буття. Я на консультаціях слухала від 328-ї чергової жіночки, про те, що вона чітко знає про свою інкарнацію Марії Магдалєни, наприклад. Але це всього лиш діалог з ТРАВМОЮ жіночого колективного болю планети. Бо ця ВОНА є рівнем свідомості, що називається програма «зцілення гену шлюшності і перехід до безумовної любові». Розумієте? 😘 Я пишу для вібраційно споріднених зі статусу Свідомості Вчителя Алхімії Живого Життя!🙏 Якщо вам не видно в собі цього рівня свідомості, ви і в інших його не побачите - проходьте повз і не затримуйтесь. Ми з вами з різних космічних Племен. А зараз усі повинні прийти до свого РОДУ ДУШІ. Тому йдіть за покликом і знайдіть своїх… 🙏 бажаю вам удачі! Мій путь людини - це приклад обнулення егрегорів, зцілення розділення і війн; мій путь Душі - мироТворчість і проСвітлення… Тому поза межами кімнат з кривими дзеркалами - все сильно інакше. Моя міжгалактична багатовимірна Суть нікому нічого не повинна і під образи уявлень про норму не підлаштовується… не очікуйте, якими вам мають бути «правильними» вібраційні вчителі. Я все одно вестиму через путь інтуїції алхіміків і робитиму те, що потрібно, а не те що комусь подобається. Спокійно. Мудро. Красиво. І хоробро… бо в потоці істини завжди спокійно, захищено і ресурсно… 🙏💗 Зустрінемось на схилах Кришталевої гори зовсім скоро на ретриті \"Проявлення Духу\" в Ізках з тими Жінками, які дійсно є носіями зіркових ДНК, і мають задачі розпаковки своїх дарів NEOжриці, NEOберегині, NEOшаманки, бо в цьому полягає моя роль в процесах Землі. Будемо працювати з проекцією аури перемоги! 🙌 Це буде мій 39-й ретрит, організований для жінок…🤗 Ви уявляєте, який це колосальний труд? Ті, хто хоч щось в своєму житті створював, ніс відповідальність дорослу і йде свій путь вірності Творцю - знають точно. В мене усе добре з усвідомленням своєї місії, усе добре з самоцінністю особистості, усе в гармонії в роду… всюди є любов і чистота мотивації. Я потужний провідник Сили МА та мудрих знань від Джерела. Ділюсь ними щедро… Обіймаю усіх! Ретрит проведу 21-26 травня… Набір в групу закриваю 12.05. 😘Золоті, ніхто не буде бігати за вами з персональними запрошеннями. Бо часи зараз такі, що ментально зрілі усе чують… (Можна приєднатися до ранкових онлайн сатсангів! Пишіть… дамо посилання) В Ізках житиму також глибоке служіння Життю, братиму з собою в походи і церемонії усіх енергетичних двійників своїх учнів, реалізовуватиму сеанс родового зцілення, архівуючи грубі програми викреслених генів, розірваних звʼязків… Ну і звичайно, що вестиму саму мега потужну програму ретритну #ПроЯвлення Духу, після якої суттєво і якісно зміниться і моя команда, і мої проекти, реалізовуючи перехід на рівень масштабу Лідерів Золотого Віку Творця… ✨✨✨ …коли йде дощ, хтось радіє і танцює під ним, а хтось жаліється і чекає сонця. Коли приходить сонце - вже заважає спека… І за усім цим димом без вогню криється звичка людей - страждати «по любому»… Вибирай - «Побуду щасливою», бо про страждання вже усе знаю! Вибір без вибору! 😘 Бо усі ми точно знаємо, який буде наступний крок… © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','10 травня 2024','6 хв читання','/images/posts/Проявлення-Духу.png','[]',1,'2024-05-10T10:21:35','2024-05-10T10:21:35');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1869','%d1%83%d1%81%d1%96%d1%85-%d0%bc%d0%b0%d0%bc-%d0%b7%d1%96-%d1%81%d0%b2%d1%8f%d1%8','Що таке материнство','Материнство це не героїзм… а простота життя і природній стан зрілої жінки, яка повинна завжди залишатися Жінкою, без втечі в цю гавань #яжемать, де ніби то так багато усіляких прав і свобод… а головне ілюзії влади. Материнство - це стан середовища ви...','["Материнство це не героїзм… а простота життя і природній стан зрілої жінки, яка повинна завжди залишатися Жінкою, без втечі в цю гавань #яжемать, де ніби то так багато усіляких прав і свобод… а головне ілюзії влади. Материнство - це стан середовища високої гідності, що визріло для продовження і передачі набутого досвіду. Духовне материнство аналогічно, берегині роду людського в першу чергу - це особистості цілісні, реалізовані та щасливі. 🙏Нехай в цьому світі плодиться зріле і здорове материнство, вільне і ресурсне… в повноті стосунків в першу чергу жінки з собою та життям, потім з партнером, і лиш із сінергії сильних - нехай приходять у світ нові люди, із любові та мудрості зрощені… Материнство своє потрібно із поваги і вдячності прийняти, визнати його простоту, відпустити і жити себе жінку та живого життя висоту. Усіх мам, зі святом! 🌺🌼🌸🌹 Різні ми - різні у нас діти, різні сценарії долі… але усі прекрасні по-своєму… Усіх, хто являється частиною циклу творіння в статусі #жінка, вітаю з усвідомленням і ролі #мама… бо це роль, а не ідентичність. В структурі особистості, в нашій монаді внутрішньої сімʼї не повинна МАМА займати увесь простір, витісняти інші рівні свідомості і заповнювати собою як єдиною інстанцією поле… це призводить до слабкої позиції батька, чоловічого начала, до подавленої волі, до залежностей і різних видів супутніх наслідків, що породжують дисбаланс, в тому числі є причиною жертвенного мислення. І навпаки бути не повинно. Коли мама не визнана і не отримує за своє «я є» вдячності та цінності… Я вібраціолог, - розвиваю науку про вібрацію Творця, чистого Бога, що кружляє крізь виміри по циклу СА ТА НА МА. Кожен звук, стан, колір, висока думка - це вібрація. Це спектр. Це частота. І це дія та її результат… СА - вічність ТА - життя НА - смерть МА - переродження Подивіться на слово МАТИ (мата) - МА ТА - переродження життя… тобто ЕВОЛЮЦІЯ. На слово МАМА - переродження двічі. Тобто черговий шанс на зміну сценарію роду отримують усі, хто має відношення до таїнства материнства і плекає його чистоту повагою до жінки. МАТИ - це завжди про еволюцію. А підтримкою самого життя, забезпеченням гармонії системної займається ТАТО, розумієте? Мама - це і прохід до божественного і вихід із божественного. Але без чіпляння за статус. Має бути свобода від усього. І від цього теж… Велика МА голосом душі до усіх людей ллється через красу природи, музику вітру, шелест листя, обійми дощу, і нагадує чиї ми діти насправді - любові Божої. І уся природа - наша мати. Ось так я відчуваю життя. Себе в ньому. І його задачі… Кому резонує? 😘 А кого це дратує? 😘 💗 Пробуджені прекрасні душі, ми маємо еволюціонувати і це. Поняття Мама, сімʼя, батько, рід… Нехай проростає філософія істини єдиної…🌱 Кожній хочу сказати - ти НАЙКРАЩА МАТИ для своїх дітей, і можеш іще більше дати, коли дозволиш собі щодня щасливішою, мудрішою і здоровішою ставати… 😍🤗 Хочу нагадати про наявність двох фундаментальних курсів, які розкривають ці теми і розширюють свідомість до рівня бачення реальності реальною, без ілюзій про як «правильно». Це курс #ЯЖінка і #СферичнаСімя від #IMARIA Знайдіть і пізнайте більше через досвід, посилання залишаю 🫶👇 https://pipl.net.ua © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','12 травня 2024','3 хв читання','/images/posts/get-2.jpg','[]',1,'2024-05-12T10:56:00','2024-05-12T10:56:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1876','%d0%bf%d1%80%d0%b8%d0%b9%d0%bc%d0%b8-%d1%81%d0%b2%d1%96%d0%b9-%d0%bf%d1%83%d1%82','Прийми свій путь, увесь свій шлях, кожен крок і дію !','Ти хочеш щоб минуле і далі мало над тобою владу, чи все ж таки пора жити свою Суть? Прийми свій путь, увесь свій шлях, кожен крок і дію ! І ти приймеш себе… Ти перестанеш купувати і продавати любов, і почнеш проживати любов… Прийми свій путь і в прое...','["Ти хочеш щоб минуле і далі мало над тобою владу, чи все ж таки пора жити свою Суть? Прийми свій путь, увесь свій шлях, кожен крок і дію ! І ти приймеш себе… Ти перестанеш купувати і продавати любов, і почнеш проживати любов… Прийми свій путь і в проекціях батьків та дітей, і в історії предків, і в твоїй персональній історії, де ти щодня програвала сама собі, зраджуючи мрії і реалізовуючи дії, які не хочеться навіть пригадувати і дивитися на них… бо не такі. Не «які»? Чому? Чому ми такі жорстокі до себе і світу? Бо на вузькій ділянці буття нам не відразу доступна уся палітра сенсів і відповідальність за наслідки. Ми сліпі в своїй неідеальності ума і в той же час, ми прекрасні в кожній миті. Проявляючи наполегливу жагу до путі, іноді вибираємо коридори маршруту не ті… Допоки тобі соромно, допоки є почуття провини за помилки і не ідеальність… - ти не можеш рухатися вперед, тебе тягнутиме назад ця резинка від старих трусів і боляче вдарятиме в самий не підходящий момент… ти падатимеш на коліна знову і знову і вимолюватимеш прощення у не існуючих палачів… Дежавю. 🌀 А хто суддя? Ніхто. Ум будує плани і розчаровується об них. А дух створює реальність… Все вже є. І завжди було… Прийми свій путь! Той, який позаду і попереду… Прийми свій путь і перестань ображатися на Бога за нього. Тоді буде свобода і початок… Пішли разом… 🙌🧬 Будемо активувати код безумовної любові! … початок 🌀 Вже скоро. РЕТРИТ В КАРПАТАХ \"Проявлення Духу\" 21-26 травня. Готуюсь до неймовірної програми, яка мене саму вже окриляє до небес від передчуттів та прекрасної енергії… 🙏🥰 А сьогодні в програмі #Крила проведу для учасниць цілительний сеанс, який живуть лише один раз за втілення. Вперше проведу. Бо прийняла і я свій путь… в усі сторони… 🧬🧬🧬 В унікальні часи ми з вами спостерігаємо за життям… Правда? IMARIAMASTER #way #soul © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','13 травня 2024','3 хв читання','/images/posts/440749450_422385353982063_7952801425827297287_n.jpg','[]',1,'2024-05-13T12:09:39','2024-05-13T12:09:39');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1879','%d0%bc%d0%b0%d0%bc%d0%b0-%d0%b7%d0%b5%d0%bc%d0%bd%d0%b8%d1%85-%d0%b4%d1%96%d1%82','МАМА земних дітей, материнська проекція і позиція...','Мама та Батько! - твій квиток у гарантовані зміни на краще! Я буду короткою в цьому посланні, у цій статті, але ефективною за змістом. Читайте. Беріть алмази цінності та покращуйте своє буття. 💎Все, що ми осуджували коли-небудь, що піддали критиці, в...','["Мама та Батько! - твій квиток у гарантовані зміни на краще! Я буду короткою в цьому посланні, у цій статті, але ефективною за змістом. Читайте. Беріть алмази цінності та покращуйте своє буття. 💎Все, що ми осуджували коли-небудь, що піддали критиці, все на що ми образилися, відкинули - стає частиною нашого енерго-інформаційного поля і переслідує, як страшний кошмар наяву! Чому? Як це працює? По-перше, всім рекомендую вивчити СТРУКТУРУ ЛЮДИНИ і етичні закони живого життя, що пояснюють істинні причини всього. Приходьте – я створила дистанційний курс фундаментальний , який можна пройти у вільному потоці самостійно та зрозуміти реальність напряму. Матриця – це система. Можна жити у ній. А можна жити поза нею. Але в рамках іншої системи. У будь-якому випадку, поки ми в тілі і живі, – у нас є рамки, межі матерії. Вони нас обумовлюють. І скільки б ми не втікали від цього факту, це фактом залишиться - ми тілесні, ми з плоті та крові, ми зіткані з генів предків, з «Єдиного планетарного пластиліну», який може або керувати нами, або ми ним, спрямовуючи ресурси і потенціали реалізації справжнього плану Душі. І ось вона простота намалювалася. Якщо ми в матриці страждань - то повністю залежні від генів предків, «від системи», в якій завжди є хтось СТАРШИЙ і винний чи відповідальний за все (і сюди ми можемо поставити батьків, рід, владу в країні, закони, мораль, релігію, екологію, погоду, Бога… будь-які обставини). І ми можемо бути частиною іншої системи - ВІЛЬНИХ Зрілих дорослих душ, які несуть самі відповідальність за свою реальність, керують нею, об''єднуються з собі подібними і пульсують в унісон не на догоду Догмі або вигоді, а за законами творчого потоку і чистого натхнення. Перші зазвичай опиняються в ув''язненні своїх механічних налаштувань через неусвідомлені претензії на будь-якого зовнішнішнього аспекту (зовнішній аспект = ЗА, ще раз розшифрую поняття і далі писатиму тільки ЗА, маючи на увазі, що це і/або рід, країна, нація, влада, начальство, президент, культура, правила, традиції, релігія, Бог…). Тобто, банально, людина навіть не пам''ятає цього, але в душі сидить емоція образи наприклад на батька чи маму через нереалізовані потреби, і блокує вільну течію енергії, яка насправді дає можливість усвідомити себе Божественним, і створюючи на екрані життя цієї людини обставини, в яких інші істоти будуть на ЦЮ Ж ТЕМУ ЙОГО ОБРАЖАТИ. Данний тип блоку я називаю - «обрив зв''язків нижнього рівня». І є ще один. Це коли ми всередині себе, на рівні вже ДУМОК І ПЕРЕКОНАНЬ (а не емоцій) носимо уявлення про «правильне-неправильне» і засуджуємо те, що нам «не прийнятно» - створюючи тим самим ситуації, в якій ми зіткнемося з проживанням того, що самі ж висміювали чи критикували. Чому? Тому що це наша зона зростання для прийняття СЕБЕ і світу безумовно, безоціночно. І ось це я називаю – «обрив зв''язків верхнього рівня». Можна також описати умовно як «обрив зв''язків внутрішнього рівня» є в нас і «обрив зв''язків зовнішнього рівня» у нас є. І ще простіше – перший пов''язаний з МАМОЮ. А другий пов''язаний із БАТЬКОМ. Перший – емоційний, чуттєвий, з мамою пов''язаний, з потребами, з ресурсами, з внутрішнім світом, ще його можна назвати – минулим досвідом. Другий – ментальний, інтелектуальний, розумовий, з батьком пов''язаний, із визнанням безумовної геніальності без оцінки, із зовнішніми комунікаціями та досягненнями, з результатами, ще його можна назвати – Майбутнім, якого ми прагнемо. Побачили взаємозв''язки? Чудово! А тепер спитайте себе «КОМУ Я СТАРАЮСЯ? КОМУ Я ДОКАЗУЮ І ЩО? Навіщо я це роблю?». Запитайте себе ще «ЯКІ МОЇ ПОТРЕБИ НЕ ЗАДОВОЛЕНІ? ЧОМУ? ЧОГО МЕНІ НЕ ВИСТАЧАЄ і я чекаю цього від партнерів та світу? Що було б якби мені всього вистачало, яким би було моє життя?». Мільйони людей шукають підтвердження своєї важливості, похвали та значущості, тому що «ТАТО цього не дав» (читай як ЗА), або дав мало. Мільйони людей шукають прийняття безумовного і своєї потреби тому, що «Мама цього не дала» (читай як ВА), або дала мало. Такий світ у нас з вами був – дефіцитний! Не тата та мами погані, а система так влаштована - за правилами гри боротьби за ресурси. Не втягуйтесь, не запрошуйтесь до страждань у гості! 🤗 Бо світ є й інший! Не такий чорно-білий. Змінюйте налаштування системи. Не ремонтуйте старі гаджети в собі, викидайте і ставте нові версії «програмного забезпечення» під час для людини-духовної. Досить рятуватися і «працювати над собою», це не ефективно – зараз апгрейд системи досягається смертю старого его, зміною мірності, запитом еталонних кодів та шифрів на щасливе життя. Не чекайте від предків минулого підтримки - їм нема чим підтримати, вони не мають тих ресурсів, які нам потрібні зараз для побудови нової цивілізації, але те, що вони мають МИ здатні ВИКОРИСТОВУВАТИ на благо і застосувати у своїх системах. Ми істоти Світла!✨ І це треба зрозуміти. І наповнити Світлом планету, світочі. І ось у нас з вами є певна точка ТУТ І ЗАРАЗ, в якій ми і не в минулому (не залежні від емоцій та блоків дитинства життя і Душі, не очікуємо, що нам додасть мама, природа та задовольнить потреби) і в якій ми не в Майбутньому (не залежні від думок і планів на конкретні результати, не ділимо світ на «такий і не такий», не шукаємо лайки та успішний успіх заради визнання батьком, не намагаємося бути добрими для Бога, або навпаки не бунтуємо проти нього)! У цій точці ми є по-справжньому. Ми в ній ЖИВІ. В решті – ми в ілюзії і нас хитає маятник Матриці, як підвішену тушку на гілці буття. У точці ЄДНОСТІ ми самі собі мати і самі собі батько! Ми дорослі та зрілі! Ми вдячні минулому і ми цінуємо сьогодення і ми відкриті спонтанності майбутнього, ми не контролюємо потік, а рухаємось у потоці та розширюємось у потоці, іноді ми звужуємось, і не надаємо цьому ярликів, не навішуємо на будь-який досвід оцінок, ми не називаємо щось успішним, а щось не успішним, ми не шукаємо схвалень, думок, не боремося з системою, ми не тікаємо від відповідальності, а навпаки відчуваємо єдність з усім світом і свої дії узгоджуємо з потребами всього живого і сущого, беремо на себе більше природної відповідальності; ми не сумуємо від дрібниць, відчуваючи різні почуття, не стаємо їх заручниками, відчуваючи різні думки не стаємо їх рабами; нам не «повинні» і ми «не винні»; ми не захищаємо себе парканом «я все знаю», а навпаки відкриті всьому новому, прагнемо контактів та практичного досвіду; ми не чекаємо старості, і не боїмося смерті, і відповідно не боїмося самого життя та його мінливості, його потоковості, нестатичності, воно нам цікаве - ми весь час чогось ХОЧЕМО, бажаємо, прагнемо (і справа не у віці за паспортом!) . Ми несемо відповідальність за близьких і не з мотивації слабкості й страху, боргових контрактів щоб вижити, та з Сили любити і ділитися повнотою; ми не тікаємо від чогось, а рухаємося до… але коли приходить досвід і треба бігти і створювати безпеку - ми робимо це, не втягуючись в агонію пристрастей та страждань рівня «трилер відпочиває», «жерсть, зате буде що згадати». Зрозумійте, ми тут не для того, щоб було що згадати! Ми тут для того, щоб ПРОЖИВАТИ КОЖНИЙ МОМЕНТ, як найнеймовірніший і найпрекрасніший; щоб ніколи було ЗГАДАТИ і порівнювати, і не було про що шкодувати… ми тут для руху у духовному вертикальному розширенні, через прояв СЕБЕ у формі. Ми тут ЛЮБИТИ. Ми тут щоб Бога собою відчути. Не вірити у нього чи не вірити. Відчути. Відчути сенс та перестати шукати сенс. Жити і сяяти, творити і радіти… У цій точці «тут і зараз» можливе справжнє щастя, безумовна Любов, і чиста свобода! Щоб у неї потрапити, потрібно розплутати клубок емоцій – раз! І клубок мислеформ, установок – два! Робіть йогу. Медитуйте. Добре, якщо це робиться одночасно. Тоді ефективність вища у рази. І клубок цей починається з МАМИ І БАТЬКА! Так, дорогі, немає сенсу бігти далі, якщо з базовим не розібралися. Чоловіки та жінки по-різному влаштовані і розплутування теж процес трохи характерний. Але фундаментальні кроки – ідентичні. Багато людей роками намагаються пробачити батьків та перейти на інший рівень. А насправді робити треба не це. Багато людей намагаються перестати критикувати людей, засуджувати та ділити світ на «добрий і поганий». А насправді робити треба не це. Точніше не там вихід. Він у тій самій точці, де й вхід. ❓❓❓ Де ця точка? І що треба робити? ❗️❗️❗️ Фсе… обіцяла коротко, вийшло як завжди 🤓 Але цінність постаралася передати. Вийшло? 😘 Ефір про МАМУ: https://youtu.be/o5wSDqgHt_E © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','12 травня 2024','7 хв читання','/images/posts/maxresdefault.jpg','[]',1,'2024-05-12T12:25:12','2024-05-12T12:25:12');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1903','%d0%b7%d1%86%d1%96%d0%bb%d1%8e%d0%b2%d0%b0%d0%bb%d1%8c%d0%bd%d0%b8%d0%b9-%d1%80%','Зцілювальний ресурсний марафон "ЩАСТЯ Є!"','Як я можу через свідому позицію, через мудру проекцію та присутність, через свій медитативний розум керувати реальністю? Хоча б як мінімум опанувати свій стрес, страх, не ясність і бажання гніватися на все та всіх…? 👇 Уявіть, що у вас всередині є пев...','["Як я можу через свідому позицію, через мудру проекцію та присутність, через свій медитативний розум керувати реальністю? Хоча б як мінімум опанувати свій стрес, страх, не ясність і бажання гніватися на все та всіх…? 👇 Уявіть, що у вас всередині є певна подоба Демона (це критик, спокусник, дослідник світу через досвід, захисник граней особистості, егоїст, найчастіше говорить він усьому «ні») і Ангела (це уособлення доброти, позитивізм, ентузіазм і віра у найсвітліше, це єдність без кордонів, найчастіше каже всьому «так»). Умовно ми називаємо ці частини негативним розумом (звіриним) та позитивним розумом (казковим). Але у нас є так само і ЛЮДСЬКИЙ РОЗУМ, який ми називаємо НЕЙТРАЛЬНИМ. Він локально (дуже умовно при цьому!) знаходиться у зоні СЕРЦЯ. Негативний розум (умовно) знаходиться в зоні свадхістана чакри (репродуктивні органи), його ще називають лунним. Позитивний розум (умовно) перебуває у зоні маніпури чакри (сонячне сплетіння) , тому називають його сонячним. Як #ЛЮДИНА ми починаємося і проявляємось з СЕРЦЯ, тобто з точки нейтральності, де немає поділу на «так» і «ні», на «я» і «не я». Саме в серці кінцевий (земний, тілесний) і безкінечний (космічний, інформаційний, духовний) начала - ЄДИНІ і цілісні. Перебуваючи у свідомості нейтральності, будучи душею, яка одночасно є і шлях, і сама подорож, і мандрівник, і досвід… ми завжди здатні проаналізувати ментально кожну ситуацію та прийняти рішення з якої саме частини себе проявитися ЗАРАЗ. Тобто умовно кажучи, Ангел і Демон - це паритетні партнери, а не супротивники. Проекції якостей, згідно ситуації. У медитативному розумі ми запитуємо себе: «Яка частина мене зараз знаходиться на ЦЬОМУ ШЛЯХУ?» Я дозволяю собі ДОСТУП І ВЗАЄМОДІЮ, єдність і цілісність з цією частиною! … і далі відбувається вже реалізація! Просто приготуйся сприймати. От і все. 🤗 Хочете прожити глибину самих себе і зустрітися з потоком безкінечної енергії?😘 Тоді до зустрічі на марафоні #ЩастяЄ! з вивільненням, очищенням, підсиленням та перепроживанням Душі народження! «НЕЙТРАЛОЧКА-моя паличка виручалочка» стане вашим кредо і базовим станом. 👌 Коли? 14.06.2024 Буде 14 днів безцінного досвіду в полі ресурсному. Деталі цікаві? Напишіть слово «марафон» і усе пришлемо. А поки що нашаткуйте під цим постом причин та мотивацій, друзі, які точно вже зареєстровані на марафон, - чому ви вибираєте проживати зі мною марафони?👇😍 https://www.facebook.com/share/p/RuUiQrzGfhRveoQ5/ © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','7 червня 2024','3 хв читання','/images/posts/ЩАСТЯ-Є-1.jpg','[]',1,'2024-06-07T19:06:06','2024-06-07T19:06:06');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1907','%d0%b4%d1%96%d1%8f%d1%82%d0%b8-%d0%b2-%d1%81%d1%82%d0%be%d1%80%d0%be%d0%bd%d1%83','Діяти в сторону своїх мрій!!!','СВІТЛО. Енергетика… ЕНЕРГЕТИЧНА ВОЛЯ - тут така ж сама ситуація, як в усіх інших суспільних просторах, - вона про якість вібраційного фону колективної свідомості. Уявіть собі ситуацію ТАК.👇 «Українці дорожчають як вид!» Що скажете тепер? Не в Україні...','["СВІТЛО. Енергетика… ЕНЕРГЕТИЧНА ВОЛЯ - тут така ж сама ситуація, як в усіх інших суспільних просторах, - вона про якість вібраційного фону колективної свідомості. Уявіть собі ситуацію ТАК.👇 «Українці дорожчають як вид!» Що скажете тепер? Не в Україні усе дорожчає. А… ☝️ читай вище фразу. То чим таким цінним володіють українці? До сих пір будемо шукати відповідь в земельних угіддях, в аграрних ресурсах, в історичних насліддях, в територіальних і регіонально-географічних координатах, чи все ж таки підемо глибше, дивитися через широку рамку реальності? Давайте поговоримо … 🤗 Мислення визначає наші результати, формує емоційний стан і самопороджує можливості. Яким мисленням доречно володіти, щоб жити те, що довкола, не як «малі діти»? Актуальні ці питання для вас, шановна аудиторія? Бо мій дух не лише освітою жінок та консультуванням усіх людей зайнятий, але й читанням енерго-інформаційного квантового поля та трактуванням. 👇👇👇 В місяці червні велика кількість уваги буде зосереджена довкола «ресурсних» тем, особливо тих, що символізують собою стихію вогню. Він міг би в мирних часах бути місяцем пристрасті та романтики, але не цього разу… бо є конфлікт металу та вогню, тому чи будуть обстріли? Однозначно кажу. Неконтрольований гнів перетворюється на ракети над головою. Ви сердитесь на себе чи когось і не направляєте цю енергію в русло творче? - маємо обстріли. Це стосується лише України? Ні. По всьому світу купа регіонів, де зосередженні душі, що здатні змінити реальність. Але якщо вони «сплять» в програмах жертви/тєрпіли, і не включають в собі мудрість кармічну, то вузол лише тугіше затягується. Що робити? Діяти в сторону своїх мрій!!! ☝️ Діяти діями, а не розмовами про них. ✨ В липні піднімуться земельно-територіальні питання і фінанси (депозити, кредити, банківські активи…нерухомість… гойдатиме ринки), в серпні - інтелектуальні і інноваційні ресурси вийдуть на перший план. “Гроші із пустоти” (віртуальні) займатимуть все більше і більше місця в системі обміну енергією. ✨ В вересні будуть всплески проявлення ідей та вихід на нові ринки, особливо яскраво буде очами видно, що військовий ринок, мілітаризація під прикриттям «vійни» займатиме лідерські позиції, що є сумним фактом. Бо досягнути миру війною проти війни не можливо. Це я зараз пишу і як цілитель, і як аналітик. Без емоцій та націоналістичних ярликів. Усі ці місяці хитатиме фондовий ринок, фінансову і політичну мапу світу кроїтимуть по-живому, без анестезії. В жовтні прийде один із найскладніших, найкризовіших місяців року, клани імперські зустрінуться на рингу інтересів. В тому числі не без натиску силовими насильницькими методами… Як в цій ситуації знайти себе і своє місце простому пересічному громадянину? Дуже чітко розуміти. 👉Відповідальність за твоє життя лише в твоїх руках! 👈 Так було, є і буде. Але сліпота ілюзій дозволяла вважати, що хтось про тебе піклується, доки ти байдики бʼєш і думаєш як «урвать нєзамєтно», чи «шукаєш себе». Ніяк. Еніологічна освіта почне відігравати ключову роль в формуванні лідерства нового часу. Не звертати уваги на прогнози футорологів та вібраціологів людство просто не зможе, бо адаптація до часів потрясінь далеко не усім доступна. І хоча б трішки орієнтуватися в процесах макрокосмічного характеру - важливо кожному. Особливо тим, хто свою вищу інтуїцію розвивати і не починав. Штучний інтелект - це не ворог, а друг, вірніше реалізатор задач. «Ворог» він лише для людей з низьким рівнем свідомості, бо витіснятиме з позицій потрібності безмежну кількість професій та соціальних ролей. Вивільнення часу від побутових справ, дасть змогу свідомостям з високим рівнем вібраційного статусу проживати себе якісно і кількісно значно краще. Який сенс в усьому цьому? Виглядає як монолог «філософазадрота» - всє ми там будєм… ? … Ех, я б хотіла завершити словами - ПРОБУДЖУЙТЕСЬ, щоб знати більше за межами ума. Але знову це розшифрують як рекламацію. А я не жартую. Як і 10 років тому про епідемії, пандемії. Як і 7 років тому про часи потрясінь і зміну парадигм. Як і усі роки - про необхідність бути інтуїтивними, холістично здоровими, академічно освіченими, і психоемоційно зрілими… Медитуйте, друзі, робіть собі йогу і сидячи при свічках плануйте не акти лютої ненависті, а навпаки формуйте свої плани на живе життя, в яких є місце для мрії ЗАРАЗ, є відповідальність за свої дії, є усвідомлення етичних законів та гуманних стратегій, є наглість почати жити по-іншому, і почати з СЕБЕ… 🙌 Вхід там, де й вихід … …довкола не пастка, а липка павутина мнєній та маніпулятивних мислеформ… 🌀 Хто ти в усьому цьому хаосі подій? Розумієте, про що я тут понаписувала? 😘 Якщо складно зорієнтуватися в часі - приходьте на персональні консультації… © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','6 червня 2024','4 хв читання','/images/posts/IMG_1621.png','[]',1,'2024-06-06T19:15:55','2024-06-06T19:15:55');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1913','%d0%b2%d1%96%d0%b4%d1%87%d1%83%d0%b9-%d1%81%d0%b2%d1%96%d0%b9-%d0%b2%d1%96%d0%b1','Відчуй свій вібраційний домінантний спектр власного характеру!','Люди граються. Граються в гойдалки, в синусоїди, в цикли, в періоди, в етапи і всяке різне лінійне і дуальне, в «добре» і «погано», в успіх і факапи, в висоту і падіння… Коли домінує мислення 3d, то за кожним періодом «висоти» мусить прийти «падіння»...','["Люди граються. Граються в гойдалки, в синусоїди, в цикли, в періоди, в етапи і всяке різне лінійне і дуальне, в «добре» і «погано», в успіх і факапи, в висоту і падіння… Коли домінує мислення 3d, то за кожним періодом «висоти» мусить прийти «падіння». Так влаштована ця система. Мислення 4d дає відчуття підтримки поля, і розмиваються етапи злетів та падінь - тебе ніби підтримує колективна вібрація спільноти, і не дає гепнутись на спинку. Але це відбувається, якщо дійсно створені якісні СТОСУНКИ З СПІЛЬНОПРОСТОРОМ, це завжди твоя щедра дія. А не лише - «я є» з вами. В вимірі 5d та вище не існує гри в полярності, є путь… це путь душі, на якому діалог СОЮЗНОЇ ПАРИ - це вже не діалог, а монолог. Ти нікого не шукаєш, не чекаєш, не звинувачуєш, з тобою не стаються не «твої» люди, абсолютно спокійно проявляється Суть, бо немає винних та кращих, чи гірших. Відсутній сам алгоритм порівняння заради еволюції через боротьбу. Куди це я веду вашу увагу зараз? До себе. До СЕБЕ В СОБІ! Які ігри спостерігаєте на екрані життя ви, замислитися зайвим не буде? 😘 … Звичайно будь який левел може проживатися із повноти та довершеності, або із часткової «недо…» силоньки та потенціалу. 👌 Я запрошую вас ВІДЧУТИ СВІЙ ВІБРАЦІЙНИЙ ДОМІНАНТНИЙ СПЕКТР ВЛАСНОГО ХАРАКТЕРУ. Ніколи ще не робила таких марафонів, як планую проживати з групою крилатих зараз… 🥰 Я неповторна завжди. Знаю. Бо скопіювати дух не можливо. Але те, що загружає поле Великої МА через Аватара IMARIA MASTER Заверуху Ірину прямо зараз - дещо WOW☺️. Сам дух роду патріарха Адама мене навчав протягом останнього місяця, через нові дерева і ліси, які саджаю своїми діями, руками і мріями - повертаються спектри цивілізації свідомості Едема. Райські спектри та частоти. Тобто вібрації радості і щастя… Уявляєте??? Ми з вами запускаємо справжній міжгалактичний ліфт. І я пишу як є. Пишу без прикрас та поправки на неприйняття чиєсь. Мені по цимбалах, які у кого галюни та ширми захисту від реальності. Не маю жодних причин на сумніви чи зупинки. Я медичний феномен світу. Колосально цінну статистику результативності клієнтської маю. Сотні народжених дітей і дітищ. Тисячі зведених між собою людей, бо виступаю як простір для знайомства. Святкую, спостерігаючи як крокують в свої континіуми щасливих доль люди, яких зібрала під своїм крилом і познайомила ця тендітна пані Заверуха. Так, я тішусь своїми діями і радію самому путі… Зцілюючи полем вищої інтуїції родові програми та підсвідомі тенденції людей, - я надивились на безмежну кількість блоків та розумію, в чому причина їхньої наявності. Тому нагадую вам - щасливішаєте ви - щасливішає світ, окриляється рід, перемагає країна… І не треба охати про часи та жалітися на обставини. Вони завжди були або МОЖЛИВОСТЯМИ, або перешкодами. І кожен бачить крізь свої ширми сприйняття. 🤩🤩🤩 Тому марафон #ЩАСТЯЄ! буде культовим хітом і певним завершенням моїх проектних творчих кроків, які тривали 4 роки. Це круто. Бачити широко. Жити глибоко. Любити безмежно. Вірити і діяти крізь часи… Мати відношення до прямого діалогу з самозародженням свідомості богореалізації нової цивілізації, що проЯвляється в силі живого життя… Я готова…🙌 Старт марафону - 14.06! Два тижні масштабуючих комунікацій. Ви щодня проживатимете активацію кодів Пари Нового часу. І апогеєм стане практичний семінар в Буші. Тут вже без коментарів. Бо не все можу розповідати на широкий загал. Заходьте на орбіту. Кличте своїх, залучайте друзів та людей, яким бажаєте добра, а не хочете «бідолашним прічініть просвітлення» 😉, - ми усі свою волею в праві керувати. Але й нагадую - ви не випадково тут. В Зараз. В САМОСТОЯННІ через #словакрила від #ГолосДуші берегині роду людського… … На низькому старті…🐦‍🔥 З ким летимо ? 🙌 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','10 червня 2024','3 хв читання','/images/posts/448204632_440615082159090_7457275328796169039_n.jpg','[]',1,'2024-06-10T19:44:53','2024-06-10T19:44:53');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1933','%d1%96%d1%81%d1%82%d0%be%d1%80%d1%96%d1%8f-%d1%80%d0%be%d0%b4%d1%83-%d0%bb%d1%8e','Історія Роду Людського, яку ви не знали','IMaRia - це свідомість БогоРодиць. Жінок з роду Божого. Жінок, що народжують дітей з душами роду Божого… Роду Адама. А не роду Люцифера. Так, вони обидва були достойними синами свого батька, але ж вони різні. Дуже. І не спішіть, люди, шарахатися, поб...','["IMaRia - це свідомість БогоРодиць. Жінок з роду Божого. Жінок, що народжують дітей з душами роду Божого… Роду Адама. А не роду Люцифера. Так, вони обидва були достойними синами свого батька, але ж вони різні. Дуже. І не спішіть, люди, шарахатися, побачивши імʼя Люцифер. Він не страшилка, яку релігійна казочка викривлено подала, щоб не задавали питань. Оооооо… там така історія цікава сталась. Індійські серіали відпочивають. Єва належала до космічного племені БогоРодиць. АЛЕ! Втратила свою цілісність і звʼязок зі свідомістю IMARIA і розділилась жінка земна на «частини» тоді… Шаманки стали самками матеріалістками і торговками побутовим тілом, Берегиня зайшла в роль героїчного материнства і тішилась владою над дітьми, а Жрицю-вчителя взагалі витіснили релігії в вимір відьм і знищували тисячі років, або пропонували ставати «монашками». ДРЕВО ЗНАНЬ… древо роду… в саду Адама НАВЧАЛО жінку знанням про живе життя. І ті знання були лише для НЕЇ напряму із джерела. Бо керує силою творіння - сама Велика МА. То ж насправді їсти з того дерева плоди мав «заборону» лише Адам, а не обоє. То чи була провина у Єви? Так. Частково. Вона вмовила коханого теж зʼїсти плід, бо була готова народити з ним дітей. Її Велика МА встигла підготувати до ролі БогоРодиці. Та не попередила, що у Адама свої уроки. Даремно. Наївна Єва. Поспішила…Бо для Адама Батько приготував особливий ритуал ініціації щоб продовжувати рід Божий на Землі. Який? Адам повинен був навчитись нести відповідальність за свої плоди, навчитись мистецтву високої інтуїції, навчитись чути серцем жінку, яка чує серцем усе, … і яснознає усе… і має прямий контакт з духовним Космосом і з матеріальною Землею. Адам не відчував Землю так, як Єва. Але він повинен був відчувати Єву, як себе… ✨✨✨✨✨ Потім було багато трагічний подій… Ви про них в курсі. Адам покинув Землю. Буквально. Він полетів. Так само як свого часу вони прилетіли на космічному кораблі на планету вдвох. Адам не лишився. Він покинув Єву. І більше ніколи не повертався. Тіло світла високого калібру дозволяло йому знаходитись в статусі міжгалактичного мандрівника-аскета. А вона, Єва, народила рід людський з іншим. Саме так. З Люцифером. Зраджена коханим. Покинута і роздроблена… Вона народила доньок, і навчила їх бути Жрицями. А ті народили безліч різних племен майбутніх людей. Було багато генетичних викривлень, так званих «помилок», народились і вірусні програми, які потрібно було утилізувати, знищити, але Жриці не захотіли, їм здавалося, що своїх дітей (навіть якщо вони з генетичними мутаціями) вони не повинні вбивати. Це порушило міжгалактичний баланс. Далі було ще «веселіше»… На Землю направили ЛЕГІОН ВЧИТЕЛІВ. Хранителів Частот. Щоб навести лад в розвитку популяцій. Принесені були Космічні знання. Навчені були Жриці багатьом сакральним знанням, щоб викорінити вірусні програми і вирівняти баланс. Не вийшло. Тоді лише внесли в коди програми еволюції Землі таке обновлення, як КАРМІЧНІ РІВНІ. І саме ця #гра затягнулась на віки… З тих пір …👇 КОЛЕКТИВНА ЖІНКА ЗЕМЛІ збирала себе до купи віками. І ось ми з вами в тут і зараз… Рід Адама не втілювався через Єву на Землі. Ніколи. Але! Він був втілений через Богородицю, справжню дружину Адама - космічну посланницю, яка буквально прилетіла на планету, а не народжувалась тут, і це була бабуся Ісуса носій спектрів #IMaRia, саме вона підготувала майбутню матір Месії до її ролі. Марія прийняла Ісуса від Адама серцем. (І не лише бабуся Ісуса була такою! Я вела діалоги з різними калібрами духовних свідомостей, що передавали знання. Тепер ці знання передаю своїм серцем і я. Аватар МА на Землі). 🌿🌿🌿 Ми з вами тепер повертаємо сад АДАМА НА ЗЕМЛЮ. Едем. Заходить духом чистим через дерева на планету той, який давним давно покинув Єву, бо відчув себе тоді тут обманутим усіма… відчув себе безсилим, бо не ПОЧУВ ЇЇ… з тих пір усі чоловіки намагаються зрозуміти жінок і не можуть. Але є ті, які вже активували в собі ген Пари Нового Часу і чують Жінку серцем, і чують вони усе, в тому числі Бога та саме Живе Життя… і ведуть вони потомство до РОДУ. Роду Адамового… Хто відчув резонанс з текстом? 😘 Покликати вас на NEO курс #ПАРАНОВОГОЧАСУ ? 😘 ✨✨✨✨✨ Для усіх, кому так це все цікаво, що аж до «німагу» і відразу хочеться «продовження серіалу», моя відповідь - приходьте в програми, я передаю лише так прямі ієрархічні знання! А пишу публічно про те, що «включає» увагу…🙏 Не пишіть мені кілотонни питань, на які я не маю часу відповідати. Дивіться прямі ефіри в інстаграм, там купа цінного, поки що відкритого, … і на нові приходьте. Потрудіться відкриті сатсанги пожити через ютуб. Їх сотні. Там стііііііільки всього є і сказано. Просто дійсно потрібно прикладати зусилля, а не чекати, що хтось буде дробити фундаментальне на контент розважального типу.🙏 І не ображайтесь на таке звернення, я ціную і ваш час і свій, безупинно працюю, і коли маю паузи - то витрачаю увагу на маленький відпочинок і спілкування з близькими людьми та дітьми… Розумієте? ✨✨✨✨✨ © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','3 липня 2024','4 хв читання','/images/posts/Історія-Роду-Людського.jpg','[]',1,'2024-07-03T13:34:03','2024-07-03T13:34:03');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1936','%d0%bc%d0%b8-%d0%bc%d0%b0%d1%94%d0%bc%d0%be-%d0%bf%d0%b5%d1%80%d0%b5%d0%bc%d0%b0','Ми маємо перемагати ЖИТТЯМ!','Коли приходять часи РОЗПЛАТИ… коли настають жнива… коли рухається до фінішу певний довготривалий цивілізаційний процес… - то ми майже завжди бачимо війну, або конфлікт інаковостей, полярностей. Бо це пікова фаза тертя протилежностей. Війна не являєть...','["Коли приходять часи РОЗПЛАТИ… коли настають жнива… коли рухається до фінішу певний довготривалий цивілізаційний процес… - то ми майже завжди бачимо війну, або конфлікт інаковостей, полярностей. Бо це пікова фаза тертя протилежностей. Війна не являється причиною, не являється вона і серединним шляхом. Це завжди результат. Це #фініш…це наслідок. Результат певних дій і стратегій розвитку, що побудовані були на егоїзмі та хибних насолодах. Дуже хочеться донести до мас, що війну війною не виграють… як і часто кажу людям - сексуальні блоки сексом не лікуються… бідність не лікується економією… а лише щедрістю… і т.д. часто пояснюю - що допоки ти в середині ситуації віриш в несправедливість, допоки ти в манежі, на арені цирку… - ти змінити сценарій не можеш. Потрібно вийти із схемки, піднятися над системою, хакнути алгоритм… взяти відповідальність на 100% і вивільнити себе із ілюзій ума, а не втекти від них і робити вигляд, що їх не існує… Реагування на гнів гнівом переносить гнів в подвійному обʼємі в майбутнє. Це перезасівання. Реагування на гнів страхом, статусом жертви, безсиллям - це перезасівання. Знову буде продовження того ж самого, тільки учасники поміняються ролями, інкарнують в інших формах - жертви стануть тиранами, а тирани жертвами. Немає кінця таким стратегіям… ♾️ 🙏🙏🙏 Життя покликало нас до себе. І ми тут. На Землі. Тому ми маємо перемагати ЖИТТЯМ. Єдине, чого боїться темрява - це світло. Єдине чого «боїться» смерть - це життя… Чого боїться лінь? - це регулярних дій із насолодою. Та й взагалі - суть гармонії - не про страх, не про полярності, а про застосування усіх якостей по призначенню в доречних ролях і позиціях. Не можливо подавляти силу, але там, де її не чекають і не просять - вона буде насиллям; а там, де її заперечують - вона буде безсиллям і нехваткою ресурсу… Любов має очі і БАЧИТЬ, де саме слабке звено і куди направити увагу. Там і відроджується «ліс на пустирі»… 🌿🌿🌿 Ця стратегія працює завжди! Так. Вибираючи любов діями. І не порівнюйте пліз себе з іншими. Якщо людина народжена оберігати - то має оберігати. Путь чоловіка, дхарма його - це давати захист і вірність через служіння роду. Створити середовище життя для жінки і природи, для еволюційного розвитку… - і це дуже далеко від амбіцій тиранів і егоїстичних деспотів, які мають на меті споживацьку монополію, а не всебічну гармонію. Перемога близько, друзі. Перемога не когось над кимось. А ЖИТТЯ ЖИВОГО над ілюзіями. 🌏💫 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','21 червня 2024','3 хв читання','/images/posts/IMARIA.jpg','[]',1,'2024-06-21T13:44:44','2024-06-21T13:44:44');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1939','%d1%82%d0%b2%d0%be%d1%80%d1%87%d1%96%d1%81%d1%82%d1%8c-%d1%86%d0%b5-%d0%bf%d1%80','Творчість це процес…','Я консультую усіх людей. І чоловіків, і жінок, і сімʼї, і цілі родини… різних статусів, рангів, професій, віку, структур, вірувань, … Вже 15 років консультую як бацзистка-астролог, глибше консультую як Майстер-хілер понад 8 років… Бо напрацювала прак...','["Я консультую усіх людей. І чоловіків, і жінок, і сімʼї, і цілі родини… різних статусів, рангів, професій, віку, структур, вірувань, … Вже 15 років консультую як бацзистка-астролог, глибше консультую як Майстер-хілер понад 8 років… Бо напрацювала практику і прийшов досвід. І знаєте, що я вам хочу сказати, любі. Дуже цікаво спостерігати за любителями «швидких результатів», які в усі часи самі того не розуміючи іноді продовжують втюхувати ілюзії про чарівні інструменти, які гарантовано допоможуть саме ТОБІ і саме зараз… ОДНОРАЗОВО. Не ображайтесь, люди! Буду відверта. Але. Прогрес - завжди процес «повільний» і регулярний. Тоді він гарантований. Тоді це про фундаментальність… ЗмінитиСЬ на рівні нейрофізіології нам заважають наші звички, неврози, патерни… досвід… ми знаємо, що можна інакше - не робимо, бо не вміємо змінюватись. Більшість так сліпо і неефективно стрибає від методу до методу, не досягаючи ніякої глибини контакту з собою (бо потрібна дисципліна і методологія). Потрібен глибокий досвід ПриСутності і включеності в поле Душі, щоб відбувалось усе еволюційно і не дивувало своєю «повільною швидкістю». Творчість це процес… Немає нічого миттєвого в плотній матерії. Скільки «створюється» нова людина? Вірно. 9 місяців. А вірніше це 10 циклів творіння, лунних місяців. Бо ми маємо 10 рівнів свідомості. Миттєво ми лише проживаємо імпульс чистого Бога, коли дух народжує ідею. Але, щоб вона втілилась в матерію - потрібен час. Різний. ✴️ На рівні системи ми протягом щоденного циклу в 40 днів без пропусків і відмазок можемо послабити будь-яку звичку, якщо щодня робитимемо по-іншому. 40 днів, Карл! А для напрацювання нового нейронного ментального відбитку потрібно цілих 90 днів! Більшості людям не вистачає МОТИВАЦІЇ… вони мають слабкий характер, не контрольоване его, хибні опори, залежності від емоцій і думок, не істинні наміри, і слабкий прохід духу в матерію, бо не вистачає чистоти тіла, практики, і любові безумовної, …любові до самих СЕБЕ… Це не дає можливості добратися до фінішу. Не дає можливості почати самих себе поважати за досягнення. Не дає можливості реалізувати вихід на зовню свого внутрішнього ДОРОСЛОГО, і бути авторитетом не лише собі, а ще й іншим. 💥МОТИВАЦІЯ… Тому йдуть і шукають тренера, наставника, Майстра, Гуру. Бо «роби, як він» - це працює. Так працює. Але все одно лишишся ти на одинці з собою. І буде «або, або». Або знову покотишся в прірву старих звичок, або все ж таки вивчиш і дослідиш свою структуру, візьмеш в руки алгоритм ПідСилення і проявлення, і дійдеш до фінішу. Що таке фініш? Це вміння ТВОРИТИ без нетерпіння, без критики, без порівнянь, без очікувань… В резонансі з внутрішнім Гуру, а не зовнішнім. ✴️ Ось що. Усе творити. Себе. Проекти. Життя… (нових людей, матеріальні блага, стосунки, дітища…бізнес… все сюди постав)… До чого я це пишу? 💫Вчора відбулося мега важливе явище в моєму житті. Я провела першу зустріч і бесіду з майбутніми Студентками IMARIA ™️ ACADEMIA, які починають навчання енерго-інформаційному хілінгу і матимуть шлях із трьох рівнів спеціалізацій: МЕНТОР ХІЛЕР МАЙСТЕР АЛХІМІЇ Віднині я буду продовжуватися в моїх Учнях, яким передам максимум знань і вмінь працювати зі структурою долі, з родовими системами, з багатовимірним полем свідомості, навчу проявляти поле зцілення, реалізовувати корекцію програм, діагностувати якість енергії, призначати терапію і надавати терапевтичну допомогу фахову та експертну. Я проведу їх крізь путь сертифікації. Підтримаю в дорозі прикладами та гарантованою практикою, бо маю спільноту, в якій споріднені за цінностями люди вже готові йти в досвід покращення життя… Вони зможуть «читати» поле і коригувати карму, а також надавати рекомендації про путь душі, бо перший модуль навчання присвячений саме НУМЕРОЛОГІЧНІЙ вібраційній системі аналітики долі “Way off the soul” ™️ яку я віднині активно передаватиму далі. Мої учениці вестимуть трансформаційну гру одноіменну, що нині в фазі завершення творення. Вмітимуть організовувати потужні ретрити, трансформаційні кемпи, жіночі кола і родові практикуми. І багато іншого… І йшли вони до цього дня, так само як і я, - роками. Не 3-5 місяців. А 2-3-5 років… У всіх по-різному було. Тож на ваші питання «Як провести і зустріти Рівнодення літнє?», що отримую вже дві доби, я відповідаю просто - #ПРАКТИКУЙТЕ чистоту свідомості та простору! 🤗 Долучайтесь до поля росту і практикуйте, проживайте своє унікальне «тут і зараз» і #ТВОРІТЬ життя… Досить бігати шукати швидкі магічні інструменти… зупиніться… озирніться… знайдіться… і живіть через свідому дисципліну! Майте ціль і майте сміливість до неї рухатися… І нехай Сонце внутрішнє підсвітить ваші найкращі риси, щоби проявитись в щасті… А усілякі култьтурні традиції стануть лиш симпатичними декораціями дня, а не надією на зміни… 🥰🙏 Залишу посилання на відкритий сатсанг «СОНЦЕ В ТОБІ» , який дасть вам потужний заряд енергії. 🔥🔥🔥 Але ви робіть! Не чекайте мани з неба… беріть свою долю в свої руки… 🙏 Хто вже так живе, регулярно в духовній і фізичній чистоті, регулярно етичні закони гуманізму плекаючи, регулярно і постійно поважаючи предків, шануючи себе і свою унікальність… регулярно реалізовуючи добрі справи і благодійні проекти, регулярно …? 🙌 🙋🏻‍♀️ © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','20 червня 2024','4 хв читання','/images/posts/Творчість-це-процес.jpg','[]',1,'2024-06-20T13:57:55','2024-06-20T13:57:55');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1961','%d0%b0%d0%ba%d1%82%d0%b8%d0%b2%d0%b0%d1%86%d1%96%d1%8f-%d0%ba%d0%be%d0%b4%d1%96%','Активація кодів Пари Нового часу триває ...','ЧОЛОВІКАМ.... Якщо жінка вам каже «мені від тебе нічого не треба», - то вона вже думає, що грошей на неї справжню і сутнісну у вас не вистачить… тобто вона підсвідомо знає, що «дорожча», ніж ви можете собі дозволити. Повірте, і це не її занижена само...','["ЧОЛОВІКАМ.... Якщо жінка вам каже «мені від тебе нічого не треба», - то вона вже думає, що грошей на неї справжню і сутнісну у вас не вистачить… тобто вона підсвідомо знає, що «дорожча», ніж ви можете собі дозволити. Повірте, і це не її занижена самооцінка. Частіше - це у вас вона занижена, і в вас не «вірять» навіть на рівні перспективного, якому можна дати шанс… Тобто ви не випромінюєте достатній спектр вібраційної БЕЗПЕКИ, що сформована чоловічою зрілістю. Ви чекаєте, що має бути навпаки? Що в вас мають вірити і вас музити? Чуваки, це ілюзія, бо жінка вам не мати. Віру в себе потрібно було у неї (матері своєї) через благословіння перейМати. Не знали? Ну що ж завжди не пізно поїзд часу наздогнати. Тільки поспішайте. Інструменти є, навіть якщо матері вже в живих немає… 🌀 Бо активація кодів Пари Нового часу триває… і когось цей процес косить в безсилля, а когось окриляє. Окриленими будуть одушевлені, вільні духом і сильні зрілістю своєю, які пройшли ворота роду і прийшли… Ті, в серцях яких любов перемагає усі привʼязки і очікування… Любов безумовна має цікавити вас більше ніж споживацька вигода. Відчули про що я? 😘 Жінкам то розповідаю постійно і регулярно, що насправді «яке їхало, таке здибало». І жіноча зневіра по відношенню до чоловіків - це теж результат недовіри до батька та бери вище - до Бога. Це гординя… і тут свої задачі по саморегуляції… Тобто як не крути. Зрілі люди один до одного не чіпляються з претензіями. А підсилюють один одного без втрати себе в стосунках… ⚜️⚜️⚜️⚜️⚜️ А тим часом іще раз усім нагадую, що до кінця року 2024-го веду персональні консультації на тему #ВнутрішнійСоюз і пріоритетним напрямком є ЗРІЛІСТЬ ЯДРА ВНУТРІШНЬОЇ СІМʼЇ! Ви даремно біжите «розпаковувати і запаковувати» свій особистий бренд без міцного фундаменту із ресурсів під ногами. Бо особистий бренд може мати лише сформована #ОСОБИСТІСТЬ!!! Логічно? Дуже … 🔱 Пройдіть дистанційний курс #СамСобіЦілитель вже, бо він відкриває доступ до наступних рівнів навчання в моїй #IMARIAACADEMIA: 〽️ #ProResurs - курс про гроші та енергію в 3d, в 4d і 5d реальності! 🔹#ПАРАНОВОГОЧАСУ- курс про союзи Епохи Водолія, закони розвитку сімʼї і родову космічно-земну ієрархію! 🔹#IMARIAЙогаХілінг - курс для практиків йоги свідомості з можливістю працювати з іншими людьми! 🔹#MetatesisWomens - курс для практиків терапії через жіноче коло, ретрити, тілесно-орієнтовані семінари, шерінги! … 🌿 курс #ЯЖінка і #СферичнаСімя - це просто маст хев, без коментарів… 🥰 І я не втомлююсь нагадувати людям про те, що ЖИТТЯ - це зараз, і зволікати - рахуй так і жити не почати… Не модні дипломи чи іноземні мови зроблять вас адекватними і ресурсними в цих часах, а вміння керувати своєю енергією, розвивати свідомість і фільтрувати інформацію… (хоча краще реалізувати і те, і інше… розвинувши свою геніальність🤓) Тому тут немає про що думати. Треба діяти…🙌💫 Що резонує вам? 🤗 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','18 липня 2024','3 хв читання','/images/posts/Чоловікам-.jpg','[]',1,'2024-07-18T12:45:19','2024-07-18T12:45:19');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1965','%d0%b2%d1%96%d0%b4%d0%bf%d0%be%d0%b2%d1%96%d0%b4%d0%b0%d0%bb%d1%8c%d0%bd%d1%96%d','Відповідальність за баланс в стосунках','Я хочу запросити вас в діалог… в рефлексію по темі… Спробуйте прочитати серцем. Повільно. Не спішіть, і глибоко в суть заходьте. «Ті, хто нас оберігати мав би - нападають… Ті, хто в вірності клявся - зраджують… Ті, хто мав би навчати - злидні менталь...','["Я хочу запросити вас в діалог… в рефлексію по темі… Спробуйте прочитати серцем. Повільно. Не спішіть, і глибоко в суть заходьте. «Ті, хто нас оберігати мав би - нападають… Ті, хто в вірності клявся - зраджують… Ті, хто мав би навчати - злидні ментальні самі, і знання крадуть, історію крадуть, присвоюють чуже і прикидаються дорослими…» Чуєте суть? Кожна людина живе те, що на екрані її свідомості проектор показує. А іще існує КОЛЕКТИВНА СВІДОМІСТЬ. Ядро концентрованої енергії. Так от. В силу свого дару яснобачити і читати інформаційне поле, опираючись на здатність розпаковувати знання та доносити глибинну причинність - я постійно займаюсь вібраційним хілінгом. Розпаковую. Доношу. ☝️☝️☝️ Це - ПРОГРАМИ! Як в компʼютерній грі. Людина може бути декорацією в мережі сценарію, який нею не створений, лише тоді, коли відповідальність за процес і наслідок віддала комусь. Все. Бо коли ти на 100% несеш відповідальність за все, то бачиш павутину ілюзій і маєш ВОЛЮ відсікати, фільтрувати, і творити те, що формує поле сили, а не забирає твою психічну енергію. Давайте розбиратися. «Ті, хто нас оберігати мав би - нападають…» Що бачимо? Де ми це створили як колективну свідомість? Порушення родового сценарію в алгоритмі живого життя. Такий наслідок є причиною насилля Старшими (батьками) над меншими (дітьми). Сюди ж належить вид насилля наступний : людина знущається над твариною! Тобто вібраційно вищий поїдає і подавляє популяцію вібраційно нижчого. ДОВІРА зруйнована. Починається хаос. Розумієте суть та аналогію? 😘 «Ті, хто в вірності клявся - зраджують…» Що бачимо? Де ми це створили як колективну свідомість? Тут проявлена конкуренція в стосунках між М і Ж. А також в структурі М-М «братерства», та Ж-Ж «сестринства» аналогічні порушення. Довіра зруйнована. Починається хаос. «Ті, хто мав би навчати - злидні ментальні самі, і знання крадуть, історію крадуть, присвоюють чуже і прикидаються дорослими…» Що бачимо? Де ми це створили як колективну свідомість? Тут проявлено стосунки між Мудрим началом Вчителя (Патріарха і Матріарха) та Учнем; між Владою та наРодом. Довіра зруйнована. Починається хаос. ✨✨✨✨✨ Один нападає (тиран) - інший страждає (жертва). Потім змінюються місцями душі. І так триває віками… Страждають усі, як рибки в акваріумі. То як вийти із цієї закольцованості? І чи є вихід? Є! Вихід там де і вхід. Вхід виникає, коли ми відповідальність передали комусь, і причини всього не шукаємо в собі. То який вихід? Взяти на себе ВІДПОВІДАЛЬНІСТЬ! За що? За баланс в стосунках: 🌿Батьки-Діти. Люди-Звірі. 🌿Жінки-Чоловіки. Жінки-Жінки. Чоловіки-Чоловіки. 🌿Вчителі-Учні. Влада-Народ… Крапка. А далі - дія. З себе почати і не зупинятись … 💫🫶🙏 Чи вийшло у мене через аналогії проявити суть?😘 〰️〰️〰️〰️〰️〰️ Що вам пропонує IMARIA SPACE вже зараз? 🔹 Фундаментальний курс \"Сам Собі Цілитель!\" - чекає на кожного… 🔹 Трансформаційна річна програма \"Крила\" для жінок вже в фазі набору! (Старт у вересні… перший сезон програми, рекомендую пройти кожній жінці без винятку… він триває 2,5 місяці)… 🔹Дистанційні програми \"Я Жінка\" і \"Сферична Сім''я\" вже доступні для засвоєння! 🔹Культовий марафон \"З Чистого Листа\" стартує в вересні! 🔹Простір практиків Pipl Club працює постійно. Долучайтесь до закритого клубу, щоб свідомо жити живе життя. © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','9 липня 2024','3 хв читання','/images/posts/Відповідальність.jpg','[]',1,'2024-07-09T21:15:58','2024-07-09T21:15:58');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1968','%d0%b4%d1%83%d1%85%d0%be%d0%b2%d0%bd%d0%b0-%d0%b2%d1%96%d0%b9%d0%bd%d0%b0-%d0%b3','Духовна війна... гроші... влада... гординя','Підозрюю, що система знову буде хотіти приховати цю мою публікацію в тіньовий бан, тому реагуйте пліз активно… 😘 Звідки ростуть «ноги» протистояння між духовними та матеріальними цінностями і чому існує боротьба за ресурси? Першопричина достатку, про...','["Підозрюю, що система знову буде хотіти приховати цю мою публікацію в тіньовий бан, тому реагуйте пліз активно… 😘 Звідки ростуть «ноги» протистояння між духовними та матеріальними цінностями і чому існує боротьба за ресурси? Першопричина достатку, процвітання та СТАТУСУ була споконвік лише високочастотна, тобто освячена світлом істинних знань, що миттєво засвоюються розумом серця і йдуть в матеріалізацію через щедрість думки, дії та емоції. «Частота» -це слово дуже схоже на «чистоту», в цьому і є глибока суть. Висока частота вібрації думки давала гарантію чистоти і навпаки. Трохи розшифрую. Нами керує СВІДОМІСТЬ. Вона є різних видів: під-свідомість, свідомість (масло масляне), над-свідомість, зверх-свідомість. Думка - це хвиля, вона рухома. Переміщення імпульсу (інформаціону) відбувається за законами фізики. Квантова фізика описує дуже тонкі еніокосмічні процеси нашого мислення. Але я вам нагадаю про базові поняття. Є 5 видів частотних коливань мозкових хвиль, що притаманні людині. Це Бета діапазон, альфа, тета, дельта і гамма діапазон. В цифрах це: Бета - приблизно 14-24 коливань в секунду (люди в побутовому циклі задач знаходяться саме в ньому); Альфа - 7-14 коливань в секунду (розслаблення, спокій, шлюз у підсвідомість); Тета - 4-7 коливань в секунду (медитативний піднесено духовний стан); Дельта - 0,5-4 коливань в секунду (ми спимо на цьому рівні, глибоке розслаблення). Гамма - 40-5000 коливань в секунду… Так! Не помилка. Це рівень максимальної активності мозку, геніальність, усі інсайти, усі квантові стрибки відбуваються на цьому частотному рівні, усі надздібності активуються тільки на цьому рівні. Піковий викид дофаміну, ендорфінів… І здатен на такі коливання «тренований» мозок, який вміє УСВІДОМЛЮВАТИ ВІЧНІСТЬ і свою божественність… Пропускати крізь себе ВсеСвіт, опинятися в ролі пульсару. Відбувається ослаблення стресу, миттєва синхронізація півкуль, активація частин мозку, які зазвичай не задіяні, вихід за межі меж… Суть в тому, що допінги і наркотичні речовини дають саме ось цю розкачку мозку лінивій людині, яка не хоче йти дорогою природньої еволюції через йогу і медитацію. Але я вас запевняю! 🙏 Варто йти повільніше і довше, надійно фіксуючи свої навики досвідом, без допінгів і наркотиків, бо це путь ЧИСТОТИ І ЧЕСТІ! Тут я поки що поставлю крапку. Колись до теми залежностей і «духовних пошуків через наркоту» повернусь. Існує іще дельта-гамма рівень, і тета-гамма… як суміш. Наприклад я як цілитель простір ініціацій і поле на сатсангах створюю для людей саме на цьому рівні. Коли одночасно тотальне сповільнення і розслаблення, з різкими активаціями певних зон зверхсвідомості через шишковидну залозу для тонізації інсайтами. Так стається миттєве зцілення. Миттєве осмислення. Миттєве засвоєння. Миттєва матеріалізація теж... Це вібрація чудес і чудотворців. Тому я раджу МЕДИТАЦІЮ УСІМ! (Бо ви вчитесь керувати потоком ТЕТА-рівня). Тому я раджу Кундаліні йогу усім! (Бо ви вчитесь розганяти швидкість до 4000-5000 гамма рівня). Це і є простір самозцілення… Більшість провідників, хілерів і цілителів, більшість техніків працюють все ж таки на альфа діапазоні (наприклад система рейки, гіпноз, регресії, тароаналітика…) та тета-вібраціях (атмахілінги різного рівня, остеопатія і тощо)… Детальніше про Тета-стан? В цьому діапазоні ми починаємо бачити перші сни, які є переробкою нашого життєвого досвіду. Тобто активній складовій свідомості надається символіка і будується сюжет, і ми бачимо це як сновидіння. У цьому стані можна досягнути повного усвідомлення, пережити події давно минулих днів, і життів, пройти творчий підйом і натхнення. І саме в цьому стані ми отримуємо доступ до тієї маси інформації, яка зберігається в нашій підсвідомості, але й не лише. Знімаються захисні механізми активної свідомості, і ми отримуємо доступ до певних здібностей, зрозуміло, якщо ми усвідомлені під час перебування у цьому стані. Що хотіли сказати нам древні, коли говорили: «Здіймись і запитай у Господа»? Вони мали на увазі таке: коли ви уявляєте, як Ваша свідомість піднімається, залишаючи тіло через вищу чакру, і вирушає на пошуки Бога, - то Ваш мозок миттєво перемикається на Тета-хвилі. Ось що… Тепер про ГРОШІ. Але протягом сотень тисяч років внаслідок духовного падіння безлічі цивілізацій і культур, внаслідок багатьох століть проживання брехні через заздрість, рабство, тиранії, жадібність, війни і суперечки ... внаслідок винищення носіїв священних чистих знань… була спотворена природня структура живого життя. Саме з цієї причини високо моральні істоти перестали контактувати з Егрегором грошей без наслідків для себе протягом тривалого періоду розвитку цивілізацій, - щоб не спотворювати свій частотний діапазон (читайте - як не втрачати чистоти!). Розумієте?😘 Багато духовних людей все ще відчувають цю важкість в налаштуваннях стосунків з каналом грошей, продовжуючи жити ілюзією розлуки. Вам це резонує? Фіксували в собі? ✨✨✨ Але між егрегором грошей і каналом УНІВЕРСАЛЬНОГО ДОСТАТКУ є величезна різниця! І зараз ми маємо перейти саме до нього. Маємо справитися з цим. Створити таку чистоту себе! ✨✨✨ Минуло кілька десятиліть життя, і кілотони інформації перекачували Вишні Вчителі через мій потік, перш ніж я зрозуміла, що можу вписатися в цей канал - універсального достатку, відчуваючи повну впевненість і простоту теми, ніби взагалі немає грошей у світі, але вони при цьому дивним чином завжди у мене і довкола мене є, бо притягуються і вдячно займають необхідну позицію. Служать вищій волі. Як це можливо? Саме через ВМІННЯ КЕРУВАТИ ЧАСТОТАМИ і підтримувати чистоту проходу душі! 😘✴️ Але. Я зрозуміла, що якщо не поверну собі оригінальне бачення егрегору грошей так, як вони були первинно задумані, (як аналог енергії любові) - то не зможу контролювати ці потоки ... Тобто гроші блукали би хаотично поряд як неприручений звір. Зрештою, мені це вдалося… Я нині добре розумію етичні закони живого життя, і як усе працює. Тому Сила не помилилася, вибираючи мене на певні ролі і ключові позиції у цьому світі. Спокійно розумію це. І спокійно про це заявляю. То що ж тоді заважає більшості людей проживати себе в божественному достатку? Коли дійсно тобі ДОСТАТНЬО. Коли є усе, що потрібно для реалізації місії душі… ⏺️ Бувають випадки, коли СВІТЛО (хвиля усвідомленої думки!) пролітає через систему особистості, як через каналізаційну трубу, так і ніде не зупиняючись, внаслідок так званого «протікаючого дна» або відсутності справжніх цілей, що погоджені з цінностями серця (душі). ⏺️ Бувають випадки, коли на шляху руху СВІТЛА є блоки-перешкоди, вузли відтоку, які пожирають енергію, ми будемо називати їх програмами, наприклад, \"я повинен\", \"я винен\", \"я сам/сама\", «мені усі мають дати…», «мене не розуміють…»... ⏺️ Є і ментальні блоки-установки, своєрідні скляні стелі, над якими людина не здатна піднятися. Наприклад, «я ніколи не триматиму у руках більше ніж Х тисяч доларів», «я не досягну, я не можу»… тощо. ⏺️ Бувають випадки, коли сам вхід СВІТЛА заблокований. Свідомість спить. Глибоко спить. Що? ЦЕ ЯК? ГОРДИНЕЮ заблоковане мислення. Банально. Людина возомніла себе НАД усіма. Оскільки в кожного закладений потенціал Бога - то це замашка на заявку «Я вище Бога»… «я краще Творця»… «я і є творець…». Але на справді це високовібраційне роздуте жирне его. Розумієте? Як побачити чи це Его, чи це Дух-Творець? Легко. Его не здатне на народження нового. Воно лише копіює і опирається на старий досвід. Дух створює те, чого не було; знає нізвідки, а не з книжок і чиїхось статей; бачить неочевидне… може матеріалізувати щось ніби то неможливе. Гординя - це хвороба свідомості. Лікує від гордині людину тільки її СУТНІСНИЙ АСПЕКТ. Тобто - душа. Тут теж поки поставлю крапку. ⏺️ Є ще одна причина бідності. СЕРЦЕ! Якщо воно наповнене стражданнями. Незбалансоване. Чи відкрите ваше серце? На кого ви ображаєтесь, чому ви перестали довіряти людям, чому вони перестали «бути зручними для вас», що призвело до такої ситуації, - чи не ваша власна скупість по відношенню до інших і фіксація лише на собі і своїх егоїстичних проблемах?! …. Багато, ой багато різних сценаріїв і причин дисонансу стосунків з ресурсами є у людей! Але всі вони якимось чином пов''язані з частотою мислення і здатністю мозку входити в резонанс з Універсумом. Розумієте? Це про чистоту КАНАЛУ. Це про наш хребет. Про здатність бути центрованими… і відповідно лише так ми входимо в резонанс з ПОТОКОМ УНІВЕРСАЛЬНОГО ДОСТАТКУ через СЕРЦЕ! Куди бігти, щоб розібратися з темою?😘 Перш за все, жінці потрібно зайти всередину себе, познайомитися зі своєю суттю, і побудувати гармонійну референтну структуру, в якій, природньо, з легкістю відбувається синхронізація розуму та інтуїції в серці Берегині. Приходьте вчитися, золоті жінки… 🤗 Я створила безліч потужних курсів саме для вас про усе це!!! В вересні буде старт чергового потоку річної трансформаційної програми КРИЛА 2024 . Ми відкриті… Чоловікові доведеться пройти наскрізь через жіночу сутність, пройти через свою маму спочатку, через свою душу, через очищення озера емоцій та через створення бездоганних умов для безпеки своєї внутрішньої жінки! Стати на службу до планети і роду. І тільки після цього такий чоловік, що здав іспит на вірність МаТерії - буде допущений до Універсального Каналу достатку. Через служіння жінці і живому життю - цей канал завжди буде для нього доступним. Але якщо відбувається зрада цінностей, і потакання своєму егоїзму - то звʼязок з каналом втрачається. ✨✨✨ Достаток духовний і матеріальний цілісної людини - це проста норма епохи Водолія, а не мрія чи мета. Це доказ того, що людина йде шляхом провідника світла... що справді усвідомлює долю душі та місію Духу свого. ✨✨✨ То що вибираєш ти? Вірити і далі в неповноцінність егрегору грошей порівняно з духовністю ...? Чи навпаки гратися в матеріалізм і прикидатися безсмертними, втікаючи від зустрічі з душею? Чи все ж таки бути в резонансі з Каналом Універсального Достатку і створювати резонанс через ЧИСТОТУ ТІЛА-провідника і ефективне мислення Творця? 😘 А до чоловіків я іще трохи звернусь: «Невже ви забули, золоті, що почуття - це ваш наставник, дороговказ? 👋Вам доведеться навчитися висловлювати свої почуття, довіряти їм і переставати звинувачувати інших в тому, як ви себе почуваєте... Ви втікаєте від почуттів тисячі років, тому що ви самі придумали для себе цю заборону. Вас більше не буде ніхто няньчити кризами. Точкою росту буде момент розуміння почуттів серцем, висока інтуїтивність. А не потрясіння. Прямо зараз відбувається та ключова криза, в результаті якої можна створити нову систему життя. На усій Землі. Тож використовуйте її для квантового стрибка в духовному розвитку! ￼￼ Ера допінгів і сурогатів любові закінчилась. Ласкаво просимо в кризу переходу Епохи Водолія з оплесками дитини, яких ніхто не забороняв відчувати і проявляти від рівня внутрішньої свободи. 🤗 Повстання в дусі вже йде! Тож пора встати. Перестаньте боротися за ресурси цієї планети, якими керує жіноче Начало, а не умний ум, - ви походите з інших вимірів, тому й не потрібно задовільнятися лише енергією цієї території. Бережіть мозок від технократичних маніпуляцій. Увійдіть у польові структури Душі, шукайте точку входу всередині себе. Вона там же, де і вихід - вона в Вищій Інтуїції серця та розуму». … Чи було вам цінно читати і усвідомлювати? … … Далі буде. Ділитимусь знаннями. Бо людям не вистачає вміння розслаблятись і вміння бути ефективно тонізованими геніальністю… © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','14 червня 2024','9 хв читання','/images/posts/Егрегор.jpg','[]',1,'2024-06-14T21:53:21','2024-06-14T21:53:21');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1971','%d0%b6%d1%96%d0%bd%d0%be%d1%87%d0%b0-%d1%81%d0%b8%d0%bb%d0%b0-%d0%bf%d1%80%d0%be','Жіноча сила проЯвлення','…Усі знання для проЯвлення своєї Суті закладені в нас з народження. Вони не приходять із зовні. Вони розкриваються зсередини… Потрібні умови. Саме за ними ми ганяємось крізь життя в пошуках чарівних інструментів. …Умови… Ніякого виходу із карми чи ма...','["…Усі знання для проЯвлення своєї Суті закладені в нас з народження. Вони не приходять із зовні. Вони розкриваються зсередини… Потрібні умови. Саме за ними ми ганяємось крізь життя в пошуках чарівних інструментів. …Умови… Ніякого виходу із карми чи матриці не існує. Ти переходиш із рівня на рівень. І навіть в стані пробудженої і просвітленої свідомості - реалізовуєш певні місії на Землі. І не лише на Землі… Всюди, де усвідомлюєш себе. Ілюзія про вихід із матриці - це теж навʼязлива думка его. Скільки енергії ти створила, стільки і реалізуєш… не більше і не менше… Але вид енергії має значення… Жіноча - завжди насичена, пластична, живильна, концентрована і відчутна… Коли в тобі не просто сексуальна (вітальна) енергія є, а дійсно ЖІНОЧА СИЛА БОГОРЕАЛІЗАТОРА, яка супроводжується мисленням Творця і формує 5d реальність - ти завжди помітна, і ПОВІЛЬНА при цьому. В тобі не буде ривків. Ти не реактивна… але високопотенційна… Усі твої дії завершені. Чітка ритміка рухів. Бо така ж в тобі і ритміка думок… Ти встигаєш вирішити, про що саме думати. Пропускаєш думки крізь фільтр душі і вибираєш лише погоджені з цінностями. Але ти не оцінюєш світ, а вдихаєш крізь себе життя і приймаєш рішення, що саме ОЖИВИТИ увагою, що саме підсилити і матеріалізувати… що видихнути в завершеність і довершеність… Ти не думаєш ким стати, щоб виживати. Не обслуговуєш чиєсь уявлення про твої функції чи ролі… А твориш проЯвлення і любуєшся варіаціями результату. …Результат завжди буде не статичний. Покрутивши грані обставин через координату часу та простору - ти бачиш для якого досвіду створила ту чи іншу ситуацію… #IMaRia - твоя #zirka - звірка з навігатором Душі Як розумієш написане і тобою прочитане зараз? 😘 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','5 липня 2024','3 хв читання','/images/posts/09.jpg','[]',1,'2024-07-05T22:07:23','2024-07-05T22:07:23');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1976','%d0%bc%d0%b0%d1%81%d1%88%d1%82%d0%b0%d0%b1%d1%83%d0%b9-%d0%b6%d0%b8%d1%82%d1%82%','Масштабуй життя всюди де ти є!','Нам з вами судилося проявитися легендарними… Просто памʼятайте про це. Бути і сильними, і слабкими, будь-якими… бути живими душею 💫 Бо! 👇 Не має значення де ти. Має значення ХТО ТИ. Не має значення звідки ти. Має значення КУДИ ТИ… путь проявляє твоя ...','["Нам з вами судилося проявитися легендарними… Просто памʼятайте про це. Бути і сильними, і слабкими, будь-якими… бути живими душею 💫 Бо! 👇 Не має значення де ти. Має значення ХТО ТИ. Не має значення звідки ти. Має значення КУДИ ТИ… путь проявляє твоя Суть… ✨✨✨ …не воюю - а живу живе життя… Ціную. Люблю. Оберігаю. Взрощую. Виховую. Навчаю. Створюю в Україні осередок #ImariaSpace… а учні несуть по світу вібрацію мудрої любові та сакральних знань:.. 🌿🌿🌿 Світанковий сатсанг з активацією Вищої інтуїції реалізувала!🙏 Запис зустрічі доступна усім для досвіду… https://youtube.com/live/5bRmpGPNXHw © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','31 липня 2024','3 хв читання','/images/posts/Сатсанг.jpg','[]',1,'2024-07-31T08:36:05','2024-07-31T08:36:05');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1984','%d1%80%d0%b5%d1%82%d1%80%d0%b8%d1%82-%d1%83-%d0%b3%d1%80%d1%83%d0%b7%d1%96%d1%97','Ретрит у Грузії «Ти перлина Океану Життя»','В серпні я лечу з ретритом в ГРУЗІЮ… Це буде мій 40-й ювілейний РЕТРИТ, організований для жінок заради щастя…😍😍😍 То не пропускайте свій шанс зустрітися і обійнятися в практиці живого життя і в таїнствах прямої передачі Сили та проживати ініціації. Хт...','["В серпні я лечу з ретритом в ГРУЗІЮ… Це буде мій 40-й ювілейний РЕТРИТ, організований для жінок заради щастя…😍😍😍 То не пропускайте свій шанс зустрітися і обійнятися в практиці живого життя і в таїнствах прямої передачі Сили та проживати ініціації. Хто розуміє - той розуміє, що це безцінно. Що буде на ретриті «Ти перлина Океану Життя» ? Оооооо… програма мега насичена і ресурсна. Вона про активацію пари Нового Часу. Вона про цілісне процвітання і святкування своєї присутності на Землі. Я закохана в Грузію сердечно. Ми з чоловіком навіть мали квартиру в Батумі на першій лінії моря. Продали якраз перед війною. Багато в мені є цінних досліджень цієї прекрасної країни, яка своїм серцем кличе мене зараз служити щастю людей і плодити любов. Я ходила по містичних і не туристичних маршрутах. Досліджувала навіть малу батьківщину Сталіна, у мене був свій духовний досвід в Уплісцихе. Дуже, дуже древня памʼять душі розмовляла про вічне і давала мені коди для реалізації своєї місії тут і зараз. А що ж тут і зараз? 🥰 Ви відпочинете зі мною, відновитесь, наповнитесь, познайомитесь з жінками спорідненими і отримаєте нові вібраційні враження. Я покажу вам місця, які окриляли мене свого часу… Це ретрит для усіх жінок, які проходили будь-які мої програми, були учасницями ретритів і семінарів, або ж є клієнтками персональних консультацій чи резидентками середовища Piplclub. Новачків «з вулиці» не беру… 😘 Кому дати деталі? З собою ви навіть можете взяти дітей і когось з близьких, ми потурбувались про можливість таку. Забронювали неймовірний готель в горах Аджарії… Аааааа… якби я не була в Грузії раніше, і мені таке запропонували… навіть не знаю що сказати - я була б на сьомому небі від щастя…🤩 Бо ми як команда турботи турбуємось про усе до дрібниць… 🫂 👇👇👇👇 До кінця данного тижня іще готові прийняти в список. Ретрит триватиме з 26.08 по 1.09!!! Ну що готові до шансу? 😍🤗 Не кажіть, що не бачили новину… І все - відлік пішов…🚀 https://pipl.net.ua/retrit-georgia-2024 https://youtu.be/MTByY7HtBeY © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Новини','Ірина Заверуха','30 липня 2024','3 хв читання','/images/posts/Ретрит-Ти-перлина.jpg','[]',1,'2024-07-30T08:47:41','2024-07-30T08:47:41');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-1992','%d0%ba%d0%be%d0%bb%d0%b8-%d0%bd%d0%b0%d1%81%d1%82%d0%b0%d0%bd%d0%b5-%d1%87%d0%b0','Коли настане час здійснити задумане?','…ми можемо все, доки не переконали себе в протилежному і не повірили в це… …Їжте з красивих тарілок. Зараз. Слухайте музику свого серця і танцюйте без глядачів. Зараз. Будьте з кимось, якщо хочете близькості. Зараз. Обіймайте. Цілуйте. Регочіть чи ше...','["…ми можемо все, доки не переконали себе в протилежному і не повірили в це… …Їжте з красивих тарілок. Зараз. Слухайте музику свого серця і танцюйте без глядачів. Зараз. Будьте з кимось, якщо хочете близькості. Зараз. Обіймайте. Цілуйте. Регочіть чи шепочіть на вушко. Зараз. Створюйте собі спокій чи самість, будьте в тиші, смакуйте розлуку зріло, без втечі. Чесно. Зараз. Малюйте картини. Пишіть вірші. Співайте пісні. Зараз. Готуйте страви, яких ніколи не куштували. Створюйте романтичні листи для коханих і романтичні листи читайте з відчуттям кожної букви. Зараз. Починайте проекти, від яких вас мурашить…, відкривайте свою справу, масштабуйте існуючу. Зараз. Гортайте пальцями живі книги з сенсами, а не лише стрічки соцмереж, де сенси тонуть в мулі часу… Торкайтесь до безкінечності через кінечне. Зараз… Подумайте про свій рід та слід на Землі. Відчуйте його. Посадіть дерево, бо воно одночасно тягнеться корінням і вгору, і вниз. Поливайте ті, які посадили до вас. Зараз. Прийміть відповідальність за своє тіло та життя. Не шукайте винних. Зараз. Переставайте гратися в ілюзію успішного успіху і маніпулювати духовністю знову заради грошей та слави, але ніби то з великою місією. Зараз. І робіть добро, бо це дОбре. Зараз. …Велич людини в її божественній матеріальності, в матеріальній божественності - вона завжди тиха і проста, тому й очевидна… Зупиніться, щоб почався ПУТЬ… 💫 ✨IMARIASPACE✨ - Сила та Простір, в якому окриляються душі © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','2 серпня 2024','3 хв читання','/images/posts/_IMARIASPACE_.jpg','[]',1,'2024-08-02T12:48:00','2024-08-02T12:48:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2001','08-08-2024','08.08.2024','Куди бігти? Що робити? Ну ось і настав цей день 8.08.2024 і він буде черговим днем шансу прожити живу реальність, або ж черговим ілюзорним шабашем, довкола якого створили воронку уваги. Як це розуміти? Практики, містики, провідники різних традицій пр...','["Куди бігти? Що робити? Ну ось і настав цей день 8.08.2024 і він буде черговим днем шансу прожити живу реальність, або ж черговим ілюзорним шабашем, довкола якого створили воронку уваги. Як це розуміти? Практики, містики, провідники різних традицій проявляють для людей з менш широким рівнем свідомості новини із великого галактичного радіо. І суть полягає в тому, щоб ми були максимально в контакті зі своїм ідентичним сутнісним Началом та достатньо наповнені потоками світла власної душі. Вчора в середовищі свого закритого клубу практиків Piplclub я саме цим і займалась - ділилась технікою швидкого наповнення енергією. Щоб вібраційний резонанс покращився і не лякали ніякі потрясіння, та не якорили матеріальні процеси в провокаціях зупинки спокусами безсилля. Все - мої вміють дихати із виміру душі себе та формувати стан для польоту крізь часи потрясінь. За них я спокійна. Доєднуйтесь до поля практиків і не тому, що день такий, ви знаєте - вас кличу роками, зазиваю діяти на благо живого життя вже 15 років різними способами. Аби центральне духовне сонце змогло пробитися своїми променями в серцях більшої кількості людей і проявитися. Але зараз я хочу написати трохи тексту з загальним баченням процесів. Як проживати найближчі дні та період? 1. БУТИ В КОНТАКТІ З РОДОМ. Під родом маю на увазі космічне племʼя і земне коріння. Бо лише так людина являється дійсно деревом, а не бурʼяном. Якщо ви не маєте Вчителя, свого проходу до мудрості, благословіння традицією, то як мінімум можете шанувати приРоду і через свої еко відомі стосунки з Землею бути в резонансі з її частотами гармонії. 2. МАТИ НАЕНЕРГЕТИЗОВАНЕ ТІЛО. Бо саме тіло є простором, в якому або темрява несвідома коїться, і немає місця душі, або ж це чистий канал проходу, це джерело живого проявлення Сили. Тому робіть йогу. Обовʼязково. Робіть чистим свій простір для живого життя. Покажіть своїми діями свій намір та вибір. Хребет має бути наповнений духовним потенціалом. 3. СЛУЖИТИ СПРАВІ ЖИТТЯ. ЙТИ СВІЙ ПУТЬ ДУШІ. Дітям достатньо бути зараз в повазі до батьків. А от дорослим важливо йти свій путь душі і допомагати дітям стати на їхній. Тим не менше зараз багато дорослих «вирішують» замість власних дітей, як їм буде краще, бо страшно самим батькам. Перестаньте це робити. Займіться собою. Ви повинні дізнатися своє ПРИЗНАЧЕННЯ. Відчувати і проживати свою системну роль часу. Нині формується матриця нового тіла планети. Під 5d реальність не планета підлаштовується, а люди. Бо на Землі давним давно є безліч реальностей. І завжди були. Але люди кількісно формують плотність поля. На курсі ProResurs іще взимку я розповідала про важливість розуміння як жити в різних вимірах і створювати ресурси. Нині усі побачать свою «правду». Творці життя із 5d та вище ще більше ствердяться в Силі своїй і масштабно в місяцях серпня-жовтня черговий раз проживуть свої здобутки, результати. Амбасадори спільнот із 4d виміру будуть ще більше цінувати «своїх» і нарешті зрозуміють, що це ресурс - простір з єдиними цінностями. А от глибоко застрявши в матриці карми страждань це буде період потрясінь і практично останніх шансів змінитися та пробудитися. Як це зробити? Ви не можете проходити ніякі містичні Ворота Лева, доки не пройшли елементарні ворота матері і батька. Ворота власної зрілості людської. !!! Не грайтесь в ілюзії духовного розвитку. Живіть себе - духовну особистість достойно. Дитина роду бере благословіння у батьків і пропускає крізь себе усі спектри роду, приймаючи їх, а не граючись в корекції, зміни і покращення. ПРИЙНЯТТЯ. І тільки після цього стається інтеграція та «сепарація», тобто здорові стосунки, а не кожен сам по собі. Привʼязки до грання в «маленьких дітей бунтарів» чи навпаки «рятівників» когось - це і є 3d матриця. Якщо ви вважаєте, що хтось чи щось, а не ви створюєте вашу долю - ви іще в тренажерній залі 3d ілюзій. В великій імітаційній грі. Чи існує швидкий спосіб еволюціонувати? Ні. Це процес і путь. Тому можете не вірити маніпуляціям з різних екранів про те, що вас зараз швиденько за певну велику плату кудись переправлять. Ніхто нікого не «перевозить». Перехід стається сам в середині нас. Тому що це процес. Повторюсь. Ви і тільки ви здатні приймати рішення, заходити в свою структуру долі і в ній реалізовувати зміни такого рівня. Що я можу порадити? Практику «ЗМІНА МІРНОСТІ» в якості старту. І далі - не зупиняйтесь. Створила я цей інструмент. Якщо вам резонують мої техніки і ви готові попрацювати та застосувати в дію - напишіть. Покажу де лежить і як придбати цей продукт…😘 (Усім, хто збирався діяти, але новина про оплатність техніки, а це аж 20$, - обломала ваші наміри, скажу відразу - ваша глибина дефіцитної дитячості скоріш за все в такій формі, що і продукт не допоможе. Тому так. Не купуйте нічого. Не змінюйтесь. Навіть не намагайтесь… вам точно нічого не світить… …Це ви хотіли почути про себе із рівня «жертви» щоб знецінюватися далі і себе зсередини жерти? Ну все. Почули. Йдіть страждати далі. Жаліти ніхто не буде і доганяти. Або псіханіть нарешті і подолайте свою звичку шукати всюди шару. Бо це і є наслідок стосунків з Богом і образи на життя через очікування). 4. Тема місяця серпня - МІСТИЧНИЙ ПРАЙД МУДРОСТІ… великі жнива почались! І це буде потік швидкої сурової ВОДИ, навіть можна сказати льодяної. Хтось «тонутиме» в своїх страхах та ілюзіях, а хтось побудує світи в новому СВІТІ своєї внутрішньої планети щастя…добре усвідомлюючи системну роль. … і тут я поставлю крапки. Бо кожен з нас проживе даний місяць так, як вміє і може. Так, як вистачає зрілої мудрості. ✴️✴️✴️ P.S. Ваші реакції і коментарі - це завжди свідчення того, чи писати іще подібні тексти. Бо насправді є чим зайнятися. Ввечері вестиму прямий ефір в інста сьогодні. Кому цінно поговорити про масштабування в часи потрясінь - приходьте. Ефір вестиму з Дмитром Александровим в парному діалозі 🙌 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','8 серпня 2024','5 хв читання','/images/posts/454607921_478306681723263_7859832405716096222_n.jpg','[]',1,'2024-08-08T12:39:39','2024-08-08T12:39:39');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2005','%d0%b2%d0%b8%d1%89%d0%b0-%d1%81%d1%83%d1%81%d0%bf%d1%96%d0%bb%d1%8c%d0%bd%d0%b0-','Вища суспільна нагорода - Орден "За громадянську доблесть"','Люди, чарівні неймовірні люди, я щаслива нести смолоскип знань крізь часи, і роблю це не перше життя, та тішусь дитячою радістю від кожного вашого досягнення, перемог, прориву, прозріння, прояснення, пробудження, просвітлення, зцілення, народження… 🙏...','["Люди, чарівні неймовірні люди, я щаслива нести смолоскип знань крізь часи, і роблю це не перше життя, та тішусь дитячою радістю від кожного вашого досягнення, перемог, прориву, прозріння, прояснення, пробудження, просвітлення, зцілення, народження… 🙏Нехай усі, хто в путі, - дійдуть! 🙏Нехай усі, хто шукають - знайдуть! 🙏Нехай усі, хто зробили крок в проявлення - сміливо реалізують свою Суть… Ціную безмежно усе, що вдається реалізувати, ціную безмежно уроки, які навчають ставати іще більш люблячим полем… ціную життя і зроблю усе, на що здатна, аби Голос Душі живородної будив і далі сплячі серця… та масштабував силу вже проявлених. Нагороду традиційно (як і попередню в 2022 році), отримати у вказану дату не зможу, бо в путі буду та служінні. Цього разу у мене зйомки кліпу на потужну і неймовірну баладу Берегині, яка стане птахою не менш окриляючою, ніж книга-цілитель \"Бесіди з Ангелами\" , що полетіла по світу і понесла український дух волі та невгамовної творчої сердечної краси… Як і всі учениці, в яких я продовжуюсь. Як і усі студенти курсів та навчальних програм… поціловані вірою та жагою до живого життя… Кому з вас дійсно резонує і бринить цінністю це бачити в своєму полі та реальності? 🤗😘 А можливо комусь байдуже чи здається не на часі? Маєте бажання виразити діями свою реакцію? - то підтримуйте проекти, які я створила вже. Обіймаю словом живим… і йду далі…🫂 А «квіти» вмію приймати спокійно через створені умови ось тут 👇 https://pipl.net.ua/podyaka-vchytelyu Бо мені завжди є куди направити далі усі матеріальні блага… 🤗 Я Жива Сила МА і оживляю усе, до чого торкаюсь… 🌿🌿🌿 P.S. Коли триматиму в руках нагороду - то обовʼязково покажу іще раз. Бо це результат не лише мій, - ділю путь зі своєю командою та родиною…💫🌍💚🙌🪽 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Новини','Ірина Заверуха','7 серпня 2024','3 хв читання','/images/posts/Нагорода.jpg','[]',1,'2024-08-07T12:50:59','2024-08-07T12:50:59');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2020','%d0%b4%d0%be%d0%bf%d0%be%d0%ba%d0%b8-%d1%96%d0%bb%d1%8e%d0%b7%d1%96%d1%97-%d0%ba','Допоки ілюзії керують увагою - ви нічим не керуєте!','Цей текст я сьогодні пишу для «романтиків-ілюзіоністів»… Пардон, якщо чиїсь почуття зачепить. Чи ваше мнєніє про мою персону та суть зміниться. Коли я дивлюсь на людей, які смакують свої думки, як чіпси з дешевого пакетика, то іноді хочеться таки псі...','["Цей текст я сьогодні пишу для «романтиків-ілюзіоністів»… Пардон, якщо чиїсь почуття зачепить. Чи ваше мнєніє про мою персону та суть зміниться. Коли я дивлюсь на людей, які смакують свої думки, як чіпси з дешевого пакетика, то іноді хочеться таки псіханути і порушити закони життя на Землі. Бо назріває внутрішній гнів. Але його ловлю сачком свого розуму і направляю на дії. На створення інструментів, що пробуджують свідомість. Люди, попереду у нас з вами десятки РОКІВ відновлення країни, психічного і ментального здоровʼя людей, адаптація покалічених війною і впровадження неймовірно величезних змін в структуру управління реальністю. Ви маєте не шукати спосіб втечі від життя в алкоголь, то в ігри, то в їжу, то іще в якусь фігню, навіть часто в релігію чи її полярні крайнощі та похоть - а шукати спосіб підсилення своєї нервової системи і стійкості. Ви маєте бути зайняті 24/7 масштабуванням мислення через участь в суспільних задачах, через дотримання практики щедрості, через вібраційний хакінг свого жлобського егоїзму. Досить порівнювати - себе дослідіть. Себе полюбіть. Себе прийміть. Себе одобріть. Себе створіть. Займіться тілом, харчуванням, режимом… цінуйте життя діями базової турботи. Себе обійміть і захочеться обіймати інших. А не ховатися як страус в імітацію вибірковості. Чи жалітися на стрес. Все по своїй природі пусте саме по собі. Ми наділяємо події якостями і сенсами. Хтось бачить проблему, а хтось в ній бачить можливість і розквітає в силі. То хіба не є еволюційним вчитись бачити #МОЖЛИВІСТЬ, а не топити інших в болоті, в якому самі тонете? Допоки ілюзії керують увагою - ви нічим не керуєте. Взагалі нічим. Зайдіть в практику. Навчіть себе перемагати СЕБЕ! Реалізуйте подвиг. Призначте собі челендж і досягніть фінішу. Навіть без оцінки результату. Просто дійдіть до кінця… Це неймовірно важливо! Моя система пропускає через Вище серце Берегині роду людського потоки і в життя і в смерть. Бо це єдиний канал циклу творіння. Вже багато років я пробуджена свідомість і проявлений Аватар МА, окриляю хілерів, активую хранителів частот, навчаю жінок природі ЖІНОК. І справа в тому, що гратися в ігри ілюзорного світу не має ні бажання, ані і натхнення, ні потреби. Ілюзія лопне. Бо це бульбашка. І усе стає очевидним саме собою. Ви жалієтесь на океан інфоциган і що нікому не можна довіряти? А я хочу у вас запитати- чому ваш інфодебіл шукав інфоциган, щоб об них ранитися і не довіряти вже нікому, і казати, що - «я вже все пробував/ла, це фігня, бо нічого не працює»… Що саме вам не працює? Швидкий дофамін і чудодійні мультики не приходять після трьох спроб, чи ви таки робили дисципліновано хоча б років 3 без пропусків і маєте моральний слой досвіду? Щось ОДНЕ, без перескакування на всяке різне робили хоча б 3 роки щоденно без пропусків, крім свого ниття, критики, жалості і заздрощів??? Ні? То інфодебіл, який шукав пильцу фей і чекав чудес свого вознєсєнія в вимір рожевих носорогів, має інфоциган. І тішиться тим фактом, що їх багато і можна просто перебігати як порося, від корита до корита. В пошуках смачніших ілюзій. Бо простір Вчителя вам завжди буде влаштовувати кузькіну мать істинних зусиль та випробувань, доки ви не навчитесь смиренню, терпінню і вірності. Завжди!! Без винятків… Уроки гуманної педагогіки - то для дітей в дитинстві. А для вас - невротиків хронічних, носіїв травм минулих як мінімум шести поколінь - ніяка гуманна педагогіка не працює зараз тут. Бо це як клін/кліном. Ви не солоденькі тєхніки шукайте, а той вид простору, де ваш біль не осудять, не висміють, а визнають. І ви зможете вивільнитись із ілюзії упереджень. Йога свідомості - це не релаксація, і не розтяжка, не тріко в обтяжку, і не пози дзен… а прийняття РЕАЛЬНОСТІ. І в ній десь бульканням, десь беканням, десь пуканням чи кашлянням очищається тіло і підсвідомість від накопиченого хламу ментального… Очищується! А потім вже наповнити свій сосуд можна енергією істини, коли є пустота, є чистота, є спокій медитативного ума… Чи знала я, що буду будувати імперію цілителів саме для цього, щоб спостерігати, як ридають чи ригають люди, як хтось вмирає а хтось проситься на Землю, в надії на рай, але знову потрапляє в пекло, яке ми з вами створили? Ні. Чи вибирала я даний час і простір для проявлення любові до життя? Так. … А ви думаєте відрізняєтесь від мене? Ні. Чи знали ви як саме ви будете масштабувати любов на Землі через своє проявлення? Ні. Чи вибирали ви даний час і простір для життя? Так. Все. Крапка. До праці. Внутрішньої. А потім зовнішньої. А не навпаки… не настане час, коли у вас зникнуть турботи побутові. Ніколи. Ви маєте розставити пріоритети. Не вмієте? То приходьте вчитися… P.S. Мій товариш Олег Гудзенко знайшов в горах Ізок першоджерело творення гірського кришталю. Ось воно на фото. Ті кристалинки прозорі, які ви звикли бачити, в природі проходили колосальний путь зустрічі з тертям, тиском, вогнем вулканічної магми і ЧАСОМ… І що в результаті? Краса. Але ж усе відносно. Бо я бачу красу і в цих проміжних етапах теж… в цих чорних обвуглених шматках… Я відчула поряд з ними неймовірну енергію. Інтегрувала вібрала і її теж. Як і усі знання, які мої Вчителі земні і Вознесені передали… І що сказати. Це не про «жіночка» ти чи «мужичок». А про ти «людина» чи хто? Якщо ти людина, то нахіба? Якщо ви прямо зараз живете челендж дослідження себе, поділіться в коментарях який саме- нехай хтось надихається ідеями та пробує створити своє… 🥴 Не хвилюйтесь, - я не розколювала камені кулаком ), це фото показує розміри відносно моєї руки… На справді я тендітна і маленька тілом людина, але це не те, чим є Суть. І ви теж… © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','13 серпня 2024','5 хв читання','/images/posts/Камінь.jpg','[]',1,'2024-08-13T14:56:54','2024-08-13T14:56:54');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2027','%d0%bf%d0%b5%d1%80%d0%b5%d1%85%d1%96%d0%b4-%d0%b2-%d0%bd%d0%be%d0%b2%d1%83-%d0%b','Перехід в нову голограму Нової Землі','Про ХІЛЕРІВ напишу. Про цілителів. Бо назріло. Бо навчаю я сучасному енерго-інформаційному (вібраційному) хілінгу. Ні, не пішли цілителі, не зникли, - а ось мотивація в роботі змінилась. Просто цілити, як лагодити – вже не цікаво та не доречно. А що ...','["Про ХІЛЕРІВ напишу. Про цілителів. Бо назріло. Бо навчаю я сучасному енерго-інформаційному (вібраційному) хілінгу. Ні, не пішли цілителі, не зникли, - а ось мотивація в роботі змінилась. Просто цілити, як лагодити – вже не цікаво та не доречно. А що цікаво? Зцілювати так, ніби з легкістю віддаючи з шафи увесь старий немодний одяг та звільняючи місце для нового. Цей рівень вимагає довіри до потоку і від людини і від самого Майстра! Прощаєшся зі старим, не знаючи зовсім, що буде далі. Раніше так було лише під час смерті – зміни мірності, тобто треба було тіло змінювати. А зараз ти в тому ж тілі, але твоє его проживає «смерть», і немає сенсу його ремонтувати... Через активацію з виміру Галактичної Душі формуєш нову конструкцію для форми - і вперед! Вона інтегрується в системі та живеться тобою з іншого стану, ти бачиш не лише старі ігри в кармічній ілюзії; нові ігри усвідомленіші, але й бачиш світи вишні, перебуваючи в них, відчуваючи і проходячи і там і тут досвід присутності, а не періодичного гостювання. Ми поступово переходимо в нову голограму Нової Землі, більше того – ми ж її й будуємо! Є сенс додати - на рівень поза старою конструкцією насправді не всі потраплять; в рамках цього втілення, даного тіла не вдасться перелетіти вище без завершення справ у роду, в інкарнаційному досвіді душі, у дитячо-батьківських та партнерських відносинах... не зібравши достатню кількість спектрів Світла (ідентичності), ти не можеш піднятися над матерією, ти втілений механізм з грузиками... як духовний каліка, що імітує просвітлення, але насправді не має свободи вибору та достатньої кількості ресурсів. Тому змінюючи конструкцію мислення, від цих завдань не відмовляйся. Реалізуйся! Адже зможеш вже і літати і повзати, і крила зовсім не заважають цьому... ти продовжуєш збирати спектри Світла, але вже з іншої формули себе, і будуєш новий Вимір, проявляючись як частина нової цивілізації РЕАЛЬНИХ. При цьому не зникла потреба цілителям старого загартування (родовим і кармічним) продовжувати переводити в формат «апгрейд» системи тих, хто ще не зібрав все своє втрачене Світло душевних спектрів, не завершив свої ігри в «вірю/невірю»... Ну, а я йду далі! Проживши свої ПЕРЕХОДИ в буквальному сенсі, протягом останніх місяців я провела для людей безліч потужних практикумів з перезавантаженням, створила нові вібраційні продукти, реалізувала квантові трампліни для польотів… і якщо ви хочете змінити якісно СЕБЕ собі на радість, пишіть нам і приходьте ЖИТИСЬ разом… З Богом всюди! З Родом всюди! © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','25 серпня 2024','3 хв читання','/images/posts/1.jpg','[]',1,'2024-08-25T15:32:54','2024-08-25T15:32:54');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2035','%d1%96%d1%81%d1%82%d0%be%d1%80%d1%96%d1%8f-%d0%bf%d1%80%d0%be-%d0%bc%d0%b0%d1%82','Історія про «Мати і Мачуха»','Сьогодні на світанку зі мною стався діалог двох світів в моменті їхньої квантової архівації. Ці світи настворювали люди, граючись в боротьбу під час епохи Калі юга. Я часто спостерігаю як зникають голограми даної старої реальності, і навіть стаю прич...','["Сьогодні на світанку зі мною стався діалог двох світів в моменті їхньої квантової архівації. Ці світи настворювали люди, граючись в боротьбу під час епохи Калі юга. Я часто спостерігаю як зникають голограми даної старої реальності, і навіть стаю причиною цих процесів на Землі на своєму рівні колективної і регіональної відповідальності, утилізуючи їх. І так - історія про «Мати і Мачуха». Слідкуйте за думкою.👇 Були різні часи… Сатья юга - час, коли Добро і Зло жили у різних відокремлених світах, маючи чіткі межі і правила взаємодії, прописані в пактакт Вселенського Балансу. Не пересікаючись. Трета юга - це час, коли вони вже в одному світі жили і ділили сфери влади: Рам та Раван. Двапара - в одній сім''ї. Пандави та Каурави. А Калі юга - це час Коли демони та боги живуть в одній людині. І цими людьми є ми з вами. Усі, народжені до 2012 року. І ми з вами є трьох типів. Одні мають походження душі зоряне, космічне - і на Землі зараз знаходяться для набуття контактування з демонічним началом, з дуальним виміром, з грубою інформацією, і при цьому вони вирівнюють колективний баланс світлих енергій і транслюють чисті потоки знань від цивілізацій ієрархії Творця. Інші душі мають походження демонічне - і на Землі зараз набувають духовного досвіду, при цьому проживаючи високі посади, владу і матеріальне багатство, тобто вони транслюють себе як лідери напрямків та правителі, які ніби то через гроші і владу ведуть себе та інших до еволюції. І є третій тип. Земного походження душі. Вони максимально адаптовані до умов планети, і дуже часто бовтаються між таборами попередніх двох, додаючи кількості то тим то іншим… від них зараз найбільше залежить результат, саме вони можуть увібрати в себе найкращі якості полярних світів і прийняти ЧЕРЕЗ СЕБЕ ДІТЕЙ З ВИСОКИХ ВИМІРІВ… діамантових дітей… які змінять планету… ☄️☄️☄️АПОКАЛІПСИС ☄️☄️☄️ Мав відбутися рівно через 10 років після 2012! Його реалізаторами є душі з демонічним походженням. І це їхня задача. Період глобальних катастроф і бід, в який обнуляється реальність повністю. На Землі проявляються Аватари МА, щоб перенародити Нову Свідомість і почалась епоха Сатья юга… Золотий вік Творця. Настане ця епоха після того як колективна свідомість абсолютного добра, абсолютної істини, абсолютної радості, абсолютного щастя, абсолютної свободи, абсолютної любові займе своє домінантне місце і розквітне… Далі ця епоха триватиме довго. Дуже довго! ✨✨✨ До речі, хто звідки прийшов у дане втілення, з якого племені душ - чітко зрозуміло через дату народження людини. Тобто яким є походження людини - зоряним (космічним), земним, чи демонічним і які при цьому задачі у душі на Землі зараз - кожен експертний астролог-вібраціолог знає прекрасно. Я в тому числі… ✨✨✨ І от сьогодні спостерігала я за архівацією квантового прошарку «Мати /Мачуха». Як це розуміти? Уявіть собі, що ви маєте походження душі демонічне. Це означає, що в роду вашому точно є багато досвіду про владу, багатство, сексуальну розпусту, вседозволеність, крайнощі розкоші через насилля, різні залежності… І от ви в 21 столітті, де кипить повним ходом котел Апокаліпсису. Вам кажуть з усіх трибун зоряні душі - «роби добро», «кармічні відбитки», «віддавай іншим», «служи», «йди до роду!!!!», «будь собою, пробуди душу»… Аааа стоп… І бере така людина і йде ДО РОДУ, до джерела себе, до своєї суті і початку. І що вона там знайде та зустріне? … Роблю вам паузу на подумати… Вірно. Вона зустріне ДЕМОНІВ. Бо її рід такий і джерело теж. До речі, а ви знали, що демони теж мають КРИЛА? 🙃🙂 Ні? Будете знати. Вони майже нічим не відрізняються від Архангелів на вид. Тому моя програма КРИЛА , - вона для різних. Бо в програмі я допомагаю жінкам «зібрати пірʼя», тобто усі спектри своєї душі і зцілити в повноті безумовної любові, увійти в 4d реальність і еволюціонувати себе далі до тіла і свідомості 5d… 🤗 Ось чим я зайнята, як Аватар МА. А не створенням ідеальних чи святих… ні! Жінка проявляє себе ЖИВУ без внутрішньої війни світів і минулих епох. І проявляє себе ЖИВОНАРОДЖЕНУ ДУШУ в палітрі людського багатоманіття. Пардон за відступ. Йдемо далі… Так от. Така людина починає проживати колосальний внутрішній конфлікт. Часто навіть відвертатись від власного Вчителя, бо стає дуже боляче усе це жити. Як так? «Усі кажуть «йди до центру себе», я прийшла - а там такеееее?» Скажу вам відверто, я такі фрази чула сотні разів від своїх учениць. А від деяких не чула слів, але вони так і не наважились ці слова сказати в слух, хоча все зрозуміли. Ну як вам історія? Коли твоє походження душі демонічне, то що тоді? Коли усі довкола кричать про потребу зʼєднатися з родом, з руслом своїх, з початком… але ти в цьому початку приходиш до демона, бо це твоє джерело?🤔 І люди втікали від себе в імітацію «практики»…😶 Натовп пішов до зоряної «Мачухи» ілюзорно хорошої, аби лишень не єднатися з ілюзорно поганою «Матірʼю» демонічною. Як ви гадаєте, Така Мачуха (ангельського походження) стане для них справжньою матірʼю, буде вона в монаді їхнього ядра внутрішньої сімʼї бриніти в резонанс з інюмтиною такої людини? Звичайно, що ні. І одиниці лишень готові самим собі зізнатися, що питання в неприйнятті СЕБЕ і в підміні понять. Бо ніяка мачуха не замінить матері. ВИ НІКОЛИ І НІКУДИ НЕ ВТЕЧЕТЕ ВІД СЕБЕ І СВОГО ІСТИННОГО КОРІННЯ ДУШІ! КОЖНА людина зараз має прийти до повного 100% прийняття і визнання себе в собі! Гра в порівняння і сором за демонічне походження буде руйнувати з середини і брати у вас високу плату. Яку саме? Проблеми з фінансами і положенням в соціумі. Оскільки саме демонічне походження і дає людині доступи до усіх видів знань про матеріальне процвітання землян, це прошарок знань і про харчування, і про простір життя, і про різні види саме матеріальної алхімії. Андестен? До речі, аналогія працює і навпаки для інших. Ті, хто гралися в вєлікіх рєшал за владу і бабло, через здоровʼя та проблеми з тілом мусіли помучитись, задавати питання, навчатись і знайти … - коли пішли до центру себе - знайшли ангельське і зоряне походження і прозріли. Усвідомили свої задачі та ролі вчителів, цілителів і духовних лідерів часу. (До таких належу і я. Своє зоряне походження вже безліч разів описувала тут. А в книзі-цілителі \"Бесіди З Ангелами\" розказала людям безмежно багато сакральної інформації про цілісне життя… Відповідаю для колег, яких турбує технічний інтерес. Моя накшатра - Ашвіні. А яка ваша? 😘) 〰️〰️〰️〰️〰️ Тепер розкриваю карти. Я маю намір продовжувати зцілювати слої реальності і обнуляти формули «пари старого часу», та активувати в генах людей коди ПАРИ НОВОГО ЧАСУ. Цього разу у вересні на семінарі в Буші буде дана тема - МАТИ/МАЧУХА. Я вестиму людей ВПЕРШЕ через абсолютно новий інструмент, якого ніхто іще в моїх руках не бачив… І йтиме поступова підготовка до більш глибокої роботи на ретриті в жовтні, який проведу в Карпатах. 👇👇👇👇👇 Семінар МЕТАТИЗИС в Буші для інтегральних душ Хранителів частот, які своє зоряне походження давно не приховують; які мають намір проживати повноту себе в якісній парі нового часу - тобто в союзі Неба та Землі… і в тому числі для тих, хто мучиться неприйняттям свого демонічного походження - я проведу 27-29.09! І чекаю лише на тих, кому дійсно резонує мій текст і його сенси. Не спішіть бігти реєструватися, якщо не практикуєте йогу свідомості щодня мінімум 1,5 місяці. Якщо не медитуєте. Тоді вам до Буші не зі мною точно… Дякую за розуміння!🙏 Бо донести такий непростий текст і контекст до мас і при цьому достукатись до тих, кому дійсно час - це для мене задача з зірочкою кожного разу… 🤗🤪 Чи вийшло? Хто не може бути фізично ні на семінарі, ні на ретриті, але тема БРИНИТЬ, - приєднуйтесь до мого трансформаційного марафону \" З Чистого Листа\" , який стартує 22.09, бо ділитимусь активно з учасниками інформацією та практикою періоду. Адже ми з вами зараз вступаємо в коридор затемнень, під час якого є можливість якісно обнулити свої налаштування, відпустити хибне, наростити силу та мужність жити істинне… і взагалі - вийти нарешті із скоридрпів страхів перед темнотою та усіма видами розділення… © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','11 вересня 2024','7 хв читання','/images/posts/послання.jpg','[]',1,'2024-09-11T19:50:28','2024-09-11T19:50:28');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2039','%d1%82%d0%b8-%d0%b7%d0%b0%d1%80%d0%b0%d0%b7-%d1%82%d0%b0%d0%ba%d0%b0-%d0%b2-%d1%','Ти зараз така, в яку повірила …','…Вчора я записала і віддала людям голосовий вібраційний прогноз-підкаст на тиждень в закритому Pipl Club , а ввечері проводила для них прямий ефір з потужною квантовою практикою обнулення негативних програм, з розширенням орбіт процвітання для прийня...','["…Вчора я записала і віддала людям голосовий вібраційний прогноз-підкаст на тиждень в закритому Pipl Club , а ввечері проводила для них прямий ефір з потужною квантовою практикою обнулення негативних програм, з розширенням орбіт процвітання для прийняття миру і щастя в свою структуру реальності… …Знову спостерігала за тим, як люди торкаються до поля Життя, як щемливо і ніжно формується звʼязок з Голосом власної душі у тих, хто замовк в умі, чи хоча б стишив агонію внутрішніх криків его. Я веду досить багато ефірів в закритій площині, бо вже майже 20 років працюю з людьми і бачу найефективніший формат передачі. Можна бути всесвітньо відомими і медійно публічними і мати наставників духовних, яких ніхто не знає. Можна самим бути наставниками яких знають усі і консультувати зовсім не відомих, але вагомих… Можна взагалі ніде не бути, ніким не ставати, не еволюціонувати, пролистувати соцмережі, нудьгуючи про плинність часу… Тут можна все. На цій різнобарвній варіантами планеті. Це великий імітаційний акваріум для навчання життю. Вибір - в самій людині. І ніякі зовнішні мотивації не виконають внутрішньої роботи за нас, щоб вийти за межі «кордонів і стін». …Я спостерігала вчора за тим, як реагували МОЇ ЛЮДИ в групі на свій власний доторк до свого власного поля життя… Я чула їхню радість від усвідомлення факту, що сама Сила Божа повернулась до них очима і доторкнулась та покликала БУТИ… Я бачила ясно як злякались самі цього поля деякі. Злякались самі себе. І тіло їхнє в ту ж мить дало реакцію спазму, їм починало викручувати пальці, руки, ковбасити плечі… Я раділа за тих, хто навпаки в полі душі єдиної на території спільносерця усвідомлені вдохи і видохи робили без конфлікту і без очікувань результату. Бо поки ми очікуємо хоч чогось - не може початись… реальне… в присутності без оцінок. … мені тихо і спокійно… Мені ніяк. Я не плачу за тими людьми, які роками приходили крізь мене на поріг власного ПОЛЯ ЖИВОГО ЖИТТЯ, і розвернулись та пішли геть, шукати інші «двері», гратися в «я сама можу», в «тут не резонує», в «я усе це знаю», в «мені не подобається»… …Я не маю звички присвоювати собі результати тих, хто проходили крізь мене до СЕБЕ, успішно і назавжди, окриляючись і забуваючи увесь маршрут, ніби відразу був цей готовий екземпляр, що літає… Це потужно… спостерігати за різним. Без очікувань. Це дає свободу… Видихала знання. Видихаю. І видихатиму знання далі, скільки є сили бути. Створюючи простір, в якому «людина зустріла людину», «жінка зустріла жінку»… усі зустріли божу любов і в ній лишились… нею стали… бо завжди були… Є тисячі людей, які познайомились одні і з одними В МЕНІ, на території мого серця, мого поля любові… в проектах, які я створила, в програмах, на ретритах, в діалогах, в парах, в які їх ставила, на моїх святах, днях народженнях, в ролях соціальних, на які покликала… зібрала… довірила… Тисячі людей впізнали одні одних і пішли далі разом в якості друзів, працівників, партнерів, колег. І лише сотні з них усвідомили, що саме сталось… Що я бачу? Як мучаться жінки від своїх дефіцитних стосунків з «батьковою фігурою», з авторитетною персоною саме батька/патріарха в собі. І не можуть навіть це осягнути, доки не потраплять в поле вчителя, що транслює потік Бога, і не через материнські обійми, не через вібрацію безумовної любові, а через ЗНАННЯ, інформацію волі та духу без прикрас та тертя на високій швидкості відбувається смерть «хибного его», щоб проявилось істинне Я. Позаду потужна планетарна праця! Я виконала завдання Вищого Легіону Балансу - активація кодів і шифрів пари нового часу реалізована успішно. В програму КРИЛА23/24 до мене підтягувались саме ті, хто є носіями глибинних травмованих частин свідомості в цій темі, - партнерства. З собою, з протилежною статтю, з матірʼю і батьком, з дитиною… Так чи інакше - криза основна бриніла в полі «ПАРА». Не всі в цьому зізнавались на старті. Бо не усі це БАЧАТЬ в самих собі і мають сміливість та мужність нести відповідальність. Деяким здається, що вони йдуть за покликом серця в навчання, але я поки що спостерігаю як 90% жінок приходять саме за зціленням. І з них лише 10% усвідомлюють це самі. Іншим доводиться сказати. Рівно половина може дійти до кінця і не гратися в торгівлю знаннями (в «я тут купила», «а коли буде …, бо я розраховувала на оце…», а «я не буду платити за продовження, бо мені не резонує»). І друга половина - тікає геть, бо ілюзія тріщить по швах і з усіх дир витікає їхня брехня. Маніпуляції і брехня, навіть магічна… я надивилась на різне за свою діяльність. Але наприклад в цьому році вперше спостерігала за тим, як ведуть себе безпардонно люди, які сидять на ритуалах, і думають, що їм це не вилізе боком, що «так можна, бо ж так роблять». Наївні. Якщо ви «брудні від брехні» наскрізь, і вас цілитель впустив в свій простір діамантової правди - майте на увазі, вам обовʼязково буде погано. По справжньому погано. Від своїх власних токсинів, залежностей, ілюзій, від свого відображення в дзеркалі істини… відриватиметься з «кишками» усе те ілюзорне павутиння, в яке ви замотались і вплутали інших. «Синдром Іуди» обовʼязково вилізе. Не вийде приховати нічого, що вже було всередині і шукало вихід та волю. Хибне его тікає стрімголов від Сили, що загрожує йому викриттям брехні. Хибне его тягне людину в прірву, де тепленька спокуса, яка усіх «влаштовувала». Де нормою є зради, сексуальна розпуста, похоть, маніпуляції емоціями, торгівля волею, владою, шантаж, і навіть ритуали магічні (повторюсь!!! Цього нажаль дуже багато… особливо у жінок), безвідповідальність, жіноча сердечна скупість і показушна матеріальність, малодушшя, нетерпимість до інаковості, конкуренція за увагу і визнання, … гординя і понти, запаковані в імітацію високих вібрацій… Цього дуже багато. Дуже! І володіти яснобаченням, жити з ясно знанням повірте, це не солодкий мед, бо торкаєшся до цього «як є». Усі кімнатки свідомості людини, усі ці коридори… усіх Іуд бачиш, з якими тобі ж і доведеться мати справу. Але це не заважає рухатися далі, бо бути собою - це єдине, що легко. Чому я це розповідаю? Бо настав час! Багато років я чекала дня, коли збереться група цілісних особистостей духовних, які стануть моїми ПЕРШИМИ УЧНЯМИ прямої передачі знань Алхімії Живого Життя, методу аналітики долі #ПутьДуші і Божественної вібраційної Йоги. Я чекала. І знала, що це не про кількість. Я терпляча. І рухаюсь зі швидкістю, достатньою для того, щоб по путі відпали усі, хто прийшов по білету хибного его, в кому немає зрілості, немає поваги ні до роду, ні до вчителя, ні до учня в собі… бо який ти учень для своїх вчителів, - такий ти і вчитель. Або ніякий. Або справжній скарб… Тепер я маю цей день. Маю скарбничку… 🥰 Він буде 14 вересня. Перший день і доторк до сердець Учнів. Вони заходять в перший МОДУЛЬ. Етапів буде декілька. І я знаю, що до фінішу дійдуть не усі. Знаю, що життя хілера - це дорога з тотального служіння, і жінка-майстер розуміє, що своїм тілом вона не володіє, а піклується про нього і завжди переміщує свого Аватара туди, куди диктує голос душі і Велика МА; бо проявляється потенціал IMARIA, тобто цілісна вібрація БогоРодиці, свідомість НеоШаманки, НеоЖриці, НеоБерегині Нового Часу. Я бачу тенденцію. «Людина- медичний феномен» це той статус, який мені пропонували колись і місце в книзі рекордів України, бо зцілилася і зцілюю інших… Але я не можу присвоїти собі поле, яке нікому не належить. Але воля і кожна дія була саме моя. Кожен крок. Слово. Характер. Рішення… І у вас теж!!! Тільки воля, дія і кроки - тільки ваші і вами можуть бути зроблені вони… Торкаючись до енергоінформаційного поля жінки, я приймала душі нових людей в своєму серці Берегині роду людського (анахату) і через чистий канал сестринства (свадхістану) віддавала ці спектрі їм зі словами «Нехай у тебе буде більше, ніж у мене», нічого собі не лишаючи… і так відбувалось сотні разів зі мною. Діти і дітища жінок, яких вони потім народжували як своїх, приходили через моє серце БогоРодиці (тієї, що є проходом для душ із Роду Божого) - і ставали чарівними хлопчиками і дівчатками, доньками і синочками, проектами і творчими продуктами, картинами і книгами… для своїх мам і тат, авторів і авторинь… Сотні разів! Душі дітей, яких втрачали (абортованих, викиднів) душі загублених в роду… теж проходили через моє серце в канал свободи і переродження, отримуючи очищення від тяжких карм. Ніби викупані в джерельній воді, зціленні від спраги, розплутані із пут жіночого егоїзму … - вони покидали вимір астральних коридорів та лабіринтів і отримували волю та шанс на нове життя. ✨✨✨ Моє серце балансує порядок. І я це живу як є… Живу. Але останніми роками і розповідаю як саме це роблю. Бо це стосується кожної, хто розкриє свідомість #IMaRia в собі, і проявить ген Жінки-Майстра на Землі. І мої діалоги та розповіді стануть причиною для вольового прозріння. Я це знаю. Тому і пишу. Вже написала та створила практичну книгу-цілителя \"Бесіди з Ангелами\" , яка саджає ліси в Україні… і планую продовжувати. Пробуджувати. Не зупиняюсь… Продовження назріває. Скоро! 🤗 То які ж жінки прийдуть в програму КРИЛА24/25 ? Яка домінантна тема обʼєднує їх? Що саме видихатиме Земля найближчий рік, і що вона вдихатиме? … Цікаво вам читати такі мої роздуми…цінно? Писати продовження? 😘 …і напишіть будь -ласка, ті хто ходить кругами довкола поля мого і не наважується зайти… - що вас зупиняє? 〰️〰️〰️〰️〰️ Жінка - унікальна істота. Неймовірно унікальна. Найсильніша на цій планеті структура, бо створює нових людей, стає простором для ТІЛА І ДУШІ дитини; підсилює і прискорює усе, що вкладає в неї чоловік землянин, УСЕ… що дає і як відноситься до жінки чоловік - він отримує в масштабі і отримуватиме, щоб це плекати і оберігати як спільний результат… Жива душею жінка - вона як свято щоденне, видихає живе життя і чистоту духовно-матеріального процвітання. Мертва душею втягує в воронку неволі і формує поле страждань довкола себе… Жінка. А яка ти? Ти зараз така, - в яку повірила … і життя твоє саме таке, в яке ти повірила і підсилюєш щодня своєю увагою… Міцнієш серцем ти - міцніє твоя родина, міцніє твоя країна, уся людська нація єдина… Тому приходь. Як це зробили вже тисячі… і отримали свій священний результат… бо кожен досвід унікальний і священний…🥰 Приходь. Спробую тебе навчити… і відпустити… бо нікого не тримаю… навіть тих, хто хоче, щоб потримали чи прагне «потриматися» по-довше… Кожна заходить в моє поле, - коли готова, і виходить - коли прийшов час визнати наповненість і довершеність вдячністю. Я #Аватар МА - проявлена та усвідомлена. Активації Сили Жіночої Родової та сакральні ініціації проводжу для достатньо одушевлених, пробуджених і зцілених від галюцинацій претензій… Забігаючи наперед. Усім кажу, хто думає, що мене «знає»… якщо ви не були на моїх ретритах фізично, на семінарах та зустрічах живих з часів 2022 року - то поняття не маєте, що я нині роблю, що даю, чим займаюсь… бо абсолютно інша особистість живе і проявляє вібраційний потік #IMaRia через людину Ірину…😘 І це не зупиняється… Зараз я на порозі чергових масштабних змін… Програма КРИЛА24/25 в формі, яка нині - читається в останнє. А далі - буде далі… З любовʼю і обіймами до усіх - ваша розкішна мудрість 🤗 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','11 вересня 2024','9 хв читання','/images/posts/Ретрит-1.jpg','[]',1,'2024-09-11T20:25:20','2024-09-11T20:25:20');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2074','%d0%bd%d0%b0%d0%b9%d0%b3%d0%be%d0%bb%d0%be%d0%b2%d0%bd%d1%96%d1%88%d0%b0-%d0%bd%','Найголовніша наука Нового часу ...','В своїй багатій консультаційній практиці (а це понад 50 000 персональних діагностик долі!!) я неймовірну статистику напрацювала. Величезна кількість людей проходить крізь моє поле та простір саме по причині не прийняття СМЕРТІ як частини циклу творін...','["В своїй багатій консультаційній практиці (а це понад 50 000 персональних діагностик долі!!) я неймовірну статистику напрацювала. Величезна кількість людей проходить крізь моє поле та простір саме по причині не прийняття СМЕРТІ як частини циклу творіння… Саме так! Цикл творіння реальності складається з етапів. Кожен з яких важливий. СА ТА НА МА … Аватари МА зʼявляються на Землі в часи переходу. Це міжгалактична задача. Чому? СА - безкінечність, вічність ТА - життя, проявлення НА - смерть, кінець МА - переродження, початок… «Кінець» завжди торкається «початку», а він в свою чергу веде через вічність в процес самостворення Нового виду формул життя. Безліч разів в даному втіленні я була на порозі смерті, але дізналась про природу своєї Суті та місію лише тоді, коли пройшла наскрізь через даний континіум. І вийшла з іншого боку реальності… Лишень, коли себе зцілила потоком духу чистого - закони Творця зрозуміла. Аватари МА ведуть людей по реверсному путі. I MA WAY IMARIA 💫 Я йду путь IMARIA - реверсний путь еволюції душі!🙏 На даній дорозі , яка проявляється через архітектуру тіла світла символом тора, - немає відокремлених коридорів для смерті чи життя, бо він один… - по ньому душі йдуть у втілення і із втілення… Ні. Не усі Аватари МА такі. Є різні. Космічне племʼя душ з роду IMARIA готує жінок-богородиць володіти сакральними знаннями про цілісність, щоб народжувались люди саме із роду БОЖОГО на Землі. А є іще якісь інші рода? Так. Є інші. Читайте про це та різне в моїй книзі-цілителі #БесідиЗАнгелами - стане ясніше… То чим займаюсь я? 🔘Консультую усіх людей в питаннях проходу коридорів смерті (кінця будь якого виду), і переродження (початку будь якого виду)… Моя супер сила саме в цьому! 🔘Навчаю жінок-берегинь ювелірно проявляти знання про сакральне і формувати щасливі долі своїм близьким. 🔘Ділюсь досвідом з хілерами Нового часу… Створюю умови для їхнього розвитку. 🔘Направляю Лідерів по дорогах честі і відповідальності за духовне багатство і космічно-земний спадок-порядок. Ось чим… а інструменти маю різні. Тільки ціль - єдина. Тому мені не дивно, чому я народилась саме в Україні і роблю те, що роблю. Питань не маю до своєї долі чи путі. А на ваші питання про долю та як вирулити в ці часи на путь істинний та справлятися з потрясіннями - завжди готова дати підказки і чіткі відповіді… бо маю надзвичайно сильний канал яснобачення та навик «перекладача з кармічної на людську» з досвідом… 🙏 #ГолосДуші #Послання 👇👇👇 Максимальна кількість смертей з нами вже сталась. Попереду - переродження. Все, за що люди чіплялися із «несвободи ума та маніпуляцій тіла», мусіло вмерти і відійти в вимір архівації протягом 2020-2025 років. Подорослішала колективна свідомість землянина! Це радісна новина. Але розслабляти булки не варто. Дисципліна і практика - це інструменти для свободи та щастя. Далі буде трансмутація квантового поля. Кожен з нас мав зробити висновки про важливе. Усвідомити своє призначення, вийти на путь душі. Щоб цінності були причиною для дій та мотивацією, а не страхи і сором, чи провина та гординя виживання. Щоб сталось прозріння і розчинились ілюзії та ідеалізації… Чи вийшло у нас колективно просунутися в еволюцію вперед? Однозначно. Усі стали іншими. Та попереду - іспити практичні і кроки проживання кармічного врожаю. ✨✨✨ Коли до мене приходять жінки на діалоги і просять допомогти вилікуватися їхнім мамам, бо є якась хвороба (найчастіше онкологічна) - я кажу як є - це в середині ВАС і вашої монади внутрішнього ядра сімʼї є «хвора мама», як роль та проекція свідомості… зрозумійте! Ви не врятуєте нікого. Лише сама людина може зцілити себе, якщо усвідомила задачу. А вам доречно зайнятися ВАШИМ життям, терміново, вже зараз. Коли до мене приходять жінки на діалоги і просять допомогти вилікуватися чи змінитися їхнім сестрам/чоловікам/подругам, бо є якась тривога, хвороба, проблема - я кажу як є - це в середині ВАС і вашої монади внутрішнього ядра сімʼї є «хвора» роль та проекція даного виду свідомості… зрозумійте! Це жіноча конкуренція, ваша травмована мужність,власна гординя вас привела… Ви не врятуєте нікого, не зміните. Лише сама людина може зцілити/створити себе, якщо усвідомила задачу. А вам варто зайнятись СОБОЮ! Коли до мене приходять люди на діалоги і просять допомогти вилікуватися їхнім дітям, бо є якась хвороба чи питання до розвитку - я кажу як є - це в середині ВАС і вашої монади внутрішнього ядра сімʼї є «хвора дитина», як роль та проекція свідомості… зрозумійте! Ви не врятуєте нікого. Вчіться любити, прийміть себе тотально, визнайте себе і транслюйте любов дітям. Тобто знову - займіться СОБОЮ. Своєю освітою. Своєю вібраційною етичністю. Своєю еволюцією… Розумієте? Найголовніша наука Нового часу - це наука про самопізнання. І усі події даються, щоб ми це зрозуміли. Не воювали з інакомисленням, а створили здорову структуру сімʼї в собі. Без зради та болю. І не із компромісів, а на фундаменті здорової зрілої сінергії. #СферичнуСімюСвітла Чи розумієте ви суть мого допису? Чи знайшли свою цінність тут? Яку саме? Поділіться… напишіть 😘🙌👇 А я пішла готуватись до наступних кроків… 〰️〰️〰️〰️〰️〰️ 14.09 - старт тренерського курсу для Хілерів і Менторів 22.09 - старт марафону \" З Чистого Листа\" (приходьте в поле жити переродження 🙌) 22.09 - старт річної трансформаційної програми КРИЛА24/25 (встигаєте стати частиною групи, якщо мали намір. Допуском до тренерського курсу є завершена програма «КРИЛА», тому не питайте мене будь ласка, кого саме я навчаю хілерству і вмінню зцілювати долі та формувати щасливі квантові коридори - тільки випускниць КРИЛ усіх потоків 🤗) 27-29.09 - практичний семінар в Буші «М Е Т А Т Е З И С» для хранителів частот та інтегральних душ (деталі даємо по запиту!) Жовтень - ретрит в Ізках (Карпати) з унікальною програмою, яка буде ВПЕРШЕ в моїй практиці. Основою її являється Планетарний Родовий Сеанс Корекції стосунків між жіночим Началом та Богом… Будемо вести діалоги з Богинями різних пантеонів та культур, різних часів і світів… Трепетно готую себе вже...🥰 Жовтень - іще буде купа подій та сюрпризів… 🌿Запис на персональні консультації зараз веду на кінець жовтня і далі… (спішіть бронювати, бо в кінці року - буде пора гаряча і плотна). 🌿Участь в клубі практиків PiplClub - постійно доступна, і вартість щомісячного абонементу з 1.09 вже виросла. Наголошую. Доєднуючись в клуб у вересні - ви фіксуєте цю вартість щомісячну на цілий рік. А вона знову ростиме для новачків - це я вам гарантую. Бо маю намір давати амбасадорам клубу не лише найдоступніші ціни на свої консультації, послуги і навчальні бонуси (це до речі вже відбувається!), а й саме протягом року в клубі практикуватимуть хілерство мої учениці з тренерського курсу WayOffTheSoul і це неймовірний шанс прокачати свої скіли і вивести себе на якісно інший рівень проявлення в усіх сферах… 🤗 Я повернулась зараз із Грузії в Україну мега потужною. Пройшовши колосальні процеси масштабувань протягом літа… еволюційні зміни в собі, в сімʼї, в команді… …Щоб підсилити свій рід, наРід, щоб саджати нові ліси по осені, зустрічати нових діток (бо в команді моїй зараз купа вагітних жінок і це прекрасно 🤩), щоб творити далі одушевлені проекти, презентувати кліп та Баладу Берегині, що зцілює звʼязок з Живим Життям… Та безліч інших планів маю на порозі реалізації. 😘 Розказувати? Кому цікаво - дивіться запис прямого ефіру Обіймаю себе ніжно, усіх обіймаю,… і ціную все, що маю… 💞 https://youtu.be/fFEndu5I2N0 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','12 вересня 2024','6 хв читання','/images/posts/Ірина-Заверуха.png','[]',1,'2024-09-12T09:53:24','2024-09-12T09:53:24');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2080','%d0%b0-%d0%b4%d0%b5-%d1%82%d0%b8-%d0%b7%d0%b0%d1%80%d0%b0%d0%b7','А де ти зараз....?','Люди. Є різні. З різними рівнями свідомості. З різними задачами душі. З різних вимірів. З різних племен космічних… які живуть в різне «завтра»… і своє різне сьогоднішнє «я є». Люди… Ніби на поверхні однаково влаштовані. Але ні. Це ілюзія і всього лиш...','["Люди. Є різні. З різними рівнями свідомості. З різними задачами душі. З різних вимірів. З різних племен космічних… які живуть в різне «завтра»… і своє різне сьогоднішнє «я є». Люди… Ніби на поверхні однаково влаштовані. Але ні. Це ілюзія і всього лиш фантик… Ті, хто нічого не досягнув - будуть знецінювати досягнення інших. Ті, хто себе не реалізував - підуть відмовляти бажаючих реалізуватись від «втрати часу». Ті, хто так і не зміг, вмовлятимуть вас не пробувати, не йти, не шукати, не починати… Ті, хто розчарувався, скажуть, що довіри не існує. Ті, хто любов не створював, а отримав від творців безумовного потоку - висміюватимуть конфлікти і кризи молодих душ, які насправді мають право на свою школу і досвід. Ті, хто маніпулюють собою і оточенням, будуть видумувати маніпуляції і бачитимуть у всьому «підставу» , житимуть підозру. Ті, хто найбільше хочуть грошей і слави, висміюватимуть їх наявність у інших та виправдовуватимуть себе в своїх злиднях, шукаючи позитивне в бідності… Ілюзія бачить в усьому ілюзію… «Духовні каліки» з усіх трибун транслюють свою імітацію «свободи» аби лиш не зізнаватись самим собі в гордині. Істинне і сутнісне бачить в усьому божественну простоту душевної гармонії присутності. Але! Вас не обмануть лише РЕЗУЛЬТАТИ. Ваші. Та чиїсь. Тому все просто. Немає сенсу здаватися і знецінювати свій шлях та процеси, бо хтось НЕ ЗМІГ ні осягнути уроків життя, ні досягнути в ньому свободи від власних мнєній. Воля. Це риса люблячих. Де її брати? Працювати. Без напрацьованого характеру скільки завгодно можна починати спочатку, обіцяти, що завтра буде все «ок», що вже все «ок», що скоро проростуть усі «добрі вчинки», але це буде така ж сама маніпуляція, як і будь які інші. Чесність. Це риса люблячих. Де її брати? Працювати над тим, щоб транслювати правду всюди і завжди... В першу чергу в діалогах з собою. …Я безмежно вдячна кожній події в своїй долі, кожній зустрічі, кожній бесіді, кожній людині, кожній подорожі, кожному вчителю, кожному учню, кожній ініціації сакральній квантовій і досвіду з банального побутового життя, кожній мрії своїй, яка мотивувала до дії, кожній вдачі та невдачі, кожній своїй сміливій прояві, і кожній миті морозного страху, за яким ховалась сила і потенціал… Я безмежно вдячна цій планеті за гостинність та щедрість на варіанти і континіуми, за усі ролі, в які є можливість пограти богореалізованість… ЛЮДИ. Це так цікаво… вони всюди, і я всюди… іноді немає нікого, а я все одно є… і у мене МІСЦЕ є своє і немає ніякого… Я ВСЮДИ… і ніде… енергія життя живого в дорозі без «від» і «до»… Це неймовірно … …ціную шанс пройти свій путь втіленого Містика, Алхіміка та Хілера без зради факту, що людей єднає між собою не світло чи темрява, а райдуга спектрів душі… Люди. Не принижуйте себе оцінкою когось. Цінуйте все. Цінуйте кожну рисочку на своєму тілі, рахуйте морщинки та шрами як трофеї, бо вони роблять відлік досвіду… кожну свою секунду глибинного діалогу між небом і землею цінуйте… в собі… а не десь там… Милуючись ми створюємо милість… 🌀 …Я повертаюсь до когось. А з кимось стаюсь вперше. Та насправді мене іще немає і не існує для мільйонів, які так само прямо зараз мають шанс торкатися до тіла планети і відчувати подих Життя вічного за межами координат часу, але при цьому сильно зайняті втечею від себе як ума, чи тіла. Ісус пройшов континіум МА (переродження) і Вознесіння тільки завдяки наявності тіла. Будда через ум осягнув Бога і розірвав коло страждань в ілюзії… А де ти зараз, друже? В собі, вдома, в правді.., чи в пошуках підходящих варіантів, які присипляють дух і плодять творчу лінь? Обіймаю… торкаючись словом до серця… 💞 Вийшло? #РізнаЯ - грані цілого © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','6 вересня 2024','3 хв читання','/images/posts/Дизайн-без-назви-1.png','[]',1,'2024-09-06T10:18:58','2024-09-06T10:18:58');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2083','%d0%ba%d1%80%d0%b8%d0%bb%d0%b0%d1%82%d1%96-%d1%84%d1%80%d0%b0%d0%b7%d0%b8-%d0%bd','Крилаті фрази народжені в моментах діалогів в полі душі…','Веду ретрит у Грузії з темою активація кодів миротворчої Пари Нового Часу… Ловіть перли крилатих фраз, які народилися в моментах просторових квантових діалогів в полі душі… 🙏 ✨✨✨ Відійди від полотна, на якому малюєш своє життя, щоб побачити цілісну к...','["Веду ретрит у Грузії з темою активація кодів миротворчої Пари Нового Часу… Ловіть перли крилатих фраз, які народилися в моментах просторових квантових діалогів в полі душі… 🙏 ✨✨✨ Відійди від полотна, на якому малюєш своє життя, щоб побачити цілісну картину… Корисно «віддалятися» один від одного фізично - щоб наблизитись душею! Бо питання близькості - це не про географію… ✨✨✨ Коли приймеш з миром справедливість кармічну, - пізнаєш безмежно прекрасну любов космічну… ✨✨✨ Ви думаєте, що живете гру між собою і партнером? Ні… Ви разом з партнером спостерігаєте за грою живого життя… ось що таке пробудження в парі, в дусі, в Суті. Ви спостерігаєте за іграми ума і подіями на екрані епохи хаосу… ✨✨✨ Що резонує вам, друзі? 🙏😘 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','29 серпня 2024','3 хв читання','/images/posts/Дизайн-без-назви-3.png','[]',1,'2024-08-29T10:28:47','2024-08-29T10:28:47');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2087','%d1%8f%d0%ba-%d0%b1%d0%b5%d1%81%d1%96%d0%b4%d0%b8-%d0%b7-%d0%b0%d0%bd%d0%b3%d0%b','Як «Бесіди з Ангелами» допомагають знайти шлях до себе в журналі "Єдина"','Про першу книгу, вібраційну літературу, нову епоху та її цінності, сакральні знання і сучасні професії – інтерв''ю з метафізиком, провідником Нового Часу, цілителькою простору, духовною учителькою, наставницею для лідерів, інтуїтом України Іриною Заве...','["Про першу книгу, вібраційну літературу, нову епоху та її цінності, сакральні знання і сучасні професії – інтерв''ю з метафізиком, провідником Нового Часу, цілителькою простору, духовною учителькою, наставницею для лідерів, інтуїтом України Іриною Заверухою. Коли цілитель створює матеріальні об''єкти, вони стають предметами-цілителями й продовжують поширювати вібрації Майстра усім світом та зцілювати людей. Ірина Заверуха, цілителька і вчитель Живого Життя, святкувала появу першої своєї книги у день свого народження. Авторка поділилася з нами ексклюзивною інформацією про створення книжки, дала інструменти для її прочитання та розповіла про свої подальші плани. – Ірино, вітаємо з народженням книги-цілителя «Бесіди з Ангелами»! Розкажіть, будь ласка, чим зумовлена назва? Назва книги «Бесіди з Ангелами» – це не маркетинговий хід, не використання красивих слів, щоб заволодіти увагою аудиторії, а логічна назва, яка передає суть текстів. Моя книга – це діалоги з вищою ієрархією Творця. Тривалий час я вважала, що зі мною хтось говорить, розуміючи, що це не моя фантазія, оскільки бесіди одразу жилися – реальність миттєво ставала прекраснішою. Я осмислила, що відбувається контактування з чимось дуже тонким, вібраційним і чистим, оскільки мій стан і події в житті ставали дуже красивими. Зазвичай, зміни відбуваються в результаті певної дії: щось виконали – отримали результат. А я нічого не робила – сиділа в медитації або була в усвідомленому сні, потім прокидалася, записувала і просто жила в такій реальності. Довкола – ті самі декорації, а всередині – внутрішній рай. Дуже багато любові, щастя, енергії, спокою, добра і прийняття всього. Пізніше я зрозуміла, що насправді це бесіди не з чимось відокремленим, а з собою – тією частиною особистості, яку називаємо Вищим Я. Коли я це усвідомила, то почала записувати розмови не як діалоги, а як мудрі есе. Але у книзі все є бесідами з Ангелами. Читачам раджу поспостерігати за собою, що з ними відбувається, коли читають ці два види текстів. Вібраційно вони мають однакову енергетику та сенс, але якщо вам зараз більш відгукується читання діалогів, то варто усвідомити, що це ваш душевний і духовний аспект намагається поговорити з вами напряму. Завдяки книзі ви зможете багато чого зрозуміти про себе. Не тільки навчитися чогось, збагатити досвід чи розширити свідомість, але й зрозуміти, в якій фазі свого еволюційно-особистісного розвитку перебуваєте. Є ще одна негласна назва у цієї книги, яку дала їй команда – «Книга, яка саджає дерева». Адже у співпраці з платформою відновлення лісів «Деревород» народилася прекрасна соціальна місія: з кожної книги ми відраховуємо частину коштів на висадку дерев. І тепер кожна людина, яка придбала книгу, засіває ментальні насіння екосвідомості. Від книги-цілителя Душі до дерева-цілителя Землі. – Чому «Бесіди з Ангелами» – книга-цілитель? Книгу потрібно жити. Ось тому вона книга-цілитель. Під час читання розум входить в резонанс з глибинними сенсами, почуттями, цінностями, які плекає душа. Без розкритого аспекту душі ми не можемо знати свої цінності, осмислювати їх, натомість усе зводиться лише до говоріння про них. Для багатьох книга виступає активатором проживання справжньої реальності, тому що починає відбуватись резонанс розуму і цінностей через душу, і его таким чином бачить ціль. Зараз такий час: ми живемо щасливо тоді, коли реалізовуємо ціль, погоджену з цінностями. Одним з результатів доторку до книги-цілителя є активація своїх істинних цінностей. Людина усвідомлює, що хоче робити, куди рухатися – книга прояснює шлях до цілі. Ціль стає метою. Мета перетворюється на дорогу, і тоді залишається тільки діяти. – Вашу книгу «Бесіди з Ангелами» читачі називають книгою-підказкою, але водночас є інструкція-порада не читати книгу за один день, а орієнтуватися на поступове і вибіркове занурення. Чому так? Це і книжка-підказка , і книжка-дослідження, вона – пошук. Можна на цьому і закінчити відповідь. Одного разу я вже мала честь торкатися до живої свідомості у вигляді книги… Ця зустріч трапилася багато років тому в місті Амрітсар, Індія, в золотому священному храмі Гранд-гуру Сахіб, де раз у рік збираються люди з усього світу. У центрі храму лежить розгорнута книга, з якої читаються мантри. Книга сама вибирає читця... Вона ніби відчуває того, хто знає священні тексти. Саме тоді у мене з''явилося практичне розуміння, що книга – це не просто предмет. Вона може бути живою свідомістю. Тоді я зрозуміла істинні причини, чому мені так довго не вдавалось матеріалізувати знання, які через мене проходять. І коли вже пішов процес реалізації, то я вже знала, що це буде книга – жива свідомість, яка стане цілителькою. Свій досвід я мала не від розуму, тому і книгу неможливо читати лінійно. Точніше, це можливо, але то буде найпримітивніший спосіб дослідження. Читати сторінку за сторінкою під чай чи каву, чекати, що ті 140 сторінок будуть розлущені як горіх за кілька годин, бо ти маєш час і натхнення, – це зась! Книга – дорога, але вона не лінійна, а спіралеподібна. Вона може поговорити з людиною у будь-який спосіб. Книга-цілитель сама проводить людину і її свідомість крізь всі шари душі. Головне — захотіти чути й відчувати її в руках. Можна розгорнути її на будь-якій сторінці і тоді вона буде оракулом, який дасть підказку для моменту тут і зараз. Потрапивши у ваше поле, книга розв''язує найпріоритетнішу задачу, якою ви зараз живете. Вібраційні знання нашою системою сприймаються як їжа для тіла. Книга, яка оформлена як проявлене, живе, свідоме, має свій характер. І настрій у неї теж буває різним. Ви взаємодієте з нею, а вона з вами. І це дуже цікаво. Неймовірно цікаво. – Як вважаєте, на який сектор у книгарні претендує книга з таким глибоким наповненням? Чи є взагалі подібні книги? Сьогодні я легалізую сакральні знання. Якби була потреба назвати відділ, в якому має знаходитись така література, то я б назвала його «Вібраційною літературою». Але я не бачила таких секторів у книгарнях. Тож, мабуть, вона має бути у відділі «Самопізнання». За класифікаційною системою ми віднесли «Бесіди з Ангелами» до науково-популярних видань, бо інформація в ній належить до цього виду знань. А щодо книжок близьких за наповненням, то знаходячись багато років в стані транслятора й автора, я вже не читаю ніякої літератури, бо прагну досягнути чистоти провідності, потоку та уникнути викривлень, хибних висновків, домислювань раціонального ума. Моє завдання — легалізувати сакральні знання і проявити алхімію живого життя через тексти, ролики, дописи, відео і програми. З прочитаної раніше вібраційної літератури можу назвати такі: книга Гранд Гуру Сахіб, хоча це не література, а свідомість учителя, втілена через неї; «Эволюционная Азбука Жизни» мого вчителя Альберта Веніаміновича Ігнатенка та «Древняя тайна цветка жизни» Друнвало Мельхіседека. Впевнена, що нині існують ще якісь видання, але зараз я не читач. – Сьогодні активно говорять про нову епоху – Золотий Вік Творця. Ця епоха потребує нових альтернативних інструментів. І, певно, вашу книгу «Бесіди з Ангелами» можна рекомендувати як один із навігаторів для нових часів. Те, що альтернативне зараз, через років 10 буде нормою. Це зараз воно здається фантазією чи фантастикою. Наразі інформаційно-вібраційних інструментів, які будуть займати нішу освітніх, аби вдовольнити сучасні потреби людини, не створюється. Коли ми кажемо про те, що безліч професій зникне, то у цей список маємо внести не лише класичних психологів, а й освітян. Звичка роками аналізувати минулий досвід, щоби навчити молоде покоління чомусь потрібному для життя, уже не актуальна. Всі мають бути вібраціологами, освітяни – у першу чергу. Тож я радила б їм щось таке почитувати. На початках книга-цілитель та подібні сприйматимуться як інструмент самопізнання, саморозвитку, розширення спектрів свідомості. Але в цілому вібраційна література спонукатиме свідомість освітянина (чи будь-якого іншого фахівця) до створення альтернативних способів навчання (чи інших інструментів). Я це називаю доторком до Духу. Дух активує дух, а вібраційний вчитель активує вчителя, проявленого через професію. Вібраційна література, як і вібраційні предмети, одяг чи будинки — це містки між реальностями. Вони дають можливість поєднати світи. Ми рухаємося до створення нової цивілізації. Створення – це творення нового, а не воскресіння чи ренесанс. Новому поколінню дітей сенс вібраційної літератури пояснювати не буде потреби. Вони залюбки братимуться за такі книги, відмовляючись від застарілої літератури. Через вібраційну літературу люди здатні розширювати свідомість, аби через інтуїтивний канал знати все, а не лише те, що написано. Я взагалі не впевнена, що те, що я зараз розповідаю, зрозуміло всім. Але впевнена, що воно буде викликати внутрішній резонанс про важливість і безмежну цікавість теми. – Скажіть, будь ласка, для кого ця книга призначена? Кому ви радили б її обов’язково прочитати? Вона для тих, хто хоче знати все. Але якщо зосередитись на професіях, то скажу те, що ми зазначили в анотації: для психологів, коучів, цілителів, енергопрактиків, терапевтів та всіх, хто працює з людьми. А ще для холістичних, тілесних та арттерапевтів. Насправді вона для всіх, хто цікавиться темою саморозвитку, еволюції, дослідженням свідомості, а також для природжених філософів, дослідників, людей з критичним мисленням, науковців, які прагнуть бачити альтернативи й розширювати свої уявлення про реальність. Додам, що вібраційна література щонайперше резонує тим, хто або дуже далеко від своєї душі, або дуже близько. Якщо ви дуже-дуже далекі від своєї душі: втратили сенси, розчаровані у собі, людях, житті, у долі чи стосунках, якщо у вас дуже багато запитань і немає відповідей, або на кожну відповідь з''являється десять нових запитань, то ця книга для вас. А якщо ви дуже близькі з власною душею, але вам час йти далі, рухатися до наступного рівня в бік проявлення через свою великодушність до інших людей, то тут ви знайдете інструменти для підсилення себе, для сміливості, бо ви зрозумієте, що схожі на ту, хто це все понаписувала, і зможете пришвидшити чи поліпшити своє експертне проявлення, стати більш цінними для своїх пацієнтів/клієнтів. Для них «Бесіди з Ангелами», якщо ви порадите цю книгу, стануть ліками. – А чи буде продовження книги? Розмови з вищими світами продовжуються? Продовжується. Почавшись, цей діалог ніколи не закінчується. Наступна книга вже є, наразі відбувається процес її оформлення. А зараз хочу усім побажати приємного проживання контакту з книгою. Ви дійсно зможете усвідомлювати стосунки з нею. Я буду безмежно вдячна усім, хто захоче розповісти про них. Приходьте на наші сервіси, пабліки, сайти, сторінки. Розповідайте про ваші враження і досвід взаємодії. Це дуже-дуже цікаво. Окрім того, ваша розповідь, можливо, допоможе комусь іншому наважитися на власні стосунки. – Які ваші сподівання від цієї книги в контексті реакції читачів? Я вкладаю дуже багато енергії в створення всього, але дуже мало думаю про те, як воно далі буде. Книга була прожита в мій день народження, так спланувала команда. Але весь процес відбувся у повній творчій спонтанності. Чи уявляла я, як усе має статись? В деталях – ні. Але у мене була довіра, внутрішня сила, яка каже: «Все буде добре, так, як треба, і тим способом, який найпростіший, а при цьому найцінніший». Десь так і жилась презентація книги – дуже родинно, камерно і душевно. Я відчувала, що щось діється всередині тих, хто дивиться, хто знаходиться в полі, хто поряд. Відчувала, що щось буде. Ми кажемо «пробудження-пробудження». Я тепер знаю, як виглядає пробудження. Я знаю його усіма своїми сенсорами. Завдяки цій презентації, я знаю, як воно відбувається, що я відчуваю, коли знаходжуся поряд з тими, хто його проживає. На презентації щось прокидалось, будилось. В моїй пам''яті тепер є цей досвід. Нехай ще багато людей зможе торкнутися до цієї високої вібрації, багато читачів пізнаватимуть себе з нею, відчують пробудження свого Творця. Це і є відповідь на питання про очікування від мого читача після взаємодії з книжкою. Завдяки живій презентації, завдяки тому, що люди мали фізичне контактування, доторк до створення поля, я змогла зрозуміти ціль. Це пробудження. Просто так. Красиво. Книга-цілитель \"Бесіди з ангелами\" https://pipl.net.ua/knyha-besidy-z-anhelamy Стаття в \"Єдина\": https://edyna.media/uk/ee-istoriya/intervyu/38077-yak-besidi-z-angelami-dopomagayut-znayti-shlyah-do-sebe-rozmova-z-maystrom-transformatsii-svidomosti-irinoyu-zaveruhoyu © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','27 вересня 2024','9 хв читання','/images/posts/Бесіди-з-Ангелами.png','[]',1,'2024-09-27T12:27:06','2024-09-27T12:27:06');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2122','%d1%81%d0%b8%d0%bb%d1%8c%d0%bd%d0%be-%d0%bb%d1%8e%d0%b1%d0%b8%d1%82%d0%b8-%d1%96','СИЛЬНО ЛЮБИТИ! І це початок…','Допоки ми не почнемо СИЛОЮ вважати вміння любити і проявляти милосердя, вміння створювати здорові союзи, вести зрілу комунікацію, встановлювати мир і гармонію; вміння замовкати, а не волати лозунги; вміння не мовчати про цінності, а не терпіти брехню...','["Допоки ми не почнемо СИЛОЮ вважати вміння любити і проявляти милосердя, вміння створювати здорові союзи, вести зрілу комунікацію, встановлювати мир і гармонію; вміння замовкати, а не волати лозунги; вміння не мовчати про цінності, а не терпіти брехню; вміння будувати усвідомлені проекти і бізнес… вміння прикладати зусилля, а не насилля - в цьому світі нічого не зміниться… Допоки ми самі в собі не визнаємо СИЛОЮ власну душу і усю її природню делікатність; допоки ми не почнемо захоплюватись в чоловіках вмінням бути батьком, що вчить своїх дітей радості та турботі про планету, і не інфікує рамками власних «неврозів» та егоїстичних фантазій; допоки ми не знайдемо красу СИЛИ в простих речах та вчинках без біганини за гіпер надривними ілюзорними подвигами; допоки не повернемо на достойний рівень роль матері, що створює тілом своїм нових людей із єдиного роду Божого без поділу на табори і без релігійних маркувань та кліше… допоки жінка не усвідомить свою ключову сердечну задачу і не почне плодити духовну мудрість, проявляючи усю правду про живе життя діями, а не шукаючи якісь тимчасові «насолоди», що розбещують его… - в цьому світі нічого не зміниться. То що робити? СИЛЬНО ЛЮБИТИ! І це початок… Не виходить любити? То йти в світ з цим запитом! А не шукати то гроші, то стосунки, то славу… Йти в середину себе з запитом - «ЖИТТЯ, навчи мене любити себе і тебе!» І путь почнеться… головне тільки не сходити з нього і бачити за кожною подією саме урок любові, а не знущання, несправедливість чи падлянку… чи привід загордитися своєю вєлічю та досягненнями… Хто вже почав жити саме так? Виходить? Як успіхи? © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','11 жовтня 2024','3 хв читання','/images/posts/Любити-1.png','[]',1,'2024-10-11T12:25:08','2024-10-11T12:25:08');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2135','%d0%bd%d0%b5-%d0%bb%d1%96%d0%bd%d1%83%d0%b9%d1%82%d0%b5%d1%81%d1%8c-%d0%b4%d1%96','Не лінуйтесь ділитись зі світом','…Коли тобі в особисті пишуть воїни військові, що прочитали мій допис про «стосунки на відстані» і організували дружині подарунок, бо відчули, що вона таки хоче «бути як усі жінки - жінкою… навіть під час війни» - я плачу 🥹 від щастя… Бо я думала, що ...','["…Коли тобі в особисті пишуть воїни військові, що прочитали мій допис про «стосунки на відстані» і організували дружині подарунок, бо відчули, що вона таки хоче «бути як усі жінки - жінкою… навіть під час війни» - я плачу 🥹 від щастя… Бо я думала, що написала освітню трансформаційну статтю для жінок, а виявляється для ЛЮДЕЙ, яким не байдуже. Просто є речі дуже не очевидні при всій своїй очевидності… Дякую за ваші перепости. 🙌 І ось що хочу сказати. Лише вони - ПЕРЕПОСТИ і коментарі дають можливість дописам розлітатись далеко в ТОП. Мій акаунт, який (у фейсбук) колись нараховував десятки тисяч підписників - після хакерської атаки - знищений. Цей новий. Як і в інста… І робити якісь системні рекламні потуги на дану тему мені влом. Залишила самим людям право вирішувати кому ці дописи цінні і потрібні. То ж старенькі і новенькі підписники, знайте. Ця пані Ірина - не блогер, а Вчитель і Авторка. Але час інвестую в тексти досить обʼємний. І знаю, що зміна свідомості навіть однієї людини - це для мене ХОРОША МОТИВАЦІЯ для дії. А далі чарівна команда моя несе тексти в інші соцмережі. Щоб перетворити їх і там на публікації та мотивації. Така ось логістика і ситуація. Тому не лінуйтесь ділитись зі світом. 🤗🙌Можливо десь чиясь дружина теж чекає на «голу правду», але ніяк не наважиться зайти на територію внутрішнього діалогу. І хто зна… разом з вами таким чином допоможемо більшій кількості пар знайти ресурс для свідомих дій. Дякую вам за ваші! 🙏 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','11 листопада 2024','3 хв читання','/images/posts/Любити.png','[]',1,'2024-11-11T20:14:02','2024-11-11T20:14:02');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2140','11-11-%d1%84%d0%be%d0%ba%d1%83%d1%81-%d1%83%d0%b2%d0%b0%d0%b3%d0%b8-%d1%96-%d1%8','11.11 Фокус уваги і реакція','Чи знаєте ви, що 11 листопада, це міжнародний день енергозбереження? Чи знаєте ви, що 11 вібрація відповідає за повагу до ресурсів і свідоме їх використання, … в тому числі внутрішні ресурси людини? … То як ви сьогодні використовуєте свою психічну ен...','["Чи знаєте ви, що 11 листопада, це міжнародний день енергозбереження? Чи знаєте ви, що 11 вібрація відповідає за повагу до ресурсів і свідоме їх використання, … в тому числі внутрішні ресурси людини? … То як ви сьогодні використовуєте свою психічну енергію душі, розуміючи що це ресурс? 😘 … Друзі, до чого це я? Фокус уваги і РЕАКЦІЯ! Погодьтесь вона у нас різна, якщо ми точку опори змінюємо. Резюме. Завжди вигідно мати знання. Завжди. Без винятків! Усім мудрості і терпіння бажаю в стосунках з енергіями даного дня. 🙏 Щойно записала і віддала для середовища PiplClub голосовий вібраційний прогноз на тиждень… інвестую свій час у те, що гарантовано проростає якісними результатами. І вам того бажаю! 😘 Доєднуйтесь до виміру прогресивного людства, до виміру творців і майстрів живого життя. Сьогодні безліч егрегорів будуть ловити на ось цю пастку 11.11 увагу людей, ніби то надаючи якісь преферентні послуги. Насправді це вже просто крихти під столом, де вчора «їли Боги». Не жартую. Я серйозно. Ресурси поділено. Спектри влади теж. Розкладка сил зрозуміла. Тому будьте в Силі визнати свою системну роль і діяти із готовності являтись натовпом, який несе потік, а не пульсаром своєї долі. … #далібуде © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','11 листопада 2024','3 хв читання','/images/posts/photo_5354975885217879519_y-1.jpg','[]',1,'2024-11-11T16:26:00','2024-11-11T16:26:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2143','%d0%b1%d0%b0%d0%bb%d0%b0%d0%b4%d0%b0-%d0%b1%d0%b5%d1%80%d0%b5%d0%b3%d0%b8%d0%bd%','Балада Берегині…скоро 😜','…Моє життя це якась суцільна торжественна церемонія містики та таїнств…🥹 Не встигла я вранці прожити усі діалоги з Духом Княжої влади, і перетворити це на текст для вас (що тривало дві години, бо писати довше, ніж прожити мить стану…)… Як цей вечір п...','["…Моє життя це якась суцільна торжественна церемонія містики та таїнств…🥹 Не встигла я вранці прожити усі діалоги з Духом Княжої влади, і перетворити це на текст для вас (що тривало дві години, бо писати довше, ніж прожити мить стану…)… Як цей вечір просто розплющив мене до глибини іще більшого щастя… Ніколи не думала, що відчуття любові до життя настільки безкінечне та безрозмірне... Команда режисерська прислала мені на перегляд кліп-містерію, яку ми назнімали цим літом до Балади Берегині, а потім чекали оранжування музики, а потім ми затягнули з монтажем… 🥹😜😍🤩 І ось. Цей день теж СЬОГОДНІ. А це означає, що я сідаю планувати презентацію і вибухати Силою безмежної потужності на усю країну, та за її межі… 💥💥💥 замість отих усіх вибухів, які вже задовбали натякати нам, що в середині кожного точиться vійна між невидимими світами… По ходу моя дорога миротворця все ж таки виявилась сильнішою за усі страшилки часів… без перебільшень… я в цьому переконана. І усе у нас буде добре. Якщо ми не зупинятимемось! … 💫💫💫 Люди, обіймайте себе міцно за плечі руками кожного разу, коли коїться якась тривога чи сирени, коли стрілянина чи погрози вашій безпеці… Обіймайте себе і маніфестуйте у серці та свідомості - В МЕНІ ЖИВЕ І ПРОЦВІТАЄ МИР ТА ЛЮБОВ БОЖА! 💫💫💫 Готуйте свої душі, трейнутесь живими почуттями, бо на творчому вечорі ви будете вражені силою власного серця… до якого я проведу вас Голосом Балади Берегині… Хто чекає на подію і ні за що не пропустить? 😍🤗 #скоро #баладаберегині #силасерця #УкраїнаТиНео #духКарпат #IMARIA #душа #неожриця #мояперемога © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','10 листопада 2024','3 хв читання','/images/posts/466048546_549690381251559_8924184413224731640_n.jpg','[]',1,'2024-11-10T20:39:07','2024-11-10T20:39:07');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2146','%d0%b4%d0%be%d0%b7%d0%b2%d0%be%d0%bb%d1%8f%d1%82%d0%b8-%d1%81%d0%be%d0%b1%d1%96-','Дозволяти собі ірраціональні душевні вчинки','…Хтось вважає, що життя - це книга, в якій з кожним днем все менше і менше нових сторінок, а фарби марніють. Я вважаю, що все навпаки... Ми пишемо з чистого листа кожен свій досвід від моменту відкриття повік і до моменту їх закриття, тобто - щодня.....','["…Хтось вважає, що життя - це книга, в якій з кожним днем все менше і менше нових сторінок, а фарби марніють. Я вважаю, що все навпаки... Ми пишемо з чистого листа кожен свій досвід від моменту відкриття повік і до моменту їх закриття, тобто - щодня... Люди, які бояться смерті, часто не можуть заснути вночі, мають проблеми зі сном, таким чином проявляє себе цей несвідомий страх. Смерті. Люди, які бояться жити, часто важко прокидаються вранці, ніби відтягуючи момент зустрічі себе свідомого зі світом, який лякає своєю нестабільністю, неідеальністю та вимогами. Таким чином виявляє себе цей страх. Жити. Але життя - це книга без кінця та краю. Це великий шанс і дар! Воно мінливе і сміливе... Невже ми дійсно готові витрачати його на СТРАХ перед невідомим? В кожній другій людині постійно в боротьбі знаходяться дві потужні структури: душа і его. Ум - як раціональне мислення, сформоване на основі раніше отриманого виховання, звичок, вірувань і життєвого досвіду. Ум, а точніше ліва півкуля мозку - це набір наших обмежень і страхів. Все, що ми робимо раціонально - воно засноване на аналітиці попереднього досвіду. Так, наприклад, якщо перед нами стоїть вибір між двома коридорами, один з яких призводить до ями зі сміттям, а другий веде в невідомість, его завжди вибере яму зі сміттям. Так, там хреново і смердить, але там немає невідомості, а значить, потенційно немає загрози, адже ум вже встиг згадати, що в лайні він був, там хреново, там апатія, депресія, але там зберігається ілюзія контролю за існуванням... Це основна його функція - збереження самого себе. І его підсуне купу обгрунтувань цьому. Чому він не вибере невідомість? Та тому, що в його карті пам''яті немає подібних ситуацій і не важливо, що там може виявитися рай, - ризик дуже великий, ум повинен діяти напевно. Він перелопатить купу інформації, отриманої з попереднього досвіду, з розповідей батьків, з побаченого по ТВ, з прочитаного у книгах і почутого в транспорті...він буде шукати в собі докази, він приймає лише те, що розуміє, він цінує лише те, що матеріальне... У той же час душа завжди намагається уникнути повторення ситуацій і їх постійного зациклення, вона вимагає нового досвіду і зазвичай знає де і як його можна отримати, щоб вийти в баланс, але у більшості людей вона пригнічена раціоналізаторською діяльністю ума і мозок працює не покладаючи рук, успішно гасячи душевні прохання... Кар''єра, діти, квартира, статус, місце в суспільстві, машина і матеріальні блага, влада, стабільність... В кінці-то кінців, а що скажуть люди, адже нам так важливо їхня думка і схвалення... Це все ум, а ось душі це не потрібно, душа вимагає балансу і нейтральності і чим більше раціоналізує его, тим складніше душі і тісніше в тілі, вона намагається чинити опір і ось тут можливо 2 варіанти розвитку подій. У першому варіанті душа перемагає і людина долає опір его, залишаючи звичну зону комфорту, виривається з зациклення і починає бачити трохи далі, ніж могла йому дозволити та глибока колія шаблонів, в якій він знаходився. У другому випадку перемагає его і системі нічого не лишається, окрім як створити в тілі психосоматичні хвороби, які змусять заставити задавати питання та шукати відповіді. Душа хоче на море і до зірок, але его відкидає імпульс - іпотека, контракти, борги... Як підсумок - депресія і гормональні порушення. Ми намагаємося боротися з цими хворобами фармакологією, масажем, фітнесом, але вони прогресують, адже їх причина лежить за межами фізіології та анатомії, це метаанатомія і метафізіологія, а ці науки не підвладні фармакологам, вони ірраціональні за своєю суттю рівно так само, як і душа людини і не можуть бути вивчені за допомогою логіки і лабораторних випробувань. І ось тут якраз на допомогу може прийти звичка ДОЗВОЛЯТИ СОБІ ІРРАЦІОНАЛЬНІ душевні ВЧИНКИ! Дозволяєте? 😘 ✨✨✨ Сьогодні. Комусь доведеться розширити свідомість, щоб зрозуміти мою писанину…👇 Сьогодні. Знову був діалог з колективним Духом Княжої влади. «Знову», бо я вже мала такий контакт в 2020 році, коли по стопах Княгині Ольги возила групу жінок в тур-анонімку. Цікавий збіг по датах. Сьогодні 10.11.2024. Потрудилась і знайшла свій запис того періоду: «Тайный ретрит «Единство Неба и Земли» где мы сбились с пути, или по стопам Княгини Ольги... Провела я его в лунное затмение года, стартанув 10 января 2020 в неизвестность без конкретного маршрута... …великая Женщина и ее судьба … Она послушала мнение ума извне, и упустила голос сердца... Я иду искать сбившуюся в пути, которая исказила информацию и создала ложную тропу развития целой нации... Итог моего труда - родится ребёнок, душа которого не смогла тогда стать дочерью княгини Ольги! Ибо там она потеряла ребёнка (... - и это была ее настоящая причина гнева и ярости (а не месть за смерть мужа) с которой она уничтожила древлян, бессмертного князя Мала потомка древних Друидов, отца Малуши и деда Владимира Крестителя…» 🌀🌀🌀 Пройшли віки… 🌱🌱🌱 Проросли нові реалії… Сьогодні. 10.11.2024 я спілкувалась з колективним духом свідомості княжої влади Київської, бо маю і сюди доступи як Берегиня єдиного Роду людського богореалізованого. Дух повернув мою увагу на саму себе-людину і сказав: «Ви шукаєте Силу та відповіді у нас, але вона у вас, вона в середині ВАС!» … Жодного разу я не робила прогнозів про завершення війни, хоча тисячі разів питали. Не існувало чіткого континіуму. Спостерігала при цьому як хвацько маніпулюють різні «пророки» свідомістю натовпу, пропонуючи наративи, що співпадають з бажаними сценаріями. Це звичайно сумно. Але факт. Люди ведуться на казкові сценарії, бо хочеться вивільнити той самий ум від стану СТРАХУ ПЕРЕД НЕВІДОМИМ. … Сьогодні я вперше побачила завершення війни. Вперше. І не можу це назвати «перемогою України», язик не повернеться. Бо є нюанси. Бо те, що являється завершенням даної фази зовсім не являється ні миром, ні перемогою… Я стараюсь донести до людей спрощеними словами глобальні теми. Але деякі з них не можливо спростити, щоб зрозуміти суть. Вони геополітичні, космоеніологічні… Війна з планети може піти раз і назавжди тільки УСЯ разом з ментальними відбитками гордині та колективного гніву, який ми вже настворювали і створюємо далі, війна не закінчиться шматками на окремих територіях. Бо ми єдиний рід людей. І постійно душі просто міняються місцями в даному манежі цирковому, декорації трішки інші, а суть та сама. Творчу, потенційну енергію душі жре система астральних сутностей, створених теж самими людьми. От і все. Замкнуте коло. Дико. Але факт. Страждання як джерело енергії. Чи є цьому якийсь край, рішення? Чи завершення війни зараз - це перемога? Ні. Мабуть доречно назвати - пауза. Люди, я зараз кажу про те, що в 2025 році буде кінець війни в тій фазі, яка усіх втомила сильно. Кажу саме так як кажу. І не перекручуйте на свій лад. Марафонська гра в довгу триватиме далі. Ніхто не сходить з дистанції. Але нас чекає безмежна кількість потрясінь змінами, еволюційно/революційними… і енергія на це є всередині нас. Потрібно тільки зʼєднатися з СИЛОЮ, а не боятися її, не відвертатися, не втікати від задачі та власного голосу душі… Він не замовкне! Якщо вже достукався до ума… Сьогодні. Я чітко зрозуміла, що моє бажання не вивозити жінок з України, щоб побачили світ, а завозити жінок світу, щоб побачили Україну … в собі… і довкола себе - це чітка місія. Але без обмежень і догм. Саме так я живу вже 10 років. І в своєму 2025 зайду в потужний період глобальних проектів, повʼязаних з цим. Світ почує про НеоБерегиню, народжену Україною, як про колективну Силу. А для цього потрібно і «вийти у світ». Великі часи це не десь там, колись, бо нас історично боялись і поважали за вміння страждати і вмирати. Великі часи це про зараз в тут, де нас поважають за вміння любити, творити, обʼєднувати і щасливіти. Ми вирівнюємо ваги кармічної справедливості, видихаючи розкіш та красу, мудрість та духовність, сміливість і милосердя, вірність та родинні цінності. Нарешті дух даного народу готовий стати на поріг прийняття відповідальності за цю священну землю. А хто не готовий - ще є час визнати свою «правду» і опинитись будь-де, куди тягне внутрішній механізм. Праці буде багато. Усім вистачить. Тому готуйтесь зайняти істинні системні ролі і не бубніти, а діяти. Хочете на когось чи щось сердитися? - йдіть і зцілюйте себе ВДЯЧНІСТЮ. Хочете когось чи щось порівнювати, критикувати? - йдіть і лікуйте свою гординю. Хочете комусь предʼявляти вину? Велкам. Чекаю на консультаціях і навчанні - і не має значення з якими ви там дипломами чи регаліями люди. Бо тут винних не існує! В версії гри, де є табори - існує тільки один спосіб вийти із страждань. Це Сила Любити серцем. Безсилля кожного створює колективний потік безсилля. Щедрість любові кожного створює колективний потік Щедрої Любові. Де кінець усім подіям? Не існує кінця. Події змінювали і змінюватимуть одна одну. Напругу і тиск відчуває наш ум. Тому вчіться практикою підвищувати свою нейропластичність мозку і зустрінемось в 5d реальності… 🙌😘 А більше сакральних знань та практичних інструментів для дії знайдете в моїй книзі-цілителі \"Бесіди з Ангелами\" 🙏 Читали? 😉 P.S. І знаєте, здається я таки напишу колись цю книгу «Війна в Україні очима Берегині»…бо проживати і хакерські атаки, і знищення усіх акаунтів, і повну перезагрузку команд проектів, і початок життя спочатку, і міграцію матері з дітьми, і супровід в народжені немовляти у лісі Київщини під обстрілами…, і масштабування свідомості та проектів, не залежно ні від чого, залишаючись в країні, і служіння роду через зцілення людей та пошуки зниклих безвісті, і проведення 17 ретритів трансформаційних за 1,5 роки війни, і вихід унікальної книги та створення фільму-кліпу на Баладу Берегині, і народження тисяч дітей, що пройшли ініціацію серцем, і смерті сотень тисяч загиблих, яких проводжали зі спорідненими світочами, і не зважаючи ні на що - творчість, любов, розвиток, віра, практика, сатсанги, щоденна йога, медитація, краса життя і віра. Віра. ВІРА… Як гадаєте, вона могла б бути комусь потрібною, чи що маємо - то все суто наше з вами і більш нікому не цікаве воно? #АватарМа #IMaRia #ЗаверухаІрина #ЖивеЖиття #Послання #СловаКрила #путь #ВчительВчителів #хілер © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','10 листопада 2024','8 хв читання','/images/posts/zaverukha.com_.png','[]',1,'2024-11-10T15:15:00','2024-11-10T15:15:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2149','%d0%bf%d0%be%d1%81%d0%bb%d0%b0%d0%bd%d0%bd%d1%8f-imaria','Послання IMARIA','Ми не одержимі, не загублені і не безнадійні… Планета Земля возноситься в дусі. Процес триває через пробуджені душі, які з квантовою швидкістю збільшують кількість приСутніх на планеті, тобто проявлених із СУТІ… справжніх, автентичних, ніким не клоно...','["Ми не одержимі, не загублені і не безнадійні… Планета Земля возноситься в дусі. Процес триває через пробуджені душі, які з квантовою швидкістю збільшують кількість приСутніх на планеті, тобто проявлених із СУТІ… справжніх, автентичних, ніким не клонованих, унікальних і вільних від «ярликів». Планета не залишиться такою ж, як ми її зараз знаємо. Рівно через рік світ буде вже іншим. Нові коди ПАТРІАРХА увійдуть в фазу активності і те, що «чекало свого часу», стане видимим… Це слова не про підготовку до переходу. Це слова про фінішні завершення. Дана цивілізація людей архівується. В 2025 році на планеті залишаться ті, хто вібрує в резонансі з частотами галактичної гармонії. Пробудженим не страшно. Пробуджені до змін готові, бо живе життя - це і є постійні зміни… Для деяких перехід виглядає, як знущання, несправедливість і хаос. Але це не так. Навпаки ми виходимо із безкінечних страждань, хаосу і мороку ілюзій. Ви думаєте, що планета «сумуватиме» за втраченими людьми? Ні. Там, де зникає недолуге господарювання людського его - зʼявляється відразу влада космічної ПРИРОДИ. Як виглядають села та двори, з яких виїхали давно жителі? Вони заростають бурʼянами, насіюються зарослі, виростають дерева, приходить новий господар - ЧАС. І робить безпощадно прекрасним усе. Але людина так не вважає. Чому? Бо людина обмежена в часі. І уявлення про прекрасне по цій причині відрізняється. Та душа - вічна. Тому все, що пронизане душевними спектрами, завжди милується і бачить естетику такої ж вічної гармонії… Божий Рід людський поважає не лише спільний дім - Землю, а й інших істот, сусідів по галактиці, прекрасно обмінюючись спектрами вібрацій ось уже понад 4 млрд років… І це окриляє діяти. Тому до праці, шановне людство. Будьте вибірковими до інформації, яку споживаєте, розвивайте здатність критично мислити і свою надінтуіцію, щоби просто залишатись реальними. Заберіть відповідальність за своє тіло у всіх егрегорів маніпуляцій. Турбуйтесь про чистоту мислення, чистоту свідомості, чистоту матерії… І памʼятайте, ніколи матеріальне не було важливим, і ніколи не буде домінантно важливим. Усі винаходи та досягнення людина створювала для розширення спектрів відчуттів, для масштабування своїх можливостей породжувати всесвіти серед космічного вакууму. Тому мета життя - це не матеріальний успіх, а розширення свідомості до рівня Творця Живого Життя. І без відповідальності за духовне та душевне начало - це не можливо… А на коротких відрізках маршруту, тобто в межах нашого року чи століття - ми маємо колективну свідомість, яка формує нам ілюзорні гарантії стабільності. Ми це запхали в терміни - культура, мораль, державність, цивілізаційні кодекси, і тішимось ніби то такими ж ілюзорними результатами. Гарантій зовнішніх немає. Ніяких. І не буде. Верифікація даних завершена. Zaverukha.com - твій навігатор долі в океані часу. #way #ЗолотийВікТворця #СловаКрила #ГолосДуші #АватарМА © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','9 листопада 2024','3 хв читання','/images/posts/zaverukha.com-1.png','[]',1,'2024-11-09T21:00:52','2024-11-09T21:00:52');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2152','%d0%bf%d1%80%d0%be-%d1%81%d1%82%d0%be%d1%81%d1%83%d0%bd%d0%ba%d0%b8','Про стосунки...','Два дні тому на прямому ефірі я підняла тему стосунків українців. Розповіла про свою консультацію з однією жінкою… А таких консультацій схожих я провела сотні за останні 2 роки. Суть мого проявлення наступна: «Якщо ви, пані українки, живете в іншій к...','["Два дні тому на прямому ефірі я підняла тему стосунків українців. Розповіла про свою консультацію з однією жінкою… А таких консультацій схожих я провела сотні за останні 2 роки. Суть мого проявлення наступна: «Якщо ви, пані українки, живете в іншій країні, а ваш партнер в Україні, яку ви називаєте «вдома», то питання до вас - нахіба?» … завчасно прошу усіх читати без оцінок/захисних опозицій/ критики! Спробуйте ПОБАЧИТИ ситуацію крізь широку рамку реальності, не накладаючи особисті свої обставини на мій допис… 👇👇👇 З точки зору енерго-інформаціології - ви поїхали РОЗСТАВАТИСЬ, - казала я своїй клієнтці - і розлучатись, а не тому що vійна, бо діти, тут хати нема, я не можу терпіти коли стріляють… Все воно так. АЛЕ! Якщо є сімʼя, родина, і ПАРА. Дійсно пара. І ви до сих пір вважаєте свою розлуку - «обставинами», а не вашим планом дій. То питання залишається відкритим. Він десь там. Ви десь там. У вас формуються абсолютно різні цінності. І суть в тому, що ви давним давно скоріш за все РІЗНІ. А можливо взагалі не були ніколи «ми». І відвертатися від теми не вийде. Війна виступає в долі людей ЗАВЖДИ потужним каталізатором до змін і очищення від усього ілюзорного, до проявлення кармічної справедливості. За останній рік до мене прибігали в шоці, в сльозах і розпачі сотні жінок, розповідаючи про «зраду чоловіка», який лишився в Україні. Але чесний діалог приводив в усіх цих бесідах до зізнання, що в стосунках були кризи і конфлікти і до розлуки; що вона насправді давно мріяла мати «фінансову свободу», щоб від нього піти, бо не бачить спільного майбутнього… і т.д. Далі йдуть зізнання в маніпуляціях дітьми, сексом, емоціями, ситуаціями… Золоті, хіба це не факти? Кому знайомо? Стосунки - справа серйозна. Для зрілих і абсолютно сформованих особистостей розлуки стають причиною для міцності союзу, для цінування часу, проведеного разом. Якщо люди не юзають партнера із егоїстичних потреб. Але для не зрілих розлуки - це катастрофа. Якщо ваша ілюзорна жіночка виходила заміж за таку ж ілюзорну мужність, тобто травмоване его як шерочка і машерочка знайшли один одного і відчули хімію, яку сплутали з любовʼю, - то потрясіння війною все оголило до СУТІ. Бо незрілі люди дійсно знаходяться в дефіцитних програмах співзалежності: він від жіночої енергії (і часто сугубо інстинктів самки чи мамки, яка няньчить в побуті, бо не пройшов сепарації від власної матері), а вона від чоловічої енергії (інстинктів виживання, фінансів та ілюзії безпеки; бо має очікування від батька). Сумно. Але стереотипи суспільства ось ці рагульні союзи іще й культивують в ранг - ІДЕАЛЬНИХ…😔 Генетично ми з вами як нація дуже РОДИННІ! То пора бути обізнаними хоча б в цьому. Розуміти ієрархію роду, поважати закони, усвідомлювати силу спільноти і створювати чистоту істинних стосунків… Це потребує зусиль. Але що тепер в тут і зараз? Коли ми «побачили», що те хибне чоловіче начало ні грама не може захистити нікого, а її хибне жіноче начало зовсім не має бажання няньчитись зі слабким духом…; коли побачили, що її героїзм «я королева бєнзоколонки» без чоловіка поряд нікого не впєчєтляє і доводиться робити реальні дії і ходити на реальну роботу, створювати реальні гроші, вирощувати в собі самоцінність,…бо ж і усі соціальні пособія від «співдружніх» держав не вічні, друзі. Вони дають тимчасові обійми і можливість заземлитися. А далі заземленні істоти мають СТВОРЮВАТИ ресурси своєю зрілою реалізацією. А не позиціонуватись жертвами обставин. (Я не намагаюсь усіх запхати під один образ! Мільйони українців змінили країну і почали спочатку, створили проекти, знайшли себе в нових ролях і їм ці мої тексти хіба що будуть підтвердженням того, що з ними все ок). Але я не стану називати ситуацію зі взаємною брехнею - ОК! Бо це не ок. Свідомість має еволюціонувати. І колективна теж. Тому питаю: Він тебе любив «грошима», чи як саме? Вона тебе любила «борщами», чи «трусами»? Ви один одного «любили» ілюзією правильного статусу і ілюзіями гарантій фізичної чи емоційної безпеки? Хтось скаже, що «і усім цим теж, але…» Не має ніякого АЛЕ! В умовах потрясінь як ніколи починає бути видно, де ми попутались і забрехались самі собі… 😖 Бо хибне на те і хибне, щоб лопнути в часах потрясінь, як мильна булька. Що і відбувається. І відбуватиметься й далі. Жінки, які в розлуці усвідомили, що пора РОЗСТАТИСЬ зі своїми ілюзіями, зі своїм хибним его, а не партнером, - змогли вибудувати СЕБЕ, і їхня ситуація змінилась - вона або повернулись іншими до дому і живуть далі; або ж партнери підтягнулись до них за кордон (я тут зараз спосіб реалізації цього явища обговорювати не хочу! Бо хто кому взятки давав, чи офіційно через якісь преференції має виїзний статус… це не до теми даного діалогу); або ж ці пари пішли різними дорогами і розлучились, залишившись друзями без претензій. Колосальна кількість розлучень нині. Бо давно пора отримувати професійну сімейну і людську освіту фундаментальну про життя, перш ніж заходити в стосунки для еволюції, а не виживання. 👌 Згідні? Стосунки не повинні стояти в розділі «інстинкт виживання», ми маємо перестати мірятися мірилами стандартів і традицій в цій темі і закривати очі на хаос. Ця країна нині проходить наскрізь через пекло карми переродження. Ми усі маємо викорінити гени жертви із своєї свідомості. І бути чесними з собою та партнерами! Тому, любі жінки, закликаю вас до дій. Якщо зараз ВІН НЕ МОЖЕ до вас приїхати, - то ВИ ДО НЬОГО МОЖЕТЕ! І чесність спонукає до дій. А якщо ви не ХОЧЕТЕ, то відпускайте людину, щоб потім не корчити із себе зраджених, і не шукати в собі того червʼяка власної зради себе в собі, (бо ви його точно гарантовано знайдете). Або ж робіть усе, щоб ваш союз був союзом і парою, а не тєрпілами, які разом дітей народили і мучаться хибним героїзмом. Я теж була на відстані від свого чоловіка. В межах однієї країни. Він мав зобовʼязання перед бізнесом, і знаходився в столиці, а я на Закарпатті з дітьми. При цьому ми бачились родиною, єднаючись зустрічами. Тому не пишіть мені, що я не тямлю в темі. Зараз мій чоловік військовий. Тема ще глибше і яскравіше мені зрозуміла і як свідомість Вчителя Алхімії Живого життя я безліч разів задавала собі питання - ДЛЯ ЧОГО? І як саме я можу бути максимально ефективною людям, маючи даний досвід і пробуджену свідомість. Як бачите не сиджу на островах, не вєщаю про духовний розвиток із печер, а живу в Україні тілом і проходжу однакові зустрічі з обставинами, як усі жителі столиці. Якщо ми ставимо собі чіткі істинні питання, то будуть і чіткі відповіді! Головне не відвертатися від реальності. Тоді її можна формувати. Я вже була в цьому житті дружиною аспіранта і Майстра єдиноборств; дружиною серійного підприємця, дружиною письменника і громадського діяча, дружиною дослідника та мандрівника, … і зараз я дружина військового в Україні. І мова про одну пару людей, що разом еволюціонують ось уже 21 рік, рухаючись крізь життя свідомо. … А тепер про тих, у кого ситуація така - вона будь де, а він на фронті. Відповідаю. Ми усі на фронті! В країні війна. Кожен на своєму фронті. Ваш чоловік НА СЛУЖБІ. Він реалізовує свій обовʼязок. Гідно. І чи є у нього там якісь стосунки, чи не має, тільки Бог знає, але впевнена, що такий тип чоловіків точно не може дати вам ні серіальної уваги, щоб ви тішились, ні подарунків, ні компліментів томних, ні якихось обіцянок про відпустки разом, … то ви або достойні його волі і вмієте усе це сама собі створити, і тоді ви ідеальна пара, або ж відчепіться від нього і Бога з претензіями про «моє жіноче життя проходить мімо, я хочу рамантіки, яка в ср…ку війна»… Жінка - це вам не сциклива дитинка. Завжди знайде, чим зайнятися і що створювати цінне довкола себе. Правда? Короче кажучи - є над чим замислитись! … Я маю досвід. Мій тато виїхав в іншу країну дуже давно, 24 роки тому, і через майже два роки його праці не в Україні, - постало питання в стосунках з мамою, або відпускати один одного, або вона їде до нього. Бо заходити на територію обману і зради, на територію жертви обставин ніхто не хотів… Батьки зʼєдналися. І це було найкраще, що вони могли зробити для нас з братом - дітей! Мені було 19 років, а брату 17, коли обоє наших батьків жили за кордоном а ми з ним в Україні. В нас не було ні одного дідуся, жодної бабусі на той час. Усі предки цього рівня вже померли. Але ми справились. І ми пишаємось нашими батьками. Цей шматок тексту я написала для тих, хто прикривається зараз ширмою ілюзії того, що ви робите «краще для дітей». Не обманюйте себе! Ви робите лише те, що хочете ВИ. Насмільтесь бути чесними. Ваші жертви нікому не потрібні. Якщо ви пішли за своєю хибною роллю мамки, і це нібито в вашій викривленій реальності стає причиною проблем у парі, то будь ласка подивіться чесно на ситуацію. Ви обовʼязково будете КОГОСЬ винними робити в цьому. Чи сусіда, що приніс війну, чи дітей, чи… і це вже гарантовані підсвідомі неврози. Я завжди буду за сімейні цінності, за те, щоб люди робили дії, що зміцнюють союзи. Але! На брехні і особистих жертвах ви не побудуєте щастя. Ніхто від цього не виграє. І ніякі моральні ілюзії не зможуть вас зцілити від внутрішньої пустоти. Часи змінялись. Маємо змінюватись і ми. Бути щасливими мають право усі! Тому йдіть в терапію, вивільняйте себе від пут «обставин». Розірвіть джгути своїх страхів, травм і посттравм… Тому перш ніж ображатися на мене за слова про те, що потрібно замислюватися і рефлексувати усі наші з вами рішення та ситуації… - спробуйте просто запитати у себе: «Ця людина заслуговує на щастя?» «А я заслуговую на щастя?» «Разом ми щасливі були, чи коли не разом то в мені щастя стало більше?» Шукайте не фінансову свободу, а чисту гавань свідомості в собі, свою силу людяності шукайте, свою Суть і душу шукайте, свою істинну Жіночність вирощуйте… тоді й усе інше знайдете. От побачите! Бо лише якісні стосунки з собою дають надію на успіх в стосунках з партнерами в будь яких зовнішніх обставинах життя. P.S. А в цілому ми зараз усі там, де маємо бути. Залишилось лише дізнатися «для чого?!» Приходьте розбиратися. Буду рада бачити на консультаціях і в середовищі навчальних програм… бо насправді тема стосунків зовсім не лінійна, і є купа кармічних нюансів важливих про те, як працювати з СОБОЮ, аби мати щастя в союзі. #СловаКрила #ЖивеЖиття #Вчитель #цілитель #крила #pipl #piplclub #ДуховнийІнтелект © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','7 листопада 2024','9 хв читання','/images/posts/zaverukha.com-3.png','[]',1,'2024-11-07T21:09:33','2024-11-07T21:09:33');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2163','%d1%83-%d0%b4%d1%83%d1%88%d1%96-%d1%80%d0%b5%d1%81%d1%83%d1%80%d1%81%d0%b8-%d0%b','У Душі ресурси безкінечні...','…Ну що, Душі втілені як вам живеться у великих містах? Адаптувались?🪬😎 Усі вже відчули, що настає час, в якому не місто і система своїми «палками» керуватиме ресурсами, маніпулюючи ілюзією їхньої вичерпаності, а живий потенціал алхімії пробуджених Ав...','["…Ну що, Душі втілені як вам живеться у великих містах? Адаптувались?🪬😎 Усі вже відчули, що настає час, в якому не місто і система своїми «палками» керуватиме ресурсами, маніпулюючи ілюзією їхньої вичерпаності, а живий потенціал алхімії пробуджених Аватарів? У Душі ресурси безкінечні, аби лишень джерело сили проявилось і було в резонансі з планетарним тілом. В даний резонанс ми входимо через земний рід… Андестен?😘 Проживайте єднання зі справжнім родОМ та автентичними племенами, претендуйте не просто на святкування гідності та свободи, а на ПРОЖИВАННЯ цього практичним чином! 🌎🕊️🌿💚 … А я знову вестиму родовий сеанс зцілення фантомний, дистанційний, для усіх… - з місця сили Землі Буші, де зовсім не «світлі» енергії, як багато хто думає і розказує…😎 В Буші є ворота воронки, через яку я навпаки можу витягувати душі із астральних коридорів ілюзій. Особливо якщо питання стосуються батьківсько/дитячих тем (абортовані голограми, викидні, перинатальні травми, співзалежні історії, тощо); особливо якщо це люди з вагомим характером, потенційні колеги і реалізовані майстри, особливо ті, від дій яких залежить доля великої кількості людей чи територій… Розумієте? Місця Сили на Землі не претендують на схожість. Є портали з потоками дуже різними. В Бушу я вожу себе тілом для служіння єдиному роду людському, вивільняючи спектри душ з неволі астральних контрактів і коридорів ілюзій. Я маю цю силу. І роблю усе, щоб передати свій дар далі. Окриляючи Майстрів, створюючи імперію цілителів світу… В Буші з людей «виходять» магічні контракти, насіяні в різних втіленнях. А деякі адепти до Буші тягнуться з метою підсилення своїх егоїстичних можливостей, в пошуках енергії дуже примітивного збагачення. Але Земля жива та мудра і ключі доступу є лише дійсно у тих, хто володіє знаннями за межами слів/дум/мислеформ/логік/… у Хранителів Частот… Тому так, Буша - це Душа!!! Яка саме? Невільниця. Багатостраждальна. Ось яка. Кармічно обтяжена. А іще жертовна і облита кровʼю. При цьому дуже творча та глибока, талановита і не оцінена достойно. І так історично й події проявлялись відповідним чином. Постійно там були якісь «жертви», битви і «подвиги». Розумієте про що я пишу? Одні тут виходять із пут ілюзій (якщо є тяма як це робити!), а інші - входять. В Буші багато «залежних». Від алкоголю, від ліні і гордині, від страхів, від сексу, від грошей, від… всякого… Концентровано. І це не просто так. Усе не просто так тобі випадковість. Розуміюсь на цих питаннях і не мовчу, а розповідаю. Як бачите. На семінари вожу групи теж не для тусовки. А для родової праці, що очищає русло колективної душі. Що іще? ✨✨✨ … щаслива. 🥰 Від Нічого. Бо є і причина тріумфувати. Усе вдається… Вчора завершила начитку першого Модуля в своїй Майстерні, і рухаючи системний маховик, йду далі, бо попереду в #IMARIAACADEMIA - МОДУЛЬ 2, присвячений вібраційному хілінгу. А за спиною 35 годин лекційної теорії і кілотонни голосових підкастів про аналітично-нумерологічну діагностику долі #Путьдуші (#WayOffTheSoul), що є логічним продовженням для усіх кармологів, діагностів матриці долі, бо дозволяє супроводжувати людей з рівнем свідомості 4d і формувати спільноти 5d реальності… 🤗 Ієрархічні сакральні знання для часів турбулентних повернулись на Землю знову! Бути провідником потоку МА, включати серця, зцілювати тіла, допомагати зірковим душам адаптуватися до грубих енергій, обʼєднувати в спільноти Сильних, формуючи справжні Сузірʼя чистої свідомості… - це цікаво та в той же час відповідально… 🙏 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','21 листопада 2024','3 хв читання','/images/posts/zaverukha.com_-1.png','[]',1,'2024-11-21T16:18:15','2024-11-21T16:18:15');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2166','%d1%89%d0%be-%d1%82%d0%be%d0%b1%d1%96-%d0%bf%d0%be%d1%82%d1%80%d1%96%d0%b1%d0%bd','Що тобі потрібно,щоб цвісти?','…Квітам і деревам потрібна вода та сонце, щоб цвісти, а тобі ЩО? 😘 Запитай у себе. Запиши. Реалізовуй! Те, що вчора було мрією, сьогодні має стати дією, і тоді завтра проявиться нова реальність як результат… Люди, не забувайте святкувати життя, не до...','["…Квітам і деревам потрібна вода та сонце, щоб цвісти, а тобі ЩО? 😘 Запитай у себе. Запиши. Реалізовуй! Те, що вчора було мрією, сьогодні має стати дією, і тоді завтра проявиться нова реальність як результат… Люди, не забувайте святкувати життя, не дозволяйте ніяким ментальним пасткам відбирати у себе силу живої душі… єднаючись з потоком родової автентичної волі, ми проводимо через себе нові спектри щасливої долі! Не смійтесь. Це не жарт. Державні провладні системи на Землі виникли як альтернатива Живого потоку Роду, бо від нього люди відʼєднали себе самі; Там, де не вистачає любові - проростає конфлікт і війна. То виходить, що війна - це кармічна «мачуха», проекція дисципліни і вимогливості, яка виховує швидко і навчає зусиль. Там, де жінка «спить» свідомістю, або всього лиш збуджена і не ПРОБУДЖЕНА - плодиться егоїзм і махровий героїзм. Чоловіча низька відповідальність і жіноча низька самооцінка рука об руку крокують віками по планеті… То що робити? З СЕБЕ почати. Повернутись до роду обличчям. Пройти крізь внутрішню темряву. Не злякатись її і втекти, - а пройти! Вибрати життя… честь… вдячність… вірність… гідність… щедрість… чесність… сміливість творити… 🌿🌿🌿🌿🌿 💡курс #самсобіцілитель 💡курс #СферичнаСімʼя 💡курс #ЯЖінка 💡курс #ProResurs 💡NEO курс #REволюція - «Реверсна Еволюція» про пару Нового Часу 💡пакет курсів #ЖіночаСила 💡Книга-цілитель як інтерактивний посібник для пробудження душі #БесідиЗАнгелами … тощо Це те, що я вже створила в #IMARIAACADEMIA і творю далі… Забирай! 🤗 Що тобі резонує? P.S. А мені щоб цвісти потрібні квіти … 🥰 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','20 листопада 2024','3 хв читання','/images/posts/zaverukha.com-1-1.png','[]',1,'2024-11-20T16:27:31','2024-11-20T16:27:31');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2169','%d1%89%d0%be-%d0%bc%d0%b5%d0%bd%d0%b5-%d1%80%d0%be%d0%b1%d0%b8%d1%82%d1%8c-%d1%8','Що мене робить щасливою?','Що мене робить щасливою? Нічого. Простий факт. Контакт з собою. Присутність без конфлікту з реальністю. Все. Я не заходжу в залежність від емоцій радості, печалі, гніву чи страху … і все. Тоді немає того, що робить мене нещасною… А коли є - то я йду ...','["Що мене робить щасливою? Нічого. Простий факт. Контакт з собою. Присутність без конфлікту з реальністю. Все. Я не заходжу в залежність від емоцій радості, печалі, гніву чи страху … і все. Тоді немає того, що робить мене нещасною… А коли є - то я йду в точку імпульсу, аби зрозуміти чому і для чого накопичила цю «ілюзію», з якою метою левел «сну» свідомості проживається. Розумієте? Нам потрібно так багато всього, аби бути нещасними. І абсолютно #НІЧОГО, щоб бути щасливими і приСутніми… Ви думаєте у вас до сих пір чогось немає для щастя? Ніііі. У вас є багато всього для нещастя! І це проблема. Залежність від: - страждань - гніву - радощів (і бажано легких та швидких) - страху - печалі і оцінок - порівнянь та сумнівів… - … Чому люди намагаються добитися матеріального успіху і влади? Бо їм страшно. Вони бояться. А іще бо залежні від радості, і хочуть гратися увесь час в ілюзію свободи «я усе це можу купити…», і це, і це, і ось це… Розумієте? Бо людям СТРАШНО. Чому люди шукають стосунки? Бо їм сумно і печально. З самими собою. Вони себе не «виносять». І шукають когось, хто їх буде «виносити»… І виходить, що страх та печаль породжують тривогу. А тривога породжує магнітні поля, що створюють ще більше причин для тривоги… Покажу вам іще один рівень самодослідження з метою самодіагностики. Якщо людиною керує СТРАХ, то вона тягнеться до всього по типу «правильного і корисного навіть святого», аби ніби то гарантувати собі ілюзію ідеальності реальності (усілякі тут аскези, форми ЗОШ-перекосів харчування, релігійний фанатизм). Якщо у людини залежність від ПЕЧАЛІ, то тягнеться до гіркого (кава, наприклад, різні види діяльності, де милосердя треба проявити, бо багато горенька довкола). Якщо у людини залежність від ГНІВУ то вона вибирає гостре, і в їжі, і умовах зовнішніх декорацій, і в стосунках (тут буде і тиранія, диспотія, алкоголь). Якщо у людини залежність від РАДОСТІ, то вона вибирає і шукай солодке, і всілякі насолоди, не може втриматись перед спокусами і проявляє похоть… Знайшли себе?😘 Це закольцований манеж. А душа при цьому в темниці ума зливає неймовірний потенціал в усі ці воронки егрегоріальних контузій. Де вихід? КОНТАКТ З СОБОЮ ДУШЕЮ через резонанс з тілом планети. В полі душі є енергія, що дає силу проживати усе без залежності від нього. Шукайте КОНТАКТ З СОБОЮ СУТТЮ через тіло, в якому керує СВІДОМІСТЬ, а не ум, що клепає мислеформи! І далі просто підтримуйте його… Ви будете актуальні в усі часи. Ресурсні. І прості… а не залежні на стільки, щоб видумувати постійно складні алгоритми путі до щастя.. 🙏 Було цінно? ✨🌿🌎🕊️ P.S. Майте на увазі - прибрати в собі одним рухом цю базову залежність не вийде, бо ця травма і є несуща конструкція структури більшості людей. Тому шлях до свободи - це реально шлях… інакше б ми усі давним давно жили в раю… і страждань не існувало б взагалі. Саме тому і існують провідники-аватари, які далеко не святі святоші чи «правильні», чи ідеальні, а пробуджені і проявлені в богореалізованій життєвості… © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','19 листопада 2024','3 хв читання','/images/posts/Ірина-Заверуха.png','[]',1,'2024-11-19T16:32:42','2024-11-19T16:32:42');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2384','%d1%82%d0%b0%d1%80%d0%be-%d1%96%d1%81%d1%82%d0%b8%d0%bd%d0%b0-%d1%82%d0%b0-%d1%9','Таро. Істина та ілюзії.','Запамʼятайте, запишіть, усвідомте самі і далі передайте, через #таро не можливо взаємодіяти з «Ангельськими частотами», потоками, вібраціями, енергіями!!! Поняття енергії Всесвіту, космосу, і Ангельські енергії - це не одне і те ж саме…😖 Майте освіту...','["Запамʼятайте, запишіть, усвідомте самі і далі передайте, через #таро не можливо взаємодіяти з «Ангельськими частотами», потоками, вібраціями, енергіями!!! Поняття енергії Всесвіту, космосу, і Ангельські енергії - це не одне і те ж саме…😖 Майте освіту фундаментальну, щоб розбиратися в термінах. Не видумуйте єрунди, не розказуйте людям казок, якщо не володієте знаннями глибокими першоджерельними. Ніколи егрегор таро не був, не буде і не являється нині - Ангельським і високочастотним. Канал даного типу дає доступи лише до 6-го рівня свідомості, і є інструментом Астральним. І усі його похідні теж. Сюди ж відноситься кармічна діагностика. Сюди ж відноситься уся регресологія. Це інструмент «демонічного» походження. Тобто працює з підсвідомістю. *️⃣Не плутайте з нумерологією, сакральною геометрією, які являються результатом містичного досвіду людства, визнані прикладними науками і мають філософське підгрунття та доказову базу, як і наприклад медитація та пранаяма*️⃣ І коли я це пишу, то опираюсь на свою якісну освіту, досвід, статистику та вроджені надздібності, які описала в книзі #БесідиЗАнгелами. (Читали? 😘) В одному із втілень я була потужним тарологом світу. Марія Ленорман, це та інкарнація, через яку моя душа отримувала безцінний досвід. Про егрегор знаю все з рівня свідомості його «засновників». Тому ваші тарологічні експерименти, любі провідниці, мають отримати фундаментальну основу, щоб ви розуміли на що опираєтесь і куди саме ведете людей, із яких джерел черпаєте енергію і знання. Я сьогоднішня навчаю усіх, кого цікавить чистий хілінг Нового Часу! Провідників з ангельським походженням душі, з демонічним походженням душі, з земним походженням душі… Усіх! Бо Аватар МА в Суті. А це канал Єдиного Божого Роду. 🙌 Потрібно розбиратися, друзі, що є чим, з якими витоками, де взялося і куди спрямовує. Немає «поганих» інструментів. Є різні для різного. Я не працюю з таро егрегором. Навпаки. Виводжу із контрактів з ним. Обнуляючи і архівуючи. Бо він просто так не «відпускає» за «спасібо». Як і егрегори релігій, якщо і тут «находили» контрактів. Месії не являлись творцями релігій. Ні один. Зате являлись провідниками потоку МА, усі. Потоку безумовної Любові, Свободи і Добра. То що ви там за інформацію зібрались «читати» через архетипи таро, гліфи, аркани…? Сугубо про коридори квантових варіантів в 3d…так це і називайте, а не «ангельськими частотами». … Таро це не про духовність, як і уся метафізика. Це про владу, про гроші, про управління вітальною енергією матеріалізації і нажаль не зі світлих мотивів використовували ці знання в минулій епосі… а з егоїстичними цілями. Тому егрегор має багато лабіринтів ілюзій. І підлягає утилізації. Егрегор таро буде повністю заархівований в період переходу від 3d до 4d (і не тільки він!), тому «злізайте з цієї ігли» вже і еволюціонуйте далі… якщо маєте бажання реально адекватно вбудуватися в ритми даного часу та бути в резонансі з планетарними частотами. 🙏 з повагою! © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','12 грудня 2024','3 хв читання','/images/posts/zaverukha.com_.png','[]',1,'2024-12-12T16:41:10','2024-12-12T16:41:10');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2488','%d1%8f%d0%ba-%d0%b1%d0%b5%d1%81%d1%96%d0%b4%d0%b8-%d0%b7-%d0%b0%d0%bd%d0%b3%d0%b-2','Єдина – ресурс для щасливих ​​жінок!','Дякуємо команді порталу Єдина - жіночий журнал і особисто Інна Гелетюк Ех Катющенко за увагу до теми та проявлення цінності книги-цілителя "Бесіди з Ангелами" . Дуже якісно глибоким вийшов діалог! 👌 Хто вже має книгу, друзі? Хто мріє про книгу?😘 Кому...','["Дякуємо команді порталу Єдина - жіночий журнал і особисто Інна Гелетюк Ех Катющенко за увагу до теми та проявлення цінності книги-цілителя \"Бесіди з Ангелами\" . Дуже якісно глибоким вийшов діалог! 👌 Хто вже має книгу, друзі? Хто мріє про книгу?😘 Кому цікаво як мінімум дізнатися про що вона? Вам сюди 👇 Як «Бесіди з Ангелами» допомагають знайти шлях до себе – розмова з майстром трансформації свідомості Іриною Заверухою. А для готових до дії бажаю щастя та балансу в процвітанні!🤗 Книга, що приносить удачу, веде до пробудження, допомагає зрозуміти свою космічно-земну природу, розкриває секрети діалогів з Вищими Силами і при цьому допомагає в життєвих процесах, розкриває жіночу сакральність, і є живим інтерактивним інструментом для практики… - це все про «Бесіди з Ангелами»… Більше того, вона ще й саджає ліси в Україні. Один вже росте. Наступний в фазі підготовки до посадки. Ви купуєте книгу - ми саджаємо ліс… 🤗🌱🌎🌳🌲 І це неймовірна праця, яку я люблю, робила, роблю і робитиму далі… 🙏 \"Бесіди з Ангелами\" © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Новини','Ірина Заверуха','27 вересня 2024','3 хв читання','/images/posts/Бесіди-з-Ангелами-1.png','[]',1,'2024-09-27T23:20:00','2024-09-27T23:20:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2562','%d0%b6%d1%96%d0%bd%d0%ba%d0%b0-%d0%bd%d0%b0-%d0%bc%d1%96%d0%bb%d1%8c%d0%b9%d0%be','«Жінка на мільйон»','Як ви гадаєте, «жінка на мільйон» - це фраза про ту, яка заробляє мільйони, чи через яку ВІН заробляє мільйони? Буде діалог… 🤗 …Чоловіки не дивляться оціночно на наш манікюр та зачіску, дівчата, на нього дивляться інші жінки і ми. Чоловіки не дивлять...','["Як ви гадаєте, «жінка на мільйон» - це фраза про ту, яка заробляє мільйони, чи через яку ВІН заробляє мільйони? Буде діалог… 🤗 …Чоловіки не дивляться оціночно на наш манікюр та зачіску, дівчата, на нього дивляться інші жінки і ми. Чоловіки не дивляться на наші сукні, бренди, сумки, дівчата, на це дивляться жінки і ми самі. Чоловіки лише так кажуть, що «очима їдять і люблять», але! Вони «дивляться» на кінцевий результат, що випромінює певний вібраційний вайб, або ж ні, і роблять висновки з наших емоцій та реакцій. Ну принаймі ті, що мають здорову та зрілу маскулінність, а не піс..ноносітєлі чи начиталися сумнівних «журналів», критиків про те, як «правильно» і тому підганяють себе та когось під якийсь шаблон з картинки, зовсім не сприймаючи живої істоти (але таких бажаю вам ніколи не мати на своєму шляху! Що робити, щоб таких не мати? Над своїм внутрішнім станом працювати, себе вибирати, бути справжньою для себе, жити із суті…). Насправді чоловіки більш інтуїтивно-сенсорні, ніж ви думаєте. Якщо жінка знаходиться в його полі зору, то вона вже вібраційно потенційна як «обʼєкт» взаємодії. А далі цей субʼєкт відповідно до свого рівня свідомості діє, або як «лев», чи «шакал», як «бандерлог» чи дійсно істота вищого рівня свідомості з високим ступенем духовного інтелекту підбирає слова та жести для уваги… (пардон, чоловіки, за такі порівняння і аналогії, але швидше суть доходить через метафору 😎) Тому! Домінантною завжди буде ЕНЕРГЕТИКА жінки, а не її упаковка чи якісь геометричні параметри. Чоловіки можливо навіть самі цього не «доганяють». Що вся та гра довкола форми є лиш спробою демонструвати вагомість поля. Тобто в минулих епохах так проявляти намагались статус і владу. Часи змінились. Ми теж. Цікаво почути думку вашу, проявіться, якщо маєте змогу і данну тему осмисляли та досліджували, панове чоловіки… 🤗 Продовжу. То ж. Це жінка сама себе відчуває впевненою, коли доглянута, відчуває себе королевою серед королев (або серед принцесок 😎) в тому чи іншому одязі, вигляді, фігурі, автівці, …і саме це створює її СТАН, ту енергію, яка випромінюється із поля і називається шармом. Або ж по суті - спадком, бо ці параметри дістаються нам із колективного несвідомого від народження, а далі ми вже маємо свободу волі усе змінити і створити. Кажу, казала і буду казати - не гоніться за сексуальністю, панянки, це не те, що вам потрібно…😘 Вже чую як скриплять олівці та ручки, малюючи карти бажань на новорічні дні, вимолюючи у Миколая і Боженьки спочатку «миру в Україні»( бо то ж святе!) , а потім тут же «процвітання, мужика слухняного… і далі по тексту»… Опановуйте не мистецтво звабливості та маніпуляцій, - опановуйте себе! Пробуджуйте і масштабуйте свою гідність, естетику душі, створюйте здорове зсередини тіло, а не нашліфоване чи накачане, і працюйте над зрілістю особистості, накопичуйте енергію через дисципліну (режим, харчування, сон, активність, відпочинок…), не тринькайте її на гонитву за чек-листами, якими торгують маніпулятори. Це ринок. Він існує, доки існує попит. Кількість людей на Землі буде зменшуватися. А якість ростиме. Все до того йде. Залишатимуться адекватні до Чистоти Любові. Вчіться оберігати свободу душі один одного, а не поглинати її… Тоді пізнаєте смак справжніх автентичних стосунків… Не усім потрібно розмножуватися. Не усі живуть, аби вийти заміж чи ходити на роботу за зарплату, не усі прагнуть до взаємодії фізичної, комусь найбільшою цінністю є затишок і усамітнений вайб, спілкування з природою чи творчість від душі. Люди роздули в воронках великих соціальних маркетплейсів, таких як соцмережі, ідею про безкінечну торгівлю вітальною енергією. Вам здається, що це не так? Це так. Подивіться на свої підписки. Що там? Ви хочете бути частиною ринку продажів, і є частиною. Як і я. Але чи усі усвідомлюють свою системну роль на цьому ринку? 😉 Я консультувала своїх клієнтів, супроводжуючи крізь сильні шокові потрясіння після втрати акаунтів з мільйонами підписників. У людей їхала кукуня після цього. Бо якщо вас створила технократична ілюзія і без неї немає ЛЮДИНИ як такої, немає нічого, то це велика біда. Немає головного - вертикалі. Тому не віддавайте своє життя в руки мильних бульбашок - оцінок, лайків, підписок, торгівлі експертностями. Ви маєте вміти жити і бути поза всім цим. Обовʼязково! Навчаю своїх дітей та учнів мати фах. Мати розуміння свого походження і призначення душі. Щоб усі інструменти були лише асистентами твого путі, а не причиною. Ви розумієте, про що пишу зараз?😘 Ілюзії змінюють свої маски. Одні маски зараз злітають, а під ними нова «шкіра», яка теж маска, але ще глибше врощена. Якщо не проявлена Суть і не вирощена Свідомість. Рік 2025 принесе людству велику кількість цікавих відкриттів про життя і викликів. Готуюсь до діалогів про нього. Але свої прогнози на даний рік я видаватиму на курсі #УправлінняПростором і життям в 2025. І все. Ніяких публічних прелюдій не буде. Бо прогнози це делікатна робота. Вони змінюють хід подій і долі тих, хто бере на віру буквально, не вміє знання застосувати в своїх планах, а просто сліпо копіює сказане. Тому я вибираю бути практиком, що супроводжує в путі, а не накопичує свиту і натовп любителів ілюзій швидких результатів. Бо я не вірю в швидкі результати. Ось в чому суть. Моя подруга - фундаментальність. Свобода через Дисципліну. Терпіння. Зусилля. Гра в довгу. Мені імпонує японський принцип #КайДзен. В усьому. Знаю, що #виховання та #еволюція - це регулярний прогрес, а не миттєва досконалість. Тому, любі друзі, особливо жінки, кажу як є. Я ніколи не прагнула маніпулювати кимось через красу чи енергію, і вас не навчу, а відмовлятиму. Не шукайте дофаміновий #вайб у мене тут - його немає. Не заводжу я в залежності від «магічних фантиків», а навпаки виводжу із ілюзій, і це іноді боляче. Бо порядність - то про порядок. Якщо казати мовою моїх дітей підлітків - я академічна душніла. 🤓 і мені з цим ок… Бо раджу взрощувати #відповідальність Жінки Високого Калібру через управління і собою, і реальністю створенням живого миротворчого простору та свідомого стану. 💫 P.S. З ким в резонансі? 🙌 В новому році планую реалізувати мега курс з оновленим наповненням «НеоБерегиня. Космічно-Земна» з пакетами Standart, Standart+, і VIP. Ви б на який прийшли? (Різниця вартості між першим і третім точно буде х10). © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','24 грудня 2024','5 хв читання','/images/posts/Своя-Сила.png','[]',1,'2024-12-24T21:52:25','2024-12-24T21:52:25');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2568','%d0%b6%d0%b8%d1%82%d1%82%d1%8f-%d1%82%d0%b5%d0%b6-%d0%b2%d0%bc%d1%96%d1%94-%d0%b','Життя теж вміє нас люБИТИ, іноді уроками, а іноді нагородами…','Правитель - це той, хто вміє правити себе, тобто змінювати, керувати собою, контролювати своє его, тримати своє слово, реалізовувати його діями… дотримуватися обіцянок. Визнавати помилки. Свої помилки. Розвивати свою волю і дух. Рухатись за покликом ...','["Правитель - це той, хто вміє правити себе, тобто змінювати, керувати собою, контролювати своє его, тримати своє слово, реалізовувати його діями… дотримуватися обіцянок. Визнавати помилки. Свої помилки. Розвивати свою волю і дух. Рухатись за покликом серця в совісті. Ось хто такий правитель… Служити роду і народу створена дана системна роль на Землі. Наповнена спектрами Шиви і Сварога проекція правителя в структурі ядра Суті кожної людини дає невимовну силу перемагати морок, ілюзії, ниці якості і надихати на проявлення зусиль, аби розвивались високі стани душі… ©️ Патріарх із майбутньої книги Заверухи Ірини «Споріднені» По перше, з перемогою Усика, українці! 🥊 Збирати свою волю в центрі серця нині має кожен, і направляти енергію на творчі дії… Хтось бʼється до смерті, аби інші зрозуміли - життя це цінність і воно достойне високої якості… Життя теж вміє нас люБИТИ, іноді уроками, а іноді нагородами… Почули? Побачили як неочевидно і глибоко слова кодують нашу підсвідомість? 😘 P.S. На найближчому ретриті «Галактична симфонія» в Карпатах маю намір приділити даній темі якісну увагу… То що є зусиллями, а що вже насиллям… як відрізняти… в тому числі владу від Бога та егрегоріальні ілюзії… Тому до зустрічі в глибину сенсів… 🙌доєднуйтесь… кому пора розкривати крила масштабно, а не просто тріпатись на вітрах потрясінь та наївних «хочу»… Фундаментально качну в полі тему СИЛИ… ❤️‍🔥❤️‍🔥❤️‍🔥 Ретрит для жінок, що прагнуть проявити Силу свого серця через Вільну дію. Деталі питайте, якщо вам резонує та дійсно маєте намір бути. І не сцикайте взнавати скільки коштує те, до чого ви проживаєте резонанс… 😉 Сподіваюсь нікого не образила. Бо дійсно дуже відчуваю людей, і навіть думки теж… 😎 #НеоБерегиня #IMARIA - камертон космічно-земної мудрості роду! 🙏 © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','22 грудня 2024','3 хв читання','/images/posts/470689191_580821664805097_6673760298998224231_n.jpg','[]',1,'2024-12-22T22:16:19','2024-12-22T22:16:19');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2571','%d1%8f-%d0%bd%d0%b5-%d1%82%d1%96%d0%bb%d0%be-%d0%b2-%d0%bc%d0%b5%d0%bd%d0%b5-%d1','Я не тіло, в мене є ТІЛО','…Коли розумієш, що твоє тіло дійсно виліплене річками, горами, лісами, степами і джерелами цієї прекрасної планети, що в ньому блиск зірок і шепіт вітрів, що воно несе памʼять прадавніх часів, а не має скількись там років, що в паспорті написали… Що ...','["…Коли розумієш, що твоє тіло дійсно виліплене річками, горами, лісами, степами і джерелами цієї прекрасної планети, що в ньому блиск зірок і шепіт вітрів, що воно несе памʼять прадавніх часів, а не має скількись там років, що в паспорті написали… Що в ньому продовжуються предки і таким чи нем теж живуть, хоча вже й не живі; що твоє тіло - це місце сили, і носиш ти його по Землі, активуючи звʼязок древній та неділимий через живу пробуджену душу… Коли ти це розумієш. Дійсно РОЗУМІЄШ, а не так кажеш заради галочки, бо усі кажуть… - то нарешті наважуєшся на визнання факту - я не тіло, в мене є ТІЛО. Як і в мене є мій рід. Моя сімʼя. Мій дім. Мій шанс створити більше любові і викупати себе в ній, а не шукати щось десь і клянчити за «гарну поведінку». Тіло створює потужні спектри магнітних полів, якщо ним володіє Душа. І нічого воно не створює, а лише зношується, коли ним володіє его. То де той спосіб, що пробуджує сенси і наділяє відповідальністю за якість енергії? Хіба він прихований від нас? Ні. Він на поверхні. Щоб почути - прислухайся. Щоб пізнати - запитуй. Щоб отримати - віддай щедрість. Щоб любили - люби. Щоб знайти - шукай. Щоб прийти - рухайся. Щоб бути - будь… просто будь в собі собою… ✨✨✨✨✨ Новий рік. Ця фраза так і залишиться лиш фразою, якщо ти не почнеш НОВИХ ДІЙ. Якщо не завершиш стару гру і не вимкнеш набридливу шарманку… якщо не перестанеш обслуговувати синдром своєї вивченої немічності… Якщо ти не наважишся на більше, або не зізнаєшся собі, що ти значно менше можеш і хочеш, ніж з себе корчиш… Якщо ти не відпустиш усі уявлення батьків про тебе і їхні очікування в вимір ілюзій, і не почнеш розвивати свою справжність… Якщо ти не підеш за мрією - то і не прийдеш до тріумфу перемоги. Якщо ти не вестимеш інших до перемог, а лише будеш принижувати усіх критикою і макати носом в поразки - ти ніколи не досягнеш головної перемоги - над власним его… Якщо ти не розумієш, що тіло і є інструмент творення, а Творець, твій дух, використовує цей інструмент, аби проявляти в форму любов… То… То що? То нічого. Нічого путнього із усіх цих імітацій важливих дій так і не вийде… На порозі 2025 року я буду знову кликати тебе, … усіх … до відповідальності за путь. Завтра розпочинаю начитку курсу #УправлінняПростором , життям та долею роду в 2025 році. А сьогодні я обіймаю себе увагою, турбуюсь про тіло, дім, стан, сімʼю і широку орбіту буття. Присвячуючи кожну свою дію загальній гармонії… А як ти створюєш свій священний сакральний звʼязок з живим життям? Розкажи… 👇 І приходь на діалог про простір. А місце для тебе в моєму знайдеться завжди… 🥰🤗 #IMaRia #БерегиняЗемлі #ГолосДуші #СловаКрила #imariaacademia #way © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','21 грудня 2024','3 хв читання','/images/posts/zaverukha.com-1.png','[]',1,'2024-12-21T22:23:37','2024-12-21T22:23:37');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2596','%d1%81%d0%b5%d0%bc%d1%96%d0%bd%d0%b0%d1%80-%d1%81%d0%b5%d0%ba%d1%80%d0%b5%d1%82%','Семінар "Секрети енергії процвітання"','🤩🔥Ну що ж… це має бути дещо wow… Подія лише для ментально зрілих людей, які не бояться успіху, удачі, слави, публічності, відповідальності…👌 Реєстрація і бронь відкриті. Новий формат виходу за межі ума… Чистий 5d запуск… і не кажіть, що не бачили нов...','["🤩🔥Ну що ж… це має бути дещо wow… Подія лише для ментально зрілих людей, які не бояться успіху, удачі, слави, публічності, відповідальності…👌 Реєстрація і бронь відкриті. Новий формат виходу за межі ума… Чистий 5d запуск… і не кажіть, що не бачили новину 😉 А я тепер реально спатиму спокійно, бо континіум 1 раз на 5 років такий, … і позорно мені не буде за те, що володіла знаннями й не поділилась з людьми, не зробила все, що могла… 🤗 Погнали в стратосферу! 💫🙌 P.S. Ці дві панянки знають толк в тому, що транслюють. Коли ми розказуємо про духовне - то проявляються реальні «чоботарі з чоботами», а не езотеричні одувани. Коли розказуємо про гроші і матеріальне - аналогічно… Обидві в межах року 2024 вийшли на рівень творців, що платять десятки тисяч податків державі, донатять на благодійні проекти по 100к грн, саджаючи ліси в Україні. Обидві на рівні родини створили і переїхали в житло з інвестиційною вартістю за 10🍋. Обидві щасливі і реалізовані жінки, в зрілих союзах, мами і лідерки. Любимо людей і життя, піклуємось про себе… Я пишаюсь партнерством з Наталія Пузенко, бо наші дії завжди погоджені з Вищим Я та волею Сили МА. Тому в нашому полі кояться справжні дива. Це з нею я реалізувала майже 30 ретритів із 42, які проводила для жінок світу. З нею ми «вмирали» разом в старій шкірці на старті повномасштабної і починали все з початку. Ми потужні обидві і взрощуємо екосистему, де в нашій сінергії визрівають нові колеги, хілери, ментори, куратори, вібраціологи і просто класні люди, жінки-берегині… Щасливі прагнуть масштабувати щастя, і це помітно неозброєним оком, правда?… 🤓 бо не обманюють тільки результати! До зустрічі в потоці живої присутності … https://pipl.net.ua/seminar-secrets-prosperity © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','7 лютого 2025','3 хв читання','/images/posts/476444009_616712577882672_5706620014308267673_n.jpg','[]',1,'2025-02-07T20:00:06','2025-02-07T20:00:06');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2599','%d1%82%d1%83%d1%80%d0%b1%d1%83%d1%8e%d1%81%d1%8c-%d0%bf%d1%80%d0%be-%d0%ba%d0%b0','Турбуюсь про карму. Вашу і свою…','Золоті, у мене такі цікаві стосунки з різними мнєніями Я вам зараз розкажу. Мене ніколи не цікавить думка людей, яких я б не попросила поради. Ніколи. Порад в житті я прошу, вчитись люблю. У цінних експертів. Яких сама вибрала і про щось запитала, а ...','["Золоті, у мене такі цікаві стосунки з різними мнєніями Я вам зараз розкажу. Мене ніколи не цікавить думка людей, яких я б не попросила поради. Ніколи. Порад в житті я прошу, вчитись люблю. У цінних експертів. Яких сама вибрала і про щось запитала, а не мені хтось це доказує з піною у рота, як я сильно не панімаю, що це круто. Бо тренд, бренд, посада… тощо… В моїй картині світу хейту немає. Ніде. Ніколи. На безпардонність я уваги не звертаю. Наглість пропускаю. А відверту токсичність посилаю в бан без розмов і діалогів. Бо мова про мій простір. Про мою сторінку і на ній атмосферу та чистоту. Яснобачення і професійна чуттєвість та досвід хілера дають мені можливість на 100% гарантій бачити картину реакції будь якої людини на будь що. Тому я і є тим ким є. Цілителем. Хакером ілюзій. Коли мої тексти в інших людях викликають цікавість - я веду діалог далі, коли викликають обурення - я раджу їм «іти далі», коли хтось починає мене запевняти, що я сильно не права, - я співчуваю і забуваю про цю людину як субʼєкта взаємин… Бо ми з вами стосунки формуємо всюди на основі цінностей внутрішніх. І мої в мені пробудовані на принципі поваги, любові і еволюційної етики. Я не пишу про людей, про особистостей, а лише про свій досвід та сутністні поняття цивілізаційні. Тому ви тут не знайдете скандальних історій про когось. Душніла я за мірками сучасного жаргону молоді… Академічна душніла. Без прелюдій і анестезій. Я не ходжу по акаунтах інших людей. Мені просто ніколи. І не маю в цьому потреби. Не пишу нікому порад, як їм жити. Не задаю питань пустих. Я не збирач пустих підписників чи лайків. Але увагу людей поважаю і завжди ціную за те, що робите перепости, турбуєтесь про щедрість діями і виступаєте мостами для знань, які летять далі! Не розбираюсь я в статистиках і параметрах алгоритмів. Але враховую правила гри, а не залежу від них. При цьому мої програми завжди заповнені. Групи набрані. Консультації розписані на місяці вперед, реалізовую наставництво і навчання. Бо істинна причина якісної самореалізації зовсім не в тому полягає, щоб не злазити з рекламних екранів гаджетів людей… Мене не цікавить публічність заради публічності. Я спокійно дякую за пропозицію і відмовляю в участі на конференціях чи виступах, якщо це не резонує з моїми цінностями, чи не вписується в графік життя. Я спокійно заявляю, коли хочу проявитись там, де мені це важливо. От сьогодні наприклад погодила свою участь в одному із весняних проектів. А на вихідні теж піду на закритий фешн показ, бо є сердечний резонанс з цінностями організаторів… Мені зовсім не цікаво чим усе, що я вище описала, здається комусь. Бо бути свідомістю Вчителя Алхімії на Землі, це вже заявка на безкінечну тригерність в людях на твоє поле і чистоту мотивації. Усі собі щось із своїх ілюзій домислюють. За своїми ширмами і діафільмами ума бачать якісь очікування, мультики, проекції… Коли маю натхнення і відчуття відповідальності проявити інформаційну щедрість - я пишу тексти і викладаюсь в ефірах знаннями. Глибоко. Від душі. Бо якщо робити - то якісно. Нині і консультую, і веду марафон, і тренерський курс модерую, бо в учениць сертифікація, і збори своїх команд веду, і готуюсь до поїздок, які скоро, і реалізовую побутові справи (бо заїхали в нульцевий дім, де все потрібно організувати), і прогнози записую (голосовий сьогодні полетів до амбасадорів #piplclub )… тощо… купа зайнятості. Ну що вам ще сказати. От такі справи. Тому по собі нікого не судіть. Цікаво, цінно, резонує? Супер. Не цікаво, не цінно, не резонує? …далі ідіть. Не подобається щось, а ви терпите, бо що? Питаю в лоб - нахіба? Не хочеться мені бути причиною пустих балачок і неефективних емоцій інших людей. Турбуюсь про карму. Вашу і свою… Сат Нам! З повагою, Master IMARIA © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','10 лютого 2025','3 хв читання','/images/posts/IMG_4539-scaled.jpg','[]',1,'2025-02-10T20:10:14','2025-02-10T20:10:14');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2647','%d0%bf%d0%bb%d0%b0%d0%bd-%d0%b4%d1%83%d1%88%d1%96-%d1%88%d0%bb%d1%8f%d1%85-%d0%b','План Душі - шлях до успіху.','Інтуїція без плану — це лише мрії. Ірина Заверуха, IMARIA MASTER, переконана, що дисципліна та стратегія є ключем до успіху. Вона ділиться своєю історією зцілення, розповідає про допомогу іншим та пояснює, як створити план душі. Засновниця платформи ...','["Інтуїція без плану — це лише мрії. Ірина Заверуха, IMARIA MASTER, переконана, що дисципліна та стратегія є ключем до успіху. Вона ділиться своєю історією зцілення, розповідає про допомогу іншим та пояснює, як створити план душі. Засновниця платформи розвитку PIPL, майстер-берегиня IMARIA, еніопсихолог, інтуїт, астролог бацзи, енерго-інформаційний цілитель, вчитель йоги свідомості. Організаторка ретритів і трансформаційних програм. Президентка міжнародної громадської організації «Aurum Soul Club» – «У мене завжди є план!» Так кажуть багато хто з нас. Проте велика ілюзія думати, що інтуїція та духовний шлях — це можливість просто плисти за течією та нічого не планувати. Лише дисципліна та стратегія є інвестицією в нашу свободу та успіх. Попри феноменальні вроджені здібності та дар, я розвиваю себе все життя і не планую зупинятися, адже когнітивні функції не повинні погіршуватися з віком. Людина має неймовірний потенціал і безмежні можливості. Я зцілила себе в 27 років від онкології та стала медичним феноменом країни. Народила двох дітей, попри діагноз «безпліддя», і допомогла з’явитися на світ 402 дітям у різних куточках світу. Вже понад 16 років я допомагаю людям долати кризи та виходити із замкненого кола проблем. Понад 10 років навчаю колег, виховую хілерів, консультую лідерів різних соціальних рівнів, реалізую освітні, культурні та мистецькі проєкти. Мої таланти проявляються у співі, танцях, малюванні. Я несу мудрість знань на трибуни та сцени. Моя душа соціальна та невгамовна. І це теж частина плану та стратегії! Без відповідальності, дисципліни та рішучих дій не буває лідерства й успіху. Ми повинні бути в діалозі з Богом. Внутрішній стрижень формується волею та духом. Наше серце має бути відкритим і наповненим любов’ю. Повернімося до плану. Він має бути завжди. І це не просто список пунктів, які потрібно викреслювати в кінці року. Це глобальна стратегія. Коли ви рухаєтеся в резонансі зі своїми цінностями, ваш шлях стає чітким і сміливим. Інтуїція — це сила концентрації думки та потужність мислення, яка створює могутнє магнітне поле і формує квантові коридори матеріалізації. Якщо вам цікаво, детальніше я розповіла про це в своїй книзі-цілителі «Бесіди з Ангелами» . Досліджуйте себе! Беріть себе в руки, створюйте енергію, яка трансформується в матерію. Плануйте своє майбутнє, інвестуючи в щедрість — до природи, жінок, дітей, пращурів, носіїв мудрості, миротворців. Йдіть до кінця! До свого плану. Де цей кінець — вирішуєте тільки ви. І це теж частина плану. Якого? Плану душі. З любов’ю до жіноцтва та людей світу Ірина Заверуха — IMARIA MASTER Посилання на статтю © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Новини','Ірина Заверуха','7 березня 2025','3 хв читання','/images/posts/5357502631657991216.jpg','[]',1,'2025-03-07T13:30:20','2025-03-07T13:30:20');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2710','%d1%81%d0%b2%d0%be%d0%b1%d0%be%d0%b4%d0%b0-%d1%81%d0%be%d1%8e%d0%b7-%d0%bf%d1%80','Свобода. Союз пробуджених душею','Марафон, який не просто трансформує — він повертає тебе до себе справжньої. 21 день глибини. 21 день звільнення від чужих програм. 21 день практик, які відкриють тобі силу твоєї Душі. Це не чергова подія. . Це — простір, де відбуваються активації. Дл...','["Марафон, який не просто трансформує — він повертає тебе до себе справжньої. 21 день глибини. 21 день звільнення від чужих програм. 21 день практик, які відкриють тобі силу твоєї Душі. Це не чергова подія. . Це — простір, де відбуваються активації. Для кого: для тих, хто відчуває поклик на глибину для тих, кому тісно в старому \"я\" для тих, хто готовий до свободи у тілі, у виборі, у житті. Старт: 12 травня Доєднатись можна до 16 травня Ми — не просто учасники. Ми — Союз Пробуджених Душею. Запрошуємо тебе у священний простір трансформаційного марафону «Свобода. Союз пробуджених Душею» © Ірина Заверуха, 2024 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Новини','Ірина Заверуха','12 травня 2025','3 хв читання','/images/posts/5249044154699347549-1.jpg','[]',1,'2025-05-12T13:28:50','2025-05-12T13:28:50');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2728','%d0%b6%d0%b8%d1%82%d0%b8-%d1%82%d0%b2%d0%be%d1%80%d0%b8%d1%82%d0%b8-%d0%bb%d1%8e','Жити! Творити! Любити! Дякувати!','Цей рік для мене реально святковий, ювілейний, переможний… в багатьох аспектах… сподіваюсь, що масштабується дана енергія і на широкі орбіти… зачепить країну та велику кількість людей… 🥰🤩🤗 Нехай. Нехай будуть всебічні перемоги нашою реальністю. Нехай...','["Цей рік для мене реально святковий, ювілейний, переможний… в багатьох аспектах… сподіваюсь, що масштабується дана енергія і на широкі орбіти… зачепить країну та велику кількість людей… 🥰🤩🤗 Нехай. Нехай будуть всебічні перемоги нашою реальністю. Нехай буде сила свята нашою реальністю… А тим часом. Я тихенько підводжу підсумки. В 2015 році - прийняла рішення навчати людей, передавати свій досвід та знання далі. Результат - тисячі учнів закінчили мої курси, а в 2025 році IMARIAACADEMIA сертифікувала та випустила перших професійних колег Хілерів, Вібраціологів, Менторів терапевтичних програм, які вміють аналізувати долю в методі Путь Душі (Way Of The Soul), які вміють організувати терапевтичне коло, ретрит, конференцію сенсів, колектив чи захід… тощо… Які вміють зцілювати травматичні та посттравматичні стани і покращувати якість енергії. Принаймі усі знання про це я їм передала. Далі - тільки досвід кожної. Справедливості задля скажу як є - проекти IMARIA®️&PIPL™️ для мене це дійсно місце любові до професії та сумлінність в проявлені дару, щоденна кропітка праця. Влада і слава - це про відповідальність. Багатство - про щедрість. Здоровʼя - про дисципліну… Такі маю опори. А досвід щодня нагадує про колосально важливе…👇 В 2001 році - стала на шлях громадської діячки. Не сходила з нього. В 2004 році - стала на шлях заміжньої жінки. Не сходила з нього. В 2006 році - вперше відкрила для себе йогу. І через 20 років по тому планую проявити світу Школу тренерів Divine Yoga by IMARIA. Є намір - буде і результат…🙌 Права маю усі, бо належу до Золотої мережі Духовних Вчителів світу, провідників прямої лінії передачі білої тантри від духовних істот, що не мали інкарнацій на Землі, але навчали землян мудрості та просвітленню (в тому числі усіх Будд)… В 2007 році - вперше стала мамою, поза діагнозами про безпліддя. Після того іще 405 разів отримувала новину про материнство від своїх клієнток…🥹 В 2009 році - усвідомила свою глибоку внутрішню кризу, наслідком якої була онкологія, і почала шлях самозцілення та розпаковки путі душі, вишкрібаючи свою суть із пут ума. Нон-стоп навчалась та пізнавала сакральні знання. Стала медичним феноменом країни. Навчалась у найкращих. Розпакувала себе. Проконсультувала з питань призначення та аналітики долі за 16 років практики понад 50 000 людей. Серед яких і медійні персони, зірки шоубізу, політики, керівники TOP рівня, і люди, які жодного високого бренду в руках ніколи не тримали. Але ж усі люди - ЛЮДИ. І проблеми дуже схожі мають в структурі ядра особистості та долі. Організувала і була в співорганізації сукупно 17 культурних, освітніх і мистецьких заходів. Створила фізичний Центр саморозвитку для сімей AURUM SOUL CLUB, який успішно працював 2 роки, але закрився ковідом, і перевів мою увагу в онлайн освіту. Побачила свій масштаб. З 2018 року отримала 6 міжнародних соціальних нагород за професійну діяльність. В 2025 році зафіксувала 43 реалізованих ретрити для жінок світу, і зараз планую 44-й нішевий. Кайфую, маючи причетність до масштабування радості у світі. В 2024 році написала і видала книгу-цілитель «Бесіди з Ангелами» і взагалі понад 3000 алгоритмів, статей, протоколів, медитацій для людей з еволюційною метою створила за 15 років творчого служіння. Заснувала видавництво, аби створювати вібраційну літературу, що розпаковує сакральний спадок космічного роду. Працюю над випуском іще 2 книг, терапевтичних колод, трансформаційної гри в форматі 5d активації. В 2024 році в українських Карпатах зняла кліп-ініціацію до Балади Берегині (написаної іще в 2017 р) про сакральний діалог та пробудження душі. Створила заради цієї мети справжній шедевр разом із брендом GaEva - оберегову сукню-кейп «Споріднені» для НеоБерегинь світу, яку придбати можна лише на моїх ретритах та жіночих ініціаціях… 😘🤩 … На побутовому фронті: побудувала родинний дім. Інвестиційну нерухомість за кордоном. Виховала психічно стійких та морально глибоких здорових дітей. Відвідала понад 20 країн світу з дослідницькою метою (4 з яких в Азії). Взростила потужну команду зрілих та свідомих експертів. Допомогла тисячам людей знайти опори, відповіді, «своїх». Обійняла крилами добра величезну кількість благодійних ініціатив. Посадила 3 ліси в Україні, де росте понад 11 000 дерев (надихнула прикладом на це інших). Не смійтесь, але повністю відновила зуби: виносила брекет систему 2 роки, реалізувала протезування за показаннями (що на рівні інформації є виходом із негативних карм родових програм через відповідальність)… за ціною однокімнатної квартири у Києві…хто в темі - зрозуміє, для мене це реально був подвиг 😜🤓 Пізнала досвід дружини військового. І живу його нині… … На найважливішому фронті: З собою - чуйність, турбота, зусилля, мудрість, чесність, безпека, усвідомленість, чистота, баланс, повага, відвага, увага і любов. Як результат: з батьками, з дітьми і всіма партнерами - повага, увага, довіра і любов. Ну і тепер мої плани дуже прості…🤗 Жити! Творити! Любити! Дякувати! Без людей ідеї залишаються лише мріями. Я ціную своїх і дякую за путь. P.S. На фото наша чарівна всебічно талановита патентна повірена Nataliia Nazarenko вручає мені документи на торгову марку бренду IMARIA®️, які «випадково» були отримані саме під наш випускний тренерського курсу… Дякую тобі Наталочка, за всю кропітку працю, яку ти робиш для добробуту людей. З Наталочками мені щастить по життю. Маю неймовірну партнерку Наталія Пузенко , з якою несемось крізь вічність… А інші подяки залишаю внизу, вкорінюючи в історію… 🥰👇 © Ірина Заверуха, 2025 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','19 травня 2025','4 хв читання','/images/posts/IMG_7773-scaled.jpg','[]',1,'2025-05-19T10:15:49','2025-05-19T10:15:49');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2738','%d0%bf%d1%80%d0%be%d0%b2%d0%be%d0%ba%d1%83%d1%8e-%d0%b7%d0%b0%d0%bc%d0%b8%d1%81%','… провокую замислитись…','Зараз буде непопулярний рознос про спроби людей через блоги різних «експертів» вирішувати важливі проблеми і досягати мети… 🤨 Люди, ви не вилікуєте свою пневмонію, дивлячись на рекламу антибіотиків в соцмережах, ви не вилікуєте її навіть якщо будете ...','["Зараз буде непопулярний рознос про спроби людей через блоги різних «експертів» вирішувати важливі проблеми і досягати мети… 🤨 Люди, ви не вилікуєте свою пневмонію, дивлячись на рекламу антибіотиків в соцмережах, ви не вилікуєте її навіть якщо будете описи антибіотиків прикладати до якихось «правильних» точок на собі… чи ставити на ті описи воду і пити маленькими ковтками. Цілительство не в цьому полягає. Цілительство це не про самонавіювання. Не про позитивне мислення. Не про сільську магію забобонів чи заклинань… 🫤 Від того, що ви дізналися ким були в минулих життях і находилися по якихось кабінетах «провідників/ченелерів», які вам наставили діагнозів чи реалізували ретравматизацію станів - теж не зникнуть ваші проблеми. Від того, що ви почитали про позитивний досвід подруги і тепер знаєте, що саме вона робила - теж не зникнуть конкретно ваші проблеми. Бо «проблеми» - це не проблеми (тобто явища з негативним кліше) 🤪 а задачі для еволюції. У еволюції свідомості є етапність. І від рівня до рівня - змінюється все. Звідки ж такі асоціації та очікування по відношенню до своєї душі? По відношенню до психіки, до теми стосунків, внутрішніх криз…? От мені реально цікаво… 🧐 Чому в 21 столітті, де ШІ і нанотехнології процвітають до рівня особистих помічників людини, - у деяких до сих пір в голові каша про структуру самих себе?! Невже дійсно так глибоко вкорінилася пліснява ліні і немає жодного бажання розібратися з термінами, з поняттями, з сенсами… і бути не відлетівшими шизотериками, які сліпо вірять, бо «так сказали», чи навпаки ні в що не вірять, бо ж довкола одні «шарлатани». А слабо дослідити? Із дорослої позиції… Поцікавитися доказовою базою? Включити критичне мислення? Осмислити квантову фізику і хоча б базові знання з вібраціології мати? Аби не зависати в своїх «перекосах» і не ховатися від реальності? Феномен ефективності медитації в досягненні нейропластичності мозку науково доведений. Феномен ефективності йогічної терапії науково доведений. Цілі інститути по всьому світу вже понад 70 років якісно працюють і масштабуються. Магнітний вплив хілінгу на структуру клітини науково доведений. Ефірний терапевтичний позитивний вплив звуків та музики згідно різниці частот науково доведений. Хвильова теорія світла давним давно не псевдонаука, а втілення на практиці. Тонкоінформаційну матерію теж давно виміряли через коваленту, тобто ми можемо розмовляти про СИЛУ БОГА мовою науки… а не мовою казочок про релігійні гіпотези… Що таке з людьми робиться?… Коли йде мова про якісне виконання технічних робіт наприклад з вашою автівкою, ви куди її везете? На СТО, вірно? Тобто до професіоналів майстрів. В майстерню. Коли зуби болять ви йдете дивитися ролики про стоматологію? Чи записуєтесь до спеціаліста на прийом? …. У мене питання. Чому ви очікуєте чарівних безкоштовних примочок від експертів, що якісно працюють з полем душі ? Чому ви знецінюють дар цілителів і хілерів, вивалюючи на голову свої проблеми, замість того аби записуватися на професійний менторінг, що веде до результату? Як виміряти ефективність результату, працюючи з вібраціями, яких не видно, але вони відчутні? Дуже просто. Ви після походу в душ бачите, що стали чистішими? Бачите. А після походу до вібраціолога ви ВІДЧУВАЄТЕ чистоту, спокій, гармонію… Ви можете побачити любов? Ні. А відчути можете? Так. Ви можете побачити турботу? Таааак! А чому ви турботу називаєте любовʼю? Хз… Це одне й те ж? Ні. Але в любов входить турбота? Так. А в турботу входить любов? Ні. Може бути турбота із рівня «так потрібно». Але ви відчуваєте, коли турбота реалізована з любовʼю, а коли бо «так потрібно»? Так… 🙃 Іще питання є? P.S. у мене є питання до цеху колег - чому ви дозволяєте такому явищу ставатися? Відповідь. Занижена самооцінка? Харе цим прикриватися. Це ваші власні сумніви в адекватності своєї праці та її потрібності. Приходьте вчитися до Заверухи в IMARIAACADEMIA - я вас «вилікую» від цієї інфекції просто своєю присутністю. Не вірите? Почніть з моїх марафонів, ретритів, до речі скоро буде 44-й… 🙌 © Ірина Заверуха, 2025 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','18 травня 2025','3 хв читання','/images/posts/zaverukha.com-2.png','[]',1,'2025-05-18T10:25:01','2025-05-18T10:25:01');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2743','%d0%bf%d1%80%d0%be%d1%81%d1%82%d1%96%d1%80-%d0%b4%d0%b5-%d0%b7%d0%bd%d0%b0%d0%bd','Простір, де знання стають досвідом, а досвід – ключем до еволюції особистості на путі Душі.','«…Ти помреш. І я теж. Тому усвідом, для чого ти живеш…» Колись, почувши це, я отримала найпотужніший поштовх до дії і самомотивацію. Мені було всього лиш 27 років, і я ніби не планувала іще. Помирати. Але сам факт - це зʼявилось тоді «в планах життя»...','["«…Ти помреш. І я теж. Тому усвідом, для чого ти живеш…» Колись, почувши це, я отримала найпотужніший поштовх до дії і самомотивацію. Мені було всього лиш 27 років, і я ніби не планувала іще. Помирати. Але сам факт - це зʼявилось тоді «в планах життя» на мене. Тільки залишається питання - КОЛИ. І все. Тому зараз я глибоке спілкування зі своїми клієнтами та учнями, починаю саме з цієї фрази: ТИ ПОМРЕШ, це 100% факт, і є купа інших - в яких ти сумніваєшся. Вірно? ******* Осягнувши структуру Всесвіту- макрокосму, і окремо його «копію» - одиницю мікрокосму - людину, отримавши сакральні знання про влаштування системи живого життя, - ви не просто відчуваєте, коли і які саме вам дії робити, а й їх осмисляти здатні. #Вібраціологія - це наука майбутнього! Вона доступна проявленим інтуїтам. Про неї формував гіпотези свого часу навіть Ейнштейн, розуміючи в куди еволюціонує людство. І не лише він. «Якщо ви хочете дізнатись таємниці всесвіту - досліджуйте енергію, частоти і вібрацію» - Н.Тесла Ми усі з вами вже знаходимось в епосі, де проявленими сусідками є 3 типи реальності і вони своїми слоями здатні не пересікатися. Але бути однією планетою в матерії і взаємодіяти за законами багатовимірності… - резонансу та дисонансу. За цим безмежно цікаво спостерігати…🥰 і навіть приносити квіти на «братські могили» вчорашніх типу «експертів-колег», які насправді шукали спосіб вибитися в люди, а не йшли духовний шлях. За свою чесність і вірність місії я безліч разів спостерігала і сарказм, і насмішки, і «Іуд», що не справились з власним его, але мені точно ніколи не було і не буде соромно ні за них, ні за себе, - набутий досвід сформував колосальний імунітет. Маю честь вклонятися з вдячністю своїм Вчителям, бо абсолютно з усіма в стосунках любові та поваги! Маю честь пишатися і своїм шляхом достойного Учня, якому цього разу вдалося на усіх фронтах…🙏 Сьогоднішня я, Заверуха Ірина IMARIA MASTER, чим зайнята найбільше в своїй стратегії праці? Активними діями, що ведуть до трансформації вчорашніх езотериків в професійних хілерів-вібраціологів, сьогоднішніх психологів, кармологів, енерго практиків, йогінів, тілесних терапевтів, духовних коучів в пробуджених і експертних менторів по саморозвитку, що є і родологами космістами одночасно (здатними надати підтримку і супровід в терапії), а також показати маршрут розвитку аби людина не застряла в безкінечних коридорах вельми цікавих, але безперспективних ПРОЦЕСІВ зміни минулого. Це надзвичайно важливо! Деякі «деталі» гаджетів потрібно замінити, а не ремонтувати. Іноді варто замінити увесь гаджет. Створивши новий. Це ж нам зрозуміло, правда, на рівні побуту? З форматами мислення так само… Але знаєте як часто кажуть гуру і гуріси, опираючись лишень на свій особистий досвід, за який їм дуже хочеться урвати максимальний монетизований зиск, бо вкладено купу енергії в свій шлях? «Я маю алгоритм», «Я створив авторську методику продажів», «Я дослідила і отримала результат»… І це гарні слова. Все прекрасно в них. Достойно поваги. Але! Це не враховує ваших персональних етапів еволюції в довгостроковій перспективі…🧐 Якщо ваша система прямо зараз знаходиться в циклі часу, де домінантою є #активність, а ви застосуєте поради Наставника, що заводить на територію внутрішніх процесів, тобто в дослідження пасивності - у вас не буде результатів! Ніяких. Ви профукаєте свій час. І вчитель тут не винен. Бо може реально давати гарні поради, тільки вони в ДИСОНАНСІ з задачами вашої душі (ось вам і вібраціологія в дії). І навпаки аналогічно звичайно ж. Якщо ви людина стихії вогонь, чи земля - то наприклад класичні старі стратегії блогінгу, маркетингу, продажів, - вам заходили буквально іще «вчора» на ура! А якщо ж ви людина стихії води, дерева чи … - тут вже буде купа нюансів. Нині все навпаки. Епоха Водолія, де домінанта - ПУСТОТА, робить неймовірно результативними людей, що проявляються крізь ЕФІР, тобто вібрацію безумовної любові. В усьому. Чи є тут стратегія? Певною мірою. Звичайно є. Вона полягає в розумінні своєї структури МОНАДИ ДУШІ в резонансі з координатою часу. І не хіхікайте зі слів, друзі, а йдіть гуглити чи з чатом gpt діалоги вести по темі. І ви побачите спрощену форму інтерпретації складних філософських концепцій. Та чи прискорить це вас в путі? Ні. Якщо прямо зараз ви знаходитесь в ілюзорному коридорі буття, тобто ви ніби рухаєтесь, але це інволюція хибного его. Так. Якщо прямо зараз ви знаходитесь в істинному континіумі, що вібраційно резонує з Вищим Я. Тоді еволюція, або ж Rеволюція (реверсна еволюція) вам гарантовані… … 🌟🌟🌟🌟🌟🌟 Сьогодні я маю честь представити широкому загалу своїх учениць-хілерів, які здали проміжкову сертифікацію і вже успішно практикують! Провели консультації за донат в просторі Pipl Club і виходять у відкритий океан світу. Це справжня духовна еліта. #Вібраціологи, що розкриють вам знання про Путь Душі і дадуть якісні поради з будь-яких питань. Пишаюсь кожною, бо ми довгий шлях навчання і практики з ними прожили! 🙏🤩 Стукайтесь до них, знайомтесь з унікальністю методу, який заземлився через мій канал та досвід, аби служити людям Землі в епоху Водолія, коли мега важливим є навик вищої інтуїції - Way Of The Soul - квінтесенція сакральних знань про вібраціологію…🤗😍 Все. Тепер офіційно я несу цей стяг перемоги над власними «демонами» і гордині, і страхів, і ліні, бо ставати на шлях, який у тебе до кінця життя і навіть за його межі - для особистості непросто. Але я вийшла з гри ілюзій ума. Бій завершено. Позаду понад 50 000 персональних консультацій (тааак! величезний досвід). Організовано 42 ретрити. Написано і видано книги, медитації, відеоролики, вірші, пісні, протоколи зцілення, мотиваційні ессе, вібраційні предмети-обереги. Народжено 402 дитини. Отримано 6 міжнародних соціальних нагород за активну громадську діяльність та громадянську позицію… І тепер я Майстерити буду інших Майстрів, тримаючи руку на пульсі якості послуг даного «ринку». Свою репутацію, своє імʼя, досягнення особистості, феноменальні результати пробудженої свідомості, славу і час я ставлю на одну ячейку - служіння Живому Життю, усвідомивши свій Аватар проявлення Бога в спектрі МА; залишивши собі лиш щастя жінки, яка насолоджується абсолютною духовною реалізацією в парі. 🤗🙏 Будете мати натхнення, розповідайте про ваші враження від спілкування з моїми Учнями. Бо я наставник з вимогами до чистоти мотивації та якості результату. І кажу як є: «Якщо до заду когось прилипло пірʼя, це не означає, що перед вами велична птаха, вибирайте по справах людину, дивіться за її «польотом», дослідіть її ціль та місію, а не начесаний до блиску пушок…» … Zaverukha.com - камертон сакральної мудрості, та сама НеоБерегиня, що пробуджує душі, саджає ліси, пише книги, співає балади і створює поле зцілення. 👇Кому цікаві деталі маршруту в IMARIAACADEMIA з метою навчання та отримання фахової професії, пишіть… Посилання лишаю внизу. Робіть перепост - створюйте ментальні відбитки ВАШОЇ успішної самореалізації, єднаючи людей з тим, що вони шукають, з якісними спеціалістами… 🤗 І спішіть забронювати собі місце для унікальної консультації про ВАШ ПУТЬ ДУШІ, про код особистого бренду, про задачі в союзі сімʼї, про самореалізацію в новому часі, про космічне племʼя вашого походження, про пожиттєві обовʼязки перед родом для виходу із 3d матриці, про … ааааа… ви стііііільки всього здатні дізнатися у моїх чарівних випускниць вже прямо зараз… 🤗🤗🤗 СУЗІРʼЯ ПЕРШИХ: 💫 Катерина Дера 💫 Катерина Ольховик 💫 Elena Bakuley 💫 Natalya Voznenko 💫 Oleksandra Bohdanova 💫 Viktoriia Vostrikova 💫 Viola Dianova 💫 Diana Palamarenko 💫 Юлія Зелінська 💫 Anna Zyniuk 💫 Julia Korzh 💫 Inna Shuliak 💫 Olena Kraievska 💫 Oksana Nikitenko 💫 Nataliia Nazarenko 💫 Tamila Lukianenko 💫 Ірина Сачик 💫 Kateryna Rayda 💫 Ольга Чугреева 💫 Elvira Stepanets 💫 @КрабіхлерІрина 💫 Сакович Алёна … Полетіли 🛸🤗 © Ірина Заверуха, 2025 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','15 травня 2025','6 хв читання','/images/posts/491126545_672768395610423_1410081531369642011_n.jpg','[]',1,'2025-05-15T22:17:55','2025-05-15T22:17:55');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2770','%d0%b4%d1%83%d1%85%d0%be%d0%b2%d0%bd%d0%b0-%d0%be%d1%81%d0%be%d0%b1%d0%b8%d1%81%','«Духовна особистість» це взагалі не особистість','…На духовному шляху немає контрактів «ти мені я тобі». «Духовна особистість» це взагалі не особистість. Немає обміну. Є лише сяйво. Без «давати і брати»…без усіляких історій про баланс та дисбаланс. Проявляється Видих безмежного. Ти робиш те, що ство...','["…На духовному шляху немає контрактів «ти мені я тобі». «Духовна особистість» це взагалі не особистість. Немає обміну. Є лише сяйво. Без «давати і брати»…без усіляких історій про баланс та дисбаланс. Проявляється Видих безмежного. Ти робиш те, що створюється в лоні Єдиного Всесвіту, погодженого з виміром живого життя, а не дещо егоїстичне, бо повірила в відірваність від цілого. Ти йдеш туди, де твоя присутність не потребує від людей очікувань обміну. Це важливо… Тобі здається, що на спині важка ноша? Придивись - то крила. Важко лиш тому, що ти повзаєш, а не літаєш ними… і прикидаєшся звіриною істотою. Але ти людина із роду божого. Подивись, що довкола коїться? З екранів навʼязують безкінечне бездумне гіперпотреблятство, щоб синтетичні душі людей ХОТІЛИ, і з похоті транслювали потоки енергії. Мразі нею живляться. Паразитуючі цивілізації не видимі очима для більшості людей. Але вони тримають людство насправді в рабстві. Якщо ти віриш, що з тобою щось не так, бо ти не маєш «ось такої сумки», чи «ось таких годинників», чи якихось іще форм… - знай, ти адепт світу ілюзій, ти не в реальності. І цей світ зникає. Тому замість агонії і паніки - розбирайся з темою. (Почни з книги «Бесіди з Ангелами» , приходь навчатися, не сходь з орбіти спільнот світочів) Бо зовсім скоро Земля почне масову зачистку і в паралелі - йтиме процес духовного вознесіння планети, як єдиного тіла та свідомості. І керує цим наша єдина МА, через проявлену міжгалактичну Душу, що має шифри і коди, втілені в носіях Хранителів Частот. Назад дороги не має. Це не континіум один із. Ні. Вже закінчились усі варіанти перехресть. Попереду єдиний путь. Це путь любові. Путь доброти. Путь радості. Путь щедрості… Золотий вік Творців. Паразитуючі форми і цивілізації загарбників покинуть планету. Одні самі полетять, перемістяться. І відловлюванням їм подібних провідники такі, як я, займаються вже понад 20 років. Це процес без пауз і зупинок. Триває нон-стоп. Істоти низькочастотних вимірів провокують людину із божого роду переходити на сторону звіриного мислення через різні маніпуляції владою і багатством. Вони харчуються низькочастотними елементалами емоцій, вони пожирають спектри душі в момент смерті. Знаходяться найбільше там, де багато війн і вбивств. І крадуть таким чином ключі та шифри від родових програм. Тому такі як я - НеоБерегині Землі в часи переходу, - стоять на стражі процесу не лише життя, але й смерті. В самих епіцентрах подій! Оберігаючи душі від втрати ключів, від інформаційного хакінгу. Реалізовуючи чистоту переходу. Працюючи справжніми мостами (містиками) для душ, щоб вони не потрапили в полон до паразитів в своєму стані розгубленості і шоку… (це триває в перші 3 доби після смерті). А що з живими? Віруси інформаційних інфекцій дуже сильні. Людина втрачає контроль за власною психікою і емоціями. Блокується центр вищої інтуїції і критичного мислення. Тому ви повинні чинити супротив цим атакам. Оберігати себе та дітей. Знаходитись в практиці постійної енергетизації духовними вібраціями. І це не про релігії. Все навпаки. Релігійні лідери служать паразитуючим структурам і усі культи та ритуали направлені на рабство душі та її безцінну енергію сяяння. Генератор надпотужних імпульсів сили - це людське серце. Не як орган, а як імпульс контакту з центральним сонцем галактики, що постійно посилає випромінювання в частотних діапазонах доброти та турботи. Будь яка навіть інфікована звіриним демонічним егоїзмом людина, здатна оживати душею, коли відбувається доторк до поля просвітлених носіїв зіркових ДНК. Пробуджується памʼять, що здатна торкатися коріння предків глибше, ніж 12-14 тисяч років назад. А саме тоді сталося остаточне поневолення свідомості планети. Тому зараз дуже важливо не просто йти до роду, як до прізвищ в семи поколіннях. Не паразитувати на цій памʼяті. А задача полягає в доторку до першоджерельних спектрів Сили духовної. Алхімія взаємодії стихій відкриває ворота. Ліси планети є живими порталами переходу. Вони теж відловлюють елементалів паразитів і утилізують їх. Тому важливо саджати свідомі ліси. Ідіть до лісу. Дихайте! Не втрачайте світло душі! Не ведіться на ілюзії виміру форм. Не присвячуйте своє життя досягненням предметів… ви живете не заради цього. Літо 2025 року буде поворотним і до кінця 2026 перша стадія вознесіння вже станеться. Це жорсткий час. В який Творець зібрав усіх нас разом для неймовірно важливої місії. … Я розкриватиму спектри знань про усе це в глибину на кожній події, яку проводитиму: 💌 в Буші на семінарі-благословінні; 💌 на презентації Балади Берегині, яка проявиться концертом-медитацією; 💌на ретритах в Карпатах у липні (їх до речі буде два, хто не встиг потрапити в першу групу, бо вона набрана була за 45 хвилин після оголошення деталей, - напишіть тут про бажання бути і дамо деталі для броні). 💌на нео-курсі «Пара Нового Часу», який читатиму вперше! 💌 на усіх сатсангах в середовищі PiplClub … 💌на марафонах, через які служу вознесінню Землі… і на навчальних програмах Крила , та тренерському курсі Путь Душі, де передаю колегам знання про Вібраціологію та хілінг… Все дуже серйозно, друзі. І чим ближче до релізу та катарсису, - тим більше ілюзії та брехня присипляють увагу людей… © Ірина Заверуха, 2025 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','26 травня 2025','4 хв читання','/images/posts/zaverukha.com_-1.png','[]',1,'2025-05-26T18:45:06','2025-05-26T18:45:06');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2773','%d0%b1%d0%b0%d0%bb%d0%b0%d0%b4%d0%b0-%d0%b1%d0%b5%d1%80%d0%b5%d0%b3%d0%b8%d0%bd%-2','Балада Берегині …Коли ти Тиша в епіцентрі хаосу…','Новина, на яку ми чекали, вривається у цей день потужно і гучно🔥🔥🔥 Нарешті станеться!!! «Балада Берегині» вилітає у простір життя, аби окриляти серця… 22 червня у Києві відбудеться прем’єра кліпу до «Балади Берегині» та концерт-медитація від цілителя...','["Новина, на яку ми чекали, вривається у цей день потужно і гучно🔥🔥🔥 Нарешті станеться!!! «Балада Берегині» вилітає у простір життя, аби окриляти серця… 22 червня у Києві відбудеться прем’єра кліпу до «Балади Берегині» та концерт-медитація від цілителя IMARIA Заверухи Ірини – унікальний творчий перформанс, містерія, що пробуджує в тілі генетичний код роду, єднає кожну душу з джерелом любові та наповнює жагою до життя. Це не лозунг, а феномен, який ми — організатори, вже проживаємо! А що кожній людині конче потрібно нині? Сила та віра, надія і мотивація, ресурсність і чудо… Усе тут є. Не пропустіть… таке буває один раз у житті…🤗 Бронюй свою участь у заході (офлайн або онлайн), саджай разом з нами іще один ліс в Україні, читай деталі у розділі новини, дивись тизер до шедеврального кліпу в YouTube каналі, і окриляйся разом зі спорідненими на цілий рік вперед. Детальніше про подію. А також, слідкуйте за процесом підготовки до прем’єри “Балади Берегині” на особистій інстаграм сторінці Ірини Заверухи https://youtu.be/GWC1t0ik8XI?si=_g05UmxGlHC_fPVH © Ірина Заверуха, 2025 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','28 травня 2025','3 хв читання','/images/posts/photo_5312259759694541521_y.jpg','[]',1,'2025-05-28T15:03:49','2025-05-28T15:03:49');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2791','%d0%bd%d0%b0%d1%86%d1%96%d0%be%d0%bd%d0%b0%d0%bb%d1%8c%d0%bd%d0%b0-%d0%bf%d1%80%','Національна премія «Жінка України»','Сьогодні день жіночої емансипації… Мені більше імпонує подача терміну «жіночої дружби»… Бо будь яка боротьба за будь що - вже по факту свідчить про розділення і статус «кращий/гірший». Не можу мислити іншими поняттями. Транслюю саме це - зрілість хоч...','["Сьогодні день жіночої емансипації… Мені більше імпонує подача терміну «жіночої дружби»… Бо будь яка боротьба за будь що - вже по факту свідчить про розділення і статус «кращий/гірший». Не можу мислити іншими поняттями. Транслюю саме це - зрілість хоче бути не «особливою», а щасливою серед щасливих, красивою серед красивих, королевою серед королев, гідною серед гідних… А не зрілість спонукає до конкуренції. Я не вірю в конкуренцію. Зате бачу прекрасні результати Сили Єдності. Була на цій церемонії. Жила разом з кожною миті тріумфу. І плакала. І сміялась. І пишалась… Дякую тобі Інна Гелетюк Ех Катющенко за все, що ти створюєш і як саме це проявляється… «Жінка України 2025»: стали відомі імена лауреаток 💞💞💞 © Ірина Заверуха, 2025 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Новини','Ірина Заверуха','1 червня 2025','3 хв читання','/images/posts/111_50-1-scaled.jpg','[]',1,'2025-06-01T14:48:23','2025-06-01T14:48:23');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2795','%d0%b1%d0%b0%d0%bb%d0%b0%d0%b4%d0%b0-%d0%b1%d0%b5%d1%80%d0%b5%d0%b3%d0%b8%d0%bd%-3','«Балада Берегині» уже доступна до прослуховування!','На всіх музичних платформах!!! «Все, що тобі треба — причаїлось в серці, Ти звернись до неба — і помітиш дверці!» 🎙️Автор слів Ірина Заверуха 🎼Автор музики Ірина Заверуха 🎛️Звукорежисер і аранжування Костянтин Галецький 🎙️Студія звукозапису NEWWAVE S...','["На всіх музичних платформах!!! «Все, що тобі треба — причаїлось в серці, Ти звернись до неба — і помітиш дверці!» 🎙️Автор слів Ірина Заверуха 🎼Автор музики Ірина Заверуха 🎛️Звукорежисер і аранжування Костянтин Галецький 🎙️Студія звукозапису NEWWAVE Sound Workshop 📉Куратор дистрибуції Віталій Керестен 👩‍💻Графічний дизайнер Аліна Хаблова 📸Фотохудожник Влада Мазур Щоб прослухати пісню- переходь за https://linktr.ee/Zaverukha або 🔍вводь на музичних платформах YouTube Music, Apple Music, Spotify, Instagram, TikTok — IMARIA «Балада Берегині». Слухайте, поширюйте і щасливійте 💚💚💚 І вже зовсім скоро, 22 червня, ми зустрінемося на премʼєрі кліпу «Балади Берегині». Це буде справжня містерія, бо Балада Берегині — це ключ, що відкриває памʼять. Код, що живе в серці кожної жінки. Нитка, яка веде до ресурсів Роду. Премʼєра кліпу 22 червня — це жива дія, де під час звучання Ірини Заверухи IMARIA MASTER буде створене потужне магнітне поле, яке активується тільки у моменті, тільки у присутності. Саме тоді відбувається ініціація. Прем’єра «Балади Берегині» реалізовується не для перегляду в записі, а для проживання — тілом, душею, серцем. Не пропусти можливість бути частиною цієї події. Бо вона для тебе. І для твого Роду. Приходь, щоб зʼєднатися з собою, зі своїм Родом, з Душею♥️ https://pipl.net.ua/imaria-balada-berehyni © Ірина Заверуха, 2025 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','10 червня 2025','3 хв читання','/images/posts/zaverukha.com_.png','[]',1,'2025-06-10T13:20:17','2025-06-10T13:20:17');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2799','%e2%9a%9c%ef%b8%8fluxury-retreat-by-imaria-%e2%9a%9c%ef%b8%8f','⚜️Luxury retreat by IMARIA ⚜️','Цього разу буде нішевий ретрит. Ні, ти ще такого зі мною не проживала... та я й сама іще ні з ким такого не проживала… 🤓 Програма, насичена красою і турботою про наше ЖІНОЧЕ. Буде не просто багато практики, а меееега багато уваги до себе, до тіла, до...','["Цього разу буде нішевий ретрит. Ні, ти ще такого зі мною не проживала... та я й сама іще ні з ким такого не проживала… 🤓 Програма, насичена красою і турботою про наше ЖІНОЧЕ. Буде не просто багато практики, а меееега багато уваги до себе, до тіла, до догляду, до граней особистості, що не вибирає між матеріальним та духовним… а проживає екологічну розкіш буття. Кілька пакетів участі. Неймовірно казкове місце, де від самої присутності вже розкривається і розквітає гармонія насолоди… В планах - поїздка і похід за покликом голосу Роду до Смерекового каменю. …Я проведу тебе стежками заповідника «Зачарований край», що приховує серед вулканічної лави та тиші букового лісу таємниці Атлантів, нашіптуючи ельфійською мовою дуже сакральні рецепти про щастя… Ні. Це не лозунги казкові… це все реальність. До речі і назви теж 🤗 У нас буде ритм вальсу, а швидкість процесів - рівня квантової… що і є прекрасно… бо ми ж з тобою хочемо ефективності своїх інвестицій часом. Вірно? Вірно! Тебе чекає естетика на кожному міліметрі простору. Від моєї програми, самого закладу «Поляна птахів», … до харчування і фототерапії в станах КОРОЛЕВА ЖИВОГО ЖИТТЯ… Вартість участі: Пакет Стандарт - 24 000 грн. Пакет Максі - з сеансом масштабування родового дару! - 31 000 грн. Можлива оплата частинами. Кількість місць для участі в ретриті дуже обмежена, лише 22 учасниці. Тому ніяких «я подумаю» не вийде. Ти можеш обрати дату, коли хочеш приїхати на ретрит: 1 група: з 10 по 15 липня (1 місце) 2 група: з 16 по 21 липня (10 місць) Місце: \"Поляна Птахів\", Закарпаття Забронюй свою участь оплатою авансового внеску у розмірі 4000 грн., який не повертається у разі скасування поїздки будь якою зі сторін, але ти можеш використати його як частину оплати за участь онлайн. Бажаю тобі успіхів. Встигай… За реквізитами і відповідями на питання пиши в Телеграм @annaazadorozhna © Ірина Заверуха, 2025 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','13 червня 2025','3 хв читання','/images/posts/photo_5357573039056876785_y.jpg','[]',1,'2025-06-13T09:15:02','2025-06-13T09:15:02');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2827','imaria-%d0%b1%d0%b0%d0%bb%d0%b0%d0%b4%d0%b0-%d0%b1%d0%b5%d1%80%d0%b5%d0%b3%d0%b8','IMARIA – Балада Берегині ПРЕМ''ЄРА 2025','«Балада Берегині» створена цілителем, тому вона пробуджує в житті ЖИТТЯ… Це мистецький інструмент для трансформації свідомості та ініціації сакрального звʼязку душі з ресурсами роду. Занурюючись в твір активно, слухач має можливість проживати сердечн...','["«Балада Берегині» створена цілителем, тому вона пробуджує в житті ЖИТТЯ… Це мистецький інструмент для трансформації свідомості та ініціації сакрального звʼязку душі з ресурсами роду. Занурюючись в твір активно, слухач має можливість проживати сердечне єднання з полем Живого Життя. Генетичний код космічного першопочатку проявляє Силу духу предків і гармонізує стан. Кліп до Балади Берегині знято в лоні українських Карпат під час повномасштабної війни, саме в період коли чоловік авторки ставав до лав Захисників людської гідності. Це справжня повість про Силу пробудженої жінки, яка здатна зцілювати простір присутністю і любовʼю, турботою про себе, про природу, про всеСвіт. З перших нот Балада Берегині огортає вібраційною могутністю і заводить на глибину океану душі… Ірина Заверуха: «Балада Берегині не про сексуальність, не про гроші, не про романтику, а про внутрішню розкіш. Так, сила серця не питає дозволу на проявлення. Ніколи. Коли ти тиша навіть посеред хаосу. Як це осягнути? 2025 рік здатен наше з вами життя з ніг на голову перевернути. І лише вона, жіноча, тиха, ніжна, наповнена присутність, може зцілити цей світ і створити новий, бо жінка у нас творець життя, чи не так? Нам з вами в цьому новому вимірі зараз потрібні не мільярдери, а жінки, які живуть серцем, які можуть чути і відчувати, і їхні ідеї, проєкти, проявлення – це не про товар, ні, а про присутність. Не про торгівлю, а про обмін. Не про те, щоб кудись бігти і чогось досягати, а про те, щоби пригадати: ти цінність навіть в бездіяльності. М''яка сила стане фундаментом нового часу, і усі, хто вміють жити в цій гармонії, збудують нове начало, зародять нове зерно потенціалу. І коли звучить фраза, що в цьому світі виживе лише любов, це не лозунг, це реальність. Як залишатися в серці живими, коли стільки смерті довкола? Цей світ змінять не революції! Ні! А жінки, які більше не мовчать, коли болить, які не погоджуються, не толерують насилля, які беруть на себе відповідальність за ось це “зараз”. Так, немає зовнішніх ворогів, просто душа виходить на орбіту влади. Душа людства більше не витримує брехні. І саме жінки здатні стояти на цій межі. Між старим і новим світом, між життям і смертю. Жінки-берегині. Коли все дестабілізаційно, коли немає ні на що надії… Лише жінки, які відчувають себе, які чують свою душу, дійсно здатні не лише встояти, але й втримати. Так, жінко, будь в контакті з собою, почуй істину, не грай чужі ролі. Через свою велич присутності, м''якість. Не обов''язково бути гучною, святою, але потрібно бути справжньою, живою, свідомою, здоровою, ресурсною, собою. Жінко України, ти той міст, через який душа проходить у новий світ і народжує його. Згадуй себе разом зі мною. Слухайте серцем на всіх платформах: https://linktr.ee/Zaverukha Над баладою працювали: Lyrics Iryna Zaverukha Music Iryna Zaverukha Arranged Constantin Galetsky Record NEWWAVE Sound Workshop Distribution curator Vitaliy Keresten Над відео працювали: Director and producer Yuri Pavlishinets Camera and videographer Victor Pavlysh Photographer and videoartist Vlada Mazur Designer Alina Khablova Dress designed by sisters Alina Gaeva , Karina Gaeva and Iryna Zaverukha (сукня-берегиня «Споріднені») Accessories: Willna , Kochut , Guzema Location: Verkhovyna Hotel , Ukrainian Carpathians – Lake Synevyr , Mount Pishkonya https://youtu.be/_tGgxUY7z4o?si=cZ0O7MPxvgJ05a8p БАЛАДА БЕРЕГИНІ Дихають Карпати, соснами покриті, Скелі волохаті плещуться в блакиті, Піснею заманить лісова діброва, І радію щиро, що я з ними знову… Тьохкання пташине будить душу вранці, І кружляє літо в смерековім танці, Матінка природа п’є з струмочка воду, Босими ногами я торкаюсь роду… Під горою тихо стану і замрію, Про майбутнє світле, про життя, надію, Закупаюсь в росах і укриюсь сміхом, Буду щасливіти Ангелам на втіху… Принесу в долонях зоряне намисто, Одягну на душу я сорочку чисту, І розсиплюсь в світі перлами-словами, Щоб Любов розлилась морем поміж нами.. Як знайдеш перлину, що тобі послала, Не ховай у скриню, де хустки складала, Одягай на душу чистую сорочку, І навчи те ж саме ти робити дочку… Щоб у кожнім домі заспівали птахи, Щоб зникали кволі, бідні і невдахи, Ти ходи до річки босими ногами І пізнаєш тайну, яку знали МАМИ… Мавкина стежина заведе до раю, Як туди потрапить — твоє серце знає, Розбуди у тілі ти свою Богиню, Будеш для країни Лада-Берегиня… Будеш всіх плекати, щастя дарувати, Намалюєш радість на паркані хати, Все, що тобі треба — причаїлось в серці, Ти звернись до неба — і помітиш дверці! ©Заверуха І.Л., 2017-2025. Усі права захищено. https://linktr.ee/Zaverukh © Ірина Заверуха, 2025 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','22 червня 2025','4 хв читання','/images/posts/zaverukha.com-1-1.png','[]',1,'2025-06-22T17:17:00','2025-06-22T17:17:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2837','%d0%b2%d1%81%d0%b5-%d1%89%d0%be-%d1%82%d0%be%d0%b1%d1%96-%d1%82%d1%80%d0%b5%d0%b','«ВСЕ, що тобі треба, причаїлось в серці, ти звернись до неба, і помітиш дверці…»','… усе в житті хоче бути своєчасним! 🤩🌎💫🌿🙏 Я це зробила… ми це зробили… 🇺🇦🥹 Премʼєра кліпу до Балади Берегині реалізована на найвищому та достойному її рівні! 🌟22.06.2025 ще один день в історії моєї долі… Буду ділитись усім поступово. А поки що кажу с...','["… усе в житті хоче бути своєчасним! 🤩🌎💫🌿🙏 Я це зробила… ми це зробили… 🇺🇦🥹 Премʼєра кліпу до Балади Берегині реалізована на найвищому та достойному її рівні! 🌟22.06.2025 ще один день в історії моєї долі… Буду ділитись усім поступово. А поки що кажу словами балади: «ВСЕ, що тобі треба, причаїлось в серці, ти звернись до неба, і помітиш дверці…» ©️ 👇👇👇 https://youtu.be/_tGgxUY7z4o Слухати як пісню тут - https://linktr.ee/Zaverukha Відчиняйте дверці серця 🫶 дивіться очима внутрішніми 🥰 і поширюйте кліп з присвятою — для краси прояву кожної Душі та миру на Землі 🙏 Мрію, щоб у кожному домі звучали слова балади, а любов лилася поміж нами 🤍🌿 🎥 Зі словами глибокої вдячності до всіх творців 🙏🫶 Над кліпом до балади працювали: Слова - Ірина Заверуха Музика - Завурухи Ірини Оранжування і продакшн - Newwave Sound Workshop Kуратор дистрибуції - Віталій Керестен Режисер сценарію - Юрій Павлишинець Оператор - Viktor Pavlysh Фотохудожник і відеомейкер - Vlada Mazur Графічний дизайнер - Алина Хаблова Одяг - сукня-берегиня «Споріднені» авторська розробка від Заверухи Ірини і сестер Karina Gaeva та Alina Haieva Декор - Willna Ювелірний партнер - Kochut Локація зйомки - Verkhovyna Resort Medical & Wellness & Ukrainian Carpathians – Lake Synevyr, Mountain Pishkonya… ✨✨✨✨✨ #далібуде… P.S. ця жінка однозначно пройшла свою «мавкину стежину» і веде до раю інших людей… 🥰🙏 Хто вже бачив кліп? Відчули масштаб енергії, потужність послання і обійми любові від живого життя та роду…? © Ірина Заверуха, 2025 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','23 червня 2025','3 хв читання','/images/posts/zaverukha.com_.png','[]',1,'2025-06-23T09:41:00','2025-06-23T09:41:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2861','%d0%bd%d0%be%d0%b2%d0%b0-%d0%b2%d0%b5%d1%80%d1%81%d1%96%d1%8f-%d0%b1%d0%b0%d0%bb','Нова версія «Балади Берегині» — SHAMANKA by IMARIA','Танцюй. Відчувай. Заряджайся. Зцілюйся… Реміксова версія Балади Берегині запалює вогонь у ритмі космічно-земного імпульсу. Вона має місію будити СИЛУ РОДОВУ в кожному серці! Без перебільшень… Зустрічайте нову версію «Балади Берегині» — SHAMANKA by IM...','["Танцюй. Відчувай. Заряджайся. Зцілюйся… Реміксова версія Балади Берегині запалює вогонь у ритмі космічно-земного імпульсу. Вона має місію будити СИЛУ РОДОВУ в кожному серці! Без перебільшень… Зустрічайте нову версію «Балади Берегині» — SHAMANKA by IMARIA ✨ Це нова хвиля для нового часу... Це — вібрації вільної жіночої сили: 🌪 Драйв 🌺 Насолода ❤️ Любов 🌈 Краса і естетика ✨ Пробудження 💃 Збудження...просвітлення… Слухайте і дивіться просто зараз: YouTube Всі музичні платформи До речі, тут поділюсь моментом спонтанного зародження шаманської версії #БаладаБерегині — все було саме так… Я проводила ретрит в Ізках і зловила хвилю настрою. Попросила @vladamazurs це зняти на телефон… і все. Фіксація сталася. Тобто тут це не постановка, а абсолютний живий момент. Там — за кадром — я співаю вслух ритм і мотив, які народилися в ту версію, що ви тепер чуєте і відчуваєте … Відчуваєте силу життя, яке воскресає всередині? https://www.instagram.com/p/DTs81soCExz/ Творці Ballad of beregyny SHAMANKA: Слова і музика — Заверуха Ірина Оранжування і продакшн — Костянтин Галецький, Newwave Sound Workshop Куратор дистрибуції — Віталій Керестен Фотохудожник і відеомейкер — Влада Мазур Графічний дизайнер — Аліна Хаблова Локація — еко курорт Ізки P.S. «Душу й тіло ми пробудимо за нашу свободу і покажемо, що ми сила з шаманського роду…» © Ірина Заверуха, 2025 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','22 липня 2025','3 хв читання','/images/posts/2.jpg','[]',1,'2025-07-22T12:48:45','2025-07-22T12:48:45');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2904','%d1%96%d0%bd%d1%88%d0%be%d1%97-%d0%bf%d0%bb%d0%b0%d0%bd%d0%b5%d1%82%d0%b8-%d1%83','…Іншої планети у нас немає…','Ніби й кожен це знає. Але чомусь не хочеться брати відповідальність за таку глобальну дальність… Друзі, ми саджатимемо черговий ліс…🥰🌳🌲 Вкорінюватимемо мудрість у вічність. Нехай тіло планети отримує від нас не тільки ниття та сміття, а й шанс на кра...','["Ніби й кожен це знає. Але чомусь не хочеться брати відповідальність за таку глобальну дальність… Друзі, ми саджатимемо черговий ліс…🥰🌳🌲 Вкорінюватимемо мудрість у вічність. Нехай тіло планети отримує від нас не тільки ниття та сміття, а й шанс на краще життя. Варто лишень трішки подумати, трішки душею цінність відчути і тоді реально почути… серцебиття живого життя… 💚 Книга Бесіди З Ангелами почала цю ініціативу. І надихнула інших. Тому я щаслива… 🖐Щоб придбати книгу, заходь сюди 👉 IMARIA SPACE Разом з партнерами, екосистемою Derevorod ми йдемо дерева саджати… 🌿🌎🫶 Пішли разом! 🙌 Кошти, які створені на премʼєрі Балада Берегині — ми вже передали. І маємо намір не зупинятися. 📣🤩Тому зовсім скоро 12 жовтня відбудеться жива зустріч у Києві, черговий Magic Woman Day з присвятою служінню планеті! Не пропустіть… Приходьте, приїздіть у Київ… Бронюйте місце за посиланням👇 https://secure.wayforpay.com/button/bd45c008feffa Захід має соціальну місію. Не комерційну. Ми створюватимемо матеріальний ресурс для посадки лісу через свій творчий ресурс організаторів... З любовʼю, IMARIA®️ & PIPL®️ © Ірина Заверуха, 2025 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','8 жовтня 2025','3 хв читання','/images/posts/48.jpg','[]',1,'2025-10-08T13:32:04','2025-10-08T13:32:04');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2906','%d0%ba%d1%96%d0%bd%d0%b5%d1%86%d1%8c-%d1%86%d0%b5-%d0%bf%d0%be%d1%87%d0%b0%d1%82','Кінець - це початок!','Друзі, тепер ви можете придбати запис лекції без реєстрації в PIPL CLUB! Цей ефір — відкриття року для тих, хто відчуває поклик до глибшого розуміння духовних процесів і власного місця у великій еволюції Свідомості 🌍 У ньому — унікальні знання від Ір...','["Друзі, тепер ви можете придбати запис лекції без реєстрації в PIPL CLUB! Цей ефір — відкриття року для тих, хто відчуває поклик до глибшого розуміння духовних процесів і власного місця у великій еволюції Свідомості 🌍 У ньому — унікальні знання від Ірини Заверухи: 🟠 про ієрархію еволюційних етапів розширення свідомості людини; 🟠про ролі вчителів та учнів в цьому часі; про те, чому існують у світі духовні вчителі і для чого так багато зараз; 🟠про реверсний путь: родовий канал розвитку в полі Великої МА; 🟠про єдиний і неповторний кристал, що формує звʼязок з центральним духовним сонцем галактики і розкриває доступ до надздібностей; 🟠про силу благословіння та силу вдячності; 🟠про світ духів, якими вони бувають, і з ким саме контактувати починає ієрархія Світла в першу чергу; 🟠на що робити ставку та акцент людям допомагаючих професій найближчі 1,5 роки; 🟠про істинне джерело матеріального процвітання та про те, що зараз важливо відпускати не лише непотріб, а навіть «хороше», але яке ВЖЕ не потрібне … 💫 Не відкладайте це на потім. Відчуйте, як знання з цього ефіру розставляють усе по місцях, пробуджують пам’ять Душі й відкривають доступ до нового рівня розуміння. 🎧 Слухайте запис одразу, як дізнались про цю можливість. 👉 https://zaverukhacomgmailcom.lms.softbook.app/shop/item/10909 © Ірина Заверуха, 2025 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','7 жовтня 2025','3 хв читання','/images/posts/5390977400604589285.jpg','[]',1,'2025-10-07T13:42:14','2025-10-07T13:42:14');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-2938','%d0%bc%d0%be%d1%8f-%d1%82%d0%b2%d0%be%d1%80%d1%87%d1%96%d1%81%d1%82%d1%8c','Моя творчість','Ну що ж вітайте — пані Вчителька стала і артисткою!🎤🎬🤗 … усе в житті хоче бути своєчасним! Я це зробила іще в червні 2025 року… ми це зробили з командами IMARIA®️ & PIPL®️ @pi_platform … 🇺🇦🌏🤗🤩🤗🫂 Премʼєра кліпу до Балади Берегині була реалізована на н...','["Ну що ж вітайте — пані Вчителька стала і артисткою!🎤🎬🤗 … усе в житті хоче бути своєчасним! Я це зробила іще в червні 2025 року… ми це зробили з командами IMARIA®️ & PIPL®️ @pi_platform … 🇺🇦🌏🤗🤩🤗🫂 Премʼєра кліпу до Балади Берегині була реалізована на найвищому та достойному її рівні! 🌟22.06.2025 ще один день в історії моєї долі… І 4.12.2025 стає другим днем народження мене із ролі #АРТИСТ …🤓 Буду ділитись усім поступово. А поки що кажу словами балади: «ВСЕ, що тобі треба, причаїлось в серці, ти звернись до неба, і помітиш дверці…» ©️ 👇👇👇 https://youtu.be/_tGgxUY7z4o?feature=shared Слухати як пісню тут: https://linktr.ee/Zaverukha Хайлайтс моєї офіційної сторінки в інстаграм . Для тих, кому цікаво як відбувався шлях до Премʼєри кліпу— завітайте на старий заблокований аккаунт в Instagram, — там є всі послідовні кроки . Відчиняйте дверці серця, дивіться очима внутрішніми 😍 і поширюйте кліп з присвятою — заради краси прояву кожної Душі на землі 🙏 Мрію, щоб у кожному домі звучали слова балади, а любов лилася поміж нами 🤍 Зі словами глибокої вдячності до всіх творців 🙏🫶 Над баладою працювали: Lyrics - Iryna Zaverukha Music - Iryna Zaverukha Arranged - Галецький Костянтин Record - Newwave Sound Workshop Distribution curator - Vitaly Keresten @uakrstn Над відео працювали: Director and producer - Yurii Pavlyshynets Camera and videographer - Viktor Pavlysh Photographer and videoartist - Vlada Mazur Designer - Alina Khablova Dress designed by sisters — Alina Haieva & Karina Gaeva and Iryna Zaverukha (сукня-берегиня «Споріднені») — @imaria_space Accessories: Willna , Kochut , Guzema Ukraine Location: Verkhovyna Resort , Ukrainian Carpathians – Lake Synevyr, Mountain Pishkonya © Ірина Заверуха, 2026 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','24 листопада 2023','3 хв читання','/images/posts/IMG_8598.jpg','[]',1,'2023-11-24T14:27:00','2023-11-24T14:27:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-3004','%d1%96%d0%bd%d1%81%d1%82%d1%80%d1%83%d0%bc%d0%b5%d0%bd%d1%82%d0%b0%d0%bb%d1%8c%d','Інструментальна версія Балади Берегині','Ви просили — ми зробили! ІНСТРУМЕНТАЛЬНА ВЕРСІЯ Балада Берегині вже в доступі і готова служити людям. Вчіть слова, золоті, і співайте свої версії, навчайте дітей, збагачуйте власний репертуар українським сучасним фолком … БАЛАДА БЕРЕГИНІ Дихають Карп...','["Ви просили — ми зробили! ІНСТРУМЕНТАЛЬНА ВЕРСІЯ Балада Берегині вже в доступі і готова служити людям. Вчіть слова, золоті, і співайте свої версії, навчайте дітей, збагачуйте власний репертуар українським сучасним фолком … БАЛАДА БЕРЕГИНІ Дихають Карпати, соснами покриті, Скелі волохаті плещуться в блакиті, Піснею заманить лісова діброва, І радію щиро, що я з ними знову… Тьохкання пташине будить душу вранці, І кружляє літо в смерековім танці, Матінка природа п’є з струмочка воду, Босими ногами я торкаюсь роду… Під горою тихо стану і замрію, Про майбутнє світле, про життя, надію, Закупаюсь в росах і укриюсь сміхом, Буду щасливіти Ангелам на втіху… Принесу в долонях зоряне намисто, Одягну на душу я сорочку чисту, І розсиплюсь в світі перлами-словами, Щоб Любов розлилась морем поміж нами.. Як знайдеш перлину, що тобі послала, Не ховай у скриню, де хустки складала, Одягай на душу чистую сорочку, І навчи те ж саме ти робити дочку… Щоб у кожнім домі заспівали птахи, Щоб зникали кволі, бідні і невдахи, Ти ходи до річки босими ногами І пізнаєш тайну, яку знали МАМИ… Мавкина стежина заведе до раю, Як туди потрапить — твоє серце знає, Розбуди у тілі ти свою Богиню, Будеш для країни Лада-Берегиня… Будеш всіх плекати, щастя дарувати, Намалюєш радість на паркані хати, Все, що тобі треба — причаїлось в серці, Ти звернись до неба — і помітиш дверці! ©Заверуха І.Л., 2017-2025. Усі права захищено. YouTube Music Spotify Apple Music © Ірина Заверуха, 2026 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','1 лютого 2023','3 хв читання','/images/posts/5085a830-e32c-4f2b-9f2e-f0a003183016.jpg','[]',1,'2023-02-01T18:31:00','2023-02-01T18:31:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-3014','%d0%bd%d0%be%d0%b2%d0%b0-%d0%b2%d0%b5%d1%80%d1%81%d1%96%d1%8f-%d0%b1%d0%b0%d0%bb-2','Нова версія «Балади Берегині» — SHAMANKA by IMARIA','Танцюй. Відчувай. Заряджайся. Зцілюйся… Реміксова версія Балади Берегині запалює вогонь у ритмі космічно-земного імпульсу. Вона має місію будити СИЛУ РОДОВУ в кожному серці! Без перебільшень… Зустрічайте нову версію «Балади Берегині» — SHAMANKA by IM...','["Танцюй. Відчувай. Заряджайся. Зцілюйся… Реміксова версія Балади Берегині запалює вогонь у ритмі космічно-земного імпульсу. Вона має місію будити СИЛУ РОДОВУ в кожному серці! Без перебільшень… Зустрічайте нову версію «Балади Берегині» — SHAMANKA by IMARIA Це нова хвиля для нового часу.... Це — вібрації вільної жіночої сили: 🌪 Драйв 🌺 Насолода ❤️ Любов 🌈 Краса і естетика ✨ Пробудження 💃 Збудження...просвітлення… Слухайте і дивіться просто зараз: YouTube Всі музичні платформи До речі, тут поділюсь моментом спонтанного зародження шаманської версії #БаладаБерегині — все було саме так… Я проводила ретрит в Ізках і зловила хвилю настрою. Попросила @vladamazurs це зняти на телефон… і все. Фіксація сталася. Тобто тут це не постановка, а абсолютний живий момент. Там — за кадром — я співаю вслух ритм і мотив, які народилися в ту версію, що ви тепер чуєте і відчуваєте … Відчуваєте силу життя, яке воскресає всередині? https://www.instagram.com/p/DTs81soCExz/ Творці Ballad of beregyny SHAMANKA: Слова і музика — Заверуха Ірина Оранжування і продакшн — Костянтин Галецький, Newwave Sound Workshop Куратор дистрибуції — Віталій Керестен Фотохудожник і відеомейкер — Влада Мазур Графічний дизайнер — Аліна Хаблова Локація — еко курорт Ізки P.S. «Душу й тіло ми пробудимо за нашу свободу і покажемо, що ми сила з шаманського роду…» © Ірина Заверуха, 2025 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','5 березня 2023','3 хв читання','/images/posts/photo_5271746849318573747_y.jpg','[]',1,'2023-03-05T19:16:00','2023-03-05T19:16:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-3019','%d0%bc%d0%be%d1%8f-%d1%82%d0%b2%d0%be%d1%80%d1%87%d1%96%d1%81%d1%82%d1%8c-2','Моя творчість','Премʼєра кліпу до Балади Берегині Інструментальна версія Балади Берегині Нова версія «Балади Берегині» — SHAMANKA by IMARIA Зміни вносити в іншому блоці!','["Премʼєра кліпу до Балади Берегині Інструментальна версія Балади Берегині Нова версія «Балади Берегині» — SHAMANKA by IMARIA Зміни вносити в іншому блоці!"]','Блог','Ірина Заверуха','9 березня 2023','3 хв читання','/images/posts/формат-ютюб-1.jpg','[]',1,'2023-03-09T19:16:00','2023-03-09T19:16:00');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-3244','%d0%bc%d0%b5%d0%b4%d1%96%d0%b9%d0%bd%d0%b0-%d0%bf%d1%80%d0%b5%d0%bc%d1%94%d1%80%','Медійна прем''єра','Знаєте, що для мене в становленні на шлях місії душі було найскладнішим? Йти дорогою служіння мудрості, створюючи щоденні причини для духовної глибини практикою, і при цьому не замикатися в межах одного «жанру», не перетворитися на нафталінову сіру б...','["Знаєте, що для мене в становленні на шлях місії душі було найскладнішим? Йти дорогою служіння мудрості, створюючи щоденні причини для духовної глибини практикою, і при цьому не замикатися в межах одного «жанру», не перетворитися на нафталінову сіру бабоньку, яка «пахне» тільки ладаном і нагадує своєю присутністю про те, що смерть дихає нам в в спину… 🫣 Смішно? Зовсім ні. Ми усі знаємо, що життя закінчується смертю. Але не для душі… 💫 І оберігати свою яскраву природу, бачити і чути кожну людину, що навпроти, відчувати життя і не ставати усіма емоціями інших, проживати життя і не зливатись з ідентифікаціями ролей… ооооось це було найскладнішим. Тобто, створити живий ритм путі. Я кайфую від путі Майстра, і шаную усі етапи рівнів реальності людини-жінки... 🥰 Я тут заради дітей Землі і щастя родин, – оберігати душі богореалізовані, підіймати серця творчістю, мистецтвом, мудрістю, диханням, практикою справжньої присутності в кожній миті, де б не була – це та симфонія, яку ніщо і ніхто не заглушить, бо ллється вона із першоджерела… Ну що ж. Зустрічайте. 29 червня о 14:14 за київським часом відбудеться прем''єра треку, що відкриває гілку реальності для втілення та проявлення цілого альбому #IMARIACODE 🎶… 🤩👌🇺🇦🌍💫👇 Щоб прослухати пісню — натисніть ТУТ або 🔎 Вводьте на музичних платформах YouTube Music, Apple Music, Spotify, Instagram — «IMARIA CODE». І ще дещо дуже важливе. 🌳 У день прем’єри пісні IMARIA CODE я хочу запросити вас стати частиною ще одного народження. Цієї осені проєкт IMARIA ® & PIPL ® разом із БФ DEREVOROD висадить вже шостий ліс. І саме сьогодні, у день появи нової пісні, ми відкриваємо збір на його створення. Разом із вами ми вже посадили десятки тисяч дерев. І я щоразу переконуюся: мистецтво здатне не лише торкатися сердець, а й буквально повертати життя нашій землі. Якщо відгукується — долучайтеся до народження нового лісу. 🌿 Зробити свій внесок можна: Monobank Картка: 4874 1000 2367 5476 PayPal Соціальна місія творчості IMARIA — створювати ліси в Україні. Бо коли мистецтво служить людині, а людина служить життю — народжується майбутнє. Над піснею IMARIA CODE працювали: 🎙️Автор слів — Ірина Заверуха 🎼 Автор музики — Ірина Заверуха 🎛️ Звукорежисер і аранжування — Костянтин Галецький 🎙️Студія звукозапису NEWWAVE Sound Workshop 📉 Куратор дистрибуції — Віталій Керестен 🌟 Автор ідеї — Жанна Солоднікова 👩‍🎨 Графічний дизайнер — Аліна Хаблова 📸 Фотохудожник — Влада Мазур Чекаю на вашу підтримку коментарями, прослуховуваннями, репостами і цікавими запрошеннями до взаємодії… … домовились? Вперед! Вже час… 🥴🙌 Приємного прослуховування і до зустрічі на путі IMARIA… бо допомагати людям єднатися з душею і реалізовувати свою місію - це і є моїм життям… 😉 © Ірина Заверуха, 2025 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Блог','Ірина Заверуха','29 червня 2026','3 хв читання','/images/posts/2026-06-29-11.34.28.jpg','[]',1,'2026-06-29T13:07:59','2026-06-29T13:07:59');
INSERT OR IGNORE INTO articles (id, slug, title, excerpt, content, category, author, date, read_time, cover_image, tags, published, created_at, updated_at) VALUES ('wp-3298','%d0%bd%d0%b5%d0%bc%d0%be%d0%b6%d0%bb%d0%b8%d0%b2%d0%be-%d0%b7%d0%bd%d0%b0%d0%b9%','«Неможливо знайти те, що ніколи не губилося»: велике інтерв''ю Ірини Заверухи для журналу Viva!','«Не можливо знайти те, що не губилося»… VIVA.UA, дякую за розмову, дякую за публікацію!','["Раді поділитися з вами знаковою подією! Відоме медіавидання Viva! опублікувало ексклюзивне інтерв''ю з духовною майстринею та засновницею нашого простору — Іриною Заверухою . У цій глибокій розмові Ірина вперше так відверто розповіла про свій новий творчий шлях — масштабний музичний проєкт IMARIA®CODE та вихід вібраційних пісень, які зцілюють простір роду. Про що ще ви дізнаєтеся в інтерв''ю: Як створювалася відома «Балада Берегині» та чому в альбомі використовується виключно жива музика; Чому місія нової творчості спрямована на зцілення структури сім''ї та роду; Які внутрішні виклики сьогодні проходять українці та чому нам так важливо розбудити власну гідність. Повну версію щирої розмови про духовну логіку, музику та сміливість бути собою читайте за посиланням нижче: 👉 Читати повне інтерв''ю на сайті Viva! VIVA.UA , дякую за розмову, дякую за публікацію! © Ірина Заверуха, 2025 Всі матеріали даного сайту є обʼєктами авторського права. Копіювання та розповсюдження матеріалів можливе лише за попереднього погодження з автором та вказанням активного посилання на цей сайт"]','Новини','Ірина Заверуха','4 вересня 2026','3 хв читання','/images/posts/61.jpg','[]',1,'2026-09-04T22:35:30','2026-09-04T22:35:30');